#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADS1115 I2C address when ADDR pin is tied to GND */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the wire):
 *   [15]    OS       = 1  (begin single conversion)
 *   [14:12] MUX      = 100 (AIN0 single-ended)
 *   [11:9]  PGA      = 001 (PGA ±4.096V)
 *   [8]     MODE     = 1  (single-shot)
 *   [7:5]   DR       = 100 (128 SPS)
 *   [4:0]   COMP_QUE = 111 (disable comparator)
 *
 * Binary: 11000111 10000000 = 0xC780
 */
#define ADS1115_CONFIG_SINGLE_AIN0 0xC780

/* MLX91219 characteristics */
#define MLX91219_SENSITIVITY 0.0040f   /* V/A */
#define MLX91219_OFFSET      0.0f      /* V at zero current */
#define MLX91219_VREF        3.3f      /* Pi 3.3V rail */

/* ADS1115 PGA full-scale range for PGA ±4.096V */
#define ADS1115_PGA_4_096V 4.096f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends the register address, then the data
 * bytes in the order sent, so the ADS1115 sees the register address first,
 * then the high byte, then the low byte.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);  /* ADS1115 expects MSB first */
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData sends the register address, then reads 2 bytes.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* ADS1115 sends MSB first */
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success, -1 on I2C error.
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    uint16_t config;
    uint16_t conversion;
    int ret;

    /* Write config: single-shot, AIN0 single-ended, PGA ±4.096V, 128 SPS */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_SINGLE_AIN0) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Poll OS bit (bit 15) until it reads 1 (conversion complete) */
    for (int i = 0; i < 10; i++) {
        ret = ads1115_read_reg(handle, ADS1115_REG_CONFIG, &config);
        if (ret < 0)
            return -1;
        if (config & 0x8000)
            break;
        gpioDelay(1000);  /* 1 ms */
    }
    if (!(config & 0x8000)) {
        fprintf(stderr, "Error: ADS1115 conversion timeout\n");
        return -1;
    }

    /* Read conversion result */
    ret = ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conversion);
    if (ret < 0)
        return -1;

    *raw_out = (int16_t)conversion;
    return 0;
}

/*
 * Convert raw ADC value to current in amperes.
 * raw is signed 16-bit; PGA ±4.096V -> 1 bit = 125 µV.
 */
static float raw_to_current(int16_t raw)
{
    float voltage = (float)raw * ADS1115_PGA_4_096V / 32768.0f;
    return (voltage - MLX91219_OFFSET) / MLX91219_SENSITIVITY;
}

int main(void)
{
    int16_t raw;
    float current;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Check wiring: SDA=GPIO2, SCL=GPIO3, ADDR=GND\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current sensor reader started. Press Ctrl+C to exit.\n");
    printf("Sensor: MLX91219 | ADS1115 @ 0x%02X | AIN0 | PGA ±4.096V | SPS 128\n", ADS1115_ADDR);

    while (g_running) {
        if (ads1115_read_ain0(g_i2c_handle, &raw) == 0) {
            current = raw_to_current(raw);
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Warning: failed to read current, continuing...\n");
        }
        gpioDelay(500000);  /* 500 ms */
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

