#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(int pin) {
    return gpioRead(pin);
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_temperature(int adc_value) {
    return 10.0f + (float)adc_value * (40.0f - 10.0f) / 1023.0f;
}

static int log_data(FILE *fp, int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_PIN);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int adc_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = calculate_temperature(adc_value);

        if (log_data(log_file, flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

