#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO       27
#define I2C_BUS           1
#define ADS1115_ADDR      0x48
#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CFG   0x01
#define ADS1115_CFG_OS    0x8000
#define ADS1115_CFG_MUX_A0 0x4000
#define ADS1115_CFG_PGA_4_096V 0x0200
#define ADS1115_CFG_MODE_SINGLE 0x0100
#define ADS1115_CFG_DR_128SPS 0x0080
#define ADS1115_PGA_4_096V 4.096
#define ADS1115_MAX_COUNT 32767.0
#define TEMP_THRESHOLD    60.0
#define DEBOUNCE_MS       50
#define POLL_MS           100
#define BUZZER_MS         2000
#define LOG_FILE          "fire_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event_flag = 0;
static volatile uint32_t last_flame_tick = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        uint32_t elapsed = tick - last_flame_tick;
        if (elapsed >= DEBOUNCE_MS * 1000) {
            last_flame_tick = tick;
            flame_event_flag = 1;
        }
    }
}

static int read_ads1115(int handle, double *voltage) {
    char cfg[3];
    cfg[0] = ADS1115_REG_CFG;
    cfg[1] = (ADS1115_CFG_OS | ADS1115_CFG_MUX_A0 | ADS1115_CFG_PGA_4_096V |
              ADS1115_CFG_MODE_SINGLE | ADS1115_CFG_DR_128SPS) >> 8;
    cfg[2] = (ADS1115_CFG_OS | ADS1115_CFG_MUX_A0 | ADS1115_CFG_PGA_4_096V |
              ADS1115_CFG_MODE_SINGLE | ADS1115_CFG_DR_128SPS) & 0xFF;
    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config\n");
        return -1;
    }
    gpioDelay(10000);
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register\n");
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion\n");
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *voltage = (raw * ADS1115_PGA_4_096V) / ADS1115_MAX_COUNT;
    return 0;
}

static double voltage_to_temperature(double v) {
    if (v < 0.0) v = 0.0;
    if (v > 3.3) v = 3.3;
    return 20.0 + (v / 3.3) * 60.0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_file);
    }
}

static void sound_buzzer(int duration_ms) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(BUZZER_GPIO, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set flame sensor pull-up\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0,
                         flame_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for flame sensor\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        cleanup();
        return 1;
    }
    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    while (running) {
        if (flame_event_flag) {
            flame_event_flag = 0;
            int flame = gpioRead(FLAME_SENSOR_GPIO);
            double voltage = 0.0;
            int adc_ok = (read_ads1115(i2c_handle, &voltage) == 0);
            double temp = voltage_to_temperature(voltage);
            char msg[128];
            if (adc_ok && temp > TEMP_THRESHOLD) {
                snprintf(msg, sizeof(msg),
                         "Flame and temperature exceeded threshold: %.2f C", temp);
                log_event(msg);
                sound_buzzer(BUZZER_MS);
            } else if (adc_ok) {
                snprintf(msg, sizeof(msg),
                         "Temperature: %.2f C", temp);
                log_event(msg);
            } else {
                snprintf(msg, sizeof(msg),
                         "ADC read failed or sensor absent");
                log_event(msg);
            }
            if (flame == 0) {
                log_event("Flame detected!");
            }
        }
        gpioDelay(POLL_MS * 1000);
    }
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioWrite(BUZZER_GPIO, 0);
    cleanup();
    return 0;
}

