#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP_NAME  "gpiochip4"
#define FAN_GPIO_LINE   18
#define LOG_FILE        "current_log.txt"
#define DEFAULT_SENSITIVITY 0.100f  /* 100 mV/A */
#define DEFAULT_THRESHOLD   5.0f    /* A */
#define SAMPLE_INTERVAL_US  1000000 /* 1 second */
#define ADC_MAX_VALUE       1023
#define ADC_VREF            3.3f

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_fan   = NULL;

static float g_sensitivity = DEFAULT_SENSITIVITY;
static float g_threshold   = DEFAULT_THRESHOLD;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint32_t speed = 1000000;
    uint8_t  bits  = 8;
    uint8_t  mode  = SPI_MODE_0;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_label(GPIO_CHIP_NAME);
    }
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_number(0);
    }
    if (!g_chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    g_fan = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_fan, "mlx91219-fan", 0) < 0) {
        perror("gpiod_line_request_output");
        g_fan = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    return 0;
}

static int read_adc(uint16_t *value)
{
    if (g_spi_fd < 0)
        return -1;

    uint8_t tx[3] = { 0x01, 0x80, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    *value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static float adc_to_current(uint16_t adc)
{
    float voltage = (float)adc * ADC_VREF / (float)(ADC_MAX_VALUE + 1);
    return voltage / g_sensitivity;
}

static int log_data(float current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.3f A\n", ts, current);
    } else {
        fprintf(fp, "(unknown-time), Current: %.3f A\n", current);
    }

    fclose(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_fan) {
        gpiod_line_set_value(g_fan, 0);
        gpiod_line_release(g_fan);
        g_fan = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(int argc, char *argv[])
{
