#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/*
 * Calibration constants for the SGX Sensortech / Honeywell MICS-4514
 * CO sensor. Replace with your calibrated values.
 */
#define R0_CO 10000.0f
#define R_LOAD_CO 10000.0f
#define VREF 3.3f
#define ADC_MAX 32767.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Simulate a 16-bit ADC reading from the MICS-4514.
 * Returns a 16-bit value (0-65535) representing the raw resistance.
 */
static int simulate_adc_read(void) {
    return (rand() % 65536);
}

/*
 * Convert raw ADC value to CO concentration in PPM using a calibrated
 * logarithmic curve. Returns -1.0f on error.
 */
static float calculate_co_ppm(int raw_adc) {
    if (raw_adc < 0 || raw_adc > 65535) {
        return -1.0f;
    }

    float adc_value = (float)raw_adc;
    float voltage = (adc_value / ADC_MAX) * VREF;

    if (voltage <= 0.0f) {
        return -1.0f;
    }

    float resistance = R_LOAD_CO * (VREF / voltage - 1.0f);

    if (resistance <= 0.0f) {
        return -1.0f;
    }

    float log_ratio = log10f(resistance / R0_CO);
    float co_ppm = powf(10.0f, -log_ratio);

    if (co_ppm < 0.0f) {
        return -1.0f;
    }

    return co_ppm;
}

static int log_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = simulate_adc_read();
        float co_ppm = calculate_co_ppm(raw_adc);

        if (co_ppm < 0.0f) {
            fprintf(stderr, "Error: Invalid sensor reading (raw ADC: %d)\n", raw_adc);
        } else {
            if (log_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            printf("CO: %.2f PPM\n", co_ppm);
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

