#define I2C_ADDR_2 0x49
#define AVG_REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY_DBV_PA -38.0
#define REFERENCE_PRESSURE_PA 20e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

double read_sound_pressure(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, AVG_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading I2C block data: %d\n", result);
        return ERROR_VALUE;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    double pressure_pa = (double)raw * 1e-6;
    double sound_pressure_db = SENSITIVITY_DBV_PA + (pressure_pa - REFERENCE_PRESSURE_PA) * 100.0;
    return sound_pressure_db;
}

double calculate_average(double v1, double v2) {
    if (v1 == ERROR_VALUE || v2 == ERROR_VALUE) {
        return ERROR_VALUE;
    }
    return (v1 + v2) / 2.0;
}

void log_data(double avg_db) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file!\n");
