    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, I2C_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, I2C_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Acoustic Leak Detection System started. Press Ctrl+C to exit.\n");

    while (running) {
        double v1 = read_sound_pressure(i2c_handle_1);
        double v2 = read_sound_pressure(i2c_handle_2);
        double avg = calculate_average(v1, v2);
        log_data(avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

