#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define SAMPLE_WINDOW_MS 100
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / 1000)
#define RMS_THRESHOLD 0.7
#define LED_ON_DURATION_US 500000 // 500 ms

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen("audio_events.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open audio_events.csv for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Allocate memory for samples
    int *mic1_samples = (int *)malloc(NUM_SAMPLES * sizeof(int));
    int *mic2_samples = (int *)malloc(NUM_SAMPLES * sizeof(int));
    if (mic1_samples == NULL || mic2_samples == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read samples from both microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_mcp3008(0); // Mic1 on CH0
            mic2_samples[i] = read_mcp3008(1); // Mic2 on CH1

            if (mic1_samples[i] < 0 || mic2_samples[i] < 0) {
                fprintf(stderr, "Error: Failed to read ADC samples\n");
                program_running = 0;
                break;
            }

            gpioDelay(SAMPLE_INTERVAL_US); // 1 ms delay
        }

        if (!program_running) break;

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Check if threshold is exceeded
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_GPIO, 1); // Turn on LED
