#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0 // Amperes
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: Single-shot, AIN0, +/-4.096V, 128 SPS, Disable comparator
#define ADS1115_CONFIG_BASE 0x8000 // OS bit
#define ADS1115_CONFIG_MUX_A0 0x4000 // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // PGA = 4.096V
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // Disable comparator

#define ADS1115_CONFIG_VALUE (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

// Global variables
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void check_threshold(float average_current);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char read_buf[2];

    // Write config to start a single conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_VALUE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_VALUE & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write config to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (~8ms for 128 SPS)
    gpioDelay(10000);

    // Read conversion register
    if (i2cWriteDevice(i2c_handle, (char *)&ADS1115_REG_CONVERSION, 1) != 0) {
        fprintf(stderr, "Failed to set read pointer\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data\n");
        return -1;
    }

    *raw_value = (int16_t)((read_buf[0] << 8) | read_buf[1]);
    return 0;
}

// Function to convert raw ADC value to current (Amperes)
float convert_to_current(int16_t raw_value) {
    // MLX91204: 0.5V to 4.5V maps to 0-100A
    // Assuming 5V supply, 16-bit signed ADC, PGA = 4.096V
    // Raw value range: -32768 to 32767
    // 0.5V = 0 counts, 4.5V = 32767 counts
    // 100A = 32767 counts
    // 0A = -32768 counts
    // Current = (raw - min_raw) / (max_raw - min_raw) * (max_current - min_current) + min_current
    const float min_raw = -32768.0;
    const float max_raw = 32767.0;
    const float min_current = 0.0;
    const float max_current = 100.0;
    const float v_supply = 5.0;
    const float pga_range = 4.096;

    float voltage = (raw_value / 32767.0) * pga_range;
    float current = (voltage - 0.5) / (4.5 - 0.5) * (max_current - min_current) + min_current;
    return current;
}

// Function to add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to check if the average current exceeds the threshold
void check_threshold(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize circular buffer
    CircularBuffer current_buffer = {0};

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting current monitoring...\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(&current_buffer, current);
            float average_current = calculate_average(&current_buffer);
            check_threshold(average_current);
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

