#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define I2C_BUS 1
#define LOG_FILE "color_log.csv"
#define MAX_CONSECUTIVE_ERRORS 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(reg | TCS34725_COMMAND_BIT), (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char cmd = (char)(reg | TCS34725_COMMAND_BIT);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    char cmd = (char)(reg | TCS34725_COMMAND_BIT);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read 16-bit from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint16_t)(((uint8_t)data[1] << 8) | (uint8_t)data[0]);
    return 0;
}

static int sensor_init(int handle) {
    uint8_t id;
    if (i2c_read_reg(handle, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error: Failed to read ID register\n");
        return -1;
    }
    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Error: Unexpected ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg(handle, TCS34725_ATIME, 0xFF) != 0) return -1;
    if (i2c_write_reg(handle, TCS34725_CONTROL, 0x01) != 0) return -1;
    if (i2c_write_reg(handle, TCS34725_ENABLE, 0x03) != 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, TCS34725_CDATA, clear) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, red) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, green) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, blue) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

