        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(g_log_file);
    }

    int consecutive_errors = 0;
    while (g_running) {
        uint16_t clear, red, green, blue;
        if (read_color_data(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
            log_data(g_log_file, clear, red, green, blue);
        } else {
            consecutive_errors++;
