#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_kPa)
{
    char reg = (char)PRESSURE_REG;
    char buf[2];
    int  rc;

    rc = i2cWriteDevice(g_i2c_handle, &reg, 1);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: pigpio error %d\n",
                PRESSURE_REG, rc);
        return -1;
    }

    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: pigpio error %d\n",
                PRESSURE_REG, rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Short read on register 0x%02X: got %d bytes, expected 2\n",
                PRESSURE_REG, rc);
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *pressure_kPa = ((float)raw / 65535.0f) * 500.0f;
    return 0;
}

static int log_data(float pressure_kPa)
{
    time_t now;
    struct tm tm_utc;
    char timestamp[32];

    time(&now);
    gmtime_r(&now, &tm_utc);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
        fprintf(stderr, "Error writing CSV header\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_log_file);

    printf("Logging pressure to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        float pressure_kPa;
        int   retries = 0;
        int   success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_pressure(&pressure_kPa) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying (%d/%d)...\n", retries, MAX_RETRIES);
                time_sleep(0.1);
            }
        }

        if (success) {
            if (log_data(pressure_kPa) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries; skipping sample\n",
                    MAX_RETRIES);
        }

        if (g_running) {
            time_sleep(SAMPLE_PERIOD);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

