#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0
#define MAX_RETRIES 3

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: single-shot, AIN0 vs GND, 128 SPS, gain 2/3 (FSR ±6.144V) */
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_6144 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_6144 | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128)

#define VREF 6.144
#define ADC_MAX 32767.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: ADS1115 config write failed\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error: ADS1115 register select failed\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: ADS1115 conversion read failed\n");
        return -1;
    }
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_ads1115_voltage(int handle, double *voltage) {
    int16_t raw;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ads1115_write_config(handle, ADS1115_CONFIG) != 0) {
            gpioDelay(10000);
            continue;
        }
        gpioDelay(10000); /* 10 ms for 128 SPS conversion */
        if (ads1115_read_conversion(handle, &raw) == 0) {
            *voltage = (double)raw * VREF / ADC_MAX;
            return 0;
        }
        gpioDelay(10000);
    }
    fprintf(stderr, "Error: ADS1115 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static double voltage_to_pressure(double voltage) {
    return (voltage / 5.0) * 400.0;
}

static double voltage_to_temperature(double voltage) {
    return (voltage / 2.0) * 100.0;
}

static void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: GPIO17 setMode failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

