#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended CH0 */
#define ADC_MAX          1023       /* 10-bit ADC */
#define VREF             3.3        /* MCP3008 Vref */
#define SENSOR_ZERO_V    1.65       /* MLX91209 midpoint at Vcc/2 */
#define SENSOR_SENS_V    0.066      /* 66 mV/A */
#define OVERCURRENT_THRESHOLD 10.0  /* Amperes */
#define SAFETY_GPIO      27         /* GPIO27 for motor shutdown */
#define LOG_FILE         "current_log.txt"
#define SAMPLE_US        100000     /* 100 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer cleanup to main()             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.     */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (clock out low bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in low nibble
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to current (A)                                   */
/* ------------------------------------------------------------------ */
static double adc_to_current(int adc_value)
{
    double voltage = (double)adc_value * VREF / (double)(ADC_MAX + 1);
    return (voltage - SENSOR_ZERO_V) / SENSOR_SENS_V;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                        */
/* ------------------------------------------------------------------ */
static void log_reading(double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open; cannot log reading.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Overcurrent safety monitor                                          */
/* ------------------------------------------------------------------ */
static void check_overcurrent(double current)
{
    if (current > OVERCURRENT_THRESHOLD) {
        fprintf(stderr, "OVERCURRENT DETECTED: %.2f A > %.1f A\n",
                current, OVERCURRENT_THRESHOLD);
        if (log_file) {
            fprintf(log_file, "OVERCURRENT DETECTED: %.2f A > %.1f A\n",
                    current, OVERCURRENT_THRESHOLD);
            fflush(log_file);
        }
        gpioWrite(SAFETY_GPIO, 1);   /* Assert motor shutdown */
    } else {
        gpioWrite(SAFETY_GPIO, 0);   /* Deassert */
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SAFETY_GPIO, 0);   /* Ensure shutdown is off */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure safety GPIO */
    if (gpioSetMode(SAFETY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", SAFETY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SAFETY_GPIO, 0);   /* Start de-asserted */

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Motor current monitoring started.\n");
    fprintf(stderr, "  SPI0 CE0 @ %d Hz, ADC channel %d\n", SPI_SPEED, ADC_CHANNEL);
    fprintf(stderr, "  Overcurrent threshold: %.1f A\n", OVERCURRENT_THRESHOLD);
    fprintf(stderr, "  Safety GPIO: GPIO%d (active HIGH)\n", SAFETY_GPIO);
    fprintf(stderr, "  Log file: %s\n", LOG_FILE);
    fprintf(stderr, "Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping sample.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = adc_to_current(adc_value);
        log_reading(current);
        check_overcurrent(current);

        gpioDelay(SAMPLE_US);   /* 100 ms */
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

