#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define ALARM_GPIO 4
#define VOLTAGE_THRESHOLD 2.5
#define VREF 3.3
#define LOG_FILE "co_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static int spi_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    if (!error_log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid ADC channel requested");
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        log_error("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_alarm(int state) {
    if (gpioWrite(ALARM_GPIO, state) != 0) {
        log_error("Failed to write alarm GPIO");
    }
}

static void log_data(float voltage) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("Failed to open error log file");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set alarm GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        log_error("Failed to open SPI channel");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            control_alarm(0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (adc_value / 1023.0f) * VREF;

        if (voltage > VOLTAGE_THRESHOLD) {
            control_alarm(1);
        } else {
            control_alarm(0);
        }

        log_data(voltage);
        gpioDelay(SAMPLE_INTERVAL_US);
