    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            control_alarm(0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (adc_value / 1023.0f) * VREF;

        if (voltage > VOLTAGE_THRESHOLD) {
            control_alarm(1);
