#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000 // Start single conversion, AIN0, +/-4.096V, 128SPS
#define ADS1115_MV_PER_BIT 0.0001875 // 1 bit = 187.5 uV
#define ADS1115_MAX_COUNT 32767.0 // 16-bit signed max
#define VREF 4.096
#define SENSOR_OFFSET_V 0.5
#define SENSOR_SENSITIVITY_V_PER_KPA 0.1
#define MIN_PRESSURE_KPA 0.0
#define MAX_PRESSURE_KPA 100.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
double convert_to_pressure(int16_t raw_value);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication with ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char buffer[2];

    // Write config to start single conversion on AIN0
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_BASE & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (~8ms at 128SPS)
    gpioDelay(10000);

    // Read conversion register
    if (i2cWriteByte(i2c_handle, ADS1115_REG_CONVERSION) != 0) {
        fprintf(stderr, "Error setting conversion register pointer\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading conversion data from ADS1115\n");
        return -1;
    }

    *raw_value = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Convert raw ADC value to pressure in kPa
double convert_to_pressure(int16_t raw_value) {
    double voltage = (raw_value / ADS1115_MAX_COUNT) * VREF;
    double pressure = (voltage - SENSOR_OFFSET_V) / SENSOR_SENSITIVITY_V_PER_KPA;
    return pressure;
}

// Log pressure reading with timestamp
int log_pressure(double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            double pressure = convert_to_pressure(raw_value);

            if (pressure >= MIN_PRESSURE_KPA && pressure <= MAX_PRESSURE_KPA) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure.\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading from ADS1115.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

