    float humidity_voltage = (float)humidity_adc / ADC_MAX_VALUE * SUPPLY_VOLTAGE;
    float temperature_voltage = (float)temperature_adc / ADC_MAX_VALUE * SUPPLY_VOLTAGE;

    if (humidity_voltage < 0.0 || humidity_voltage > SUPPLY_VOLTAGE) {
        fprintf(stderr, "Humidity voltage out of range: %.3f V\n", humidity_voltage);
