#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define ADC_CHANNELS 3
#define SENSITIVITY 0.300
#define ZERO_G_VOLTAGE 1.65
#define SUPPLY_VOLTAGE 3.3
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4 (single-ended + channel select)
     * Byte 2: 0x00 (don't care, clocks out low 2 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS\n");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static double adc_to_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * SUPPLY_VOLTAGE;
}

static double voltage_to_g(double voltage) {
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

static void log_data(int x, int y, int z, double gx, double gy, double gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f\n",
            timestamp, x, y, z, gx, gy, gz);
    fflush(log_file);
}

static void check_impact(double gx, double gy, double gz) {
    double magnitude = sqrt(gx * gx + gy * gy + gz * gz);
    if (magnitude > IMPACT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,IMPACT DETECTED,%.3f,%.3f,%.3f\n",
                timestamp, gx, gy, gz);
        fflush(log_file);
        printf("IMPACT DETECTED! Magnitude: %.3f g\n", magnitude);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(CS_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADXL335 + MCP3008 Impact Detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_values[ADC_CHANNELS];
        int error = 0;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            int val = read_mcp3008(i);
            if (val < 0) {
                fprintf(stderr, "ADC read error on channel %d\n", i);
                error = 1;
                break;
            }
            adc_values[i] = val;
        }

        if (error) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double vx = adc_to_voltage(adc_values[0]);
        double vy = adc_to_voltage(adc_values[1]);
        double vz = adc_to_voltage(adc_values[2]);

        double gx = voltage_to_g(vx);
        double gy = voltage_to_g(vy);
        double gz = voltage_to_g(vz);

        log_data(adc_values[0], adc_values[1], adc_values[2], gx, gy, gz);
        check_impact(gx, gy, gz);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

