code:
/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO2 (I2C bus 1)
 *   Si1172 SCL -> GPIO3 (I2C bus 1)
 *   Si1172 VDD -> 3.3 V
 *   Si1172 GND -> GND
 *
 * Build: gcc -Wall -o si1172_hr si1172_hr.c -lpigpio -lrt
 * Run:   sudo ./si1172_hr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172 constants (SiLabs Si1172-A30-GMR datasheet) ---- */
#define SI1172_I2C_ADDR        0x49          /* 7-bit I2C address */
#define I2C_BUS                1             /* /dev/i2c-1 on RPi Zero W */

/*
 * Si1172 command register (0xC0).
 * Writes to this register trigger a measurement.
 * The actual command byte depends on the specific command opcode.
 * For this example we use 0x00 as a placeholder; the Si1172-A30-GMR
 * requires proprietary command sequences to start HR/SpO2 measurements.
 */
#define SI1172_CMD_REG         0xC0
#define SI1172_CMD_START_MEAS  0x00          /* placeholder for a real command */

/*
 * FIFO data registers (0xC1-0xC4).
 * The Si1172-A30-GMR outputs photoplethysmography (IR and RED) samples
 * in a FIFO buffer.  We proxy the raw IR and RED values as HR and SpO2
 * respectively, since the Si1172-A30-GMR does not have a built-in HR/SpO2
 * algorithm.  A real implementation would decode the FIFO data stream
 * using the Si1172 HR/SpO2 algorithm (SILABS_HR_SpO2_Algorithm.c).
 */
#define SI1172_FIFO_DATA0      0xC1
#define SI1172_FIFO_DATA1      0xC2
#define SI1172_FIFO_DATA2      0xC3
#define SI1172_FIFO_DATA3      0xC4

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly */
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register                             */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1172 register                            */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from a Si1172 register              */
/* ------------------------------------------------------------------ */
static int si1172_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns the word as (high_byte << 8) | low_byte */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    /*
     * A real Si1172 application would send a sequence of commands
     * to configure the sensor for HR/SpO2 measurement.  The exact
     * sequence depends on the specific Si1172 variant and the
     * application's requirements.  This example uses a placeholder
     * command to start a measurement.
     */
    if (si1172_write_reg(handle, SI1172_CMD_REG, SI1172_CMD_START_MEAS) < 0) {
        fprintf(stderr, "[ERROR] Failed to initialize Si1172 (sensor may be absent or unresponsive)\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read HR, SpO2, and error flags from the Si1172                       */
/* ------------------------------------------------------------------ */
static void read_si1172_data(int handle, int *hr, int *spo2, int *error)
{
    uint16_t ir_raw   = 0;
    uint16_t red_raw  = 0;

    /*
     * Proxy: read raw IR and RED ADC values from the FIFO.
     * The Si1172-A30-GMR does not have a built-in HR/SpO2 algorithm.
     * We proxy the FIFO data as HR (IR) and SpO2 (RED).
     */
    if (si1172_read_word(handle, SI1172_FIFO_DATA0, &ir_raw) < 0) {
        *hr    = 0;
        *spo2  = 0;
        *error = 1;          /* I2C read error */
        return;
    }
    if (si1172_read_word(handle, SI1172_FIFO_DATA1, &red_raw) < 0) {
        *hr    = 0;
        *spo2  = 0;
        *error = 1;
        return;
    }

    /*
     * Proxy: use the raw IR and RED values as proxy for HR and SpO2.
     * A real implementation would decode the FIFO stream using the
     * Si1172 HR/SpO2 algorithm (SILABS_HR_SpO2_Algorithm.c).
     */
    *hr    = (int)ir_raw;
    *spo2  = (int)red_raw;
    *error = 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                     */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int hr, int spo2, int error)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return;
    }
    fprintf(fp, "%ld,%d,%d,%d\n", (long)now, hr, spo2, error);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 address */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1172_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1172 sensor */
    if (si1172_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed (sensor may be absent or unresponsive)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(\"biometric_log.csv\")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Si1172 HR/SpO2 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int hr    = 0;
        int spo2  = 0;
        int error = 0;

        read_si1172_data(g_i2c_handle, &hr, &spo2, &error);

        log_data(g_log_file, hr, spo2, error);

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

