#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define VREF 3.3
#define FLOW_RATE_MAX 5.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double adc_to_flow_rate(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    double voltage = (adc_value / (double)ADC_MAX_VALUE) * VREF;
    double flow_rate = (voltage / VREF) * FLOW_RATE_MAX;

    if (flow_rate < 0.0 || flow_rate > FLOW_RATE_MAX) {
        fprintf(stderr, "Error: Flow rate out of plausible range: %.2f L/min\n", flow_rate);
        return -1.0;
    }

    return flow_rate;
}

static int log_data(double flow_rate) {
    struct timeval tv;
    struct tm tm_info;
    char timestamp[40];

    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "Error: gettimeofday failed\n");
        return -1;
    }

    localtime_r(&tv.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, (long)tv.tv_usec, flow_rate) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("Oxygen Concentrator Monitoring System started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: Sensor absent or bus error (ADC at rail: %d)\n", adc_value);
        } else {
            double flow_rate = adc_to_flow_rate(adc_value);
            if (flow_rate < 0.0) {
                fprintf(stderr, "Error: Failed to convert ADC to flow rate\n");
            } else {
                if (log_data(flow_rate) != 0) {
                    fprintf(stderr, "Error: Failed to log data\n");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Oxygen Concentrator Monitoring System stopped.\n");
    return EXIT_SUCCESS;
}

