#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x67
#define MEASURE_CMD 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (cmd >> 8) & 0xFF, cmd & 0xFF };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int16_t raw_pressure, raw_temperature;
    uint8_t crc;

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;

    // Wait for conversion (high-precision mode takes ~10ms)
    usleep(15000);

    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    // CRC check (simplified: XOR of all bytes)
    crc = data[0] ^ data[1] ^ data[2] ^ data[3] ^ data[4];
    if (crc != data[5]) {
        fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n", crc, data[5]);
        return -1;
    }

    raw_pressure = (data[0] << 8) | data[1];
    raw_temperature = (data[2] << 8) | data[3];

    // Calibration formulas from ICP-10125 datasheet
    *pressure = (float)raw_pressure * 1.0f;
    *temperature = (float)raw_temperature * 0.1f;

    return 0;
}

void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(fp);
}

void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    float temperature, pressure;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nCleanup complete. Exiting.\n");
    return 0;
}

