        return -1;
    }

    char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
}

int main(int argc, char *argv[]) {
    float gain = 1.0;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0) {
            fprintf(stderr, "Error: Gain must be a positive number.\n");
            return 1;
        }
