            fprintf(stderr, "Error: Failed to read MCP3008 channel(s).\n");
            break;
        }

        int diff = mic1_val - mic2_val;
        int output = (int)(diff * gain);

        printf("%d,%d,%d\n", mic1_val, mic2_val, output);
