#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define BUZZER_GPIO 18
#define GPIO_CHIP "gpiochip4"

#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

#define DEFAULT_TEMP 25.0
#define VOLTAGE_THRESHOLD 1.0
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_temperature(double *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        *temp = DEFAULT_TEMP;
        return -1;
    }
    if (fscanf(fp, "%lf", temp) != 1) {
        fprintf(stderr, "Warning: invalid temperature in %s\n", TEMP_FILE);
        *temp = DEFAULT_TEMP;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4 | 0x80),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static double compensate_voltage(int adc_value, double temperature) {
    double voltage = (adc_value * 3.3) / 1023.0;
    return voltage + (temperature - 25.0) * 0.001;
}

static void log_data(int adc_value, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n",
            timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    double temperature = DEFAULT_TEMP;
    int adc_value, retries;
    double voltage, compensated_voltage;
    int flame_detected;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        fclose(log_file);
        return 1;
    }

    unsigned int mode = SPI_MODE;
    unsigned int bits = SPI_BITS;
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO line %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Warning: using default temperature %.2f°C\n", DEFAULT_TEMP);
        }

        flame_detected = 0;
        retries = 0;
        do {
            if (read_mcp3008(0, &adc_value) != 0) {
                fprintf(stderr, "Error: SPI read failed, retrying...\n");
                gpiod_line_set_value(buzzer_line, 0);
                break;
            }
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "Error: ADC value out of range (%d), retrying...\n", adc_value);
                retries++;
                usleep(10000);
                continue;
            }
            voltage = (adc_value * 3.3) / 1023.0;
            compensated_voltage = compensate_voltage(adc_value, temperature);
            if (compensated_voltage > VOLTAGE_THRESHOLD) {
                flame_detected = 1;
            }
            break;
        } while (retries < MAX_RETRIES && program_running);

        if (program_running) {
            if (gpiod_line_set_value(buzzer_line, flame_detected) < 0) {
                fprintf(stderr, "Error: failed to set buzzer GPIO: %s\n", strerror(errno));
            }
            log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

