#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define WATER_LEVEL_CHANNEL 0
#define HIGH_THRESHOLD 75.0
#define LOW_THRESHOLD 70.0
#define SAMPLE_INTERVAL_US 5000000
#define SPI_XFER_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < SPI_XFER_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, SPI_XFER_RETRIES, pigpio_error(ret));
        gpioDelay(10000);
    }
    return -1;
}

static double calculate_water_level(int adc_value) {
    return (double)adc_value / 1023.0 * 100.0;
}

static void log_to_json(double water_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(json_fp, "  {\"timestamp\": \"%s\", \"water_level\": %.2f}\n",
            timestamp, water_level);
    fflush(json_fp);
}

static void control_led(double water_level) {
    if (water_level > HIGH_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else if (water_level < LOW_THRESHOLD) {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (json_fp) {
        fprintf(json_fp, "]\n");
        fclose(json_fp);
        json_fp = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    json_fp = fopen("water_levels.json", "a");
    if (!json_fp) {
        perror("Failed to open water_levels.json");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(json_fp, 0, SEEK_END);
    long fsize = ftell(json_fp);
    if (fsize == 0) {
        fprintf(json_fp, "[\n");
        fflush(json_fp);
    } else if (fsize > 0 && fsize < 3) {
        fprintf(stderr, "JSON file truncated or not a JSON array\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(WATER_LEVEL_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            double water_level = calculate_water_level(adc_value);
            log_to_json(water_level);
            control_led(water_level);
            printf("Water Level: %.2f%%\n", water_level);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

