#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300
#define SAMPLE_INTERVAL 5

static int spi_fd = -1;

void cleanup(int signum) {
    (void)signum;
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    exit(0);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
