    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Failed to set SPI speed: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    printf("Soil Moisture Sensor Reading (MCP3008 CH0)\n");
    printf("Dry ADC: %d, Wet ADC: %d\n", DRY_ADC_VALUE, WET_ADC_VALUE);
    printf("Press Ctrl+C to exit.\n\n");

    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
