#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel 0
#define VREF 3.3            // Reference voltage for ADC
#define MIN_PRESSURE 0.5    // Minimum pressure in kPa (0.1 bar)
#define MAX_PRESSURE 150.0  // Maximum pressure in kPa (1.5 bar)
#define MIN_VOLTAGE 0.5     // Minimum voltage for valid reading
#define MAX_VOLTAGE 4.5     // Maximum voltage for valid reading
#define SAMPLE_INTERVAL 1   // Seconds between readings

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double voltage_to_pressure(double voltage);
void log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, (char *)spi_tx_buf, (char *)spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | spi_rx_buf[2];
    return adc_value;
}

// Convert voltage to pressure (kPa)
double voltage_to_pressure(double voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage %.3fV out of valid range [%.1fV, %.1fV]\n", voltage, MIN_VOLTAGE, MAX_VOLTAGE);
        return -1.0; // Indicate invalid reading
    }
    return (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE) + MIN_PRESSURE;
}

// Log pressure with timestamp
void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    printf("[%s] Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting pressure monitoring...\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value / 1023.0) * VREF;

        // Check for sensor-absent conditions (stuck at 0V or 3.3V)
        if (voltage < 0.01 || voltage > 3.29) {
            fprintf(stderr, "Warning: Sensor absent or disconnected (voltage: %.3fV)\n", voltage);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert voltage to pressure
        double pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Warning: Invalid pressure reading (voltage: %.3fV)\n", voltage);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Log the pressure
        log_pressure(pressure);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

