        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Data Logging (MCP3008 CH%d)\n", MCP3008_CHANNEL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        if (moisture < 0.0f) moisture = 0.0f;
        if (moisture > 100.0f) moisture = 100.0f;

        printf("Moisture: %.2f%% (ADC: %d)\n", moisture, adc_value);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    if (close(spi_fd) < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

