#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define NUM_SENSORS 4
#define VREF 3.3
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }
    usleep(10);

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_voltage(int adc_value) {
    return (adc_value * VREF) / 1023.0;
}

static int log_data(FILE *fp, double v1, double v2, double v3, double v4) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, v1, v2, v3, v4) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI config");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("fopen CSV");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Sensor1,Sensor2,Sensor3,Sensor4\n");
        fflush(fp);
    }

    printf("Starting data acquisition...\n");

    while (running) {
        int adc[NUM_SENSORS];
        int error = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc[i] = read_mcp3008(spi_fd, cs_line, i);
            if (adc[i] < 0) {
                fprintf(stderr, "SPI read error on channel %d\n", i);
                error = 1;
                break;
            }
        }

        if (error) {
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        double v1 = calculate_voltage(adc[0]);
        double v2 = calculate_voltage(adc[1]);
        double v3 = calculate_voltage(adc[2]);
        double v4 = calculate_voltage(adc[3]);

        if (log_data(fp, v1, v2, v3, v4) < 0) {
            perror("log_data");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    fclose(fp);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return EXIT_SUCCESS;
}

