#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_CHANNEL 0
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int spi_handle = -1;
static CircularBuffer log_buffer;
static volatile sig_atomic_t running = 1;

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, time_t ts, int moisture, int pump) {
    cb->entries[cb->head].timestamp = ts;
    cb->entries[cb->head].moisture_level = moisture;
    cb->entries[cb->head].pump_state = pump;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void print_buffer(const CircularBuffer *cb) {
    printf("\n--- Log Buffer (%d entries) ---\n", cb->count);
    int start = (cb->count < BUFFER_SIZE) ? 0 : cb->head;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char tbuf[32];
        struct tm *tm = localtime(&cb->entries[idx].timestamp);
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Moisture: %4d  Pump: %s\n",
               tbuf, cb->entries[idx].moisture_level,
               cb->entries[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
    fflush(stdout);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void timer_callback(void *user) {
    (void)user;
    int moisture = read_mcp3008(MOISTURE_CHANNEL);
    if (moisture < 0) {
        fprintf(stderr, "Error: Failed to read moisture sensor\n");
        return;
    }
    static int pump_state = 0;
    if (moisture < LOW_THRESHOLD && !pump_state) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture=%d < %d)\n", moisture, LOW_THRESHOLD);
        } else {
            fprintf(stderr, "Error: Failed to turn pump ON\n");
        }
    } else if (moisture > HIGH_THRESHOLD && pump_state) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture=%d > %d)\n", moisture, HIGH_THRESHOLD);
        } else {
            fprintf(stderr, "Error: Failed to turn pump OFF\n");
        }
    }
    time_t now = time(NULL);
    add_to_buffer(&log_buffer, now, moisture, pump_state);
    print_buffer(&log_buffer);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    init_circular_buffer(&log_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started.\n");
    printf("  SPI: CE0 @ %d Hz, MCP3008 ch%d, pump GPIO%d\n",
           SPI_SPEED, MOISTURE_CHANNEL, PUMP_GPIO);
    printf("  Low: %d, High: %d, Sample: %.1f s\n",
           LOW_THRESHOLD, HIGH_THRESHOLD, SAMPLE_INTERVAL_US / 1e6);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    cleanup();
    return EXIT_SUCCESS;
}

