#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MAX30102_ADDR 0x57
#define I2C_BUS 1

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVERFLOW_CTR 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100
#define FIFO_DEPTH 32
#define FIFO_DATA_SIZE (FIFO_DEPTH * 6)

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, int len) {
    return i2cReadI2CBlockData(handle, reg, (char *)buf, len);
}

static int init_max30102(int handle) {
    uint8_t part_id;
    if (i2c_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID register\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(handle, REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, REG_INTR_ENABLE_2, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, REG_OVERFLOW_CTR, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_RD_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_CONFIG, 0x0F) < 0) return -1;
    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x03) < 0) return -1;
    if (i2c_write_reg(handle, REG_SPO2_CONFIG, 0x27) < 0) return -1;
    if (i2c_write_reg(handle, REG_LED1_PA, 0x24) < 0) return -1;
    if (i2c_write_reg(handle, REG_LED2_PA, 0x24) < 0) return -1;

    return 0;
}

static int read_fifo_data(int handle, uint8_t *buf, int len) {
    return i2c_read_burst(handle, REG_FIFO_DATA, buf, len);
}

static void log_health_data(int spo2, int heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open health_log.txt for writing\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(fp, "%s, SpO2: %d%%, Heart Rate: %d BPM\n", ts, spo2, heart_rate);
    fclose(fp);
}

static int detect_heart_rate(const uint8_t *ir_data, int num_samples) {
    int peaks = 0;
    int threshold = 100;
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir_data[i] > threshold && ir_data[i-1] < threshold && ir_data[i+1] < threshold) {
            peaks++;
        }
    }
    return peaks * 60 * SAMPLE_RATE_HZ / num_samples;
}

static int calculate_spo2(const uint8_t *red_data, const uint8_t *ir_data, int num_samples) {
    double red_sum = 0, ir_sum = 0;
    for (int i = 0; i < num_samples; i++) {
        red_sum += red_data[i];
        ir_sum += ir_data[i];
    }
    if (ir_sum == 0) return -1;
    double ratio = red_sum / ir_sum;
    int spo2 = (int)(ratio * 100);
    if (spo2 > 100) spo2 = 100;
    return spo2;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
