            continue;
        }

        int num_samples = bytes_read / 6;
        for (int i = 0; i < num_samples; i++) {
            ir_data[i] = red_data[i * 6 + 3];
        }

        int spo2 = calculate_spo2(red_data, ir_data, num_samples);
        int heart_rate = detect_heart_rate(ir_data, num_samples);

        if (spo2 >= 0 && spo2 < SPO2_THRESHOLD) {
            log_health_data(spo2, heart_rate);
        }
        if (heart_rate > HR_THRESHOLD) {
            log_health_data(spo2, heart_rate);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    i2cClose(i2c_handle);
