#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define RELAY_PIN      17
#define REED_PIN       27
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 50
#define POLL_DELAY_MS   200
#define RELAY_ON_MS    3000
#define LOG_FILE       "/var/log/door_events.log"

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS */
#define ADS1115_CFG_BASE 0x8000 | 0x4000 | 0x0100 | 0x0080

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay = NULL;
static struct gpiod_line *g_reed = NULL;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void cleanup(void) {
    if (g_relay) {
        gpiod_line_set_value(g_relay, 0);
        gpiod_line_release(g_relay);
        g_relay = NULL;
    }
    if (g_reed) {
        gpiod_line_release(g_reed);
        g_reed = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_adc(int fd, int16_t *raw) {
    uint16_t cfg = ADS1115_CFG_BASE | 0x0003; /* single-shot, start */
    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) return -1;
    usleep(10000); /* 10 ms conversion */
    uint16_t cfg_read;
    if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg_read) < 0) return -1;
    if (!(cfg_read & 0x8000)) return -1; /* not ready */
    uint16_t raw_u;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw_u) < 0) return -1;
    *raw = (int16_t)raw_u;
    return 0;
}

static int calibrate_threshold(int fd, float *threshold) {
    int16_t samples[NUM_SAMPLES];
    int valid = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        if (read_adc(fd, &samples[i]) < 0) {
            fprintf(stderr, "ADC read error during calibration\n");
            log_event("ADC read error during calibration");
            continue;
        }
        valid++;
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    if (valid == 0) return -1;
    long sum = 0;
    for (int i = 0; i < valid; i++) sum += samples[i];
    *threshold = (float)sum / valid * 0.8f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    g_relay = gpiod_chip_get_line(g_chip, RELAY_PIN);
    g_reed = gpiod_chip_get_line(g_chip, REED_PIN);
    if (!g_relay || !g_reed) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(g_relay, "door_relay", 0) < 0 ||
        gpiod_line_request_input(g_reed, "door_reed") < 0) {
        perror("gpiod_line_request");
        cleanup();
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c");
        cleanup();
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    float threshold;
    if (calibrate_threshold(g_i2c_fd, &threshold) < 0) {
        fprintf(stderr, "Calibration failed\n");
        log_event("Calibration failed");
        cleanup();
        return 1;
    }
    printf("Threshold: %.2f\n", threshold);

    while (g_running) {
        int16_t raw;
        if (read_adc(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error\n");
            log_event("ADC read error");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        if ((float)raw < threshold) {
            printf("Proximity detected! Releasing door lock.\n");
            log_event("Proximity detected, releasing door lock");
            if (gpiod_line_set_value(g_relay, 1) < 0) {
                perror("relay on");
                log_event("Relay on failed");
            }
            usleep(RELAY_ON_MS * 1000);
            if (gpiod_line_set_value(g_relay, 0) < 0) {
                perror("relay off");
                log_event("Relay off failed");
            }
            int reed = gpiod_line_get_value(g_reed);
            if (reed < 0) {
                perror("reed read");
                log_event("Reed sensor read failed");
            } else {
                printf("Reed sensor: %s\n", reed == 0 ? "opened" : "closed");
                log_event(reed == 0 ? "Door opened" : "Door not opened");
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

