    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, cs_pins[i]);
        if (cs_lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", cs_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(cs_lines[i], "mcp3008_cs", 1) < 0) {
            fprintf(stderr, "Failed to request CS line %d as output: %s\n", cs_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

    while (program_running) {
        int sensor1 = read_mcp3008(spi_fd, cs_lines[0], ADC_CHANNEL);
        int sensor2 = read_mcp3008(spi_fd, cs_lines[1], ADC_CHANNEL);
        int sensor3 = read_mcp3008(spi_fd, cs_lines[2], ADC_CHANNEL);

        if (log_data(fp, sensor1, sensor2, sensor3) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    ret_code = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (cs_lines[i] != NULL) {
            gpiod_line_release(cs_lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret_code;
}

