#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CH0 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60
#define DRY_ADC 200
#define WET_ADC 800
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | rx[2];
            return adc;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, ret);
        log_message("SPI transfer failed");
        gpioDelay(100000);
    }
    return -1;
}

static int read_moisture_percent(void) {
    int adc = read_mcp3008(MCP3008_CH0);
    if (adc < 0) return -1;
    if (adc < DRY_ADC) adc = DRY_ADC;
    if (adc > WET_ADC) adc = WET_ADC;
    int pct = (int)(((float)(adc - DRY_ADC) / (WET_ADC - DRY_ADC)) * 100.0f);
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    return pct;
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d) failed\n", PUMP_GPIO);
        log_message("Failed to write pump GPIO");
        return;
    }
    printf("Pump %s\n", on ? "activated" : "deactivated");
    log_message(on ? "Pump activated" : "Pump deactivated");
}

static void irrigate(int duration) {
    printf("Irrigation started for %d seconds\n", duration);
    log_message("Irrigation started");
    control_pump(1);
    for (int i = 0; i < duration && !terminate; i++) {
        gpioDelay(1000000);
    }
    control_pump(0);
    printf("Irrigation complete\n");
    log_message("Irrigation complete");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration <= 0) {
        fprintf(stderr, "Duration must be positive\n");
        return EXIT_FAILURE;
    }
    if (sleep_interval <= 0) {
        fprintf(stderr, "Sleep interval must be positive\n");
        return EXIT_FAILURE;
    }
    printf("Config: threshold=%d%%, duration=%ds, sleep=%ds\n",
           threshold, duration, sleep_interval);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture irrigation system started. Press Ctrl+C to exit.\n");
    log_message("System started");

    while (!terminate) {
        int moisture = read_moisture_percent();
        if (moisture < 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle\n");
            log_message("Sensor read failed; skipping cycle");
        } else {
            printf("Moisture: %d%%\n", moisture);
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture: %d%%", moisture);
            log_message(msg);
            if (moisture < threshold) {
                irrigate(duration);
            }
        }
        for (int i = 0; i < sleep_interval && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    log_message("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

