#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* Configuration */
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  /* OS bit: start single conversion */
#define ADS1115_CONFIG_MUX_AIN0 0x4000  /* AIN0 single-ended */
#define ADS1115_CONFIG_PGA_4_096V 0x0200  /* PGA = 4.096 V */
#define ADS1115_CONFIG_MODE_SINGLE 0x0100  /* Single-shot mode */
#define ADS1115_CONFIG_DR_128SPS 0x0080  /* 128 SPS */
#define ADS1115_CONFIG_CQUE_NONE 0x0003  /* Disable comparator */
#define MOTOR_GPIO 27
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0f
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define ADC_MAX_COUNT 32767.0f  /* 16-bit signed, positive range */
#define ADC_VREF 4.096f  /* PGA = 4.096 V */
#define VCC 3.3f
#define ZERO_FIELD_VOLTAGE 2.5f  /* SS49E at 0 Gauss */
#define SENSITIVITY_GAUSS_PER_VOLT 0.0014f  /* 1.4 mV/Gauss */

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer */
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Function prototypes */
static int init_pigpio(void);
static int init_i2c(void);
static int read_ads1115(int16_t *raw_out);
static float convert_to_gauss(int16_t raw);
static void update_buffer(float gauss);
static float calculate_average(void);
static void control_motor(float avg_gauss);
static void signal_handler(int sig);
static void cleanup(void);

int main(void) {
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (init_pigpio() != 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialization failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", MOTOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall sensor monitoring started (threshold %.1f Gauss)", THRESHOLD_GAUSS);

    while (!terminate) {
        int16_t raw;
        if (read_ads1115(&raw) != 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = convert_to_gauss(raw);
        if (gauss < 0.0f || gauss > 3.3f) {
            syslog(LOG_ERR, "Invalid voltage reading: %.3f V (raw=%d)", gauss, raw);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        update_buffer(gauss);
        float avg = calculate_average();
        control_motor(avg);

        syslog(LOG_INFO, "Gauss: %.2f, Avg: %.2f Gauss", gauss, avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X: %d", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw_out) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    /* Write config: pointer auto-increment, MSB first */
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config");
        return -1;
    }

    /* Wait for conversion (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion register */
    char reg_buf[1] = { ADS1115_REG_CONVERSION };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        syslog(LOG_ERR, "Failed to set ADS1115 conversion register pointer");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion data");
        return -1;
    }

    *raw_out = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static float convert_to_gauss(int16_t raw) {
    float voltage = ((float)raw / ADC_MAX_COUNT) * ADC_VREF;
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY_GAUSS_PER_VOLT;
    return gauss;
}

static void update_buffer(float gauss) {
    buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += buffer[i];
    return sum / (float)buffer_count;
}

static void control_motor(float avg_gauss) {
    if (avg_gauss > THRESHOLD_GAUSS) {
        syslog(LOG_WARNING, "Threshold exceeded: avg=%.2f Gauss > %.1f Gauss", avg_gauss, THRESHOLD_GAUSS);
        gpioWrite(MOTOR_GPIO, 1);
    } else {
        gpioWrite(MOTOR_GPIO, 0);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(MOTOR_GPIO, 0);
    gpioTerminate();
    closelog();
}

