    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > MAX_ADC_VALUE) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static int log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

static int water_plant(int duration) {
    printf("Watering plant for %d seconds...\n", duration);
    if (control_pump(1) != 0) return -1;

    for (int i = 0; i < duration && running; i++) {
        sleep(1);
    }

    if (control_pump(0) != 0) return -1;
    printf("Watering complete.\n");
    return 0;
}

static int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            moisture_level = read_mcp3008(0);
            if (moisture_level >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) sleep(1);
        }

        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture after %d retries. Pump deactivated.\n", MAX_RETRIES);
            control_pump(0);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            if (water_plant(WATERING_DURATION) != 0) {
                fprintf(stderr, "Error: Pump control encountered an error during watering.\n");
            }
        }

        if (log_event(moisture_level) != 0) {
            fprintf(stderr, "Warning: Failed to log event.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

