#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_ON_US 50000
#define BLINK_OFF_US 50000
#define DEFAULT_THRESHOLD 100.0
#define ADC_MAX 32767.0
#define VREF 4.096
#define SENSITIVITY 0.001

static int i2c_handle = -1;
static double threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_ads1115(int handle, double *voltage) {
    char config[3];
    config[0] = 0x01;
    config[1] = 0xC3;
    config[2] = 0x83;
    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config\n");
        return -1;
    }
    gpioDelay(10000);
    char reg[1] = {0x00};
    if (i2cWriteDevice(handle, reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 pointer\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 data\n");
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    *voltage = (raw / ADC_MAX) * VREF;
    return 0;
}

static double voltage_to_gauss(double voltage) {
    return voltage / SENSITIVITY;
}

static void blink_led(int gpio, int duration_us) {
    gpioWrite(gpio, 1);
    gpioDelay(BLINK_ON_US);
    gpioWrite(gpio, 0);
    gpioDelay(BLINK_OFF_US);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field on ADS1115 AIN0 (I2C 0x%02X). Threshold: %.2f Gauss\n", ADS1115_ADDR, threshold);

    while (!terminate) {
        double voltage;
        if (read_ads1115(i2c_handle, &voltage) != 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        double gauss = voltage_to_gauss(voltage);
        printf("Magnetic Field: %.2f Gauss\n", gauss);
        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for 1 second.\n");
            for (int i = 0; i < 10 && !terminate; i++) {
                blink_led(LED_GPIO, BLINK_DURATION_US);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

