#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_TOPIC "pump_control"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define SAMPLE_INTERVAL_SEC 60
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) return ((rx[1] & 0x03) << 8) | rx[2];
        syslog(LOG_WARNING, "SPI transfer failed (attempt %d/%d): %d", attempt + 1, MAX_SPI_RETRIES, ret);
        usleep(10000);
    }
    syslog(LOG_ERR, "SPI transfer failed after %d retries", MAX_SPI_RETRIES);
    return -1;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "Relay %s", state ? "ON" : "OFF");
    return 0;
}

static void publish_moisture(int moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "{\"moisture\": %d}", moisture);
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture data");
    } else {
        syslog(LOG_INFO, "Published moisture: %d", moisture);
    }
}

static void pump_control_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[16];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        if (strcmp(payload, "pump_on") == 0) {
            control_relay(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_relay(0);
        } else {
            syslog(LOG_WARNING, "Invalid pump control command: %s", payload);
        }
    }
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to broker");
        if (mosquitto_subscribe(m, NULL, MQTT_PUMP_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to pump topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", rc);
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed on channel %d", SPI_CHANNEL);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Mosquitto new failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, pump_control_callback);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pump_state = 0;
    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            syslog(LOG_ERR, "Sensor read failed; skipping cycle");
        } else if (moisture > 1023) {
            syslog(LOG_ERR, "Sensor value out of range: %d", moisture);
        } else {
            publish_moisture(moisture);
            if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                control_relay(1);
                pump_state = 1;
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                control_relay(0);
                pump_state = 0;
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down");
    control_relay(0);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

