            double v0 = adc_to_voltage(adc[0]);
            double v1 = adc_to_voltage(adc[1]);
            double v2 = adc_to_voltage(adc[2]);

            if (log_data(v0, v1, v2) != 0) {
                fprintf(stderr, "Warning: log_data failed\n");
            }
