    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    unsigned int speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI configuration failed");
        cleanup();
        return 1;
    }

    printf("Vibration control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping iteration\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            int duty_cycle = (int)(((float)adc_value / 1023.0f) * PWM_RANGE);
            set_motor_pwm(MOTOR1_PIN, duty_cycle);
            set_motor_pwm(MOTOR2_PIN, duty_cycle);
            log_event(adc_value);
        } else {
            set_motor_pwm(MOTOR1_PIN, 0);
            set_motor_pwm(MOTOR2_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

