#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CONT_HRES2 0x11
#define BH1750_CONV_MS   180

#define SPI_DEVICE     "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define LOG_FILE       "tamper_log.csv"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux) {
    unsigned char cmd = BH1750_CONT_HRES2;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: got %zd bytes (%s)\n", n, strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int mcp3008_read(int fd, int channel) {
