#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define NUM_SENSORS 3
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_adc_to_valve_position(int adc_value) {
    if (adc_value < 0) return 0;
    if (adc_value > 1023) return 100;
    /* Inverse mapping: dry soil (low ADC) -> high opening, wet soil (high ADC) -> low opening */
    return 100 - (int)(((float)adc_value / 1023.0f) * 100.0f);
}

static int set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    int duty = (int)(((float)position / 100.0f) * PWM_RANGE);
    if (gpioPWM(VALVE_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
        return -1;
    }
    return 0;
}

static int log_data(int sensor_readings[], int average_adc, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d, Sensor3: %d, Average: %d, Valve: %d\n",
            timestamp, sensor_readings[0], sensor_readings[1], sensor_readings[2], average_adc, valve_position);
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    int sensor_readings[NUM_SENSORS];
    int average_adc;
    int valve_position;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d (handle=%d)\n", SPI_CHANNEL, spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int valid_readings = 0;
        int sum = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = read_mcp3008(i);
            if (val < 0) {
                fprintf(stderr, "Sensor %d read failed, skipping\n", i);
                sensor_readings[i] = -1;
            } else {
                sensor_readings[i] = val;
                sum += val;
                valid_readings++;
            }
        }

        if (valid_readings == 0) {
            fprintf(stderr, "All sensors failed, skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        average_adc = sum / valid_readings;
        valve_position = map_adc_to_valve_position(average_adc);

        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }

        if (log_data(sensor_readings, average_adc, valve_position) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

