#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0         // Mode 0, active low CS
#define MCP3008_CHANNEL 0   // CH0
#define LOG_FILE "soil_data.txt"
#define READ_INTERVAL 5     // Seconds
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 1000000 // 1 second in microseconds

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void log_data(float moisture_level);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended mode + channel selection)
    // Byte 2: 0x00 (Don't care)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits in its lower 2 bits
    // rx_buf[2] contains the 8 least significant bits
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | spi_rx_buf[2];

    // Validate ADC value range (10-bit ADC: 0-1023)
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    // Example linear conversion (adjust based on sensor calibration)
    // Assuming dry soil = 0 ADC, wet soil = 1023 ADC
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to file
void log_data(float moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Moisture: %.2f%%\n", timestamp, moisture_level);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        int delay_us = RETRY_DELAY_BASE;

        // Retry loop with exponential backoff
        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break; // Success
            }

            fprintf(stderr, "Warning: SPI read failed (attempt %d/%d), retrying in %d us...\n",
                    retries + 1, MAX_RETRIES, delay_us);
            gpioDelay(delay_us);
            delay_us *= 2; // Exponential backoff
            retries++;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries, skipping reading.\n", MAX_RETRIES);
        } else {
            float moisture_level = convert_to_moisture(adc_value);
            log_data(moisture_level);
            printf("Moisture Level: %.2f%%\n", moisture_level);
        }

        // Wait for the next reading interval, checking for termination
        for (int i = 0; i < READ_INTERVAL && !terminate; i++) {
            gpioDelay(1000000); // 1 second
        }
    }

    // Cleanup
    cleanup();
    fprintf(stderr, "Soil moisture monitoring stopped.\n");

    return 0;
}

