    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) { perror("gpiod_chip_open"); return -1; }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) { perror("gpiod_chip_get_line"); return -1; }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0 ||
        gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("gpiod_line_request"); return -1;
    }
    return 0;
}

int init_pwm() {
    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0", O_RDWR);
    if (pwm_fd < 0) { perror("open pwm"); return -1; }
    if (write_sysfs("/sys/class/pwm/pwmchip0/pwm0/period", "10000000") < 0 ||
        write_sysfs("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "5000000") < 0 ||
        write_sysfs("/sys/class/pwm/pwmchip0/pwm0/enable", "1") < 0) {
        perror("pwm init"); return -1;
    }
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open spi"); return -1; }
    int mode = SPI_MODE_0;
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("spi config"); return -1;
    }
    return 0;
}

int read_adc(int channel) {
    if (spi_fd < 0) return -1;
    unsigned char tx[3] = {0x01, (0x08 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("spi xfer"); return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int read_distance() {
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1;
    struct timespec t1, t2;
    int val;
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) return -1;
        clock_gettime(CLOCK_MONOTONIC, &t1);
    } while (val == 0);
    do {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) return -1;
        clock_gettime(CLOCK_MONOTONIC, &t2);
        if ((t2.tv_sec - t1.tv_sec) * 1000000 + (t2.tv_nsec - t1.tv_nsec) / 1000 > 30000) return -1;
    } while (val == 1);
    long long diff = (t2.tv_sec - t1.tv_sec) * 1000000 + (t2.tv_nsec - t1.tv_nsec) / 1000;
    return (int)(diff / 58.0);
}

int map_distance(int distance) {
    if (distance < 2) distance = 2;
    if (distance > 400) distance = 400;
    return MIN_FREQUENCY + (distance - 2) * (MAX_FREQUENCY - MIN_FREQUENCY) / 400;
}

int map_adc(int adc) {
    if (adc < min_adc) adc = min_adc;
    if (adc > max_adc) adc = max_adc;
    return MIN_FREQUENCY + (adc - min_adc) * (MAX_FREQUENCY - MIN_FREQUENCY) / (max_adc - min_adc);
}

int set_frequency(int freq) {
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", freq);
    if (write_sysfs("/sys/class/pwm/pwmchip0/pwm0/frequency", buf) < 0) return -1;
    return 0;
}

int set_volume(int adc) {
    int freq = map_adc(adc);
    if (set_frequency(freq) < 0) return -1;
    int duty = (freq - MIN_FREQUENCY) * PWM_DUTY_CYCLE_NS / (MAX_FREQUENCY - MIN_FREQUENCY);
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", duty);
    if (write_sysfs("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", buf) < 0) return -1;
    return 0;
}

int load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) return 0;
    if (fscanf(fp, "%d %d", &min_adc, &max_adc) != 2) {
        fclose(fp); return 0;
    }
    fclose(fp);
    return 0;
}

int save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) return -1;
    fprintf(fp, "%d %d", min_adc, max_adc);
    fclose(fp);
    return 0;
}

void cleanup() {
    if (pwm_fd >= 0) {
        write_sysfs("/sys/class/pwm/pwmchip0/pwm0/enable", "0");
        close(pwm_fd);
    }
    if (spi_fd >= 0) close(spi_fd);
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    signal(SIGINT, signal_handler);
    if (init_gpio() < 0 || init_pwm() < 0 || init_spi() < 0) {
        cleanup(); return 1;
    }
    load_calibration();
    int last_valid_adc = 512;
    while (running) {
        int dist = read_distance();
        if (dist > 0) {
            int freq = map_distance(dist);
            if (set_frequency(freq) < 0) break;
        }
        int adc = read_adc(0);
        if (adc >= 0) {
            if (set_volume(adc) < 0) break;
            last_valid_adc = adc;
        } else {
            set_volume(last_valid_adc);
        }
        usleep(SAMPLE_DELAY_US);
    }
    save_calibration();
    cleanup();
    return 0;
}

