#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define MCP3008_CHANNEL 0
#define PPM_SCALE       0.5f
#define PPM_OFFSET      -10.0f
#define ALCOHOL_THRESHOLD_HIGH 50.0f
#define ALCOHOL_THRESHOLD_LOW  20.0f
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100
#define SAMPLE_INTERVAL_S 1
#define LOG_FILE        "alcohol_log.txt"
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       8  /* GPIO8 = SPI0 CE0 */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((channel << 4) | 0x80), 0x00 };
    uint8_t rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        return 0;
    }

    fprintf(stderr, "Failed to read MCP3008 after %d attempts.\n", MAX_RETRIES);
    return -1;
}

static float adc_to_ppm(int adc_value) {
    return (float)adc_value * PPM_SCALE + PPM_OFFSET;
}

static void log_data(float ppm, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s, PPM: %.2f, Status: %s\n", timestamp, ppm, status);
    fclose(fp);
}

static void check_alcohol_level(float ppm) {
    const char *status;
    if (ppm > ALCOHOL_THRESHOLD_HIGH) {
        status = "Alcohol detected! Limit exceeded.";
    } else if (ppm < ALCOHOL_THRESHOLD_LOW) {
        status = "Sobriety confirmed.";
    } else {
        status = "Alcohol level within acceptable range.";
    }
    log_data(ppm, status);
    printf("PPM: %.2f, Status: %s\n", ppm, status);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device '%s': %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = 0;
        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            float ppm = adc_to_ppm(adc_value);

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor may be absent or disconnected.\n", adc_value);
            }

            check_alcohol_level(ppm);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

