        if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        return 0;
    }

    fprintf(stderr, "Failed to read MCP3008 after %d attempts.\n", MAX_RETRIES);
    return -1;
}

static float adc_to_ppm(int adc_value) {
    return (float)adc_value * PPM_SCALE + PPM_OFFSET;
}

static void log_data(float ppm, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s, PPM: %.2f, Status: %s\n", timestamp, ppm, status);
    fclose(fp);
}

static void check_alcohol_level(float ppm) {
    const char *status;
    if (ppm > ALCOHOL_THRESHOLD_HIGH) {
        status = "Alcohol detected! Limit exceeded.";
    } else if (ppm < ALCOHOL_THRESHOLD_LOW) {
        status = "Sobriety confirmed.";
    } else {
        status = "Alcohol level within acceptable range.";
    }
    log_data(ppm, status);
    printf("PPM: %.2f, Status: %s\n", ppm, status);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device '%s': %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = 0;
        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            float ppm = adc_to_ppm(adc_value);

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor may be absent or disconnected.\n", adc_value);
            }

            check_alcohol_level(ppm);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

