#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// MCP3008 SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0        // Mode 0

// Potentiometer ADC Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed Control
#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCEL_DELAY_MS 2000
#define DECEL_DELAY_MS 2000
#define HOLD_DELAY_MS 2000
#define PAUSE_DELAY_MS 5000

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void accelerate_motor(int motor, int speed_factor);
void decelerate_motor(int motor, int speed_factor);
void hold_motor(int motor, int speed_factor);
void move_motor_forward(int motor, int speed_factor);
void move_motor_backward(int motor, int speed_factor);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: Start bit (1), Single-ended mode (1), Channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor (logarithmic)
int map_speed(int pot_value) {
    if (pot_value <= 0) {
        return 0;
    }
    // Logarithmic mapping: 0.1 to 1.0
    double speed_factor = log10((double)pot_value + 1.0) / log10(1024.0) * 10.0;
    if (speed_factor < 0.1) speed_factor = 0.1;
    if (speed_factor > 10.0) speed_factor = 10.0;
    return (int)(speed_factor * 2.55);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        gpioWrite(MOTOR1_DIRECTION, direction);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_DIRECTION, direction);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to accelerate motor
void accelerate_motor(int motor, int speed_factor) {
    int speed = MIN_SPEED + (int)((double)speed_factor * (MAX_SPEED - MIN_SPEED) / 10.0);
    set_motor_speed(motor, speed);
    gpioDelay(ACCEL_DELAY_MS * 1000);
}

// Function to decelerate motor
void decelerate_motor(int motor, int speed_factor) {
    int speed = MAX_SPEED - (int)((double)speed_factor * (MAX_SPEED - MIN_SPEED) / 10.0);
    set_motor_speed(motor, speed);
    gpioDelay(DECEL_DELAY_MS * 1000);
}

// Function to hold motor at constant speed
void hold_motor(int motor, int speed_factor) {
    int speed = MIN_SPEED + (int)((double)speed_factor * (MAX_SPEED - MIN_SPEED) / 10.0);
    set_motor_speed(motor, speed);
    gpioDelay(HOLD_DELAY_MS * 1000);
}

// Function to move motor forward
void move_motor_forward(int motor, int speed_factor) {
    set_motor_direction(motor, 1);
    accelerate_motor(motor, speed_factor);
    hold_motor(motor, speed_factor);
    decelerate_motor(motor, speed_factor);
}

// Function to move motor backward
void move_motor_backward(int motor, int speed_factor) {
    set_motor_direction(motor, 0);
    accelerate_motor(motor, speed_factor);
    hold_motor(motor, speed_factor);
    decelerate_motor(motor, speed_factor);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Map potentiometer values to speed factors
        int speed_factor1 = map_speed(pot1_value);
        int speed_factor2 = map_speed(pot2_value);

        // Move Motor 1 forward and Motor 2 backward simultaneously
        move_motor_forward(1, speed_factor1);
        move_motor_backward(2, speed_factor2);

        // Pause for 5 seconds
        gpioDelay(PAUSE_DELAY_MS * 1000);

        // Move Motor 1 backward and Motor 2 forward sequentially
        move_motor_backward(1, speed_factor1);
        move_motor_forward(2, speed_factor2);

        // Pause for 5 seconds
        gpioDelay(PAUSE_DELAY_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

