#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CS 8
#define LED_PIN 17
#define SAMPLE_DELAY_US 10000
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_DURATION_S 5
#define NOISE_THRESHOLD_PERCENT 10.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    gpioWrite(MCP3008_CS, 0);
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    gpioWrite(MCP3008_CS, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int calibrate_noise_level(int *average_out) {
    long sum = 0;
    int valid_samples = 0;
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += val;
        valid_samples++;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - start.tv_sec) + (now.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed >= CALIBRATION_DURATION_S) break;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    *average_out = (int)(sum / valid_samples);
    printf("Average ambient noise level: %d\n", *average_out);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int ambient_level = 0;
    if (calibrate_noise_level(&ambient_level) != 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int noise_threshold = (int)(ambient_level + (ambient_level * NOISE_THRESHOLD_PERCENT / 100.0));
    printf("Noise threshold: %d\n", noise_threshold);

    int led_state = 0;
    struct timespec last_trigger = {0, 0};

    while (running) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (val > noise_threshold) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - last_trigger.tv_sec) + (now.tv_nsec - last_trigger.tv_nsec) / 1e9;
            if (elapsed > DEBOUNCE_DELAY_US / 1e6) {
                led_state = !led_state;
                gpioWrite(LED_PIN, led_state);
                printf("Sound detected! LED %s\n", led_state ? "ON" : "OFF");
                last_trigger = now;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

