#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "gas_log.txt"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_ppm(float voltage);
void log_data(float voltage, float ppm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains bits 9-2 (lower 2 bits are don't care)
    // rx_buffer[2] contains bits 1-0
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to convert voltage to PPM
float voltage_to_ppm(float voltage) {
    // Placeholder linear relationship: PPM = voltage * 1000.0
    // Replace with actual calibration curve from MP-741 datasheet
    return voltage * 1000.0;
}

// Function to log data to file
void log_data(float voltage, float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Voltage: %.3f V, PPM: %.3f\n", timestamp, voltage, ppm);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Propane Leak Detector started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 100ms...\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * VREF / 1023.0;

        // Convert voltage to PPM
        float ppm = voltage_to_ppm(voltage);

        // Log data
        log_data(voltage, ppm);

        // Print to console
        printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup (should not reach here if signal handler works)
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

