#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CS 8      // GPIO8 (CE0)
#define SAMPLE_RATE 10    // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

// ADXL335 Sensitivity (mV/g)
#define ADXL335_SENSITIVITY 300.0

// ADXL335 Zero-G Bias Voltage (V)
#define ADXL335_ZERO_G_BIAS 1.5

// Kalman Filter Parameters
#define Q 0.001
#define R 0.01

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double x; // Position
    double P; // Covariance
    double Q; // Process noise covariance
    double R; // Measurement noise covariance
} KalmanFilter;

KalmanFilter x_filter = {0, 1, Q, R};
KalmanFilter y_filter = {0, 1, Q, R};
KalmanFilter z_filter = {0, 1, Q, R};

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double read_adxl335_voltage(int channel);
double kalman_filter(KalmanFilter *filter, double measurement);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Initialize SPI for MCP3008
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC (single-ended mode)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode + channel
    tx_buf[2] = 0x00;

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
