    // Prediction
    filter->x = filter->x;
    filter->P = filter->P + filter->Q;

    // Update
    double y = measurement - filter->x;
    double S = filter->P + filter->R;
    double K = filter->P / S;

    filter->x = filter->x + K * y;
    filter->P = (1 - K) * filter->P;

