#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, const char *label) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading %s (GPIO %d): %s\n", label, gpiod_line_offset(line), strerror(errno));
        return -1;
    }
    return val;
}

static double calculate_magnetic_field(int sensor1_val, int sensor2_val, int sensor3_val) {
    double v_out = (double)sensor1_val * VCC;
    double v_quiescent = (double)sensor2_val * VCC;
    double v_sensor = (double)sensor3_val * VCC;

    if (v_sensor < v_quiescent) {
        v_sensor = v_quiescent;
    }

    double magnetic_field = (v_out - v_quiescent) / SENSITIVITY;
    return magnetic_field;
}

static void log_data(double m1, double m2, double m3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", m1, m2, m3);
    fflush(fp);
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int offsets[3] = {SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO};
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055va_reader") < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("DRV5055VA Hall-Effect Sensor Reader\n");
    printf("GPIO%d, GPIO%d, GPIO%d -> Sensor 1, Sensor 2, Sensor 3\n", SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (program_running) {
        int s1 = read_sensor(lines[0], "Sensor 1");
        int s2 = read_sensor(lines[1], "Sensor 2");
        int s3 = read_sensor(lines[2], "Sensor 3");

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Sensor read error, skipping logging.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        double m1 = calculate_magnetic_field(s1, s2, s3);
        double m2 = calculate_magnetic_field(s1, s2, s3);
        double m3 = calculate_magnetic_field(s1, s2, s3);

        if (m1 < MIN_MAGNETIC_FIELD || m1 > MAX_MAGNETIC_FIELD ||
            m2 < MIN_MAGNETIC_FIELD || m2 > MAX_MAGNETIC_FIELD ||
            m3 < MIN_MAGNETIC_FIELD || m3 > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field out of range (%.2f, %.2f, %.2f mT)\n", m1, m2, m3);
        }

        log_data(m1, m2, m3);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting gracefully.\n");
    return ret;
}

