#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define LOG_FILE "watering.log"
#define SAMPLE_INTERVAL 60

static volatile int running = 1;

void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel");
        return -1;
    }
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (handle < 0) {
        log_message("Error: spiOpen failed");
        return -1;
    }
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(handle, tx, rx, 3);
    spiClose(handle);
    if (ret < 0) {
        log_message("Error: spiXfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_message("Error: Failed to write to pump GPIO");
    }
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_message("Program started");
    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_message("Error: Failed to read moisture sensor");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d", moisture);
            log_message(msg);
            if (moisture < MOISTURE_THRESHOLD) {
                log_message("Moisture below threshold, turning pump ON");
                control_pump(1);
            } else {
                log_message("Moisture above threshold, turning pump OFF");
                control_pump(0);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }
    log_message("Program terminating, turning pump OFF");
    control_pump(0);
    gpioTerminate();
    return 0;
}

