        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_message("Error: Failed to read moisture sensor");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d", moisture);
            log_message(msg);
            if (moisture < MOISTURE_THRESHOLD) {
                log_message("Moisture below threshold, turning pump ON");
                control_pump(1);
            } else {
                log_message("Moisture above threshold, turning pump OFF");
                control_pump(0);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }
    log_message("Program terminating, turning pump OFF");
    control_pump(0);
    gpioTerminate();
    return 0;
}

