#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_LED 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        } else {
            printf("Connected to MQTT broker. Subscribed to %s\n", MQTT_TOPIC);
        }
    } else {
        log_error("MQTT connection failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_error("MQTT disconnected unexpectedly");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (payload == NULL) {
            log_error("Memory allocation failed for payload");
            return;
        }
        memcpy(payload, message->payload, message->payloadlen);
        payload[message->payloadlen] = '\0';

        cJSON *json = cJSON_Parse(payload);
        if (json == NULL) {
            log_error("Invalid JSON payload");
            free(payload);
            return;
        }

        cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (cJSON_IsBool(led_state)) {
            int gpio_value = led_state->value ? 1 : 0;
            if (gpioWrite(GPIO_LED, gpio_value) != 0) {
                log_error("Failed to write to GPIO");
            } else {
                printf("LED state updated to %s\n", led_state->value ? "ON" : "OFF");
            }
        } else {
            log_error("Invalid JSON format: expected 'led_state' as boolean");
        }

        cJSON_Delete(json);
        free(payload);
    }
}

static void cleanup(void) {
    if (mosq != NULL) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        log_error("Failed to create MQTT client");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int reconnect_delay = 1;
    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT connect failed, retrying in 1 second...");
            sleep(1);
            reconnect_delay = 1;
            continue;
        }

        rc = mosquitto_loop_start(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop start failed");
            mosquitto_disconnect(mosq);
            sleep(1);
            reconnect_delay = 1;
            continue;
        }

        while (running) {
            sleep(1);
        }

        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);

        if (reconnect_delay < MAX_RECONNECT_DELAY) {
            reconnect_delay *= 2;
        }
        if (reconnect_delay > MAX_RECONNECT_DELAY) {
            reconnect_delay = MAX_RECONNECT_DELAY;
        }
        sleep(reconnect_delay);
    }

    cleanup();
    return EXIT_SUCCESS;
}

