#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *alarm_line = NULL;
    int ret;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (GPIO17) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    ret = gpiod_line_request_input(sound_line, "sound-sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the alarm LED line (GPIO18) */
    alarm_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_line) {
        perror("gpiod_chip_get_line(alarm)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (off) */
    ret = gpiod_line_request_output(alarm_line, "alarm-led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(alarm)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("gpiod_line_get_value(sound)");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected: turn LED on */
            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(alarm on)");
                break;
            }

            /* Blink for 1 second */
            sleep(1);

            /* Turn LED off */
            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(alarm off)");
                break;
            }
        }

        usleep(100000); /* 100 ms */
    }

    /* Cleanup: release lines and close chip */
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

