#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define SEA_LEVEL_PRESSURE 101325.0
#define LOG_FILE "altitude_log.txt"
#define SAMPLE_INTERVAL_S 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) return -1;
    return 0;
}

static int read_calibration(void) {
    uint8_t buf[24];
    if (i2c_read_reg(BMP280_REG_CALIB, buf, 24) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)calib.dig_P3) >> 8) + ((var1 * (int64_t)calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)calib.dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (uint32_t)((p >> 8) * 25) / 100;
}

static double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_PRESSURE, 0.1903));
}

static int log_data(double altitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (fprintf(log_file, "%s, %.2f m\n", ts, altitude) < 0) return -1;
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(BMP280_REG_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read chip ID\n");
        cleanup();
        return 1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        cleanup();
        return 1;
    }

    if (read_calibration() != 0) {
        cleanup();
        return 1;
    }

    if (i2c_write_reg(BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP280 altitude logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint8_t data[6];
        if (i2c_read_reg(BMP280_REG_PRESS_MSB, data, 6) != 0) {
            fprintf(stderr, "Error: Failed to read pressure/temperature data\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        int32_t raw_p = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
        int32_t raw_t = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));

        compensate_temperature(raw_t);
        uint32_t p_pa = compensate_pressure(raw_p);
        double alt = calculate_altitude((double)p_pa);

        if (log_data(alt) != 0) {
            fprintf(stderr, "Error: Failed to write to log file\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

