#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3f
#define LM35_SCALE 10.0f
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n", ret, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0f;
    return voltage * LM35_SCALE;
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static void write_circular_buffer_to_file(float *buffer, int size) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    size_t written = fwrite(buffer, sizeof(float), (size_t)size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float circular_buffer[BUFFER_SIZE];
    memset(circular_buffer, 0, sizeof(circular_buffer));
    int buffer_index = 0;

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping sample\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        log_temperature(temperature);

        circular_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        write_circular_buffer_to_file(circular_buffer, BUFFER_SIZE);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

