#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define MCP4725_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    fprintf(stderr, "Error: SPI transfer failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static float adc_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -999.0f;
    }
    float voltage = (adc_value * 3.3f) / 1024.0f;
    return (voltage - 0.5f) * 100.0f;
}

static float temperature_to_dac_voltage(float temperature) {
    if (temperature < 0.0f) temperature = 0.0f;
    if (temperature > 50.0f) temperature = 50.0f;
    return (temperature / 50.0f) * 3.3f;
}

static int write_mcp4725(float voltage) {
    if (voltage < 0.0f || voltage > 3.3f) {
        fprintf(stderr, "Error: Voltage %.3f V out of range for MCP4725\n", voltage);
        return -1;
    }

    uint16_t dac_value = (uint16_t)((voltage / 3.3f) * 4095.0f);
    unsigned char tx[2] = {
        (unsigned char)((dac_value >> 8) & 0x0F),
        (unsigned char)(dac_value & 0xFF)
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, (char *)tx, 2);
        if (ret == 0) return 0;
        fprintf(stderr, "Warning: I2C write failed (attempt %d/%d, ret=%d)\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    fprintf(stderr, "Error: I2C write failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n",
                timestamp, adc_value, temperature, dac_voltage) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MCP4725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        if (temperature < -900.0f) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float dac_voltage = temperature_to_dac_voltage(temperature);
        if (write_mcp4725(dac_voltage) != 0) {
            fprintf(stderr, "Error: Failed to write DAC\n");
        }

        if (log_data(adc_value, temperature, dac_voltage) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        printf("ADC: %d, Temp: %.2f C, DAC: %.3f V\n", adc_value, temperature, dac_voltage);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

