#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// BCM GPIO pins for the four relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Number of relays
#define NUM_RELAYS 4

// GPIO chip device (Raspberry Pi 3 B+ uses gpiochip0)
#define GPIO_CHIP "/dev/gpiochip0"

// Global pointers for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS] = {NULL};
static int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

// Signal handler for graceful shutdown
static void cleanup_and_exit(int signum) {
    (void)signum;
    // Deactivate all relays (set LOW)
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
        }
    }
    // Release lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

