#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LED_PIN 16
#define SOUND_THRESHOLD 500
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define DEBOUNCE_DELAY_US 100000
#define LED_ON_DURATION_US 500000
#define LOOP_DELAY_US 10000

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(void) {
    FILE *fp = fopen("sound_events.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error: localtime failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (adc_value > SOUND_THRESHOLD) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: Failed to turn on LED\n");
            }
            log_event();
            gpioDelay(LED_ON_DURATION_US);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: Failed to turn off LED\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

