#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin assignments for L298N motor driver */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Rain sensor threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor PWM range and speed */
#define MOTOR_RANGE 255
#define MOTOR_SPEED 150

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 1000000

/* Motor run time in seconds */
#define MOTOR_RUN_TIME_S 3

/* Global state */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7).                            */
/* Returns 0-1023 on success, -1 on SPI transfer failure.              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10).                    */
/* Higher voltage = drier = lower rain level.                         */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 10 - (adc_value * 10 / 1023);
}

/* ------------------------------------------------------------------ */
/* Log rain level to file and stdout.                                  */
/* ------------------------------------------------------------------ */
static void log_rain_level(int rain_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s Rain Level: %d\n", timestamp, rain_level);
        fflush(g_log_file);
    }
    printf("%s Rain Level: %d\n", timestamp, rain_level);
}

/* ------------------------------------------------------------------ */
/* Drive motor forward for MOTOR_RUN_TIME_S seconds.                   */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
    time_sleep(MOTOR_RUN_TIME_S);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Drive motor in reverse for MOTOR_RUN_TIME_S seconds.                */
/* ------------------------------------------------------------------ */
static void motor_reverse(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
    time_sleep(MOTOR_RUN_TIME_S);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motor first for safety */
    gpioPWM(MOTOR_ENA, 0);
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs as outputs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and initial duty to 0 */
    gpioSetPWMrange(MOTOR_ENA, MOTOR_RANGE);
    gpioPWM(MOTOR_ENA, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("rain_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open rain_log.txt: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int window_closed = 0;  /* 0 = open, 1 = closed */

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping cycle\n");
            time_sleep(1.0);
            continue;
        }

        int rain_level = adc_to_rain_level(adc_value);
        log_rain_level(rain_level);

        if (rain_level >= RAIN_THRESHOLD && !window_closed) {
            printf("Rain level %d >= %d — closing window\n",
                   rain_level, RAIN_THRESHOLD);
            motor_forward();
            window_closed = 1;
        } else if (rain_level < RAIN_THRESHOLD && window_closed) {
            printf("Rain level %d < %d — opening window\n",
                   rain_level, RAIN_THRESHOLD);
            motor_reverse();
            window_closed = 0;
        }

        time_sleep(POLL_INTERVAL_US / 1000000.0);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

