#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio17/value"
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD 200.0
#define A 26.0
#define B -6.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int gpio_export(int pin) {
    FILE *fp = fopen(GPIO_EXPORT_PATH, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_unexport(int pin) {
    FILE *fp = fopen(GPIO_UNEXPORT_PATH, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int read_gpio_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "%s%d/value", GPIO_PATH, pin);
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    int value;
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading value from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

float calculate_distance(int gpio_value) {
    float voltage = (float)gpio_value * 3.3f;
    float distance = (A / voltage) + B;
    return distance;
}

int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    while (program_running) {
        int gpio_value = read_gpio_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO value, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        float distance = calculate_distance(gpio_value);

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Program terminated cleanly.\n");
    return 0;
}

