    if (!pump_line) {
        perror("Failed to get pump GPIO line");
        goto cleanup;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture", 0) < 0) {
        perror("Failed to request pump GPIO as output");
        goto cleanup;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
