#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define GPIO_CHIP       "gpiochip0"
#define CS_LINE         8

#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define VREF_MV         3300
#define DRV5055_SENS_MV 100
#define DRV5055_Q_MV    1650

#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_US       500000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mcp3008(struct gpiod_line *cs, int fd, int channel, int *adc_out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    *adc_out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float calculate_magnetic_field(int adc_value)
{
    int vout_mv = (adc_value * VREF_MV) / ADC_MAX;
    float b_mt  = (float)(vout_mv - DRV5055_Q_MV) / DRV5055_SENS_MV;
    return b_mt;
}

static int log_data(FILE *fp, time_t ts, float b_mt)
{
    if (fprintf(fp, "%ld,%.2f\n", (long)ts, b_mt) < 0) {
        fprintf(stderr, "Failed to write to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

