{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs) {
        fprintf(stderr, "Failed to get CS line %d: %s\n", CS_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs, "drv5055_mcp3008", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(cs);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Magnetic field logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(cs, spi_fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            usleep(SAMPLE_US);
            continue;
        }

        float b_mt = calculate_magnetic_field(adc_value);
        time_t now = time(NULL);

        if (log_data(log_fp, now, b_mt) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("ADC: %4d  Vout: %5d mV  B: %.2f mT\n",
               adc_value, (adc_value * VREF_MV) / ADC_MAX, b_mt);

        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    fclose(log_fp);
    gpiod_line_release(cs);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

