#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */
#define ADC_CHANNEL 0          /* MCP3008 channel 0 */
#define LED_GPIO    21         /* GPIO21 for LED */
#define VCC         3.3        /* ADC reference voltage */
#define THRESHOLD   10.0       /* mT threshold */
#define LOG_FILE    "magnetic_log.txt"
#define SAMPLE_US   100000     /* 100 ms between readings */

/* DRV5055VA ratiometric constants */
#define DRV5055_VQ  (VCC / 2.0)   /* Quiescent output at VCC/2 */
#define DRV5055_SENS_MV_PER_MT 1.65 /* Sensitivity at 3.3 V: 2.5 mV/mT */
#define DRV5055_SENS_MT_PER_MV (DRV5055_SENS_MV_PER_MT / 1000.0)

/* Global state for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read 10-bit value from MCP3008 single-ended channel */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI command: start bit, single-ended + channel, then null bit */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* Convert ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return (float)adc_value * VCC / 1023.0f;
}

/* Convert voltage to magnetic field strength in mT */
static float voltage_to_field_mt(float voltage) {
    return (voltage - DRV5055_VQ) * DRV5055_SENS_MT_PER_MV;
}

/* Log timestamped reading to file */
static int log_reading(float field_mt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Field: %.2f mT\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, field_mt);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* Control LED based on threshold */
static void control_led(float field_mt) {
    gpioWrite(LED_GPIO, (field_mt > THRESHOLD) ? 1 : 0);
}

int main(void) {
