#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W - MLX91211 Current Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 5V (Pi pin 2)
 *   MCP3008 VREF -> 5V (Pi pin 2)
 *   MCP3008 AGND -> GND (Pi pin 6)
 *   MCP3008 DGND -> GND (Pi pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 analog output (VDD/2 = 2.5V, VDD = 5.0V)
 *   MLX91211 VDD -> 5V (Pi pin 2)
 *   MLX91211 GND -> GND (Pi pin 6)
 *
 * Build: gcc -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:   sudo ./current_monitor
 */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_CODE   1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 VREF tied to Pi 5V rail */
#define VDD            5.0        /* MLX91211 VDD */
#define ZERO_CURRENT   2.5        /* MLX91211 output at 0 A (V) */
#define FULL_CURRENT   5.0        /* MLX91211 output at +50 A (V) */
#define MAX_CURRENT    50.0       /* MLX91211 full-scale current */
#define SAMPLE_US      100000     /* 100 ms between samples */
#define LOG_FILE       "current_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008                        */
/* Returns 0-1023 on success, -1 on SPI transfer error                 */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = 0x80 | (channel << 4)      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ------------------------------------------------------------------ */
/* Convert ADC code to current (A)                                     */
/* ------------------------------------------------------------------ */
static double adc_to_current(int adc_code)
{
    if (adc_code < 0 || adc_code > ADC_MAX_CODE) {
        fprintf(stderr, "ADC code out of range: %d\n", adc_code);
        return 0.0;
    }

    double voltage = ((double)adc_code / (double)ADC_MAX_CODE) * VREF;

    /* Clamp voltage to the sensor's full-scale range */
    if (voltage < ZERO_CURRENT) {
        voltage = ZERO_CURRENT;
    } else if (voltage > FULL_CURRENT) {
        voltage = FULL_CURRENT;
    }

    return (voltage - ZERO_CURRENT) * (MAX_CURRENT / (FULL_CURRENT - ZERO_CURRENT));
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static int log_current(double current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s %.2f A\n", ts, current);
    fflush(fp);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error already printed; skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        double voltage = ((double)adc / (double)ADC_MAX_CODE) * VREF;

        /* Warn if voltage is outside the sensor's full-scale range */
        if (voltage < ZERO_CURRENT || voltage > FULL_CURRENT) {
            fprintf(stderr,
                    "Warning: voltage %.2f V outside sensor range [%.1f, %.1f] - skipping sample\n",
                    voltage, ZERO_CURRENT, FULL_CURRENT);
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = adc_to_current(adc);

        if (log_current(current) != 0) {
            fprintf(stderr, "Failed to log current reading\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

