#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a single GPIO line with debounce: return 0 or 1, or -1 on error. */
static int read_sensor(struct gpiod_line *line) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        sum += val;
        if (i < DEBOUNCE_SAMPLES - 1)
            usleep(DEBOUNCE_DELAY_US);
    }
    return (sum >= DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the gpiochip that exposes the Pi's GPIOs (gpiochip0 on Pi 5). */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as inputs. B5W-DB01 has an open-collector output;
     * the internal pull-up keeps the line HIGH when no object is present. */
    if (gpiod_line_request_input(line1, "b5w-sensor1") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-sensor2") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);

    while (running) {
        int s1 = read_sensor(line1);
        int s2 = read_sensor(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            printf("Sensor 1: %s, Sensor 2: %s\n",
                   s1 ? "no object" : "object present",
                   s2 ? "no object" : "object present");
            if (s1 == 0 && s2 == 0)
                printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

