#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define PIR_GPIO 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_MS 50
#define IMAGE_DIR "/home/pi/security_cam"
#define MAX_FILENAME_LEN 256
#define MAX_CMD_LEN 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "Failed to create directory '%s': %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[MAX_CMD_LEN];
    int needed = snprintf(command, sizeof(command),
        "libcamera-still -n -o %s --width %d --height %d --encoding jpeg",
        filename, IMAGE_WIDTH, IMAGE_HEIGHT);
    if (needed < 0 || (size_t)needed >= sizeof(command)) {
        syslog(LOG_ERR, "Command buffer too small for capture command");
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep syslog clean */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        execlp("libcamera-still", "libcamera-still",
               "-n", "-o", filename,
               "--width", "1280", "--height", "720",
               "--encoding", "jpeg",
               (char *)NULL);
        /* If execvp fails */
        _exit(127);
    }

    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) continue;
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera system");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead(%d) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Initial state: %d", last_state);

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); /* microseconds */
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_GPIO);
                break;
            }
            if (confirmed == current_state) {
                last_state = confirmed;
                if (confirmed == 1) {
                    syslog(LOG_INFO, "Motion detected");

                    time_t rawtime;
                    struct tm timeinfo;
                    char filename[MAX_FILENAME_LEN];

                    time(&rawtime);
                    localtime_r(&rawtime, &timeinfo);
                    if (strftime(filename, sizeof(filename),
                                 IMAGE_DIR "/%Y-%m-%dT%H-%M-%S.jpg",
                                 &timeinfo) == 0) {
                        syslog(LOG_ERR, "strftime failed to format filename");
                        continue;
                    }

                    if (capture_image(filename) != 0) {
                        syslog(LOG_ERR, "Failed to capture image");
                    }
                }
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); /* microseconds */
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return 0;
}

