#include <sys/socket.h>
#include <netinet/in.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define MAX_FRAME_SIZE 65000
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4

#define FRAME_HEADER_SIZE 8
#define FRAGMENT_HEADER_SIZE 8
#define FRAGMENT_PAYLOAD_SIZE (MAX_FRAME_SIZE - FRAGMENT_HEADER_SIZE)

#define FRAME_INDEX_MASK 0xFFFFFFFFFFFFFFFFULL
#define FRAGMENT_INDEX_MASK 0xFFFFFFFFFFFFFFFFULL
#define TOTAL_FRAGMENTS_MASK 0xFFFFFFFFFFFFFFFFULL
#define PAYLOAD_SIZE_MASK 0xFFFFFFFFFFFFFFFFULL

typedef struct {
    void *start;
    size_t length;
    int mapped;
} buffer_t;

static volatile sig_atomic_t running = 1;
static int video_fd = -1;
static buffer_t *buffers = NULL;
static int num_buffers = 0;
static int udp_socket = -1;
static struct sockaddr_in server_addr;
static int server_addr_len = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_video(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    enum v4l2_buf_type type;

    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("open video device");
        return -1;
    }

    if (xioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        goto fail;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }

    if (fmt.fmt.pix.width != FRAME_WIDTH || fmt.fmt.pix.height != FRAME_HEIGHT) {
        fprintf(stderr, "Warning: driver did not accept %dx%d format\n", FRAME_WIDTH, FRAME_HEIGHT);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", VIDEO_DEVICE);
        goto fail;
    }

    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("calloc buffers");
        goto fail;
    }

    for (num_buffers = 0; num_buffers < req.count; ++num_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = num_buffers;

        if (xioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto fail;
        }

        buffers[num_buffers].length = buf.length;
        buffers[num_buffers].mapped = 0;

        buffers[num_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (buffers[num_buffers].start == MAP_FAILED) {
            perror("mmap");
            buffers[num_buffers].start = NULL;
            goto fail;
        }
        buffers[num_buffers].mapped = 1;
    }

    for (num_buffers = 0; num_buffers < req.count; ++num_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = num_buffers;

        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto fail;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(video_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto fail;
    }

    return 0;

fail:
    if (video_fd >= 0) close(video_fd);
    video_fd = -1;
    return -1;
}

static void cleanup_video(void) {
    if (video_fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(video_fd, VIDIOC_STREAMOFF, &type);
    }
    if (buffers) {
        for (int i = 0; i < num_buffers; ++i) {
            if (buffers[i].mapped && buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        buffers = NULL;
    }
    if (video_fd >= 0) {
        close(video_fd);
        video_fd = -1;
    }
}

static int init_udp(const char *ip, int port) {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid IP address: %s\n", ip);
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }
    server_addr_len = sizeof(server_addr);
    return 0;
}

static void cleanup_udp(void) {
    if (udp_socket >= 0) {
        close(udp_socket);
        udp_socket = -1;
    }
}

static int send_frame_udp(const unsigned char *frame_data, int frame_size) {
    int total_sent = 0;
    int total_fragments = (frame_size + FRAGMENT_PAYLOAD_SIZE - 1) / FRAGMENT_PAYLOAD_SIZE;

    for (int frag_idx = 0; frag_idx < total_fragments; ++frag_idx) {
        int payload_size = (frame_size - total_sent < FRAGMENT_PAYLOAD_SIZE)
                           ? (frame_size - total_sent)
                           : FRAGMENT_PAYLOAD_SIZE;

        unsigned char header[FRAGMENT_HEADER_SIZE];
        unsigned long long header_val = ((unsigned long long)frag_idx << 48) |
                                        ((unsigned long long)total_fragments << 32) |
                                        ((unsigned long long)payload_size);
        memcpy(header, &header_val, FRAGMENT_HEADER_SIZE);

        unsigned char *packet = malloc(FRAGMENT_HEADER_SIZE + payload_size);
        if (!packet) {
            perror("malloc packet");
            return -1;
        }
        memcpy(packet, header, FRAGMENT_HEADER_SIZE);
        memcpy(packet + FRAGMENT_HEADER_SIZE, frame_data + total_sent, payload_size);

        ssize_t sent = sendto(udp_socket, packet, FRAGMENT_HEADER_SIZE + payload_size, 0,
                              (struct sockaddr *)&server_addr, server_addr_len);
        free(packet);

        if (sent < 0) {
            perror("sendto");
            return -1;
        }
        total_sent += payload_size;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_video() < 0) {
        fprintf(stderr, "Failed to initialize video device\n");
        return EXIT_FAILURE;
    }

    if (init_udp(server_ip, server_port) < 0) {
        fprintf(stderr, "Failed to initialize UDP socket\n");
        cleanup_video();
        return EXIT_FAILURE;
    }

    printf("Streaming video to %s:%d...\n", server_ip, server_port);

    unsigned long long frame_index = 0;

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.index >= num_buffers) {
            fprintf(stderr, "Invalid buffer index: %d\n", buf.index);
            break;
        }

        if (send_frame_udp((unsigned char *)buffers[buf.index].start, buf.bytesused) < 0) {
            fprintf(stderr, "Failed to send frame\n");
            break;
        }

        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_index++;
    }

    printf("\nShutting down...\n");
    cleanup_udp();
    cleanup_video();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

