    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_video() < 0) {
        fprintf(stderr, "Failed to initialize video device\n");
        return EXIT_FAILURE;
    }

    if (init_udp(server_ip, server_port) < 0) {
        fprintf(stderr, "Failed to initialize UDP socket\n");
        cleanup_video();
        return EXIT_FAILURE;
    }

    printf("Streaming video to %s:%d...\n", server_ip, server_port);

    unsigned long long frame_index = 0;

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.index >= num_buffers) {
            fprintf(stderr, "Invalid buffer index: %d\n", buf.index);
            break;
        }

        if (send_frame_udp((unsigned char *)buffers[buf.index].start, buf.bytesused) < 0) {
            fprintf(stderr, "Failed to send frame\n");
            break;
        }

        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_index++;
    }

    printf("\nShutting down...\n");
    cleanup_udp();
    cleanup_video();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

