#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define IMAGE_FILE   "image.jpg"
#define NUM_BUFFERS  4

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap = {0};
    struct v4l2_format fmt = {0};
    struct v4l2_requestbuffers req = {0};
    struct v4l2_buffer buf = {0};
    struct v4l2_streamparm parm = {0};
    struct v4l2_buffer *buffers = NULL;
    unsigned char *mapped_buffers = NULL;
    size_t mapped_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR, 0);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        goto cleanup;
    }

    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        goto cleanup;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[i].index = i;
        buffers[i].length = buf.length;
        buffers[i].m.planes[0].length = buf.length;
        buffers[i].m.planes[0].m.userptr = 0;
        buffers[i].m.planes[0].m.userptr_offset = 0;

        mapped_size += buf.length;
    }

    mapped_buffers = mmap(NULL, mapped_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_buffers == MAP_FAILED) {
        perror("mmap");
        mapped_buffers = NULL;
        goto cleanup;
    }

    size_t offset = 0;
    for (unsigned int i = 0; i < req.count; i++) {
        buffers[i].m.planes[0].m.userptr = (unsigned long)mapped_buffers + offset;
        offset += buffers[i].length;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_STREAMON, &buf.type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "No data captured (buf.bytesused == 0)\n");
        goto cleanup;
    }

    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen(" IMAGE_FILE ")");
        goto cleanup;
    }

    size_t written = fwrite(mapped_buffers + buf.offset, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Short write: %zu of %u bytes\n", written, buf.bytesused);
        fclose(fp);
        fp = NULL;
        goto cleanup;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        fp = NULL;
        goto cleanup;
    }
    fp = NULL;

    printf("Image saved as %s (%u bytes)\n", IMAGE_FILE, buf.bytesused);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
    }

    if (mapped_buffers && mapped_buffers != MAP_FAILED) {
        if (munmap(mapped_buffers, mapped_size) == -1) {
            perror("munmap");
        }
        mapped_buffers = NULL;
    }

    if (buffers) {
        free(buffers);
        buffers = NULL;
    }

    if (fp) {
        fclose(fp);
    }

    if (fd != -1) {
        close(fd);
        fd = -1;
    }

    return ret;
}

