#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5
#define BUTTON_UP_PIN  6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9

#define SERVO_MIN_PULSE_WIDTH 1000  /* 1 ms in microseconds */
#define SERVO_MAX_PULSE_WIDTH 2000  /* 2 ms in microseconds */
#define SERVO_MID_PULSE_WIDTH 1500  /* 1.5 ms mid position */
#define SERVO_MIN_POSITION 25
#define SERVO_MAX_POSITION 125
#define SERVO_STEP 5
#define PWM_PERIOD_US 20000  /* 20 ms = 50 Hz */
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Software PWM: drive a GPIO line high for `on_us` microseconds, then low
 * for the remainder of the period.  Returns 0 on success, -1 on error.
 */
static int pwm_write(struct gpiod_line *line, int on_us) {
    if (on_us < 0) on_us = 0;
    if (on_us > PWM_PERIOD_US) on_us = PWM_PERIOD_US;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        return -1;
    }
    usleep(on_us);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        return -1;
    }
    usleep(PWM_PERIOD_US - on_us);
    return 0;
}

/*
 * Map a position value [SERVO_MIN_POSITION, SERVO_MAX_POSITION] to a
 * pulse width in microseconds.  Returns 0 on success, -1 if the value
 * is out of range.
 */
static int position_to_pulse_width(int position, int *pulse_width_us) {
    if (position < SERVO_MIN_POSITION || position > SERVO_MAX_POSITION) {
        fprintf(stderr, "Position %d out of range [%d, %d]\n",
                position, SERVO_MIN_POSITION, SERVO_MAX_POSITION);
        return -1;
    }
    *pulse_width_us = SERVO_MIN_PULSE_WIDTH +
                      (position - SERVO_MIN_POSITION) *
                      (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) /
                      (SERVO_MAX_POSITION - SERVO_MIN_POSITION);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *up_line = NULL, *down_line = NULL;
    struct gpiod_line *left_line = NULL, *right_line = NULL;
    int pan_position = SERVO_MID_PULSE_WIDTH;
    int tilt_position = SERVO_MID_PULSE_WIDTH;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    up_line = gpiod_chip_get_line(chip, BUTTON_UP_PIN);
    down_line = gpiod_chip_get_line(chip, BUTTON_DOWN_PIN);
    left_line = gpiod_chip_get_line(chip, BUTTON_LEFT_PIN);
    right_line = gpiod_chip_get_line(chip, BUTTON_RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan-servo", 0) < 0) {
        fprintf(stderr, "Failed to request pan line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "tilt-servo", 0) < 0) {
        fprintf(stderr, "Failed to request tilt line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(up_line, "button-up",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request up button: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(down_line, "button-down",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request down button: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(left_line, "button-left",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request left button: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(right_line, "button-right",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request right button: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Start both servos at the mid position */
    if (pwm_write(pan_line, pan_position) < 0) goto cleanup;
    if (pwm_write(tilt_line, tilt_position) < 0) goto cleanup;

    printf("Pan-tilt system ready. Press Ctrl+C to exit.\n");

    while (running) {
        int up_val = gpiod_line_get_value(up_line);
        int down_val = gpiod_line_get_value(down_line);
        int left_val = gpiod_line_get_value(left_line);
        int right_val = gpiod_line_get_value(right_line);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading button state: %s\n", strerror(errno));
            goto cleanup;
        }

        if (up_val == 0) {
            tilt_position += SERVO_STEP;
            if (tilt_position > SERVO_MAX_POSITION) tilt_position = SERVO_MAX_POSITION;
            if (position_to_pulse_width(tilt_position, &tilt_position) < 0) {
                fprintf(stderr, "Invalid tilt position\n");
                goto cleanup;
            }
            if (pwm_write(tilt_line, tilt_position) < 0) goto cleanup;
        } else if (down_val == 0) {
            tilt_position -= SERVO_STEP;
            if (tilt_position < SERVO_MIN_POSITION) tilt_position = SERVO_MIN_POSITION;
            if (position_to_pulse_width(tilt_position, &tilt_position) < 0) {
                fprintf(stderr, "Invalid tilt position\n");
                goto cleanup;
            }
            if (pwm_write(tilt_line, tilt_position) < 0) goto cleanup;
        }

        if (left_val == 0) {
            pan_position += SERVO_STEP;
            if (pan_position > SERVO_MAX_POSITION) pan_position = SERVO_MAX_POSITION;
            if (position_to_pulse_width(pan_position, &pan_position) < 0) {
                fprintf(stderr, "Invalid pan position\n");
                goto cleanup;
            }
            if (pwm_write(pan_line, pan_position) < 0) goto cleanup;
        } else if (right_val == 0) {
            pan_position -= SERVO_STEP;
