            if (tilt_position > SERVO_MAX_POSITION) tilt_position = SERVO_MAX_POSITION;
            if (position_to_pulse_width(tilt_position, &tilt_position) < 0) {
                fprintf(stderr, "Invalid tilt position\n");
                goto cleanup;
            }
            if (pwm_write(tilt_line, tilt_position) < 0) goto cleanup;
        } else if (down_val == 0) {
            tilt_position -= SERVO_STEP;
            if (tilt_position < SERVO_MIN_POSITION) tilt_position = SERVO_MIN_POSITION;
            if (position_to_pulse_width(tilt_position, &tilt_position) < 0) {
                fprintf(stderr, "Invalid tilt position\n");
                goto cleanup;
            }
            if (pwm_write(tilt_line, tilt_position) < 0) goto cleanup;
        }

        if (left_val == 0) {
            pan_position += SERVO_STEP;
            if (pan_position > SERVO_MAX_POSITION) pan_position = SERVO_MAX_POSITION;
            if (position_to_pulse_width(pan_position, &pan_position) < 0) {
                fprintf(stderr, "Invalid pan position\n");
                goto cleanup;
            }
            if (pwm_write(pan_line, pan_position) < 0) goto cleanup;
        } else if (right_val == 0) {
            pan_position -= SERVO_STEP;
            if (pan_position < SERVO_MIN_POSITION) pan_position = SERVO_MIN_POSITION;
            if (position_to_pulse_width(pan_position, &pan_position) < 0) {
                fprintf(stderr, "Invalid pan position\n");
                goto cleanup;
            }
            if (pwm_write(pan_line, pan_position) < 0) goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Stop PWM signals by setting lines low */
    if (pan_line) gpiod_line_set_value(pan_line, 0);
    if (tilt_line) gpiod_line_set_value(tilt_line, 0);
    if (chip) gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
