#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define JPEG_QUALITY 75
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int w, int h) {
    for (int i = 0; i < w * h; i++) {
        int y0 = yuyv[i * 2];
        int u = yuyv[i * 2 + 1] - 128;
        int y1 = yuyv[i * 2 + 2];
        int v = yuyv[i * 2 + 3] - 128;
        int r = y0 + 114 * v / 100;
        int g = y0 - 39 * u / 100 - 58 * v / 100;
        int b = y0 + 213 * u / 100;
        if (r < 0) r = 0; if (r > 255) r = 255;
        if (g < 0) g = 0; if (g > 255) g = 255;
        if (b < 0) b = 0; if (b > 255) b = 255;
        rgb[i * 3] = (unsigned char)r;
        rgb[i * 3 + 1] = (unsigned char)g;
        rgb[i * 3 + 2] = (unsigned char)b;
    }
}

static void box_blur(const unsigned char *src, unsigned char *dst, int w, int h, int radius) {
    int w4 = w * 4;
    unsigned char *tmp = malloc(w4 * h);
    if (!tmp) { perror("malloc"); return; }
    memcpy(tmp, src, w4 * h);
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int r = 0, g = 0, b = 0, n = 0;
            for (int dy = -radius; dy <= radius; dy++) {
                for (int dx = -radius; dx <= radius; dx++) {
                    int ny = y + dy, nx = x + dx;
                    if (ny < 0) ny = 0; if (ny >= h) ny = h - 1;
                    if (nx < 0) nx = 0; if (nx >= w) nx = w - 1;
                    int idx = ny * w + nx;
                    r += tmp[idx * 3]; g += tmp[idx * 3 + 1]; b += tmp[idx * 3 + 2]; n++;
                }
            }
            int idx = y * w + x;
            dst[idx * 3] = (unsigned char)(r / n);
            dst[idx * 3 + 1] = (unsigned char)(g / n);
            dst[idx * 3 + 2] = (unsigned char)(b / n);
        }
    }
    free(tmp);
}

static int save_jpeg(const char *filename, const unsigned char *rgb, int w, int h, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) { perror("fopen"); return -1; }
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);
    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    int row_stride = w * 3;
    while (cinfo.next_scanline < cinfo.image_height) {
        JSAMPROW row = (JSAMPROW)(rgb + cinfo.next_scanline * row_stride);
        jpeg_write_scanlines(&cinfo, &row, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) { perror("open"); return 1; }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) { perror("ioctl VIDIOC_QUERYCAP"); close(fd); return 1; }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) { fprintf(stderr, "Device does not support capture\n"); close(fd); return 1; }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) { fprintf(stderr, "Device does not support streaming\n"); close(fd); return 1; }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) { perror("ioctl VIDIOC_S_FMT"); close(fd); return 1; }
    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) { fprintf(stderr, "Format not supported\n"); close(fd); return 1; }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) { perror("ioctl VIDIOC_REQBUFS"); close(fd); return 1; }
    if (req.count < 2) { fprintf(stderr, "Insufficient buffers\n"); close(fd); return 1; }

    struct v4l2_buffer buf;
    struct v4l2_mmap_contig mmap_contig;
    void *buffers[NUM_BUFFERS];
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) { perror("ioctl VIDIOC_QUERYBUF"); close(fd); return 1; }
        mmap_contig.length = buf.length;
        mmap_contig.offset = buf.m.offset;
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) { perror("mmap"); buffers[i] = NULL; close(fd); return 1; }
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) { perror("ioctl VIDIOC_QBUF"); munmap(buffers[i], buf.length); buffers[i] = NULL; close(fd); return 1; }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) { perror("ioctl VIDIOC_STREAMON"); for (int i = 0; i < NUM_BUFFERS; i++) if (buffers[i]) munmap(buffers[i], buf.length); close(fd); return 1; }

    fd_set fds;
    struct timeval tv;
    int frame_ready = 0;
    while (!frame_ready && !stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = CAPTURE_TIMEOUT_SEC;
        tv.tv_usec = 0;
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) { if (errno == EINTR) continue; perror("select"); break; }
        if (r == 0) { fprintf(stderr, "Timeout waiting for frame\n"); break; }
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) { if (errno == EAGAIN) continue; perror("ioctl VIDIOC_DQBUF"); break; }
        frame_ready = 1;
    }

    if (!frame_ready || stop_flag) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) perror("ioctl VIDIOC_STREAMOFF");
        for (int i = 0; i < NUM_BUFFERS; i++) if (buffers[i]) munmap(buffers[i], buf.length);
        close(fd);
        return 0;
    }

    unsigned char *yuyv = (unsigned char *)buffers[buf.index];
    unsigned char *rgb = malloc(WIDTH * HEIGHT * 3);
    if (!rgb) { perror("malloc"); ioctl(fd, VIDIOC_STREAMOFF, &type); for (int i = 0; i < NUM_BUFFERS; i++) if (buffers[i]) munmap(buffers[i], buf.length); close(fd); return 1; }
    yuyv_to_rgb24(yuyv, rgb, WIDTH, HEIGHT);

    unsigned char *blur = malloc(WIDTH * HEIGHT * 3);
    if (!blur) { perror("malloc"); free(rgb); ioctl(fd, VIDIOC_STREAMOFF, &type); for (int i = 0; i < NUM_BUFFERS; i++) if (buffers[i]) munmap(buffers[i], buf.length); close(fd); return 1; }
    box_blur(rgb, blur, WIDTH, HEIGHT, 2);
    free(rgb);

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char filename[64];
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);
    if (save_jpeg(filename, blur, WIDTH, HEIGHT, JPEG_QUALITY) != 0) { fprintf(stderr, "Failed to save JPEG\n"); free(blur); ioctl(fd, VIDIOC_STREAMOFF, &type); for (int i = 0; i < NUM_BUFFERS; i++) if (buffers[i]) munmap(buffers[i], buf.length); close(fd); return 1; }
    free(blur);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) perror("ioctl VIDIOC_QBUF");
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) perror("ioctl VIDIOC_STREAMOFF");
    for (int i = 0; i < NUM_BUFFERS; i++) if (buffers[i]) munmap(buffers[i], buf.length);
    close(fd);
    printf("Saved %s\n", filename);
    return 0;
}

