#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_resolution(const struct v4l2_frmsizeenum *fse)
{
    if (fse->type == V4L2_FRMSIZE_TYPE_DISCRETE) {
        printf("  %ux%u\n", fse->discrete.width, fse->discrete.height);
    } else if (fse->type == V4L2_FRMSIZE_TYPE_STEPWISE) {
        printf("  %ux%u-%ux%u (step %ux%u)\n",
               fse->stepwise.min_width, fse->stepwise.min_height,
               fse->stepwise.max_width, fse->stepwise.max_height,
               fse->stepwise.step_width, fse->stepwise.step_height);
    } else {
        printf("  (unknown)\n");
    }
}

static void print_frame_rate(const struct v4l2_frmivalenum *fie)
{
    if (fie->type == V4L2_FRMIVAL_TYPE_DISCRETE) {
        printf("  %u/%u\n", fie->discrete.numerator, fie->discrete.denominator);
    } else if (fie->type == V4L2_FRMIVAL_TYPE_STEPWISE) {
        printf("  %u/%u-%u/%u (step %u/%u)\n",
               fie->stepwise.min.numerator, fie->stepwise.min.denominator,
               fie->stepwise.max.numerator, fie->stepwise.max.denominator,
               fie->stepwise.step.numerator, fie->stepwise.step.denominator);
    } else {
        printf("  (unknown)\n");
    }
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum fse;
    struct v4l2_frmivalenum fie;
    struct v4l2_queryctrl qctrl;
    int ret;
    int has_focus = 0;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus: %s\n", cap.bus_info);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Supported resolutions:\n");
    memset(&fse, 0, sizeof(fse));
    fse.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) == 0) {
        print_resolution(&fse);
        fse.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Supported frame rates:\n");
    memset(&fie, 0, sizeof(fie));
    fie.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fie) == 0) {
        print_frame_rate(&fie);
        fie.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&qctrl, 0, sizeof(qctrl));
    qctrl.id = V4L2_CID_FOCUS_AUTO;
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &qctrl);
    if (ret < 0) {
        if (errno == EINVAL) {
            printf("Autofocus not supported.\n");
        } else {
            fprintf(stderr, "VIDIOC_QUERYCTRL(FOCUS_AUTO) failed: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
    } else {
        has_focus = 1;
        printf("Autofocus supported (current value: %d)\n", qctrl.value);
    }

    close(fd);
    return EXIT_SUCCESS;
}

