#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5
#define UP_BUTTON      6
#define DOWN_BUTTON    7
#define LEFT_BUTTON    8
#define RIGHT_BUTTON   9

#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_CENTER    1500
#define STEP_US         10
#define LOOP_DELAY_US   50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_gpio_write(unsigned pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite(%u, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pull_up_down(unsigned pin, unsigned pud) {
    if (gpioSetPullUpDown(pin, pud) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(%u, %u) failed\n", pin, pud);
        return -1;
    }
    return 0;
}

static int safe_gpio_servo(unsigned pin, unsigned pulse_us) {
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "gpioServo(%u, %u) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (safe_gpio_set_mode(PAN_SERVO_PIN, PI_OUTPUT) < 0 ||
        safe_gpio_set_mode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return -1;
    }

    if (safe_gpio_set_pull_up_down(UP_BUTTON, PI_PUD_UP) < 0 ||
        safe_gpio_set_pull_up_down(DOWN_BUTTON, PI_PUD_UP) < 0 ||
        safe_gpio_set_pull_up_down(LEFT_BUTTON, PI_PUD_UP) < 0 ||
        safe_gpio_set_pull_up_down(RIGHT_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return -1;
    }

    if (safe_gpio_servo(PAN_SERVO_PIN, SERVO_CENTER) < 0 ||
        safe_gpio_servo(TILT_SERVO_PIN, SERVO_CENTER) < 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-tilt control started. Pan=GPIO%d, Tilt=GPIO%d\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons: UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON, DOWN_BUTTON, LEFT_BUTTON, RIGHT_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    int pan_pos  = SERVO_CENTER;
    int tilt_pos = SERVO_CENTER;

    while (g_running) {
        if (gpioRead(UP_BUTTON) == 0) {
            tilt_pos += STEP_US;
            if (tilt_pos > SERVO_MAX_PULSE) tilt_pos = SERVO_MAX_PULSE;
            safe_gpio_servo(TILT_SERVO_PIN, tilt_pos);
        } else if (gpioRead(DOWN_BUTTON) == 0) {
            tilt_pos -= STEP_US;
            if (tilt_pos < SERVO_MIN_PULSE) tilt_pos = SERVO_MIN_PULSE;
            safe_gpio_servo(TILT_SERVO_PIN, tilt_pos);
        }

        if (gpioRead(LEFT_BUTTON) == 0) {
            pan_pos -= STEP_US;
            if (pan_pos < SERVO_MIN_PULSE) pan_pos = SERVO_MIN_PULSE;
            safe_gpio_servo(PAN_SERVO_PIN, pan_pos);
        } else if (gpioRead(RIGHT_BUTTON) == 0) {
            pan_pos += STEP_US;
            if (pan_pos > SERVO_MAX_PULSE) pan_pos = SERVO_MAX_PULSE;
            safe_gpio_servo(PAN_SERVO_PIN, pan_pos);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

