#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_CMD_LEN 512
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_URL_LEN 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_dir(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        if (errno == EEXIST) return 0;
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[MAX_CMD_LEN];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s --width %d --height %d --quality %d --encoding jpg",
        filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_http_request(const char *filename, const char *timestamp, int motion_detected, int gpio_pin) {
    char json_string[MAX_JSON_LEN];
    char url[MAX_URL_LEN];
    int ret = snprintf(json_string, sizeof(json_string),
        "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_detected\": %d, \"gpio_pin\": %d}",
        filename, timestamp, motion_detected, gpio_pin);
    if (ret < 0 || (size_t)ret >= sizeof(json_string)) {
        fprintf(stderr, "JSON buffer too small\n");
        return -1;
    }
    ret = snprintf(url, sizeof(url), "http://%s/upload", "http://<server_ip>:<server_port>/upload");
    if (ret < 0 || (size_t)ret >= sizeof(url)) {
        fprintf(stderr, "URL buffer too small\n");
        return -1;
    }
    FILE *pipe = popen("curl -s -X POST -H \"Content-Type: application/json\" -d @- \"$URL\"", "w");
    if (!pipe) {
        fprintf(stderr, "popen() failed: %s\n", strerror(errno));
        return -1;
    }
    fputs(json_string, pipe);
    fputc('\n', pipe);
    int status = pclose(pipe);
    if (status == -1) {
        fprintf(stderr, "pclose() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "curl failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *server_ip = argv[1];
    const char *server_port = argv[2];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_dir(CAPTURE_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", PIR_GPIO);
            break;
        }
        if (motion) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];
            char filename[MAX_FILENAME_LEN];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

            int ms = (int)((rawtime % 10) * 1000);
            snprintf(filename, sizeof(filename), "%s/%s.%03d_%d.jpg",
                     CAPTURE_DIR, timestamp, ms, PIR_GPIO);

            if (capture_image(filename) != 0) {
                fprintf(stderr, "Failed to capture image\n");
            } else {
                printf("Motion detected on GPIO%d. Saving to %s\n", PIR_GPIO, filename);
                if (send_http_request(filename, timestamp, 1, PIR_GPIO) != 0) {
                    fprintf(stderr, "Failed to send HTTP request\n");
                }
            }
            gpioDelay(DEBOUNCE_SEC * 1000000);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("Motion detection stopped.\n");
    return EXIT_SUCCESS;
}

