#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000
#define CAPTURE_TIMEOUT_MS 2000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static void generate_filename(char *filename, size_t size) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        snprintf(filename, size, "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec, (int)(tm.tm_sec * 1000 % 1000));
    } else {
        snprintf(filename, size, "unknown_timestamp.jpg");
    }
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout %d --nopreview",
             filename, CAPTURE_TIMEOUT_MS);

    int status = system(command);
    if (status == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion-capture") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    log_message("Motion detection started on GPIO17.");

    while (program_running) {
        struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        char filename[256];
        generate_filename(filename, sizeof(filename));

        char full_path[512];
        snprintf(full_path, sizeof(full_path), "%s/%s", IMAGE_DIR, filename);

        if (capture_image(full_path) == 0) {
            char log_msg[512];
            snprintf(log_msg, sizeof(log_msg), "Motion detected, image saved: %s", full_path);
            log_message(log_msg);
        } else {
            char log_msg[512];
            snprintf(log_msg, sizeof(log_msg), "Error capturing image: %s", filename);
            log_message(log_msg);
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    log_message("Motion detection stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

