#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000000  // 2000 kHz for 50 Hz
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range (%d-%d).\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / MAX_ANGLE);
}

int set_servo_angle(int gpio, int angle) {
    int pw = angle_to_pulse_width(angle);
    if (pw < 0) return -1;
    if (gpioPWM(gpio, pw) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    signal(SIGINT, handle_sigint);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Pan-Tilt Camera Mount Control\n");
    printf("Use arrow keys (or 'q' to quit).\n");

    while (keep_running) {
        char c = getchar();
        if (c == 'q') break;

        int new_pan = pan_angle;
        int new_tilt = tilt_angle;

        switch (c) {
            case 'w':
            case 'W':
                new_tilt = tilt_angle + (tilt_angle < MAX_ANGLE ? 5 : 0);
                break;
            case 's':
            case 'S':
                new_tilt = tilt_angle - (tilt_angle > MIN_ANGLE ? 5 : 0);
                break;
            case 'a':
            case 'A':
                new_pan = pan_angle - (pan_angle > MIN_ANGLE ? 5 : 0);
                break;
            case 'd':
            case 'D':
                new_pan = pan_angle + (pan_angle < MAX_ANGLE ? 5 : 0);
                break;
            default:
                continue;
        }

        if (set_servo_angle(PAN_GPIO, new_pan) != 0 ||
            set_servo_angle(TILT_GPIO, new_tilt) != 0) {
            fprintf(stderr, "Error: Failed to set servo angles.\n");
            break;
        }

        pan_angle = new_pan;
        tilt_angle = new_tilt;
        printf("Pan: %d, Tilt: %d\n", pan_angle, tilt_angle);

        gpioDelay(DELAY_MS * 1000);
    }

    // Set servos to neutral position
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

