        fprintf(stderr, "Error reading temperature value\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int read_cpu_usage(float *usage) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Error opening /proc/stat");
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_user_total = 0, prev_idle_total = 0;
    unsigned long long user_total = user + nice + system + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;
    unsigned long long total = user_total + idle_total;
    unsigned long long prev_total = prev_user_total + prev_idle_total;
    if (prev_total == 0) {
        prev_user_total = user_total;
        prev_idle_total = idle_total;
        return 0;
    }
    float diff_idle = (float)(idle_total - prev_idle_total);
    float diff_total = (float)(total - prev_total);
    *usage = 100.0f - (diff_idle / diff_total) * 100.0f;
    prev_user_total = user_total;
    prev_idle_total = idle_total;
    return 0;
}

static int update_display(float temp, float usage) {
    char temp_str[16], usage_str[16];
    snprintf(temp_str, sizeof(temp_str), "%.1f C", temp);
    snprintf(usage_str, sizeof(usage_str), "%.1f%%", usage);
    if (oled_clear() != 0) return -1;
    if (oled_draw_string(0, 0, temp_str) != 0) return -1;
    if (oled_draw_string(0, 10, usage_str) != 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SSD1306_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (oled_init() != 0) {
        fprintf(stderr, "OLED initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temp, usage;
    while (running) {
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Error reading CPU temperature\n");
            temp = -1.0f;
        }
        if (read_cpu_usage(&usage) != 0) {
            fprintf(stderr, "Error reading CPU usage\n");
            usage = -1.0f;
        }
        if (update_display(temp, usage) != 0) {
            fprintf(stderr, "Error updating display\n");
        }
        sleep(1);
    }

    oled_clear();
    oled_command(OLED_CMD_DISPLAY_OFF);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

