#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16

static volatile int pulse_count = 0;
static volatile int running_total = 0;
static volatile int i2c_handle = -1;
static volatile int running = 1;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_count++;
    }
}

void signal_handler(int signal) {
    running = 0;
}

void lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return;
    }

    gpioDelay(50000);

    i2cWriteByte(i2c_handle, 0x33);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x32);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x28);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x08);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x01);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x06);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x0C);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x00);
    gpioDelay(5000);
    i2cWriteByte(i2c_handle, 0x06);
    gpioDelay(5000);
}

void lcd_clear() {
    i2cWriteByte(i2c_handle, 0x01);
    gpioDelay(2000);
}

void lcd_set_cursor(int row, int col) {
    int address = (row == 0) ? 0x80 + col : 0xC0 + col;
    i2cWriteByte(i2c_handle, address);
    gpioDelay(2000);
}

void lcd_write_string(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        i2cWriteByte(i2c_handle, str[i]);
        gpioDelay(2000);
    }
}

void lcd_write_line(int row, const char *str) {
    lcd_set_cursor(row, 0);
    lcd_write_string(str);
}

void lcd_display_flow_rate(float flow_rate, int total_volume) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Total: %d L", total_volume);

    lcd_clear();
    lcd_write_line(0, line1);
    lcd_write_line(1, line2);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    lcd_init();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t last_update = time(NULL);

    while (running) {
        time_t current_time = time(NULL);
        if (current_time - last_update >= 1) {
            int current_pulse_count = pulse_count;
            pulse_count = 0;

            float flow_rate = (current_pulse_count / PULSES_PER_LITER) * 60.0;
            running_total += (current_pulse_count / PULSES_PER_LITER);

            printf("Flow Rate: %.2f L/min, Total Volume: %d L\n", flow_rate, running_total);

            lcd_display_flow_rate(flow_rate, running_total);

            last_update = current_time;
        }
        gpioDelay(100000);
    }

