#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define ADC_STUCK_THRESHOLD 10

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static int i2c_handle = -1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static int lcd_init(void) {
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", LCD_I2C_ADDR, i2c_handle);
        return -1;
    }
    gpioDelay(50000);
    uint8_t init_cmds[] = {0x33, 0x32, 0x28, 0x0C, 0x06, 0x01};
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (i2cWriteByte(i2c_handle, init_cmds[i]) < 0) {
            fprintf(stderr, "Error sending LCD init byte %zu\n", i);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            return -1;
        }
        gpioDelay(5000);
    }
    return 0;
}

static void lcd_clear(void) {
    if (i2c_handle < 0) return;
    i2cWriteByte(i2c_handle, 0x01);
    gpioDelay(2000);
}

static void lcd_send_byte(uint8_t val, uint8_t mode) {
    if (i2c_handle < 0) return;
    uint8_t high = (val & 0xF0) | mode;
    uint8_t low = ((val << 4) & 0xF0) | mode;
    if (i2cWriteByte(i2c_handle, high) < 0) {
        fprintf(stderr, "Error sending LCD high byte\n");
        return;
    }
    gpioDelay(1);
    if (i2cWriteByte(i2c_handle, low) < 0) {
        fprintf(stderr, "Error sending LCD low byte\n");
        return;
    }
    gpioDelay(1);
}

