        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP);

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Error setting ISR for GPIO %d\n", ANEMOMETER_GPIO);
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint32_t pulses = pulse_count;
        pulse_count = 0;

        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC channel %d\n", ADC_CHANNEL);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        check_sensor_stuck(adc_value);

        float speed = calculate_wind_speed(pulses);
        float direction = calculate_wind_direction(adc_value);

        display_data(speed, direction);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
