}

void lcd_write_nibble(int handle, unsigned char nibble, int rs) {
    unsigned char data;
    if (rs) data = nibble | 0x0D;
    else data = nibble | 0x0C;
    if (i2cWriteByte(handle, data) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
    }
    gpioDelay(1);
}

void lcd_send_command(int handle, unsigned char cmd) {
    lcd_write_nibble(handle, cmd & 0xF0, 0);
    lcd_write_nibble(handle, (cmd << 4) & 0xF0, 0);
    if ((cmd == 0x01) || (cmd == 0x02)) gpioDelay(2000);
    else gpioDelay(50);
}

void lcd_send_data(int handle, unsigned char data) {
    lcd_write_nibble(handle, data & 0xF0, 1);
    lcd_write_nibble(handle, (data << 4) & 0xF0, 1);
    gpioDelay(50);
}

void lcd_string(int handle, const char *s) {
    while (*s) lcd_send_data(handle, (unsigned char)*s++);
}

void lcd_clear(int handle) {
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

void lcd_set_cursor(int handle, int row, int col) {
    unsigned char addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_command(handle, addr);
}

void lcd_init(int handle) {
    gpioDelay(50000);
    lcd_send_command(handle, 0x30);
    gpioDelay(5000);
    lcd_send_command(handle, 0x30);
    gpioDelay(150);
    lcd_send_command(handle, 0x30);
    gpioDelay(150);
    lcd_send_command(handle, 0x20);
    gpioDelay(2000);
    lcd_send_command(handle, 0x28);
    lcd_send_command(handle, 0x08);
    lcd_send_command(handle, 0x01);
    lcd_clear(handle);
    lcd_send_command(handle, 0x06);
}

void display_flow_rate(int handle, float flow_rate) {
    char buffer[20];
    lcd_clear(handle);
    lcd_set_cursor(handle, 0, 0);
    lcd_string(handle, "Flow Rate:");
    lcd_set_cursor(handle, 1, 0);
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_string(handle, buffer);
}

void cleanup() {
    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        lcd_string(i2c_handle, "Shutting down...");
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init(i2c_handle);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        static int pulse_count = 0;
        pulse_count = 0;
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);

        if (!running) break;

        int current_pulse_count = pulse_count;
        float flow_rate = (float)current_pulse_count / PULSES_PER_LITER * 60.0;

        if (current_pulse_count == 0) {
            fprintf(stderr, "Warning: No pulses detected for %d seconds. Sensor may be absent or disconnected.\n", SAMPLE_INTERVAL_SEC);
        }

        display_flow_rate(i2c_handle, flow_rate);
        printf("Flow Rate: %.2f L/min\n", flow_rate);
    }

    cleanup();
    return EXIT_SUCCESS;
}

