#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

// GPIO chip and line numbers for Raspberry Pi 40-pin header
static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_lines(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    // Set up signal handlers for clean exit
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip 0 (Raspberry Pi)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    // Request row lines as outputs, initially HIGH (anodes off)
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            release_lines();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(row_lines[i], "led-matrix", 1) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            release_lines();
            return EXIT_FAILURE;
        }
    }

    // Request column lines as outputs, initially LOW (cathodes off)
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %u\n", col_pins[i]);
            release_lines();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(col_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Failed to request column line %u as output\n", col_pins[i]);
            release_lines();
            return EXIT_FAILURE;
        }
    }

    // Wave pattern: column by column, scan left to right
    while (keep_running) {
        for (int col = 0; col < NUM_COLS && keep_running; col++) {
            // Clear matrix: set all cathodes HIGH (off), all anodes LOW (off)
            for (int i = 0; i < NUM_COLS; i++) {
                gpiod_line_set_value(col_lines[i], 1);
            }
            for (int i = 0; i < NUM_ROWS; i++) {
                gpiod_line_set_value(row_lines[i], 0);
            }
            usleep(DELAY_MS * 1000);

            // Light column: set cathode LOW (off), anode HIGH (on) for each row
            for (int row = 0; row < NUM_ROWS; row++) {
                gpiod_line_set_value(col_lines[col], 0);
                gpiod_line_set_value(row_lines[row], 1);
                usleep(DELAY_MS * 1000);
            }
            // Turn off column and all rows
            for (int i = 0; i < NUM_ROWS; i++) {
                gpiod_line_set_value(row_lines[i], 0);
            }
            gpiod_line_set_value(col_lines[col], 1);
            usleep(DELAY_MS * 1000);
        }
    }

    // Clean exit
    release_lines();
    return EXIT_SUCCESS;
}

