#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L3CX_ADDR 0x29
#define I2C_BUS 1
#define NUM_TARGETS 4
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t distance;
    uint8_t status;
} TargetData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: I2C read block from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l3cx_init(void) {
    uint8_t model_id = 0;
    if (i2c_read_reg(0x010F, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
