#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000  /* 500 ms */

/* Si1145 register addresses */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_IRQ_ENABLE 0x0F
#define REG_IRQ_STATUS 0x12
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0    0x24
#define REG_PS1_DATA1    0x25
#define REG_COMMAND      0x18

#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x05
#define CMD_ALS_FORCE   0x06
#define CMD_PSALS_FORCE 0x07

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int si1145_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
    return rc;
}

static int si1145_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[WARN] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int si1145_init(int handle)
{
    uint8_t part_id = 0;

    if (si1145_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }
    printf("[INFO] Si1145 detected (PART_ID=0x%02X).\n", part_id);

    /* Clear any stale IRQ status */
    if (si1145_write_reg(handle, REG_IRQ_STATUS, 0x00) < 0)
        return -1;

    /* Write HW_KEY (required for proper operation) */
    if (si1145_write_reg(handle, REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Set measurement rates: PS1 rate = 0x0A (10 Hz), ALS_VIS rate = 0x0A (10 Hz) */
    if (si1145_write_reg(handle, REG_MEAS_RATE0, 0x0A) < 0)
        return -1;
    if (si1145_write_reg(handle, REG_MEAS_RATE1, 0x0A) < 0)
        return -1;

    /* Enable PS1 and ALS_VIS interrupts */
    if (si1145_write_reg(handle, REG_IRQ_ENABLE, 0x03) < 0)
        return -1;

    /* Issue a forced measurement to warm up */
    if (si1145_write_reg(handle, REG_COMMAND, CMD_PSALS_FORCE) < 0)
        return -1;

    return 0;
}

static int si1145_read_data(int handle, uint16_t *prox, uint16_t *als)
{
    uint8_t lo, hi;

    if (si1145_read_reg(handle, REG_PS1_DATA0, &lo) < 0)
        return -1;
    if (si1145_read_reg(handle, REG_PS1_DATA1, &hi) < 0)
        return -1;
    *prox = ((uint16_t)hi << 8) | lo;

    if (si1145_read_reg(handle, REG_ALS_VIS_DATA0, &lo) < 0)
        return -1;
    if (si1145_read_reg(handle, REG_ALS_VIS_DATA1, &hi) < 0)
        return -1;
    *als = ((uint16_t)hi << 8) | lo;

    return 0;
}

static void log_data(FILE *fp, uint16_t prox, uint16_t als)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", ts, prox, als);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Si1145 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t prox = 0, als = 0;

        if (si1145_read_data(g_i2c_handle, &prox, &als) == 0) {
            log_data(g_log_file, prox, als);
        } else {
            fprintf(stderr, "[ERROR] I2C read failed — logging error entry.\n");
            fprintf(g_log_file, "%s, ERROR: I2C read failed\n", "");
            fflush(g_log_file);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    fclose(g_log_file);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

