#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60

#define REG_PART_ID 0x00
#define REG_HW_KEY  0x07
#define REG_CH_LIST 0x4F
#define REG_COMMAND 0x30
#define REG_PS1_DATA0 0x18
#define REG_ALS_VIS_DATA0 0x22

#define CMD_PS_FORCE 0x07
#define CMD_ALS_FORCE 0x06
#define CMD_PS_AUTO 0x0D
#define CMD_ALS_AUTO 0x0E

#define EXPECTED_PART_ID 0x45
#define HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int i2c_read_byte(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(uint8_t reg, uint16_t *val) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint16_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (i2c_read_byte(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1145 detected, PART_ID=0x%02X\n", part_id);

    if (i2c_write_byte(REG_HW_KEY, HW_KEY_VAL) != 0) return -1;

    if (i2c_write_byte(REG_CH_LIST, 0x03) != 0) return -1;

    if (i2c_write_byte(REG_COMMAND, CMD_PS_AUTO) != 0) return -1;
    if (i2c_write_byte(REG_COMMAND, CMD_ALS_AUTO) != 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *prox) {
    if (i2c_write_byte(REG_COMMAND, CMD_PS_FORCE) != 0) return -1;
    gpioDelay(10000);
    return i2c_read_word(REG_PS1_DATA0, prox);
}

static int read_ambient_light(uint16_t *als) {
    if (i2c_write_byte(REG_COMMAND, CMD_ALS_FORCE) != 0) return -1;
    gpioDelay(10000);
    return i2c_read_word(REG_ALS_VIS_DATA0, als);
}

static void log_data(uint16_t prox, uint16_t als) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, prox, als);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Logging data to biometric_data.log. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox = 0, als = 0;

        if (read_proximity(&prox) != 0) {
            fprintf(stderr, "Proximity read failed, retrying...\n");
            sleep(1);
            continue;
        }

        if (read_ambient_light(&als) != 0) {
            fprintf(stderr, "Ambient light read failed, retrying...\n");
            sleep(1);
            continue;
        }

        log_data(prox, als);
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

