        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Logging data to biometric_data.log. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox = 0, als = 0;

        if (read_proximity(&prox) != 0) {
            fprintf(stderr, "Proximity read failed, retrying...\n");
            sleep(1);
            continue;
        }

        if (read_ambient_light(&als) != 0) {
            fprintf(stderr, "Ambient light read failed, retrying...\n");
            sleep(1);
            continue;
        }

        log_data(prox, als);
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

