#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define WATERING_THRESHOLD 15.0
#define POLL_INTERVAL_SEC 60
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS 30
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static void log_distance(float distance) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Distance = %.2f cm\n", ts, distance);
    fflush(log_file);
}

static void log_watering_reminder(void) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Time to water the plant!\n", ts);
    fflush(log_file);
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 1) < 0) {
        log_message("Error: Failed to set trigger high");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_message("Error: Failed to set trigger low");
        return -1;
    }
    return 0;
}

static float measure_distance(struct gpiod_line *echo) {
    struct timespec start, end, timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = ECHO_TIMEOUT_MS * 1000000L;

    if (gpiod_line_event_wait(echo, &timeout) < 0) {
        log_message("Error: Echo event wait failed");
        return -1.0;
    }

    struct gpiod_line_event event;
    if (gpiod_line_event_read(echo, &event) < 0) {
        log_message("Error: Failed to read echo event");
        return -1.0;
    }

    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        start = event.ts;
    } else {
        log_message("Error: Echo stuck high (timeout)");
        return -1.0;
    }

    if (gpiod_line_event_wait(echo, &timeout) < 0) {
        log_message("Error: Echo event wait failed");
        return -1.0;
    }

    if (gpiod_line_event_read(echo, &event) < 0) {
        log_message("Error: Failed to read echo event");
        return -1.0;
    }

    if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        end = event.ts;
    } else {
        log_message("Error: Echo never fell (sensor absent)");
        return -1.0;
    }

    double diff_sec = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    float distance = (float)((diff_sec * SPEED_OF_SOUND) / 2.0);

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Warning: Distance out of range: %.2f cm", distance);
        log_message(msg);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line (trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_both_edges_events(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_both_edges_events (echo)");
        goto cleanup;
    }

    log_message("Program started");

    while (program_running) {
        if (trigger_sensor(trigger) < 0) {
            log_message("Error: Trigger failed");
        } else {
            float distance = measure_distance(echo);
            if (distance < 0) {
                log_message("Error: Measurement failed");
            } else {
                log_distance(distance);
                if (distance < WATERING_THRESHOLD) {
                    log_watering_reminder();
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Program exiting");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    return ret;
}

