#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x39
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    char val_buf[1];
    if (i2cReadDevice(i2c_handle, val_buf, 1) != 1) return -1;
    *value = (uint8_t)val_buf[0];
    return 0;
}

static int i2c_read_word(uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_reg(reg_low, &low) != 0) return -1;
    if (i2c_read_reg(reg_low + 1, &high) != 0) return -1;
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

static int apds9960_init(void) {
    uint8_t id;
    if (i2c_read_reg(APDS9960_ID, &id) != 0) {
        fprintf(stderr, "Error: Failed to read ID register.\n");
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Error: Invalid sensor ID (0x%02X). Expected 0xAB.\n", id);
        return -1;
    }
    if (i2c_write_reg(APDS9960_ENABLE, 0x00) != 0) return -1;
    if (i2c_write_reg(APDS9960_ATIME, 0xDB) != 0) return -1;
    if (i2c_write_reg(APDS9960_WTIME, 0xF6) != 0) return -1;
    if (i2c_write_reg(APDS9960_PPULSE, 0x87) != 0) return -1;
    if (i2c_write_reg(APDS9960_CONTROL, 0x03) != 0) return -1;
    if (i2c_write_reg(APDS9960_CONFIG2, 0x01) != 0) return -1;
    if (i2c_write_reg(APDS9960_ENABLE, 0x03) != 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *proximity) {
    if (i2c_read_word(APDS9960_CDATAL, red) != 0) return -1;
    if (i2c_read_word(APDS9960_RDATAL, green) != 0) return -1;
    if (i2c_read_word(APDS9960_GDATAL, blue) != 0) return -1;
    if (i2c_read_word(APDS9960_PDATAL, proximity) != 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (apds9960_init() != 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed.\n");
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    fflush(log_file);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (!terminate) {
        uint16_t red, green, blue, proximity;
        if (read_sensor_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error: I2C communication error. Re-initializing sensor.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed (%d).\n", i2c_handle);
                terminate = 1;
            } else {
                if (apds9960_init() != 0) {
                    fprintf(stderr, "Error: APDS9960 re-initialisation failed.\n");
                    terminate = 1;
                }
            }
        }
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

