    if (i2c_write_reg(APDS9960_CONTROL, 0x03) != 0) return -1;
    if (i2c_write_reg(APDS9960_CONFIG2, 0x01) != 0) return -1;
    if (i2c_write_reg(APDS9960_ENABLE, 0x03) != 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *proximity) {
    if (i2c_read_word(APDS9960_CDATAL, red) != 0) return -1;
    if (i2c_read_word(APDS9960_RDATAL, green) != 0) return -1;
    if (i2c_read_word(APDS9960_GDATAL, blue) != 0) return -1;
    if (i2c_read_word(APDS9960_PDATAL, proximity) != 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (apds9960_init() != 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed.\n");
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    fflush(log_file);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (!terminate) {
        uint16_t red, green, blue, proximity;
        if (read_sensor_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error: I2C communication error. Re-initializing sensor.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed (%d).\n", i2c_handle);
                terminate = 1;
            } else {
                if (apds9960_init() != 0) {
                    fprintf(stderr, "Error: APDS9960 re-initialisation failed.\n");
                    terminate = 1;
                }
            }
        }
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

