/*
 * Si1182-A-GMR heart-rate monitor for Raspberry Pi 5 (Linux i2c-dev)
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   Si1182 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_hr si1182_hr.c
 * Run:    ./si1182_hr   (user must be in the 'i2c' group or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- Si1182 register map (subset) ---- */
#define SI1182_I2C_ADDR        0x5A
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_COMMAND     0x47
#define SI1182_REG_PS_DATA0    0x24
#define SI1182_REG_PS_DATA1    0x25

#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_CMD_RESET       0x01
#define SI1182_CMD_START       0x07

#define SAMPLE_PERIOD_MS       100
#define CSV_FILENAME           "heartrate.csv"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1182 register using i2c_smbus_write_byte.
 * Returns 0 on success, -1 on error. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    if (i2c_smbus_write_byte_data(fd, reg, value) < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1182 register using i2c_smbus_read_byte.
 * Returns the byte value (0-255) on success, -1 on error. */
static int si1182_read_reg(int fd, uint8_t reg)
{
    int val = i2c_smbus_read_byte_data(fd, reg);
    if (val < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair.
 * Returns 0 on success and stores the value in *out; -1 on error. */
static int si1182_read_reg16(int fd, uint8_t reg_lo, uint16_t *out)
{
    int lo = si1182_read_reg(fd, reg_lo);
    if (lo < 0)
        return -1;

    int hi = si1182_read_reg(fd, reg_lo + 1);
    if (hi < 0)
        return -1;

    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    int part_id = si1182_read_reg(fd, SI1182_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr,
                "Unexpected PART_ID: 0x%02X (expected 0x%02X). "
                "Wrong sensor or wrong address.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* Configure measurement rate: 0x08 = 100 ms (typical for proximity). */
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE0, 0x08) < 0)
        return -1;

    /* Reset the device (soft reset). */
    if (si1182_write_reg(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle after reset */

    /* Start continuous proximity measurements. */
    if (si1182_write_reg(fd, SI1182_REG_COMMAND, SI1182_CMD_START) < 0)
        return -1;

    usleep(20000);  /* 20 ms for first measurement to be ready */
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int bpm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(fp, "%s,%d\n", ts, bpm);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1182_init(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* ---- Open CSV log ---- */
    FILE *csv = fopen(CSV_FILENAME, "a");
    if (!csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Logging heart-rate data to %s (Ctrl+C to stop).\n", CSV_FILENAME);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t prox = 0;
        if (si1182_read_reg16(fd, SI1182_REG_PS_DATA0, &prox) < 0) {
            fprintf(stderr, "Warning: failed to read proximity data.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        /* Placeholder BPM calculation — replace with real HR algorithm. */
        int bpm = (int)(prox / 100);  /* arbitrary scaling */
        if (bpm < 0) bpm = 0;

        log_sample(csv, bpm);
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    fclose(csv);
    close(fd);
    return EXIT_SUCCESS;
}

