#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER 17
#define I2C_BUS 1

#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int vl53l0x_write_byte(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_byte(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) failed for reg 0x%02X\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read failed for reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int vl53l0x_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) failed for block read at 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: I2C read failed for block at 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l0x_init(void) {
    uint8_t model_id = 0;
    if (vl53l0x_read_byte(0x010F, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(uint16_t *distance_mm) {
    if (vl53l0x_write_byte(VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    uint8_t int_status = 0;
    int timeout = 100;
    while (timeout-- > 0) {
        if (vl53l0x_read_byte(VL53L0X_REG_RESULT_INT_STATUS, &int_status) != 0) {
            return -1;
        }
        if (int_status & 0x01) {
            break;
        }
        gpioDelay(1000);
    }
    if (timeout <= 0) {
        fprintf(stderr, "Error: Timeout waiting for measurement\n");
        return -1;
    }

    uint8_t range_status = 0;
    if (vl53l0x_read_byte(VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        return -1;
    }

    uint8_t data[14];
    if (vl53l0x_read_block(VL53L0X_REG_RESULT_RANGE_STATUS, data, 14) != 0) {
        return -1;
    }

    if (vl53l0x_write_byte(VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    *distance_mm = ((uint16_t)data[10] << 8) | data[11];
    return 0;
}

static void log_distance(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init() != 0) {
        fprintf(stderr, "Error: VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (gpioRead(GPIO_TRIGGER) == 0) {
            uint16_t distance_mm = 0;
            if (vl53l0x_read_distance(&distance_mm) == 0) {
                log_distance(distance_mm);
                printf("Distance: %u mm\n", distance_mm);
            } else {
                fprintf(stderr, "Error: Failed to read distance\n");
            }
            while (gpioRead(GPIO_TRIGGER) == 0) {
                gpioDelay(1000);
            }
        }
        gpioDelay(10000);
    }

    printf("\nExiting gracefully...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

