#define READ_LEN       2
#define SAMPLE_US      200000   /* 200 ms */
#define SETTLE_US      50000    /* 50 ms  */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL)
        return -1;
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0)
        return -1;
    return 0;
}

static int log_data(const char *timestamp, int distance_mm)
{
