        return -1;
    if (fflush(g_log_file) != 0)
        return -1;
    return 0;
}

static int read_distance(int handle, int *distance_mm)
{
    char cmd = TRIGGER_CMD;
    char buf[READ_LEN];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write trigger command to I2C device.\n");
        return -1;
    }

    gpioDelay(SETTLE_US);

    if (i2cReadDevice(handle, buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: failed to read distance data from I2C device.\n");
        return -1;
    }

    *distance_mm = ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

int main(void)
{
    char timestamp[32];
    int  distance_mm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d, addr 0x%02X (pigpio error %d).\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open distance_log.txt for appending.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Starting distance measurements on CH101 at I2C bus %d, addr 0x%02X. Press Ctrl-C to stop.\n",
           I2C_BUS, CH101_ADDR);

    while (g_running) {
        if (read_distance(g_i2c_handle, &distance_mm) == 0) {
            if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_data(timestamp, distance_mm) != 0) {
                    fprintf(stderr, "Error: failed to write to log file.\n");
                } else {
                    printf("%s, Distance: %d mm\n", timestamp, distance_mm);
                }
            } else {
                fprintf(stderr, "Error: failed to generate timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error: failed to read distance, will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

