#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", GPIO_LED);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO %d to LOW.\n", GPIO_LED);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (expected 2 bytes, got %d).\n", bytes_read);
        return -1;
    }
    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *distance = (float)raw / 10.0f;
    return 0;
}

