#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, uint8_t reg, uint16_t *value) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d, retries left: %d\n", reg, result, retries - 1);
        gpioDelay(10000);
        retries--;
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return 1;
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0;
        uint16_t ambient = 0;

        if (read_sensor_data(i2c_handle, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data after retries.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_sensor_data(i2c_handle, AMBIENT_REG, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient data after retries.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(log_file, proximity, ambient) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up and exiting...\n");
    cleanup();
    return 0;
}

