#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define DEFAULT_THRESHOLD 100
#define MEASUREMENT_DELAY_US 10000
#define LOOP_DELAY_US 50000

#define ICU20201_REG_WHO_AM_I 0x00
#define ICU20201_REG_DISTANCE 0x04
#define ICU20201_WHO_AM_I_VAL 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, int *distance) {
    char reg = (char)ICU20201_REG_DISTANCE;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set register pointer for distance read.\n");
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

static int log_data(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

static void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    char reg = (char)ICU20201_REG_WHO_AM_I;
    char who_am_i_val;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set register pointer for WHO_AM_I.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cReadDevice(i2c_handle, &who_am_i_val, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if ((uint8_t)who_am_i_val != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present or wrong device.\n", (uint8_t)who_am_i_val, ICU20201_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 Ultrasonic ToF Sensor Interface\n");
    printf("Threshold: %d mm\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            if (distance < threshold) {
                control_led(LED_GPIO, 1);
            } else {
                control_led(LED_GPIO, 0);
            }
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

