        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[CMD_LEN] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, CMD_LEN) != 0) {
        return -1;
    }

    usleep(10000); /* 10 ms measurement delay */

    if (i2c_read_resp(fd, resp, RESP_LEN) != 0) {
        return -1;
    }

    if (resp[0] != 0x50) {
        fprintf(stderr, "Unexpected response header: 0x%02X (expected 0x50)\n", resp[0]);
        return -1;
    }

    *distance_mm = (resp[11] << 8) | resp[12];
    return 0;
}

static int detect_intrusion(int distance_mm) {
    return (distance_mm > 0 && distance_mm < INTRUSION_THRESHOLD_MM) ? 1 : 0;
}

