                printf("Intrusion detected! Average distance: %d mm\n", avg_mm);
            }
        } else {
            fprintf(stderr, "No valid samples in this cycle.\n");
        }

        usleep(100000); /* 100 ms between cycles */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

