#define VL53L0X_ADDR 0x29
#define I2C_BUS 1

#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

#define VL53L0X_MODEL_ID 0xEE
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_US 500000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
    }
    return rc;
}

static int init_sensor(void) {
    int model_id = i2c_read_byte(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, VL53L0X_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);
    return 0;
}

