    int elapsed = 0;
    do {
        status = i2c_read_byte(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            return -1;
        }
        gpioDelay(1000);
        elapsed += 1000;
        if (elapsed >= POLL_TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for ranging result\n");
            return -1;
        }
    } while ((status & 0x01) == 0);

    int distance = i2c_read_word(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (distance < 0) {
        return -1;
    }

    if (i2c_write_byte(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    return distance;
}

static void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance);
    fflush(stdout);
