        fprintf(stderr, "Failed to open I2C device on bus %d addr 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance readings (Ctrl+C to exit)...\n");

    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

