#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1182_ADDR        0x39
#define SI1182_REG_CONFIG  0x18
#define SI1182_REG_IRQ_ST  0x25
#define SI1182_REG_PS1_LSB 0x2A
#define SI1182_REG_PS1_MSB 0x2B

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int si1182_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

static int si1182_read_proximity(int handle)
{
    int lsb = si1182_read_reg(handle, SI1182_REG_PS1_LSB);
    if (lsb < 0) return -1;

    int msb = si1182_read_reg(handle, SI1182_REG_PS1_MSB);
    if (msb < 0) return -1;

    return (msb << 8) | lsb;
}

static int si1182_init(int handle)
{
    /* Proximity mode: enable PS1 */
    if (si1182_write_reg(handle, SI1182_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (config write failed)\n",
                SI1182_ADDR);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        int irq = si1182_read_reg(g_i2c_handle, SI1182_REG_IRQ_ST);
        if (irq < 0) {
            fprintf(stderr, "IRQ status read failed; continuing\n");
            gpioDelay(500000);
            continue;
        }

        if (irq & 0x01) {
            int proximity = si1182_read_proximity(g_i2c_handle);
            if (proximity >= 0) {
                printf("Proximity: %d\n", proximity);
            } else {
                fprintf(stderr, "Proximity read failed\n");
            }
        }

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

