#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_CH0_RESULT 0x00
#define REG_AMBIENT_RESULT 0x02
#define REG_CONFIG 0x0A
#define REG_SYSTEM_CONFIG 0x0B
#define REG_ERROR_STATUS 0x0C

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int opt3101_write_reg(uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to write to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int opt3101_read_reg(uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error: Failed to set register pointer 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int opt3101_init(void) {
    if (opt3101_write_reg(REG_CONFIG, 0x0001) != 0) return -1;
    if (opt3101_write_reg(REG_SYSTEM_CONFIG, 0x0001) != 0) return -1;
    return 0;
}

static int opt3101_read_distance(uint16_t *distance) {
    return opt3101_read_reg(REG_CH0_RESULT, distance);
}

static int opt3101_read_ambient(uint16_t *ambient) {
    return opt3101_read_reg(REG_AMBIENT_RESULT, ambient);
}

static int opt3101_read_error_status(uint16_t *error_status) {
    return opt3101_read_reg(REG_ERROR_STATUS, error_status);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", OPT3101_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3101_init() != 0) {
        fprintf(stderr, "Error: OPT3101 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("OPT3101 Distance Sensor Logging Started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance, ambient, error_status;

        if (opt3101_read_distance(&distance) != 0) {
            fprintf(stderr, "Error: Failed to read distance data\n");
        } else if (opt3101_read_ambient(&ambient) != 0) {
            fprintf(stderr, "Error: Failed to read ambient data\n");
        } else if (opt3101_read_error_status(&error_status) != 0) {
            fprintf(stderr, "Error: Failed to read error status\n");
        } else {
            printf("Distance: %u mm, Ambient: %u, Error Status: 0x%04X\n", distance, ambient, error_status);
        }

        gpioDelay(500000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

