/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (not wiringPi)
 *
 * Wiring:
 *   VCC  -> 5V  (Pin 2)
 *   GND  -> GND (Pin 6)
 *   TRIG -> GPIO 17 (Pin 11)
 *   ECHO -> GPIO 18 (Pin 12) via 1k Ohm resistor (Pin 14)
 *
 * NOTE: The HC-SR04 operates at 5V logic levels. The Pi GPIO pins are
 * 3.3V tolerant. A 1k Ohm resistor is placed in series on the echo
 * line to protect the Pi from damage from the 5V signal.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms echo timeout            */
#define LOOP_DELAY_US    1000000     /* 1 second between readings      */
#define MAX_DISTANCE_CM  400.0f      /* HC-SR04 max range (mm) / 1000 */
#define SPEED_OF_SOUND_CM_PER_US 0.0343f /* 343 m/s in cm/us            */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04: drive TRIG high for 10 us, then low            */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Measure the echo pulse width in microseconds.                      */
/* Returns: pulse width in us, or -1 on timeout/error.                 */
/* ------------------------------------------------------------------ */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_start;

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1;  /* No echo received — sensor not responding */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -2;  /* Echo stuck high — object out of range */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (us) to distance (cm).                          */
/* Returns: distance in cm, or -1.0 on invalid pulse.                  */
/* ------------------------------------------------------------------ */
static float calculate_distance(long pulse_us)
{
    if (pulse_us <= 0 || pulse_us > (long)(MAX_DISTANCE_CM * 1000.0f)) {
        return -1.0f;
    }
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with a timestamp.                                     */
/* ------------------------------------------------------------------ */
static void log_reading(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance < 0.0f) {
        printf("[%s] Distance: ERROR (pulse=%ld us)\n", timestamp, (long)distance);
    } else {
        printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    printf("HC-SR04 distance sensor started.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Max range: %.0f cm | Pulse: %d us | Loop: 1 s\n",
           MAX_DISTANCE_CM, TRIGGER_PULSE_US);
    printf("  Press Ctrl+C to exit.\n\n");

    /* Main loop — repeat once per second until signal received */
    while (g_running) {
        trigger_sensor();

        long pulse_us = measure_echo_pulse();
