#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define RANGE_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define FRAME_SIZE (128 + 8)
#define MAGIC_WORD_LEN 8
#define MAGIC_WORD_0 0x02
#define MAGIC_WORD_1 0x01
#define MAGIC_WORD_2 0x04
#define MAGIC_WORD_3 0x03
#define MAGIC_WORD_4 0x06
#define MAGIC_WORD_5 0x05
#define MAGIC_WORD_6 0x08
#define MAGIC_WORD_7 0x07

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static const uint8_t MAGIC_WORD[MAGIC_WORD_LEN] = {
    MAGIC_WORD_0, MAGIC_WORD_1, MAGIC_WORD_2, MAGIC_WORD_3,
    MAGIC_WORD_4, MAGIC_WORD_5, MAGIC_WORD_6, MAGIC_WORD_7
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            return 0;
        }
        total += (size_t)n;
    }
    return (int)total;
}

static int find_magic_word(int fd) {
    uint8_t byte;
    int idx = 0;
    while (running) {
        ssize_t n = read(fd, &byte, 1);
        if (n < 0) {
            perror("Error reading magic word");
            return -1;
        }
        if (n == 0) {
            return 0;
        }
        if (byte == MAGIC_WORD[idx]) {
            idx++;
            if (idx == MAGIC_WORD_LEN) {
                return 1;
            }
        } else {
            idx = 0;
        }
    }
    return 0;
}

static int read_range_profile(int fd, uint16_t *range_profile) {
    uint8_t buf[FRAME_SIZE];

    if (find_magic_word(fd) != 1) {
        return -1;
    }

    if (read_exact(fd, buf, FRAME_SIZE) != FRAME_SIZE) {
        fprintf(stderr, "Error: Incomplete frame received.\n");
        return -1;
    }

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        range_profile[i] = (uint16_t)(buf[8 + i * 2] | (buf[8 + i * 2 + 1] << 8));
    }
    return 0;
}

static float calculate_distance(const uint16_t *range_profile) {
    int max_bin = 0;
    for (int i = 1; i < NUM_RANGE_BINS; i++) {
        if (range_profile[i] > range_profile[max_bin]) {
            max_bin = i;
        }
    }
    return (float)max_bin * RANGE_RESOLUTION;
}

static void trigger_alert(float distance) {
    printf("Intrusion detected! Distance: %.2f meters\n", distance);
    gpioWrite(GPIO_LED, 1);
    gpioDelay(2000000);
    gpioWrite(GPIO_LED, 0);
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance(m)\n");
        fflush(log_file);
    }

    uint16_t range_profile[NUM_RANGE_BINS];

    while (running) {
        if (read_range_profile(uart_fd, range_profile) == 0) {
            float distance = calculate_distance(range_profile);
            if (distance < RANGE_THRESHOLD) {
                trigger_alert(distance);
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Error reading range profile.\n");
        }
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    return 0;
}

