#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DIST_HIGH_REG  0x31
#define DIST_LOW_REG   0x32
#define ALERT_GPIO     17
#define DIST_THRESHOLD 10.0f
#define SAMPLE_US      100000
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance)
{
    int hi = i2cReadByteData(g_i2c_handle, DIST_HIGH_REG);
    if (hi < 0) {
        fprintf(stderr, "I2C read error (high byte): %d\n", hi);
        return -1;
    }
    int lo = i2cReadByteData(g_i2c_handle, DIST_LOW_REG);
    if (lo < 0) {
        fprintf(stderr, "I2C read error (low byte): %d\n", lo);
        return -1;
    }
    uint16_t raw = (uint16_t)((hi << 8) | (lo & 0xFF));
    *distance = (float)raw / 10.0f;
    return 0;
}

static int log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        perror("fprintf failed");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose failed");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALERT_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Chirp ICU-20201 distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;
        if (read_distance(&distance) != 0) {
            gpioWrite(ALERT_GPIO, 0);
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Logging failed for distance %.2f cm\n", distance);
        }

        if (distance < DIST_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1);
        } else {
            gpioWrite(ALERT_GPIO, 0);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

