#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_MS   100

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_MODEL_ID                  0x010F
#define REG_SOFT_RESET                0x0000
#define REG_SYSTEM_MODE_START         0x007
#define REG_SYSRANGE_START            0x000
#define REG_RESULT_INTERRUPT_STATUS   0x013
#define REG_RESULT_RANGE_STATUS       0x078
#define REG_SYSTEM_INTERRUPT_CLEAR    0x014

#define EXPECTED_MODEL_ID             0xEA
#define SYSTEM_MODE_CONTINUOUS_BACK_TO_BACK 0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a 16-bit big-endian value */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address, then read 2 bytes (big-endian) */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint16_t model_id = 0;

    /* Verify sensor identity */
    if (vl53l1x_read_reg16(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Start continuous back-to-back ranging */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE_START,
                            SYSTEM_MODE_CONTINUOUS_BACK_TO_BACK) < 0) {
        fprintf(stderr, "Error: failed to start continuous mode\n");
        return -1;
    }

    /* Poll SYSRANGE_START bit 0 until it clears (data ready) */
    uint16_t status = 0;
    int waited = 0;
    while (waited < POLL_TIMEOUT_MS) {
        if (vl53l1x_read_reg16(handle, REG_SYSRANGE_START, &status) < 0) {
            fprintf(stderr, "Error: failed to poll SYSRANGE_START\n");
            return -1;
        }
        if ((status & 0x01) == 0)
            break;
        gpioDelay(1000); /* 1 ms */
        waited++;
    }
    if (waited >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: timeout waiting for VL53L1X data-ready\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;

    /* Poll RESULT_INTERRUPT_STATUS bit 0 for data-ready */
    int waited = 0;
    while (waited < POLL_TIMEOUT_MS) {
        if (vl53l1x_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Error: failed to poll interrupt status\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(1000);
        waited++;
    }
    if (waited >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: timeout waiting for data-ready\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian at RESULT_RANGE_STATUS + 10) */
    uint16_t range_reg = REG_RESULT_RANGE_STATUS + 10;
    uint16_t range_raw = 0;
    if (vl53l1x_read_reg16(handle, range_reg, &range_raw) < 0) {
        fprintf(stderr, "Error: failed to read range register\n");
        return -1;
    }

    /* Clear interrupt so next measurement can signal */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
    }

    *distance_mm = range_raw;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

static void print_guidance(uint16_t distance_mm)
{
    if (distance_mm < 300)
        printf("[GUIDANCE] STOP\n");
    else if (distance_mm < 600)
        printf("[GUIDANCE] APPROACH\n");
    else if (distance_mm < 1200)
        printf("[GUIDANCE] SLOW\n");
    else
        printf("[GUIDANCE] CLEAR\n");
    fflush(stdout);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,distance_mm\n");
    fflush(g_log_file);

    printf("Parking Assistance System started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
            log_distance(g_log_file, distance_mm);
            print_guidance(distance_mm);
        } else {
            fprintf(stderr, "Warning: sensor read failed, retrying...\n");
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

