#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x45          /* TDK InvenSense CH201 default */
#define GPIO_LED             18            /* BCM 18, physical pin 12 */
#define LED_ON_TIME_US       1000000       /* 1 s half-cycle  -> 1 Hz blink */
#define LED_OFF_TIME_US      1000000       /* 1 s half-cycle  -> 1 Hz blink */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000         /* 10 ms between retries */

/* ----------------------------- Globals ---------------------------------- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_distance(uint16_t *distance_mm);
static void set_led_frequency(uint16_t distance_mm);
static void log_data(uint16_t distance_mm, uint32_t blink_freq_hz);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C -------------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit distance value from the CH201.
 * Returns 0 on success, -1 on persistent failure.
 */
static int read_distance(uint16_t *distance_mm)
{
    char buf[2];
    int  attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadDevice(i2c_handle, buf, 2);
        if (n == 2) {
            *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) |
                           (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] I2C read attempt %d/%d returned %d\n",
                attempt + 1, MAX_RETRIES, n);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ----------------------------- LED -------------------------------------- */
static void set_led_frequency(uint16_t distance_mm)
{
    /*
     * Map 50 mm -> 10 Hz, 500 mm -> 1 Hz.
     * Clamp outside the range to 1 Hz (off).
     */
    uint32_t freq_hz;
    if (distance_mm < 50) {
        freq_hz = 10;
    } else if (distance_mm > 500) {
        freq_hz = 1;
    } else {
        freq_hz = 100 - (distance_mm * 9);   /* 100 - 9*d */
    }

    if (freq_hz == 0) {
        gpioWrite(GPIO_LED, 0);
        return;
    }

    uint32_t half_period_us = 1000000 / freq_hz;

    /*
     * Blink one half-cycle.  pigpio gpioDelay is a busy-wait; we use
     * gpioDelay(0) to yield CPU so the next half-cycle starts promptly.
     */
    gpioWrite(GPIO_LED, 1);
    gpioDelay(half_period_us);
    gpioWrite(GPIO_LED, 0);
    gpioDelay(half_period_us);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(uint16_t distance_mm, uint32_t blink_freq_hz)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %u mm | Blink: %u Hz\n",
           ts, distance_mm, blink_freq_hz);
    fflush(stdout);
}

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance monitor running.  Ctrl+C to exit.\n");
    fflush(stdout);

    while (!terminate) {
        uint16_t distance_mm = 0;

        if (read_distance(&distance_mm) != 0) {
            fprintf(stderr, "[ERROR] Sensor read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        set_led_frequency(distance_mm);

        /*
         * The LED half-cycle already consumed LED_ON_TIME_US +
         * LED_OFF_TIME_US, so the next half-cycle starts promptly.
         * We still need to sleep the remainder of the sample period.
         */
        gpioDelay(SAMPLE_PERIOD_US - LED_ON_TIME_US - LED_OFF_TIME_US);
    }

    cleanup();
    printf("\n[INFO] Shutdown complete.\n");
    return EXIT_SUCCESS;
}

