#define REG_MEAS_STAT  0x06
#define REG_DIST_HIGH  0x08
#define REG_DIST_LOW   0x09
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_MS      500
#define MEAS_TIMEOUT_MS 50

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X,0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ch101_trigger_and_read(int fd, uint16_t *distance_mm) {
    if (i2c_write_reg(fd, REG_MEAS_TRIG, 0x01) < 0)
        return -1;

    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        uint8_t status = 0;
        if (i2c_read_reg(fd, REG_MEAS_STAT, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
    }

    uint8_t hi = 0, lo = 0;
    if (i2c_read_reg(fd, REG_DIST_HIGH, &hi) < 0)
        return -1;
    if (i2c_read_reg(fd, REG_DIST_LOW, &lo) < 0)
        return -1;

    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_data(FILE *fp, uint16_t distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance);
    fflush(fp);
}

