    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE,0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    fprintf(fp, "# timestamp,distance_mm\n");
    fflush(fp);

    while (g_running) {
        uint16_t dist = 0;
        if (ch101_trigger_and_read(fd, &dist) == 0) {
            log_data(fp, dist);
        } else {
            fprintf(stderr, "CH-101 read failed; skipping sample.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return 0;
