#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VL53L5CX_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define NUM_ZONES 64
#define POLL_INTERVAL_MS 500

/* VL53L5CX register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET 0x000B
#define REG_SYSTEM_MODE 0x0001
#define REG_RANGE_CONFIG 0x0004
#define REG_ZONE_CONFIG 0x0005
#define REG_ZONE_RESULT 0x001E
#define REG_RESULT_RANGE_STATUS 0x001F
#define REG_RESULT_DISTANCE 0x0020
#define REG_RESULT_PEAK_SIGNAL 0x0022
#define REG_RESULT_RANGE_STATUS 0x001F

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address, then a 16-bit big-endian value */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address, then read 2 bytes back (big-endian) */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out) {
    uint8_t addr_buf[2];
    uint8_t data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (write(fd, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data_buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data_buf[0] << 8) | data_buf[1];
    return 0;
}

static int vl53l5cx_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x0001) < 0) return -1;
    usleep(10000); /* 10 ms */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x0000) < 0) return -1;
    usleep(10000); /* 10 ms */

    /* Set system mode to standby (0x00) */
    if (i2c_write_reg16(fd, REG_SYSTEM_MODE, 0x0000) < 0) return -1;
    usleep(1000);

    /* Configure range config: 0x0001 = default */
    if (i2c_write_reg16(fd, REG_RANGE_CONFIG, 0x0001) < 0) return -1;
    usleep(1000);

    /* Configure 8x8 zone grid: 0x0008 = grid size 8x8 */
    if (i2c_write_reg16(fd, REG_ZONE_CONFIG, 0x0008) < 0) return -1;
    usleep(1000);

    /* Start continuous ranging */
    if (i2c_write_reg16(fd, REG_SYSTEM_MODE, 0x0001) < 0) return -1;
    usleep(10000); /* 10 ms for first measurement */

    return 0;
}

static int read_zone_distance(int fd, int zone_index) {
    uint16_t status_reg;
    uint16_t distance_reg;

    /* Read range status for this zone */
    if (i2c_read_reg16(fd, REG_RESULT_RANGE_STATUS + (uint16_t)(zone_index * 2), &status_reg) < 0) {
