#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define READ_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t cur_len = strlen(buf);
    snprintf(buf + cur_len, len - cur_len, ".%03ld", ts.tv_nsec / 1000000);
}

static int read_distance(int handle, int *distance) {
    char cmd[2] = {0x00, 0x00};
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        gpioDelay(1000);

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        *distance = (buf[0] << 8) | buf[1];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    char timestamp[32];
    int distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, MLX75030_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            printf("[%s] Distance: %d mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            get_timestamp(timestamp, sizeof(timestamp));
            fprintf(stderr, "[%s] Error reading distance.\n", timestamp);
        }

        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

