static int i2c_read_reg(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l4cx_init(int handle) {
    if (i2c_write_reg(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    if (i2c_write_reg(handle, REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "System start failed\n");
        return -1;
    }
    return 0;
