        gpioTerminate();
        return 1;
    }

    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        int rc = vl53l4cx_read_distance(i2c_handle, &distance);
        if (rc == 0) {
