            fprintf(stderr, "I2C communication error, skipping cycle\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

