static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write (reg select) for 0x%04X failed\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read from 0x%04X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) != 0) return -1;
    if (vl53l1x_write16(handle, REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

