        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X (err=%d)\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

