            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus, exiting\n");
                break;
            }
            if (vl53l1x_init(i2c_handle) != 0) {
                fprintf(stderr, "Error: VL53L1X re-initialisation failed, exiting\n");
                break;
            }
            buzzer_active = 0;
            gpioWrite(BUZZER_GPIO, 0);
            continue;
        }

        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_MM && !buzzer_active) {
            gpioWrite(BUZZER_GPIO, 1);
            buzzer_active = 1;
        } else if (distance >= DISTANCE_THRESHOLD_MM && buzzer_active) {
            gpioWrite(BUZZER_GPIO, 0);
            buzzer_active = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

