#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG   -90.0
#define MAX_ANGLE_DEG   90.0
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US   200000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin %d as output\n", SERVO_PIN);
        return -1;
    }
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    return (double)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    return MIN_ANGLE_DEG +
           (distance - MIN_DISTANCE_CM) *
           (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
           (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

static void set_servo_angle(double angle) {
    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;
    int pulse_width = (int)(500 + (angle / 90.0) * 2000);
    gpioServo(SERVO_PIN, pulse_width);
}

static void log_data(double distance, double angle) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %.2f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    while (g_running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance, skipping this reading\n");
        } else {
            double angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

