#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_US 0.0343f
#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define BUZZER_THRESHOLD_CM 30.0f
#define ECHO_TIMEOUT_US 30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US   100000  /* 100 ms between readings */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

/* Shared state between alert callback and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_seen  = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * We compute the 32-bit delta with wraparound semantics.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0) {
        g_end_tick   = tick;
        g_echo_seen  = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float calculate_distance(uint32_t start, uint32_t end)
{
    int32_t delta = (int32_t)(end - start);
    return (float)delta * SPEED_OF_SOUND_CM_PER_US;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register alert callback for echo pin --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d | Buzzer: GPIO %d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Threshold: %.1f cm | Loop interval: %d us\n",
           BUZZER_THRESHOLD_CM, LOOP_DELAY_US);

    int buzzer_active = 0;

    while (g_running) {
        /* Reset shared state before each measurement */
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen  = 0;

        trigger_sensor();

        /* Wait for echo with timeout so we can detect sensor-absent or stuck echo */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);  /* 100 us granularity */
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout — sensor absent or no object in range.\n");
            gpioWrite(BUZZER_PIN, 0);
            buzzer_active = 0;
        } else {
            float distance = calculate_distance(g_start_tick, g_end_tick);

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f, %.0f].\n",
                        distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
                gpioWrite(BUZZER_PIN, 0);
                buzzer_active = 0;
            } else {
                printf("Distance: %.2f cm\n", distance);

                if (distance < BUZZER_THRESHOLD_CM) {
                    if (!buzzer_active) {
                        gpioWrite(BUZZER_PIN, 1);
                        buzzer_active = 1;
                    }
                } else {
                    if (buzzer_active) {
                        gpioWrite(BUZZER_PIN, 0);
                        buzzer_active = 0;
                    }
                }
            }
        }

        /* Sleep 100 ms between readings */
        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    gpioTerminate();

    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

