    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d | Buzzer: GPIO %d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Threshold: %.1f cm | Loop interval: %d us\n",
           BUZZER_THRESHOLD_CM, LOOP_DELAY_US);

    int buzzer_active = 0;

    while (g_running) {
        /* Reset shared state before each measurement */
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen  = 0;

        trigger_sensor();

        /* Wait for echo with timeout so we can detect sensor-absent or stuck echo */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);  /* 100 us granularity */
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout — sensor absent or no object in range.\n");
            gpioWrite(BUZZER_PIN, 0);
            buzzer_active = 0;
        } else {
            float distance = calculate_distance(g_start_tick, g_end_tick);

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f, %.0f].\n",
                        distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
                gpioWrite(BUZZER_PIN, 0);
                buzzer_active = 0;
            } else {
                printf("Distance: %.2f cm\n", distance);

                if (distance < BUZZER_THRESHOLD_CM) {
                    if (!buzzer_active) {
                        gpioWrite(BUZZER_PIN, 1);
                        buzzer_active = 1;
                    }
                } else {
                    if (buzzer_active) {
                        gpioWrite(BUZZER_PIN, 0);
                        buzzer_active = 0;
                    }
                }
            }
        }

        /* Sleep 100 ms between readings */
        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    gpioTerminate();

    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

