#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define MQTT_BROKER "tcp://mqtt.eclipse.org:1883"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate_control"
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle) {
    uint8_t status;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) return -1;
    if ((status & 0x01) == 0) return -1;
    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) return -1;
    return (dist_buf[0] << 8) | dist_buf[1];
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = (angle * 2000) / 180 + 500;
    gpioServo(SERVO_PIN, pulse_width);
}

static void mqtt_message_arrived(void *context, char *topic, int topic_len, MQTTClient_message *message) {
    (void)context;
    (void)topic_len;
    if (!message || !message->payload) return;
    char *payload = (char *)message->payload;
    if (strcmp(payload, "force_open") == 0) {
        set_servo_angle(180);
        log_event("Gate forced open");
    } else if (strcmp(payload, "force_close") == 0) {
        set_servo_angle(0);
        log_event("Gate forced closed");
    } else if (strcmp(payload, "status_request") == 0) {
        int dist = vl53l1x_read_distance(i2c_handle);
        if (dist >= 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Current distance: %d cm", dist);
            log_event(msg);
        } else {
            log_event("Error reading distance");
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topic);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT create failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        MQTTClient_destroy(&client);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    MQTTClient_message_init(&pubmsg);
    pubmsg.payload = "Gate controller started";
    pubmsg.payloadlen = strlen(pubmsg.payload);
    pubmsg.qos = 2;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed\n");
    }

    MQTTClient_subscribe(client, MQTT_TOPIC, 2);

    MQTTClient_setCallback(client, mqtt_message_arrived);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Gate controller started");

    while (running) {
        int dist = vl53l1x_read_distance(i2c_handle);
        if (dist >= 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %d cm", dist);
            log_event(msg);
            if (dist <= DISTANCE_THRESHOLD) {
                set_servo_angle(180);
                log_event("Object detected, gate opened");
            } else {
                set_servo_angle(0);
                log_event("Path clear, gate closed");
            }
        } else {
            log_event("Error reading distance, retrying...");
            vl53l1x_init(i2c_handle);
        }
        gpioDelay(100000);
    }

    set_servo_angle(0);
    log_event("Gate controller stopping");

    MQTTClient_unsubscribe(client, MQTT_TOPIC);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

