#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_VALID_PULSE_US       100
#define MAX_VALID_PULSE_US       30000
#define MEASUREMENT_INTERVAL_US  200000
#define ECHO_TIMEOUT_US          60000
#define LOG_FILE_NAME            "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* Shared state between callback and main thread */
static volatile uint32_t g_rising_tick  = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile int      g_echo_seen    = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* pigpio alert callback: fires on every edge of ECHO_PIN */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_rising_tick  = tick;
        g_echo_seen    = 1;
    } else if (level == 0) {
        g_falling_tick = tick;
    }
}

/* pigpio tick is a 32-bit microsecond counter that wraps every ~72 min */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;
}

static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stdout, "%s Distance: %.2f cm\n", timestamp, distance_cm);
    if (g_log_file) {
        fprintf(g_log_file, "%s Distance: %.2f cm\n", timestamp, distance_cm);
        fflush(g_log_file);
    }
}

static void log_warning(const char *msg)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "%s WARNING: %s\n", timestamp, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s WARNING: %s\n", timestamp, msg);
        fflush(g_log_file);
    }
}

int main(void)
{
    int ret;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise TRIGGER_PIN %d LOW.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback on ECHO_PIN --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIGGER: GPIO %d | ECHO: GPIO %d | Log: %s\n", TRIGGER_PIN, ECHO_PIN, LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        /* Reset shared state */
        g_rising_tick  = 0;
        g_falling_tick = 0;
        g_echo_seen    = 0;

        /* Generate 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            log_warning("Failed to set TRIGGER_PIN HIGH");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }
        gpioDelay(10);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            log_warning("Failed to set TRIGGER_PIN LOW");
        }

        /* Wait for echo with timeout (poll every 1 ms) */
        uint32_t waited = 0;
        while (g_running && !g_echo_seen && waited < ECHO_TIMEOUT_US) {
            gpioDelay(1000);
            waited += 1000;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            log_warning("Echo timeout: no object detected or sensor absent");
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);

        if (pulse_us < MIN_VALID_PULSE_US || pulse_us > MAX_VALID_PULSE_US) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Invalid pulse width: %u us (out of range)", pulse_us);
            log_warning(msg);
            gpioDelay(MEASUREMENT_INTERVAL_US);
            continue;
        }

        /* distance = (pulse_us * speed_of_sound) / 2 */
        float distance_cm = (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0f;
        log_distance(distance_cm);

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    /* --- Cleanup --- */
    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

