#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read VL53L1X model ID.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid VL53L1X model ID: 0x%02X (expected 0x%02X).\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop sensor.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }
    uint8_t dist_buf[2] = {0};
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf) != 0) {
        return -1;
    }
    *distance = (dist_buf[0] << 8) | dist_buf[1];
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }
    return 0;
}

