    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set shutdown pin mode.\n");
        cleanup();
        return 1;
    }
    gpioWrite(SHUTDOWN_PIN, 1);

    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt pin mode.\n");
        cleanup();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", VL53L1X_ADDR);
        cleanup();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set servo pin mode.\n");
        cleanup();
        return 1;
    }

    servo_set_angle(SERVO_CENTER_ANGLE);
    log_event("Gate initialized: Center position.");

    int gate_open = 0;
    int last_distance = -1;

    while (running) {
        int distance = -1;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);

        if (ret == 0) {
            if (distance >= 0 && distance <= 500) {
                if (!gate_open && distance < DISTANCE_THRESHOLD_OPEN) {
                    servo_set_angle(SERVO_OPEN_ANGLE);
                    gate_open = 1;
                    log_event("Gate opened.");
                } else if (gate_open && distance > DISTANCE_THRESHOLD_CLOSE) {
                    servo_set_angle(SERVO_CLOSE_ANGLE);
                    gate_open = 0;
                    log_event("Gate closed.");
                }
            } else {
                fprintf(stderr, "Warning: Invalid distance reading: %d\n", distance);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read/write error.\n");
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

