#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses (MSB first) */
#define VL53L1X_SOFT_RESET 0x0003
#define VL53L1X_SYSTEM_MODE_START 0x0000
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s %s\n", ts, event);
    fflush(log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], buf + 1, 2);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr[0], addr + 1, 1) < 0) return -1;
    return i2cReadI2CBlockData(handle, addr[0], (char *)buf, len);
