#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FWD 17
#define GPIO_MOTOR_BWD 18
#define DISTANCE_THRESHOLD_FWD 100
#define DISTANCE_THRESHOLD_BWD 300
#define POLL_TIMEOUT_MS 100
#define POLL_DELAY_US 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, 0x0000, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, 0x0000, 0x01) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    uint8_t dist_buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_reg16(handle, 0x0000, 0x01) != 0) {
            fprintf(stderr, "I2C write error (start measurement), retry %d\n", retries + 1);
            gpioDelay(1 << retries);
            retries++;
            continue;
        }

        uint32_t elapsed = 0;
        do {
            if (i2c_read_reg16(handle, 0x0089, &status, 1) != 1) {
                fprintf(stderr, "I2C read error (status), retry %d\n", retries + 1);
                gpioDelay(1 << retries);
                retries++;
                break;
            }
            if (retries >= MAX_RETRIES) break;
            gpioDelay(POLL_DELAY_US);
            elapsed += POLL_DELAY_US;
        } while (!(status & 0x01) && elapsed < (POLL_TIMEOUT_MS * 1000));

        if (retries >= MAX_RETRIES) break;

        if (!(status & 0x01)) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue;
        }

        if (i2c_read_reg16(handle, 0x0096, dist_buf, 2) != 2) {
            fprintf(stderr, "I2C read error (distance), retry %d\n", retries + 1);
            gpioDelay(1 << retries);
            retries++;
            continue;
        }

        *distance = (dist_buf[0] << 8) | dist_buf[1];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1;
}

static void motor_stop(void) {
    gpioWrite(GPIO_MOTOR_FWD, 0);
    gpioWrite(GPIO_MOTOR_BWD, 0);
}

static void motor_control(uint16_t distance) {
    if (distance < DISTANCE_THRESHOLD_FWD) {
        gpioWrite(GPIO_MOTOR_FWD, 1);
        gpioWrite(GPIO_MOTOR_BWD, 0);
        printf("Motor: Forward (%u mm)\n", distance);
    } else if (distance > DISTANCE_THRESHOLD_BWD) {
        gpioWrite(GPIO_MOTOR_FWD, 0);
        gpioWrite(GPIO_MOTOR_BWD, 1);
        printf("Motor: Backward (%u mm)\n", distance);
    } else {
        gpioWrite(GPIO_MOTOR_FWD, 0);
        gpioWrite(GPIO_MOTOR_BWD, 0);
        printf("Motor: Stop (%u mm)\n", distance);
    }
}

static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level != 1) return;

    uint16_t distance;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        motor_control(distance);
    } else {
        fprintf(stderr, "Sensor read failed, stopping motor\n");
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_MOTOR_FWD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BWD, PI_OUTPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN);
    motor_stop();

    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", GPIO_TRIGGER);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

