#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LED_GPIO 27
#define PROXIMITY_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_ELE0_T_THRESH 0x41
#define MPR121_ELE0_R_THRESH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AUTO_CONFIG0 0x7B
#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write(MPR121_TL, 0xB4) < 0) return -1;

    if (mpr121_write(MPR121_ELE0_T_THRESH, PROXIMITY_THRESHOLD) < 0) return -1;
    if (mpr121_write(MPR121_ELE0_R_THRESH, RELEASE_THRESHOLD) < 0) return -1;

    if (mpr121_write(MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int mpr121_read_touch(uint16_t *touch) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *touch = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_proximity(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int id = i2cReadByteData(i2c_handle, MPR121_SOFTRESET);
    if (id != 0x63) {
        fprintf(stderr, "MPR121 not found (ID: 0x%02X)\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch;
        if (mpr121_read_touch(&touch) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch & 0x0001) {
            printf("Proximity detected on electrode 0\n");
            log_proximity();
            gpioWrite(LED_GPIO, 1);
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

