        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *touch = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_proximity(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int id = i2cReadByteData(i2c_handle, MPR121_SOFTRESET);
    if (id != 0x63) {
        fprintf(stderr, "MPR121 not found (ID: 0x%02X)\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch;
        if (mpr121_read_touch(&touch) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch & 0x0001) {
            printf("Proximity detected on electrode 0\n");
            log_proximity();
            gpioWrite(LED_GPIO, 1);
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

