#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SAMPLE_INTERVAL_S 1
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
}

static int trigger_sensor(struct gpiod_line *trigger)
{
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1;
    }
    usleep(5);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        log_error("Failed to set trigger high");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1;
    }
    return 0;
}

static int wait_for_echo(struct gpiod_line *echo, int timeout_us)
{
    int elapsed = 0;
    while (elapsed < timeout_us) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_error("Echo read error during wait");
            return -1;
        }
        if (val == 1)
            return 0;
        usleep(100);
        elapsed += 100;
    }
    log_error("Echo never rose (sensor absent or wiring fault)");
    return -1;
}

static int measure_pulse_width(struct gpiod_line *echo, int timeout_us)
{
    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    while (1) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_error("Echo read error during pulse measurement");
            return -1;
        }
        if (val == 0)
            break;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                          (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > timeout_us) {
            log_error("Echo pulse timeout");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t_start);
    while (1) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_error("Echo read error during pulse measurement");
            return -1;
        }
        if (val == 1)
            break;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                          (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > timeout_us) {
            log_error("Echo pulse timeout");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    return (int)((t_now.tv_sec - t_start.tv_sec) * 1000000L +
                 (t_now.tv_nsec - t_start.tv_nsec) / 1000L);
}

static double calculate_distance(int pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_distance(FILE *fp, double distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s Distance: %.2f cm\n", ts, distance);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("Failed to install SIGINT handler");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        goto cleanup;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        log_error("Failed to get trigger line");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        log_error("Failed to get echo line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        log_error("Failed to request trigger line as output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        log_error("Failed to request echo line as input");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    while (program_running) {
        if (trigger_sensor(trigger) < 0) {
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (wait_for_echo(echo, ECHO_TIMEOUT_US) < 0) {
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        int pulse_us = measure_pulse_width(echo, ECHO_TIMEOUT_US);
        if (pulse_us < 0) {
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        double distance = calculate_distance(pulse_us);
        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            log_error("Distance out of range (rejected)");
        } else {
            log_distance(fp, distance);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp)
        fclose(fp);
    if (trigger)
        gpiod_line_release(trigger);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

