#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define LOG_FILE        "distance_log.txt"

/* HC-SR04 round-trip max ~400 cm (23 ms at 343 m/s) */
#define MAX_PULSE_US 23000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_pulse_start = 0;
static volatile uint32_t    g_pulse_end   = 0;
static volatile int         g_echo_seen   = 0;

static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* pigpio ISR callback: fires on EITHER_EDGE of ECHO_PIN */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_pulse_start = tick;
        g_echo_seen   = 0;
    } else if (level == 0) {
        g_pulse_end = tick;
        g_echo_seen = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Compute distance in meters from the falling-edge start to the rising-edge end.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * Returns -1.0 on invalid pulse width.
 */
static float calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start; /* correct even across wraparound */
    if (diff == 0 || diff > MAX_PULSE_US)
        return -1.0f;

    return (float)diff * 343.0f / 2000000.0f;
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance < 0.0f)
        fprintf(g_log, "%s, ERROR: Invalid pulse width\n", timestamp);
    else
        fprintf(g_log, "%s, Distance: %.2f m\n", timestamp, distance);

    fflush(g_log);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50); /* let sensor settle */

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on ECHO_PIN --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. TRIG=GPIO%d, ECHO=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        trigger_sensor();

        /*
         * Wait for the ISR to set g_echo_seen.
         * gpioDelay(1000) is a busy-wait; a real production loop would
         * use a pigpio timer or a sleep-free busy-wait.
         */
        uint32_t waited = 0;
        const uint32_t step = 100; /* 100 us */
        while (g_running && !g_echo_seen && waited < 100000) {
            gpioDelay(step);
            waited += step;
        }

        if (!g_running)
            break;

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo pulse timeout (no end detected).\n");
            log_distance(-1.0f);
        } else {
            float dist = calculate_distance(g_pulse_start, g_pulse_end);
            log_distance(dist);
        }

        /* 1 s between measurements */
        gpioDelay(1000000);
    }

    /* --- Cleanup --- */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); /* disable ISR */
    gpioWrite(TRIGGER_PIN, 0);
    fclose(g_log);
    gpioTerminate();

    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

