    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50); /* let sensor settle */

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on ECHO_PIN --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. TRIG=GPIO%d, ECHO=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        trigger_sensor();

        /*
         * Wait for the ISR to set g_echo_seen.
         * gpioDelay(1000) is a busy-wait; a real production loop would
         * use a pigpio timer or a sleep-free busy-wait.
         */
        uint32_t waited = 0;
        const uint32_t step = 100; /* 100 us */
        while (g_running && !g_echo_seen && waited < 100000) {
            gpioDelay(step);
            waited += step;
        }

        if (!g_running)
            break;

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo pulse timeout (no end detected).\n");
            log_distance(-1.0f);
        } else {
            float dist = calculate_distance(g_pulse_start, g_pulse_end);
            log_distance(dist);
        }

        /* 1 s between measurements */
        gpioDelay(1000000);
    }

    /* --- Cleanup --- */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); /* disable ISR */
    gpioWrite(TRIGGER_PIN, 0);
    fclose(g_log);
    gpioTerminate();

    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

