#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_RANGE_START 0x0015
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0016
#define VL53L1X_REG_SYSTEM_INTERRUPT_STATUS 0x0017
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0018
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0021
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_LO 0x0022
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE_HI 0x008A
#define VL53L1X_REG_RESULT_DISTANCE_LO 0x008B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int vl53l1x_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        log_message("I2C write failed");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        log_message("I2C write (reg select) failed");
        return -1;
    }
    char val_buf[1];
    if (i2cReadDevice(i2c_handle, val_buf, 1) != 1) {
        log_message("I2C read failed");
        return -1;
    }
    *value = (uint8_t)val_buf[0];
    return 0;
}

static int vl53l1x_read_reg16(uint8_t reg_hi, uint16_t *value) {
    char reg_buf[1] = {(char)reg_hi};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        log_message("I2C write (reg select 16) failed");
        return -1;
    }
    char val_buf[2];
    if (i2cReadDevice(i2c_handle, val_buf, 2) != 2) {
        log_message("I2C read 16-bit failed");
        return -1;
    }
    *value = ((uint16_t)(uint8_t)val_buf[0] << 8) | (uint8_t)val_buf[1];
    return 0;
}

static int vl53l1x_init(void) {
    uint8_t model_id = 0;
    if (vl53l1x_read_reg(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        log_message("Failed to read model ID");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Unexpected model ID: 0x%02X", model_id);
        log_message(msg);
        return -1;
    }

    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) != 0) return -1;
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_RANGE_START, 0x00) != 0) return -1;
    if (vl53l1x_write_reg(VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (vl53l1x_write_reg(VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_LO, 0x00) != 0) return -1;
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_RANGE_START, 0x01) != 0) return -1;

    return 0;
}

static int read_distance(float *distance_cm) {
    uint8_t status = 0;
    if (vl53l1x_read_reg(VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) return -1;
    if ((status & 0x01) == 0) {
        log_message("Ranging not ready");
        return -1;
    }
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    uint16_t distance_mm = 0;
    if (vl53l1x_read_reg16(VL53L1X_REG_RESULT_DISTANCE_HI, &distance_mm) != 0) return -1;

    *distance_cm = (float)distance_mm / 10.0f;
    return 0;
}

static void control_gate(float distance_cm) {
    static int gate_open = 0;
    if (distance_cm < DISTANCE_THRESHOLD && !gate_open) {
        if (gpioWrite(GATE_GPIO, 1) == 0) {
            gate_open = 1;
            log_message("Gate opened");
        } else {
            log_message("Failed to open gate");
        }
    } else if (distance_cm >= DISTANCE_THRESHOLD && gate_open) {
        if (gpioWrite(GATE_GPIO, 0) == 0) {
            gate_open = 0;
            log_message("Gate closed");
        } else {
            log_message("Failed to close gate");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "GPIO mode set failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Gate control system started");

    while (!terminate) {
        float distance = 0.0f;
        if (read_distance(&distance) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_message(msg);
            control_gate(distance);
        } else {
            log_message("Failed to read distance");
        }
        gpioDelay(100000);
    }

    log_message("Gate control system stopping");
    gpioWrite(GATE_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

