#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <string.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define MOVING_AVG_SIZE 5
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_DEFAULT_ANGLE 90
#define TRIGGER_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end = 0;
static volatile int g_pulse_ready = 0;

static double g_distance_buffer[MOVING_AVG_SIZE];
static int g_buffer_index = 0;
static int g_buffer_filled = 0;

static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        g_pulse_start = tick;
    } else if (level == 0) {
        g_pulse_end = tick;
        g_pulse_ready = 1;
    }
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;
    int waited = 0;

    while (!g_pulse_ready && waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);
        waited += 100;
    }

    if (!g_pulse_ready) {
        fprintf(stderr, "Error: Echo timeout\n");
        return -1.0;
    }

    start_tick = g_pulse_start;
    end_tick = g_pulse_end;
    g_pulse_ready = 0;

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }

    return distance;
}

static double calculate_moving_average(double new_distance) {
    g_distance_buffer[g_buffer_index] = new_distance;
    g_buffer_index = (g_buffer_index + 1) % MOVING_AVG_SIZE;
    if (g_buffer_index == 0) {
        g_buffer_filled = 1;
    }

    double sum = 0.0;
    int count = g_buffer_filled ? MOVING_AVG_SIZE : g_buffer_index;
    for (int i = 0; i < count; i++) {
        sum += g_distance_buffer[i];
    }
    return sum / count;
}

static int map_distance_to_angle(double distance) {
    if (distance < 2.0) distance = 2.0;
    if (distance > 400.0) distance = 400.0;

    double log_distance = log10(distance);
    double log_min = log10(MIN_DISTANCE);
    double log_max = log10(MAX_DISTANCE);

    double angle = (log_distance - log_min) / (log_max - log_min) * 180.0;
    if (angle < 0.0) angle = 0.0;
    if (angle > 180.0) angle = 180.0;

    return (int)angle;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return -1;
    }

    int pulse_width = SERVO_MIN_PULSE_US + (int)((angle / 180.0) * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(g_log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed\n");
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv\n");
        gpioTerminate();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "Timestamp,Distance(cm),ServoAngle(deg)\n");
        fflush(g_log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: Invalid distance reading, using default servo angle\n");
            set_servo_angle(SERVO_DEFAULT_ANGLE);
            log_data(-1.0, SERVO_DEFAULT_ANGLE);
        } else {
            double avg_distance = calculate_moving_average(distance);
            int angle = map_distance_to_angle(avg_distance);
            set_servo_angle(angle);
            log_data(avg_distance, angle);
        }
        gpioDelay(TRIGGER_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    fclose(g_log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

