#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define TIMEOUT_US    200000
#define TRIGGER_US    10
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        return -1;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin mode.\n");
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        return -1;
    }
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle.\n");
        return -1;
    }
    return 0;
}

static float measure_distance(void) {
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed.\n");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo start.\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo end.\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    return (float)pulse_width / 58.0;
}

static float calculate_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f].\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }
    float log_dist = log10(distance);
    float freq = MIN_FREQUENCY * powf(10.0, log_dist);
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return freq;
}

static int set_frequency(float frequency) {
    if (frequency < 0) return -1;
    if (gpioSetPWMfrequency(PWM_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed.\n");
        return -1;
    }
    if (gpioPWM(PWM_PIN, 500) < 0) {
        fprintf(stderr, "Error: gpioPWM failed.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    float last_frequency = MIN_FREQUENCY;

    while (running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Warning: measurement failed, using previous frequency.\n");
        } else {
            float freq = calculate_frequency(distance);
            if (freq < 0) {
                fprintf(stderr, "Warning: out-of-range distance, using previous frequency.\n");
            } else {
                if (set_frequency(freq) < 0) {
                    fprintf(stderr, "Error: failed to set frequency.\n");
                } else {
                    last_frequency = freq;
                }
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

