#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 5.0f
#define MAX_DISTANCE_CM 50.0f
#define MIN_FREQ_HZ     200
#define MAX_FREQ_HZ     2000

#define TIMEOUT_US      100000  /* 100 ms */
#define LOOP_DELAY_US   10000   /* 10 ms  */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or read error.
 * Uses pigpio's gpioDelay for microsecond timing.
 */
static float read_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    /* distance = (pulse_us / 2) * 0.0343 cm/us */
    return (float)pulse_us * 0.0343f / 2.0f;
}

static int set_buzzer_frequency(int frequency)
{
    if (frequency < MIN_FREQ_HZ) frequency = MIN_FREQ_HZ;
    if (frequency > MAX_FREQ_HZ) frequency = MAX_FREQ_HZ;

    /* gpioHardwarePWM takes frequency in Hz and duty cycle in range 0-1000000 */
    if (gpioHardwarePWM(BUZZER_PIN, frequency, 500000) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for freq %d\n", frequency);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop PWM output */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    float last_valid_distance = (MAX_DISTANCE_CM + MIN_DISTANCE_CM) / 2.0f;

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read failed, using last valid distance: %.2f cm\n",
                    last_valid_distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        /* Map distance to frequency: 5 cm -> 200 Hz, 50 cm -> 2000 Hz */
        int frequency = MIN_FREQ_HZ +
            (int)((float)(MAX_FREQ_HZ - MIN_FREQ_HZ) *
                  (MAX_DISTANCE_CM - distance) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM));

        if (frequency < MIN_FREQ_HZ) frequency = MIN_FREQ_HZ;
        if (frequency > MAX_FREQ_HZ) frequency = MAX_FREQ_HZ;

        if (set_buzzer_frequency(frequency) < 0) {
            fprintf(stderr, "Warning: failed to set buzzer frequency\n");
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

