    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    float last_valid_distance = (MAX_DISTANCE_CM + MIN_DISTANCE_CM) / 2.0f;

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read failed, using last valid distance: %.2f cm\n",
                    last_valid_distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        /* Map distance to frequency: 5 cm -> 200 Hz, 50 cm -> 2000 Hz */
        int frequency = MIN_FREQ_HZ +
            (int)((float)(MAX_FREQ_HZ - MIN_FREQ_HZ) *
                  (MAX_DISTANCE_CM - distance) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM));

        if (frequency < MIN_FREQ_HZ) frequency = MIN_FREQ_HZ;
        if (frequency > MAX_FREQ_HZ) frequency = MAX_FREQ_HZ;

        if (set_buzzer_frequency(frequency) < 0) {
            fprintf(stderr, "Warning: failed to set buzzer frequency\n");
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

