#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 29.1  /* cm/us */
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TOO_CLOSE_THRESHOLD 10.0
#define TIMEOUT_US 50000      /* 50 ms */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   -1 on timeout (no echo received)
 *   -2 on error (pigpio read error)
 *   >=0 pulse width in microseconds
 */
static int measure_echo_pulse(void) {
    uint32_t start_tick, end_tick;
    int level;

    /* Wait for echo to go high (start of pulse) */
    start_tick = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            return -2;
        }
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;
        }
    } while (level == 0);

    /* Wait for echo to go low (end of pulse) */
    end_tick = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            return -2;
        }
        if (gpioTick() - end_tick > TIMEOUT_US) {
            return -1;
        }
    } while (level == 1);

    return (int)(gpioTick() - end_tick);
}

int main(void) {
    int ret;

    /* Register signal handler for clean exit */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register signal handler\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(5000);  /* 5 ms settle */

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Send 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger high\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger low\n");
            break;
        }

        /* Measure echo pulse */
        int pulse_width = measure_echo_pulse();

        if (pulse_width < 0) {
            if (pulse_width == -1) {
                fprintf(stderr, "Warning: echo timeout (no object detected or sensor fault)\n");
            } else {
                fprintf(stderr, "Warning: echo read error\n");
            }
        } else {
            /* Calculate distance in cm */
            double distance = (double)pulse_width / 2.0 / SPEED_OF_SOUND;

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading: %.2f cm\n", distance);
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < TOO_CLOSE_THRESHOLD) {
                    printf(" - Too close!");
                }
                printf("\n");
            }
        }

        /* Wait 500 ms before next measurement */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean up */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

