#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define READ_INTERVAL_MS 100

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    if (spi_handle < 0) return -1;
    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    gpioWrite(CS_PIN, 1);
    return ret;
}

static int init_sensor(void) {
    uint8_t tx[3] = {0x01, 0x01, 0x00};
    uint8_t rx[3] = {0};
    if (spi_transfer(tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write error (init 0x01)\n");
        return -1;
    }
    gpioDelay(1000);
    tx[0] = 0x02; tx[1] = 0x00; tx[2] = 0x00;
    if (spi_transfer(tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write error (init 0x02)\n");
        return -1;
    }
    gpioDelay(1000);
    tx[0] = 0x00; tx[1] = 0x01; tx[2] = 0x00;
    if (spi_transfer(tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write error (init 0x00)\n");
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t tx[3] = {0x0C, 0x00, 0x00};
    uint8_t rx[3] = {0};
    if (spi_transfer(tx, rx, 3) != 0) {
        fprintf(stderr, "SPI read error (low byte)\n");
        return -1;
    }
    *distance = (uint16_t)rx[1];
    tx[0] = 0x0D;
    if (spi_transfer(tx, rx, 3) != 0) {
        fprintf(stderr, "SPI read error (high byte)\n");
        return -1;
    }
    *distance |= ((uint16_t)rx[1] << 8);
    return 0;
}

static void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,distance_mm\n");
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (!terminate) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Read failed, continuing\n");
        }
        gpioDelay(READ_INTERVAL_MS * 1000);
    }
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

