#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define SI1175_REG_COMMAND 0x46
#define SI1175_CMD_RESET 0x01
#define SI1175_CMD_ALS_FORCE 0x06
#define LOG_FILE_NAME "proximity_log.csv"
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t low, high;
    if (i2c_read_byte(fd, SI1175_REG_ALS_VIS_DATA0, &low) < 0) return -1;
    if (i2c_read_byte(fd, SI1175_REG_ALS_VIS_DATA1, &high) < 0) return -1;
    *als_visible = (uint16_t)((high << 8) | low);
    return 0;
}

static int log_data(FILE *fp, uint16_t als_visible) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", timestamp, als_visible) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_I2C_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_byte(i2c_fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0) {
        fprintf(stderr, "Sensor reset failed; sensor may be absent or bus error.\n");
        cleanup();
        return 1;
    }
    usleep(10000);

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
        fflush(log_file);
    }

    printf("Starting Si1175 ALS logging to %s every 5 seconds. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (running) {
        uint16_t als_visible;
        if (read_als_visible(i2c_fd, &als_visible) == 0) {
            if (log_data(log_file, als_visible) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ALS data; continuing.\n");
        }
        sleep(5);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

