#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET 0x30
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_ALS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_EXPECTED_PART_ID 0x41
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (reg 0x%02X): %d\n",
                attempt + 1, reg, result);
        if (attempt < MAX_RETRIES - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) return 0;
        fprintf(stderr, "I2C write attempt %d failed (reg 0x%02X, val 0x%02X): %d\n",
                attempt + 1, reg, value, result);
        if (attempt < MAX_RETRIES - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_als(int handle, uint16_t *als) {
    uint8_t lo, hi;
    if (i2c_read_byte(handle, SI1120_REG_ALS_DATA0, &lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1120_REG_ALS_DATA1, &hi) != 0) return -1;
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_ps1(int handle, uint16_t *ps1) {
    uint8_t lo, hi;
    if (i2c_read_byte(handle, SI1120_REG_PS1_DATA0, &lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1120_REG_PS1_DATA1, &hi) != 0) return -1;
    *ps1 = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t als, uint16_t ps1) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(fp, "%s, ALS: %u, PS1: %u\n", timestamp, als, ps1) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2c_read_byte(i2c_handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read part ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (part_id != SI1120_EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_EXPECTED_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_handle, SI1120_REG_RESET, 0x01) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t als = 0, ps1 = 0;
        int als_ok = read_als(i2c_handle, &als);
        int ps1_ok = read_ps1(i2c_handle, &ps1);

        if (als_ok == 0 && ps1_ok == 0) {
            if (log_data(log_file, als, ps1) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read error (ALS: %d, PS1: %d)\n",
                    als_ok, ps1_ok);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

