#define REG_HW_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_INT_CFG 0x0A
#define REG_IRQ_ENABLE 0x0B
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80

#define CMD_PS_FORCE 0x03
#define CMD_RESET 0x01

#define PROXIMITY_REG_LOW 0x16
#define PROXIMITY_REG_HIGH 0x17

#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int init_si1145(int handle) {
    int part_id = i2c_read_byte(handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (i2c_write_byte(handle, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_byte(handle, REG_HW_KEY, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, REG_MEAS_RATE, 0x02) < 0) return -1;
    if (i2c_write_byte(handle, REG_INT_CFG, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x0B) < 0) return -1;
    if (i2c_write_byte(handle, REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, REG_PS_ADC_COUNTER, 0x49) < 0) return -1;
    if (i2c_write_byte(handle, REG_PS_LED21, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, REG_PS_LED3, 0x0F) < 0) return -1;
    if (i2c_write_byte(handle, REG_PS_ADC_MISC, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, REG_PS_ADC_GAIN, 0x07) < 0) return -1;

    if (i2c_write_byte(handle, REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_proximity(int handle) {
    int low = i2c_read_byte(handle, PROXIMITY_REG_LOW);
    if (low < 0) return -1;
    int high = i2c_read_byte(handle, PROXIMITY_REG_HIGH);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_proximity(FILE *fp, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int proximity = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            proximity = read_proximity(i2c_handle);
            if (proximity >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read failed, retry %d/%d\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (proximity < 0) {
            fprintf(stderr, "Failed to read proximity after %d retries\n", MAX_RETRIES);
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: I2C read failed\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            fflush(log_file);
            break;
        }

        log_proximity(log_file, proximity);
        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

