#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

double measure_distance(int trigger_pin, int echo_pin) {
    uint32_t start_tick, end_tick, timeout_start;

    gpioWrite(trigger_pin, 0);
    gpioDelay(2);
    gpioWrite(trigger_pin, 1);
    gpioDelay(10);
    gpioWrite(trigger_pin, 0);

    timeout_start = gpioTick();
    while (gpioRead(echo_pin) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(echo_pin) == 1) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

int calculate_servo_angle(double distance) {
    if (distance < 0) return -1;
    if (distance > 200) return 0;
    if (distance > 110) return 90;
    if (distance > 20) return 180;
    return 180;
}

void set_servo_angle(int servo_pin, int angle) {
    if (angle < 0 || angle > 180) return;
    int pulse_width = MIN_PULSE_WIDTH + (int)((double)(MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) * angle / 180.0);
    gpioServo(servo_pin, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (program_running) {
        double distance = measure_distance(TRIGGER_PIN, ECHO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance reading\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = calculate_servo_angle(distance);
        if (angle < 0) {
            fprintf(stderr, "Error: Invalid servo angle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        set_servo_angle(SERVO_PIN, angle);
        printf("Distance: %.2f cm, Servo Angle: %d degrees\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

