static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (i2cWriteDevice(handle, buf, 3) != 3) return -1;
    return 0;
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *out = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

