#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0f;
    return distance;
}

static int calculate_angle(float distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;
    return MIN_ANGLE + (int)(((float)(MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE)) * (distance - MIN_DISTANCE));
}

static void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (float)(MAX_ANGLE - MIN_ANGLE)) * (float)angle);
    gpioServo(SERVO_PIN, pulse_width);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioServo(SERVO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: Ultrasonic sensor timeout or error\n");
            set_servo_angle(MAX_ANGLE);
        } else {
            int angle = calculate_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Parking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

