#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x01
#define SI7005_REG_HUM  0x02
#define SI7005_REG_CONFIG 0x03
#define SI7005_CMD_READ_TEMP 0x01
#define SI7005_CMD_READ_HUM  0x02
#define SI7005_CMD_READ_ID1  0x0F
#define SI7005_CMD_READ_ID2  0x10
#define SI7005_CMD_READ_ID3  0x11
#define SI7005_CMD_READ_ID4  0x12
#define SI7005_CMD_RESET     0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg) {
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    if (i2c_write_byte(handle, reg) < 0) return -1;
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: i2cReadDevice(0x%02X) returned %d\n", reg, n);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int si7005_reset(int handle) {
    if (i2c_write_byte(handle, SI7005_CMD_RESET) < 0) return -1;
    gpioDelay(15000);
    return 0;
}

static int si7005_read_id(int handle, uint8_t *id) {
    uint8_t cmds[] = {SI7005_CMD_READ_ID1, SI7005_CMD_READ_ID2,
                      SI7005_CMD_READ_ID3, SI7005_CMD_READ_ID4};
    for (int i = 0; i < 4; i++) {
        if (i2c_write_byte(handle, cmds[i]) < 0) return -1;
        char buf[1];
        int n = i2cReadDevice(handle, buf, 1);
        if (n != 1) {
            fprintf(stderr, "Error: ID read %d failed\n", i);
            return -1;
        }
        id[i] = (uint8_t)buf[0];
    }
    return 0;
}

static int si7005_init(int handle) {
    if (si7005_reset(handle) < 0) return -1;
    gpioDelay(10000);
    uint8_t id[4];
    if (si7005_read_id(handle, id) < 0) return -1;
    printf("Si7005 ID: %02X %02X %02X %02X\n", id[0], id[1], id[2], id[3]);
    if (i2c_write_byte(handle, SI7005_REG_CONFIG) < 0) return -1;
    if (i2cWriteByteData(handle, SI7005_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: writing CONFIG register\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int si7005_read_temp_hum(int handle, float *temp, float *hum) {
    if (i2c_write_byte(handle, SI7005_CMD_READ_TEMP) < 0) return -1;
    gpioDelay(10000);
    uint16_t raw_t;
    if (i2c_read_word(handle, SI7005_REG_TEMP, &raw_t) < 0) return -1;
    if (i2c_write_byte(handle, SI7005_CMD_READ_HUM) < 0) return -1;
    gpioDelay(10000);
    uint16_t raw_h;
    if (i2c_read_word(handle, SI7005_REG_HUM, &raw_h) < 0) return -1;
    *temp = (175.72f * (float)raw_t) / 65536.0f - 46.85f;
    *hum  = (125.0f * (float)raw_h) / 65536.0f - 6.0f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (si7005_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: Si7005 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        float temp, hum;
        if (si7005_read_temp_hum(i2c_handle, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Warning: read failed, re-opening I2C\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: re-open failed (%d)\n", i2c_handle);
                break;
            }
            if (si7005_init(i2c_handle) < 0) {
                fprintf(stderr, "Error: Si7005 re-init failed\n");
                break;
            }
        }
        gpioDelay(2000000);
    }
    cleanup();
    return EXIT_SUCCESS;
}

