#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_WHO_AM_I     0x75
#define MPU6050_REG_ACCEL_XOUT_H 0x3B

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Initialize the MPU-6050: verify presence, reset, configure, and start */
static int init_mpu6050(int handle) {
    int who_am_i;

    /* Verify sensor identity */
    who_am_i = i2cReadByteData(handle, MPU6050_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who_am_i);
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor not present or wrong address.\n",
                        who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Reset the device: write 0x80 to PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_REG_PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Error: failed to reset MPU-6050\n");
        return -1;
    }
    /* Allow time for the device to stabilize after reset */
    gpioDelay(100000); /* 100 ms */

    /* Wake up the device: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle time */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(handle, MPU6050_REG_SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error: failed to set sample rate divider\n");
        return -1;
    }

    /* Configure accelerometer: ±2 g range (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure accelerometer\n");
        return -1;
    }

    /* Configure gyroscope: ±250 deg/s range (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure gyroscope\n");
        return -1;
    }

    /* Enable accelerometer and temperature sensors (LPF disabled, no sleep) */
    if (i2cWriteByteData(handle, MPU6050_REG_PWR_MGMT_1, 0x01) < 0) {
        fprintf(stderr, "Error: failed to enable sensors\n");
        return -1;
    }

    return 0;
}

/* Read 14 bytes of raw sensor data starting at ACCEL_XOUT_H */
static int read_raw_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    char buffer[14];

    /* Read 14 bytes starting at ACCEL_XOUT_H (0x3B) */
    int bytes_read = i2cReadI2CBlockData(handle, MPU6050_REG_ACCEL_XOUT_H, buffer, 14);
    if (bytes_read != 14) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 14)\n", bytes_read);
        return -1;
    }

    /* Parse big-endian 16-bit values */
    *ax = (int16_t)((buffer[0]  << 8) | (uint8_t)buffer[1]);
    *ay = (int16_t)((buffer[2]  << 8) | (uint8_t)buffer[3]);
    *az = (int16_t)((buffer[4]  << 8) | (uint8_t)buffer[5]);
    /* buffer[6..7] = temperature (skipped) */
    *gx = (int16_t)((buffer[8]  << 8) | (uint8_t)buffer[9]);
    *gy = (int16_t)((buffer[10] << 8) | (uint8_t)buffer[11]);
    *gz = (int16_t)((buffer[12] << 8) | (uint8_t)buffer[13]);

    return 0;
}

int main(void) {
    int16_t ax, ay, az, gx, gy, gz;

    /* Register signal handlers for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X (pigpio error %d)\n",
                MPU6050_ADDR, i2c_handle);
        gpioTerminate();
