#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90614_ADDR  0x5A
#define TA_REG         0x06
#define TO_REG         0x07
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *out) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *out = (float)raw * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float ambient = 0.0f, object = 0.0f;
        int rc_a = i2c_read_reg16(fd, TA_REG, &ambient);
        int rc_o = i2c_read_reg16(fd, TO_REG, &object);

        if (rc_a != 0 || rc_o != 0) {
            fprintf(stderr, "I2C read error (ambient=%d, object=%d)\n", rc_a, rc_o);
        } else {
            if (log_temperature(fp, ambient, object) != 0) {
                perror("log_temperature");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

