#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define STS30_ADDR 0x4A
#define I2C_BUS 1
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEAS_DELAY_MS 10

static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    if (!error_log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

static int read_sts30_temperature(float *temperature) {
    unsigned char cmd[2] = {0x36, 0x1B};
    unsigned char data[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("Failed to write measurement command to STS30");
        return -1;
    }

    gpioDelay(MEAS_DELAY_MS * 1000);

    if (i2cReadDevice(i2c_handle, (char *)data, 3) != 3) {
        log_error("Failed to read data from STS30");
        return -1;
    }

    unsigned int raw_temp = ((unsigned int)data[0] << 8) | data[1];
