#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_sensor(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to SDP810: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from SDP810: expected 9 bytes, got %d (%s)\n", bytes_read, strerror(errno));
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "CRC error in scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    int16_t scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    data->differential_pressure = (float)raw_pressure / (float)scale_factor;
    data->temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting UTC time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->differential_pressure, data->temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", SDP810_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Differential Pressure (Pa),Temperature (C)\n");
        fflush(log_file);
    }

    sensor_data_t sensor_data;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            consecutive_errors = 0;
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading sensor data (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, attempting sensor re-initialization...\n");
                if (initialize_sensor() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

