#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x28
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MEAS_DELAY_US  2000     /* 2 ms  */
#define MAX_RETRIES    3
#define MAX_BACKOFF_S  16

static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP31 */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int sdp31_trigger_measurement(int handle)
{
    uint8_t cmd[2] = { 0x21, 0x96 };
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "[WARN] i2cWriteDevice (trigger) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

static int sdp31_read_measurement(int handle, float *pressure, float *temperature)
{
    uint8_t buf[6];
    int rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[WARN] i2cReadDevice failed: got %d bytes, expected 6\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[WARN] pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[WARN] temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static void log_data(FILE *f, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(f, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(f);
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "[FATAL] cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP31 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int backoff_ms = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (sdp31_trigger_measurement(i2c_handle) < 0) {
                backoff_ms = (backoff_ms == 0) ? 1 : (backoff_ms * 2);
                if (backoff_ms > MAX_BACKOFF_S * 1000) backoff_ms = MAX_BACKOFF_S * 1000;
                gpioDelay(backoff_ms * 1000);
                continue;
            }

            gpioDelay(MEAS_DELAY_US);

            float pressure, temperature;
            if (sdp31_read_measurement(i2c_handle, &pressure, &temperature) == 0) {
                log_data(log_file, pressure, temperature);
                ok = 1;
                break;
            }

            backoff_ms = (backoff_ms == 0) ? 1 : (backoff_ms * 2);
            if (backoff_ms > MAX_BACKOFF_S * 1000) backoff_ms = MAX_BACKOFF_S * 1000;
            gpioDelay(backoff_ms * 1000);
        }

        if (!ok && !terminate) {
            fprintf(stderr, "[ERROR] all %d attempts exhausted\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

