#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMID      0xF5
#define POLL_DELAY_US  10000   /* 10 ms between polls */
#define MAX_POLLS      20      /* 20 * 10 ms = 200 ms max */
#define SAMPLE_SEC     5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7015 (no data payload). */
static int si7015_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    int rc = i2cWriteDevice(handle, buf, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X) failed: %s\n",
                cmd, pigpio_error(rc));
    }
    return rc;
}

/* Read two bytes from the Si7015 (no register address). */
static int si7015_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %d bytes, got %d\n",
                len, rc);
        return -1;
    }
    return 0;
}

/* Trigger a measurement and wait for completion. */
static int si7015_measure(int handle, uint8_t cmd, uint16_t *raw)
{
    if (si7015_write_cmd(handle, cmd) < 0)
        return -1;

    for (int i = 0; i < MAX_POLLS; i++) {
        gpioDelay(POLL_DELAY_US);
        uint8_t buf[2];
        if (si7015_read_bytes(handle, buf, 2) == 0) {
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
    }
    fprintf(stderr, "[ERROR] Measurement for 0x%02X timed out after %d polls\n",
            cmd, MAX_POLLS);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static void log_data(FILE *fp, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n",
            ts, temp, hum);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("sensor_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] fopen(\"sensor_data.txt\") failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;

        if (si7015_measure(g_i2c_handle, CMD_TEMP, &raw_t) == 0 &&
            si7015_measure(g_i2c_handle, CMD_HUMID, &raw_h) == 0) {
            float temp = convert_temperature(raw_t);
            float hum  = convert_humidity(raw_h);
            log_data(fp, temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, hum);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_SEC * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    cleanup();
    return EXIT_SUCCESS;
}

