#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define MEASUREMENT_DELAY_US 10000
#define RETRY_COUNT 3
#define POLL_INTERVAL_US 2000000

#define CMD_MEASURE_TEMP_HOLD 0xE3
#define CMD_MEASURE_HUMID_HOLD 0xE5

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, float temp, float hum) {
    buf->data[buf->head].timestamp = time(NULL);
    buf->data[buf->head].temperature = temp;
    buf->data[buf->head].humidity = hum;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static int read_sensor(uint8_t cmd, uint16_t *raw) {
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        rc = i2cWriteByte(i2c_handle, cmd);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), attempt %d/%d\n", cmd, attempt + 1, RETRY_COUNT);
            gpioDelay(MEASUREMENT_DELAY_US);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_US);

        rc = i2cReadDevice(i2c_handle, buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (cmd 0x%02X), attempt %d/%d (rc=%d)\n", cmd, attempt + 1, RETRY_COUNT, rc);
        gpioDelay(MEASUREMENT_DELAY_US);
    }
    return -1;
}

static int read_temperature(float *temp) {
    uint16_t raw;
    if (read_sensor(CMD_MEASURE_TEMP_HOLD, &raw) != 0) return -1;
    *temp = 175.72f * (float)raw / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(float *hum) {
    uint16_t raw;
    if (read_sensor(CMD_MEASURE_HUMID_HOLD, &raw) != 0) return -1;
    *hum = 125.0f * (float)raw / 65536.0f - 6.0f;
    return 0;
}

static void control_fan(float temp) {
    static int fan_on = 0;
    if (temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (temp=%.2f C)\n", temp);
    } else if (temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (temp=%.2f C)\n", temp);
    }
}

static void print_buffer(const CircularBuffer *buf) {
    printf("\n--- Sensor Data Log (%d entries) ---\n", buf->count);
    int start = (buf->count < BUFFER_SIZE) ? 0 : buf->head;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&buf->data[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n", ts, buf->data[idx].temperature, buf->data[idx].humidity);
    }
    printf("--- End of Log ---\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X (rc=%d)\n", I2C_BUS, SI7021_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temp, hum;

        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Sensor read failed (temperature). Skipping cycle.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (read_humidity(&hum) != 0) {
            fprintf(stderr, "Sensor read failed (humidity). Skipping cycle.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        buffer_add(&buffer, temp, hum);
        control_fan(temp);

        char ts[32];
        struct tm *tm = localtime(&buffer.data[buffer.head].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n", ts, temp, hum);

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    print_buffer(&buffer);
    cleanup();
    return EXIT_SUCCESS;
}

