#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000  /* 5 seconds */
#define MEASUREMENT_DELAY_US 1000000 /* 1 second */

/* SCD40 Commands */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* CRC-8 calculation for SCD40 (polynomial 0x31, init 0xFF) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Send a 2-byte command to the SCD40 */
static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

/* Read 9 bytes of measurement data (6 data + 3 CRC bytes) */
static int read_measurement(uint8_t *data) {
    if (i2cReadDevice(i2c_handle, (char *)data, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SCD40\n");
        return -1;
    }
    return 0;
}

/* Verify CRC for a 2-byte word (MSB first) */
static int verify_crc(const uint8_t *data, uint8_t expected_crc) {
    uint8_t calc = crc8(data, 2);
    if (calc != expected_crc) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X, expected=0x%02X)\n",
                calc, expected_crc);
        return -1;
    }
    return 0;
}

/* Check data-ready flag; returns 1 if ready, 0 if not, -1 on error */
static int is_data_ready(void) {
    if (send_command(CMD_GET_DATA_READY_STATUS) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */
    uint8_t data[3];
    if (read_measurement(data) != 0)
        return -1;
    if (verify_crc(data, data[2]) != 0)
        return -1;
    uint16_t ready = (data[0] << 8) | data[1];
    return (ready == 1) ? 1 : 0;
}

/* Read CO2, temperature, and humidity; returns 0 on success, -1 on error */
static int read_scd40(uint16_t *co2, float *temp, float *hum) {
    if (send_command(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */
    uint8_t data[9];
    if (read_measurement(data) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    if (verify_crc(data, data[2]) != 0) return -1;
    if (verify_crc(data + 3, data[5]) != 0) return -1;
    if (verify_crc(data + 6, data[8]) != 0) return -1;

    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];

    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static void log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, SCD40_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    /* Start periodic measurement */
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(MEASUREMENT_DELAY_US); /* Wait for first measurement */

    printf("Air quality monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: Failed to check data-ready status\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (ready == 1) {
            uint16_t co2;
            float temp, hum;
            if (read_scd40(&co2, &temp, &hum) == 0) {
                log_data(co2, temp, hum);
                printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
                       co2, temp, hum);
            } else {
                fprintf(stderr, "Error: Failed to read SCD40 data\n");
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (send_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Warning: Failed to stop periodic measurement\n");
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    printf("Air quality monitoring stopped.\n");
    return 0;
}

