#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_S 5

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    return i2c_write_cmd(CMD_START_PERIODIC_MEASUREMENT);
}

static int stop_periodic_measurement(void) {
    return i2c_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT);
