    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on humidity word\n");
        return -1;
    }
    out->co2 = ((uint16_t)buf[0] << 8) | buf[1];
    out->temperature = (float)(((uint16_t)buf[3] << 8) | buf[4]) / 65536.0f;
    out->humidity = (float)(((uint16_t)buf[6] << 8) | buf[7]) / 65536.0f;
    return 0;
}

