        int idx = (start + i) % BUFFER_SIZE;
        printf("[%d] CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n",
               i, buffer.data[idx].co2,
               buffer.data[idx].temperature,
               buffer.data[idx].humidity);
    }
    printf("--- End of Buffer ---\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
