#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define TIMEOUT_US 50000             /* 50 ms edge-wait timeout */
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define MAX_CONSECUTIVE_FAILURES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the high-pulse width (TH) and total cycle width (TL) of a TMP05
 * digital output. Returns 0 on success, -1 on timeout or pigpio error.
 */
static int read_tmp05(int gpio_pin, double *th, double *tl) {
    uint32_t start_tick, end_tick, timeout_tick;
    int level;

    /* Wait for falling edge (line goes low) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while ((level = gpioRead(gpio_pin)) != 0) {
        if ((int)gpioTick() - timeout_tick >= 0) return -1;
    }
    start_tick = gpioTick();

    /* Wait for rising edge (line goes high) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while ((level = gpioRead(gpio_pin)) != 1) {
        if ((int)gpioTick() - timeout_tick >= 0) return -1;
    }
    end_tick = gpioTick();

    *th = (double)(end_tick - start_tick);
    *tl = (double)(end_tick - start_tick);
    return 0;
}

static double calculate_temperature(double th, double tl) {
    if (tl <= 0.0) return -999.0;
    return 4215.0 - (2143.0 * th / tl);
}

static void log_temperature(double temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        fprintf(log_file, "%s, ERROR: Temperature out of range (%.2f C)\n",
                timestamp, temperature);
        fflush(log_file);
        return;
    }

    fprintf(log_file, "%s, %.2f C\n", timestamp, temperature);
    fflush(log_file);
}

static void log_malfunction(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
    fflush(log_file);
}

int main(void) {
    double th, tl, temperature;
    int consecutive_failures = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_tmp05(GPIO_PIN, &th, &tl) == 0) {
            temperature = calculate_temperature(th, tl);
            if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
                log_malfunction();
                consecutive_failures++;
            } else {
                log_temperature(temperature);
                consecutive_failures = 0;
            }
        } else {
            log_malfunction();
            consecutive_failures++;
        }

        if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
            fprintf(stderr, "Too many consecutive failures (%d). Aborting.\n",
                    consecutive_failures);
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

