#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2400
#define MEASURE_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_S 5
#define LOG_FILE_NAME "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        if (*humidity > 100.0f) *humidity = 100.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;

        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d retries\n", RETRY_COUNT);
    return -1;
}

static sensor_data_t add_simulated_offset(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    double elapsed = difftime(now, 0);
    double offset_temp = 2.0 * sin(2.0 * M_PI * elapsed / 3600.0);
    double offset_hum = 5.0 * sin(2.0 * M_PI * elapsed / 3600.0);

    sensor_data_t offset_data;
    offset_data.temperature = data.temperature + offset_temp;
    offset_data.humidity = data.humidity + offset_hum;

    if (offset_data.temperature < -40.0f) offset_data.temperature = -40.0f;
    if (offset_data.temperature > 125.0f) offset_data.temperature = 125.0f;
    if (offset_data.humidity < 0.0f) offset_data.humidity = 0.0f;
    if (offset_data.humidity > 100.0f) offset_data.humidity = 100.0f;

    return offset_data;
}

static int log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        i2cClose(i2c_handle);
