#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400
#define MEASURE_DELAY_US 15000   /* 15 ms (datasheet: typ 12.1 ms, max 15 ms) */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler for clean shutdown ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Open I2C device and set slave address ---- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ---- Read temperature and humidity from SHT35 ----
 * Returns 0 on success, -1 on I2C error, -2 on CRC error.
 * Temperature: -45 °C + 175 °C * raw / 65535
 * Humidity:    0 % + 100 % * raw / 65535
 * ---- */
static int read_sht35(float *temperature, float *humidity)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB T_LSB T_CRC  RH_MSB RH_LSB RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRCs */
    if (sht35_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -2;
    }
    if (sht35_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ---- Append a CSV row with an ISO-8601 timestamp ---- */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(CSV_FILENAME, "r");
    int need_header = (fp == NULL);
    if (fp) fclose(fp);

    fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for append\n", CSV_FILENAME);
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialise I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;
        int rc = read_sht35(&temperature, &humidity);

        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0)
                fprintf(stderr, "Warning: failed to log data\n");
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I2C read error, will retry next cycle\n");
        } else {
            fprintf(stderr, "Warning: CRC error, will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

