#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define POLL_INTERVAL_MS 10
#define SAMPLE_INTERVAL_S 5

/* Si7021 commands */
#define CMD_MEASURE_HUMIDITY_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_PREV_HUM     0xE0
#define CMD_RESET                    0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Si7021: poly 0x31, init 0x00 */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Read a 3-byte measurement (MSB, LSB, CRC) from the Si7021.
 * Returns 0 on success, -1 on error.
 */
static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* Poll for data-ready with a timeout */
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += POLL_INTERVAL_MS) {
        uint8_t buf[2];
        if (i2c_read_bytes(fd, buf, 2) < 0)
            return -1;
        if ((buf[0] | buf[1]) != 0x00)
            break; /* data ready */
        usleep(POLL_INTERVAL_MS * 1000);
    }

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement (cmd 0x%02X)\n", cmd);
        return -1;
    }

    *raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_PREV_HUM, &raw) < 0)
        return -1;
    *temp = 175.72f * (float)raw / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_HUMIDITY_NO_HOLD, &raw) < 0)
        return -1;
    *hum = 125.0f * (float)raw / 65536.0f - 6.0f;
    return 0;
}

static int log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fclose(fp);
    return 0;
}

static int log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,ERROR\n", ts);
    fclose(fp);
    fprintf(stderr, "ERROR: %s\n", msg);
    return 0;
}

static int reset_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000); /* 15 ms reset recovery */
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    /* Probe: try a reset to confirm sensor is present */
    if (reset_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", SI7021_ADDR);
        close(g_i2c_fd);
        return 1;
    }

    /* Write header to log file */
    FILE *fp = fopen(LOG_FILE, "w");
    if (fp) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
        fclose(fp);
    }

    while (g_running) {
        float temp, hum;

        if (read_temperature(g_i2c_fd, &temp) < 0) {
            log_error("Temperature read failed");
            reset_sensor(g_i2c_fd);
        } else if (read_humidity(g_i2c_fd, &hum) < 0) {
            log_error("Humidity read failed");
            reset_sensor(g_i2c_fd);
        } else {
            if (log_data(temp, hum) < 0)
                fprintf(stderr, "Logging failed\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

