#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

#define SENSOR_MIN_COUNT 1638
#define SENSOR_MAX_COUNT 14745
#define SENSOR_MIN_PRESSURE 0.0
#define SENSOR_MAX_PRESSURE 10.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor(int handle, float *pressure) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: I2C read failed (expected 2 bytes, got %d)\n", bytes);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    raw &= 0x3FFF;
    raw >>= 2;

    float flow_rate = SENSOR_MIN_PRESSURE +
        (float)raw * (SENSOR_MAX_PRESSURE - SENSOR_MIN_PRESSURE) /
        (float)(SENSOR_MAX_COUNT - SENSOR_MIN_COUNT);

    *pressure = flow_rate;
    return 0;
}

static void control_fan(float pressure) {
    int duty = (int)(pressure * 100.0f / SENSOR_MAX_PRESSURE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioPWM(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float pressure;
    while (!terminate) {
        if (read_sensor(i2c_handle, &pressure) == 0) {
            control_fan(pressure);
            log_data(log_file, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping cycle\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

