        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

