#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define THRESHOLD      28.0f
#define SAMPLE_PERIOD  1.0

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read temperature from STLM75.
 * Returns 0 on success and stores Celsius in *out_temp.
 * Returns -1 on I2C error.
 */
static int read_temperature(float *out_temp)
{
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (pigpio code %d)\n", raw);
        return -1;
    }

    /* pigpio returns bytes in little-endian order: low byte first, high byte second.
     * STLM75 sends the 9-bit two's-complement value in the low 8 bits of the 16-bit
     * word; the high byte is always 0.  Swap bytes and right-shift by 7 to get
     * the 9-bit two's-complement value.  Divide by 2 to convert to Celsius.
     */
    uint16_t swapped = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));
    int16_t temp_9bit = (int16_t)(swapped >> 7);
    *out_temp = (float)temp_9bit / 2.0f;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (pigpio code %d)\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float buffer[BUFFER_SIZE];
    int   buf_idx = 0;
    int   buf_count = 0;

    while (!terminate) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer[buf_idx] = temp;
            buf_idx = (buf_idx + 1) % BUFFER_SIZE;
            if (buf_count < BUFFER_SIZE) buf_count++;

            float sum = 0.0f;
            for (int i = 0; i < buf_count; i++) sum += buffer[i];
            float avg = (buf_count > 0) ? (sum / (float)buf_count) : 0.0f;

            if (avg > THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }

            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
        } else {
            fprintf(stderr, "Skipping sample due to I2C read failure\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

