#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define VENTILATION_THRESHOLD_HIGH 1200
#define VENTILATION_THRESHOLD_LOW 800

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int write_command(uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    buf[2] = (arg >> 8) & 0xFF;
    buf[3] = arg & 0xFF;
    buf[4] = crc8(buf + 2, 2);
    if (i2cWriteDevice(i2c_handle, (char *)buf, 5) != 5) {
        fprintf(stderr, "I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_response(uint8_t *buf, int len) {
    int n = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d\n", len, n);
        return -1;
    }
    return 0;
}

static int read_data_ready(uint16_t *ready) {
    if (write_command(0x0202, 0) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (read_response(buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready status\n");
        return -1;
    }
    *ready = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_measurement(sensor_data_t *data) {
    if (write_command(0x0300, 0) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[18];
    if (read_response(buf, 18) != 0) return -1;
    for (int i = 0; i < 18; i += 3) {
        if (crc8(buf + i, 2) != buf[i + 2]) {
            fprintf(stderr, "CRC mismatch at offset %d\n", i);
            return -1;
        }
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[6] << 8) | buf[7];
    data->temperature /= 65535.0f;
    data->humidity = (buf[10] << 8) | buf[11];
    data->humidity /= 65535.0f;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, data->co2, data->temperature, data->humidity);
    fflush(log_file);
}

static void control_ventilation(uint16_t co2) {
    if (co2 >= VENTILATION_THRESHOLD_HIGH)
        printf("Ventilation: HIGH\n");
    else if (co2 >= VENTILATION_THRESHOLD_LOW)
        printf("Ventilation: LOW\n");
    else
        printf("Ventilation: OFF\n");
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        write_command(0x0104, 0x0000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", SCD30_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (write_command(0x0103, 2) != 0) {
        fprintf(stderr, "Failed to set measurement interval\n");
        cleanup();
        return 0;
    }
    gpioDelay(10000);

    if (write_command(0x0106, 0x0000) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 0;
    }
    gpioDelay(10000);

    printf("SCD30 monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t ready = 0;
        if (read_data_ready(&ready) != 0) {
            fprintf(stderr, "Failed to read data-ready flag\n");
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }
        if (!(ready & 0x07FF)) {
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        sensor_data_t data;
        if (read_measurement(&data) != 0) {
            fprintf(stderr, "Failed to read measurement data\n");
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        log_data(&data);
        control_ventilation(data.co2);

        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

