#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_SAMPLE_INTERVAL_MS 1000
#define MEASUREMENT_DELAY_MS 5
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 polynomial 0x31, init 0xFF, as per Sensirion SGP30/SDP32 datasheet */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (code %d).\n",
                I2C_BUS, SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int start_continuous_measurement(void) {
    uint8_t cmd[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send continuous-measurement command (code %d).\n", result);
        return -1;
    }
    return 0;
}

static int read_sdp32_data(float *pressure_pa) {
    uint8_t buffer[9];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 9).\n", result);
        return -1;
    }

    /* Verify CRC for pressure, temperature, and scale-factor words */
    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

static void log_data(float pressure_pa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Differential Pressure: %.2f Pa\n", timestamp, pressure_pa);
    fflush(stdout);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sample_interval_ms = DEFAULT_SAMPLE_INTERVAL_MS;

    if (argc > 1) {
        sample_interval_ms = atoi(argv[1]);
        if (sample_interval_ms <= 0) {
            fprintf(stderr, "Warning: Invalid sample interval '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_SAMPLE_INTERVAL_MS);
            sample_interval_ms = DEFAULT_SAMPLE_INTERVAL_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (start_continuous_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete */
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    int consecutive_failures = 0;

    while (!terminate) {
        float pressure_pa = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_sdp32_data(&pressure_pa) == 0) {
                success = 1;
                break;
            }
            retries++;
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (success) {
            log_data(pressure_pa);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Error: Failed to read sensor data after %d retries.\n", MAX_RETRIES);
            if (consecutive_failures >= 5) {
                fprintf(stderr, "Error: Sensor may be disconnected or bus error. Exiting.\n");
                break;
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        int remaining = sample_interval_ms;
        while (remaining > 0 && !terminate) {
            int chunk = (remaining > 100) ? 100 : remaining;
            gpioDelay(chunk * 1000);
            remaining -= chunk;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

