#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define CMD_CONT_MEAS   0x3615
#define CONV_DELAY_US  45000   /* 45 ms conversion time */
#define SAMPLE_PERIOD  1000000 /* 1 second in microseconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8: polynomial 0x31, initial value 0xFF (Sensirion spec) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read one measurement frame from the SDP810.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = { (uint8_t)(CMD_CONT_MEAS >> 8), (uint8_t)(CMD_CONT_MEAS & 0xFF) };
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale_factor(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: i2cReadDevice failed (sensor may be absent or bus error)\n");
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: scale-factor CRC mismatch\n");
        return -2;
    }

    /* Assemble 16-bit big-endian values */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: invalid scale factor (0)\n");
        return -2;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x25 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — check wiring and address\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, temperature;

    while (g_running) {
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
            fflush(stdout);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I/O error, retrying next cycle\n");
        } else {
            fprintf(stderr, "Warning: CRC error, retrying next cycle\n");
        }

        /* Sleep 1 second (microseconds) */
        gpioDelay(SAMPLE_PERIOD);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

