#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define I2C_BUS             "/dev/i2c-1"
#define CONFIG_REG_ADDR     0x02
#define TEMP_REG_ADDR       0x00
#define CONFIG_VALUE        0x1000  /* Bit 12: 1 = temp+humidity, 14-bit */
#define CONVERSION_DELAY_MS 20
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    if (i2c_write_reg16(fd, CONFIG_REG_ADDR, CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to configure HDC1000\n");
        return -1;
    }
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw_t, raw_h;

    if (i2c_read_reg16(fd, TEMP_REG_ADDR, &raw_t) != 0)
        return -1;

    /* Small delay so the 14-bit conversion completes */
    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_reg16(fd, TEMP_REG_ADDR, &raw_h) != 0)
        return -1;

    *temperature = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_h / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor may be absent)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized. Reading every %d seconds. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nExiting cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

