#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define CMD_MEASURE_TEMP_HOLD 0xE3
#define CMD_READ_ID_1 0xFA
#define CMD_READ_ID_2 0x0F
#define CMD_RESET 0xFE
#define CMD_READ_RHT_USER_REG 0xE7
#define CMD_WRITE_RHT_USER_REG 0xE6
#define CMD_READ_HEATER_CTRL 0x11
#define CMD_WRITE_HEATER_CTRL 0x51

#define MEASUREMENT_DELAY_US 15000
#define POLL_INTERVAL_US 5000000
#define I2C_TIMEOUT_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int send_command(uint8_t cmd) {
    char buf[1] = {(char)cmd};
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to send command 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_bytes(uint8_t *buf, int len) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: Failed to read %d bytes (got %d)\n", len, bytes_read);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    if (send_command(CMD_MEASURE_TEMP_HOLD) != 0) return -1;
    gpioDelay(MEASUREMENT_DELAY_US);

    uint8_t data[2];
    if (read_bytes(data, 2) != 0) return -1;

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_sensor_id(uint8_t *id) {
    if (send_command(CMD_READ_ID_1) != 0) return -1;
    gpioDelay(10000);
    if (read_bytes(id, 8) != 0) return -1;
    return 0;
}

static int initialize_sensor(void) {
    uint8_t id[8];
    if (read_sensor_id(id) != 0) {
        fprintf(stderr, "Error: Sensor not detected or ID read failed\n");
        return -1;
    }
    printf("Si7051 detected (ID: %02X %02X %02X %02X %02X %02X %02X %02X)\n",
           id[0], id[1], id[2], id[3], id[4], id[5], id[6], id[7]);

    if (send_command(CMD_RESET) != 0) return -1;
    gpioDelay(15000);

    uint8_t user_reg;
    if (send_command(CMD_READ_RHT_USER_REG) != 0) return -1;
    gpioDelay(10000);
    if (read_bytes(&user_reg, 1) != 0) return -1;

    uint8_t new_user_reg = user_reg & 0xFD;
    if (send_command(CMD_WRITE_RHT_USER_REG) != 0) return -1;
    gpioDelay(10000);
    char buf[2] = {(char)new_user_reg, 0x00};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write user register\n");
        return -1;
    }
    gpioDelay(10000);

    uint8_t heater_ctrl;
    if (send_command(CMD_READ_HEATER_CTRL) != 0) return -1;
    gpioDelay(10000);
    if (read_bytes(&heater_ctrl, 1) != 0) return -1;

    if (send_command(CMD_WRITE_HEATER_CTRL) != 0) return -1;
    gpioDelay(10000);
    char ctrl_buf[2] = {(char)heater_ctrl, 0x00};
    if (i2cWriteDevice(i2c_handle, ctrl_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write heater control\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting temperature readings every 5 seconds...\n");

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

