        if (bytes_read == 2) {
            int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
            *pressure = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        gpioDelay(10000);
    }
    return -1;
