            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

