#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define CMD_READ_OTP   0x50
#define CMD_MEASURE    0x40
#define MEASURE_DELAY_US 7000
#define SAMPLE_PERIOD_US 5000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_otp(int handle, uint16_t otp[4]) {
    char cmd = CMD_READ_OTP;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(1000);
    char buf[8];
    int n = i2cReadDevice(handle, buf, 8);
    if (n != 8) {
        fprintf(stderr, "Error: OTP read returned %d bytes (expected 8)\n", n);
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        otp[i] = ((uint16_t)(buf[2 * i]) << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_measurement(int handle, uint16_t *raw_t, uint32_t *raw_p) {
    char cmd = CMD_MEASURE;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);
    char buf[6];
    int n = i2cReadDevice(handle, buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: measurement read returned %d bytes (expected 6)\n", n);
        return -1;
    }
    if (memcmp(buf, "\xFF\xFF\xFF\xFF\xFF\xFF", 6) == 0) {
        fprintf(stderr, "Error: sensor returned all 0xFF (sensor absent or bus error)\n");
        return -1;
    }
    *raw_t = ((uint16_t)(buf[0]) << 8) | (uint8_t)buf[1];
    *raw_p = ((uint32_t)(buf[2]) << 24) | ((uint32_t)(buf[3]) << 16) |
             ((uint32_t)(buf[4]) << 8)  | (uint8_t)buf[5];
    return 0;
}

static void compensate(uint16_t raw_t, uint32_t raw_p, uint16_t otp[4],
                       float *temp_c, float *press_pa) {
    float scale_lut = (float)otp[0] / 65536.0f;
    float scale_h   = (float)otp[1] / 65536.0f;
    float scale_p   = (float)otp[2] / 65536.0f;
    float lut_offset = (float)otp[3] / 65536.0f;

    float t_scaled = (float)raw_t * scale_lut;
    float t_comp = t_scaled - lut_offset;
    float t_lin = t_comp * scale_h;
    *temp_c = t_lin;

    float p_scaled = (float)raw_p * scale_p;
    float p_comp = p_scaled - lut_offset;
    float p_lin = p_comp * scale_h;
    *press_pa = p_lin;
}

static void log_reading(float temp_c, float press_pa) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp_c, press_pa);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t otp[4];
    if (read_otp(g_i2c_handle, otp) != 0) {
        fprintf(stderr, "Error: failed to read OTP calibration coefficients\n");
        cleanup();
        return 1;
    }

    while (g_running) {
        uint16_t raw_t;
        uint32_t raw_p;
        if (read_measurement(g_i2c_handle, &raw_t, &raw_p) == 0) {
            float temp_c, press_pa;
            compensate(raw_t, raw_p, otp, &temp_c, &press_pa);
            log_reading(temp_c, press_pa);
        } else {
            fprintf(stderr, "Warning: measurement read failed, retrying next cycle\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

