#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 8000
#define LOG_FILE "airflow_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp800(float *pressure) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read 3 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC check failed for pressure data.\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw / 60.0f;
    return 0;
}

static int log_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", SDP800_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    float pressure;
    while (running) {
        if (read_sdp800(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read pressure data.\n");
        }
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

