        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", PRESSURE_REG, rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure);
    fflush(g_log_file);
}

static void check_pressure(float pressure)
{
    if (pressure < LOW_PRESSURE || pressure > HIGH_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa outside safe range [%.0f, %.0f] kPa\n",
                pressure, LOW_PRESSURE, HIGH_PRESSURE);
    }
}

static int file_is_empty(const char *path)
{
    FILE *f = fopen(path, "r");
    if (!f) return 1;
    int c = fgetc(f);
    fclose(f);
    return (c == EOF);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (file_is_empty(LOG_FILE)) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float pressure;

        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            check_pressure(pressure);
        } else {
            fprintf(stderr, "I2C read failed; re-initialising bus...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialisation failed; continuing to retry...\n");
            }
            if (read_pressure(&pressure) == 0) {
                log_pressure(pressure);
                check_pressure(pressure);
            } else {
                fprintf(stderr, "Second I2C read failed; continuing to retry...\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

