#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1024 * 1024)
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void rotate_log(void) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) return;
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fclose(fp);
    if (size > MAX_LOG_SIZE) {
        remove(LOG_FILE);
    }
}

static int read_hih6130(float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    /* Trigger measurement: write 0x00 to the sensor */
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error writing trigger byte to HIH6130: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes: [status, humidity_hi, humidity_lo, temp_hi, temp_lo] */
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading 4 bytes from HIH6130: %d\n", result);
        return -1;
    }

    /* Validate status bits (bits 7-6 of first byte) */
    if ((data[0] & 0xC0) != 0x00) {
        fprintf(stderr, "HIH6130 status error: 0x%02X\n", data[0]);
        return -1;
    }

    /* Humidity: 14-bit value in data[0] (lower 2 bits) and data[1] */
    unsigned int raw_humidity = ((data[0] & 0x3F) << 8) | data[1];
    *humidity = (float)raw_humidity * 100.0f / 16383.0f;

    /* Temperature: 14-bit value in data[2] and data[3] */
    unsigned int raw_temperature = (data[2] << 6) | (data[3] >> 2);
    *temperature = (float)raw_temperature * 165.0f / 16383.0f - 40.0f;

    return 0;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fflush(log_file);
}

