#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "pressure_log.txt"
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define NUM_NIBBLES 4
#define READ_TIMEOUT_MS 1000
#define POLL_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

static int read_sent_pressure(float *pressure) {
    uint32_t start_tick, end_tick;
    int nibbles[NUM_NIBBLES];
    int i;

    start_tick = gpioTick();
    while (running) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > (READ_TIMEOUT_MS * 1000)) {
            fprintf(stderr, "Sensor timeout: no sync pulse detected\n");
            return -1;
        }
        if (gpioRead(GPIO_PIN) == 0) break;
        gpioDelay(POLL_DELAY_US);
    }
    if (!running) return -1;

    start_tick = gpioTick();
    while (running) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > (READ_TIMEOUT_MS * 1000)) {
            fprintf(stderr, "Sensor timeout: sync pulse not detected\n");
            return -1;
        }
        if (gpioRead(GPIO_PIN) == 1) break;
        gpioDelay(POLL_DELAY_US);
    }
    if (!running) return -1;

    start_tick = gpioTick();
    while (running) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > (READ_TIMEOUT_MS * 1000)) {
            fprintf(stderr, "Sensor timeout: sync pulse not detected\n");
            return -1;
        }
        if (gpioRead(GPIO_PIN) == 0) break;
        gpioDelay(POLL_DELAY_US);
    }
    if (!running) return -1;

    for (i = 0; i < NUM_NIBBLES; i++) {
        start_tick = gpioTick();
        while (running) {
            end_tick = gpioTick();
            if ((end_tick - start_tick) > (READ_TIMEOUT_MS * 1000)) {
                fprintf(stderr, "Sensor timeout: nibble %d pulse not detected\n", i);
                return -1;
            }
            if (gpioRead(GPIO_PIN) == 1) break;
            gpioDelay(POLL_DELAY_US);
        }
        if (!running) return -1;

        uint32_t pulse_us = 0;
        start_tick = gpioTick();
        while (running) {
            end_tick = gpioTick();
            if ((end_tick - start_tick) > (READ_TIMEOUT_MS * 1000)) {
                fprintf(stderr, "Sensor timeout: nibble %d pulse not detected\n", i);
                return -1;
            }
            if (gpioRead(GPIO_PIN) == 0) break;
            gpioDelay(POLL_DELAY_US);
        }
        if (!running) return -1;

        pulse_us = end_tick - start_tick;
        uint32_t ticks = pulse_us / TICK_US;
        if (ticks < NIBBLE_MIN_TICKS || ticks > NIBBLE_MAX_TICKS) {
            fprintf(stderr, "Invalid nibble pulse width: %u ticks (nibble %d)\n", ticks, i);
            return -1;
        }
        nibbles[i] = (ticks - NIBBLE_MIN_TICKS) / 10;
    }

    int checksum = (nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3]) % 16;
    if (checksum != nibbles[3]) {
        fprintf(stderr, "Checksum error: expected %d, got %d\n", checksum, nibbles[3]);
        return -1;
    }

    int raw = (nibbles[0] << 8) | (nibbles[1] << 4) | nibbles[2];
    *pressure = (float)raw * 0.007f + 10.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    float pressure;
    while (running) {
        if (read_sent_pressure(&pressure) == 0) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Failed to log pressure\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

