#include <unistd.h>

#define SHTC3_ADDR 0x70
#define MEASURE_CMD_MSB 0x78
#define MEASURE_CMD_LSB 0x66
#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5
#define CONVERSION_DELAY_US 12400

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_shtc3(int handle, sensor_data_t *data) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t hum_raw  = ((uint16_t)buf[3] << 8) | buf[4];

    data->temperature = 175.0f * (float)temp_raw / 65535.0f - 45.0f;
    data->humidity    = 100.0f * (float)hum_raw  / 65535.0f;

    if (data->temperature < -40.0f || data->temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", data->temperature);
        return -1;
    }
    if (data->humidity < 0.0f || data->humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", data->humidity);
        return -1;
    }

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    fclose(fp);
    return 0;
}

