        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_shtc3(i2c_handle, &sensor_data) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   sensor_data.temperature, sensor_data.humidity);
            if (log_data(LOG_FILE, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Warning: log_data failed\n");
            }
        } else {
            fprintf(stderr, "Warning: read_shtc3 failed, will retry next cycle\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

