#include <errno.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "mag_temp_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, SI7202_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: expected 2 bytes, got %d\n", result);
        data->magnetic_field = NAN;
        data->temperature = NAN;
        return -1;
    }
    int16_t raw_value = (int16_t)((buf[0] << 8) | buf[1]);
    data->magnetic_field = (float)raw_value * 0.1f;
    data->temperature = (float)raw_value * 0.01f - 25.0f;
    return 0;
}

static int log_data(const sensor_data_t *data) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
        fseek(log_file, 0, SEEK_END);
        if (ftell(log_file) == 0) {
            fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        }
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->magnetic_field, data->temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

