    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values...\n");
            sensor_data.magnetic_field = NAN;
            sensor_data.temperature = NAN;
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

