#define SAMPLE_INTERVAL_US 1000000
#define FLOW_MIN 0.0
#define FLOW_MAX 25.0
#define TEMP_MIN -40.0
#define TEMP_MAX 100.0
#define FLOW_SCALE 0.8
#define FLOW_OFFSET 0.1
#define TEMP_SCALE 0.8
#define TEMP_OFFSET 0.1
#define TEMP_OFFSET_C 40.0
#define FLOW_RAW_MAX 16384.0
#define TEMP_RAW_MAX 4096.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *raw_flow, uint16_t *raw_temp) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C device: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *raw_flow = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint8_t)buf[1];
    *raw_temp = ((uint16_t)(buf[2] & 0x3F) << 8) | (uint8_t)buf[3];
    return 0;
}

static float convert_flow(uint16_t raw_flow) {
    float flow = ((float)raw_flow / FLOW_RAW_MAX - FLOW_OFFSET) / FLOW_SCALE * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
    if (flow < FLOW_MIN) flow = FLOW_MIN;
    if (flow > FLOW_MAX) flow = FLOW_MAX;
    return flow;
}

static float convert_temperature(uint16_t raw_temp) {
    float temp = ((float)raw_temp / TEMP_RAW_MAX - TEMP_OFFSET) / TEMP_SCALE * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
    if (temp < TEMP_MIN) temp = TEMP_MIN;
    if (temp > TEMP_MAX) temp = TEMP_MAX;
    return temp;
}

