    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Flow Rate: %.2f SLPM, Temperature: %.2f C\n", timestamp, flow_rate, temperature);
    fflush(log_file);
}

