#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_US 2000000  /* 2 seconds */
#define MAX_RETRIES 3

/* DHT11 timing constants (microseconds) */
#define START_LOW_US  18000          /* 18 ms low to trigger the sensor */
#define RESP_LOW_US   80             /* 80 us low response from sensor */
#define RESP_HIGH_US  80             /* 80 us high response from sensor */
#define BIT_LOW_US    50             /* 50 us low pulse per bit */
#define BIT_THRESHOLD_US 40          /* >40 us high => '1', else '0' */
#define TIMEOUT_US    1000           /* per-phase timeout */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a timestamped line to the log file. */
static void log_line(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    }
    fclose(fp);
}

/*
 * Read 40 data bits from the DHT11.
 * Returns 0 on success and fills *humidity and *temperature.
 * Returns -1 on timeout, -2 on checksum failure, -3 on sensor-absent.
 */
static int read_dht11(int gpio, float *humidity, float *temperature)
{
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i;

    /* --- Start signal: pull low for 18 ms, then high --- */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        log_line("ERROR: gpioSetMode(output) failed");
        return -1;
    }
    if (gpioWrite(gpio, 0) < 0) {
        log_line("ERROR: gpioWrite(0) failed");
        return -1;
    }
    gpioDelay(START_LOW_US);
    if (gpioWrite(gpio, 1) < 0) {
        log_line("ERROR: gpioWrite(1) failed");
        return -1;
    }
    gpioDelay(20);  /* let pull-up pull the line high */

    /* Switch to input; external pull-up keeps line high */
    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        log_line("ERROR: gpioSetMode(input) failed");
        return -1;
    }

    /* --- Sensor response: ~80 us low, ~80 us high --- */
    uint32_t t0 = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - t0 > TIMEOUT_US) {
            log_line("ERROR: sensor response low timeout");
            return -1;
        }
    }
    t0 = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - t0 > TIMEOUT_US) {
            log_line("ERROR: sensor response high timeout");
            return -1;
        }
    }
    t0 = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - t0 > TIMEOUT_US) {
            log_line("ERROR: sensor response low timeout");
            return -1;
        }
    }

    /* --- Read 40 data bits --- */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of ~50 us low pulse) */
        t0 = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - t0 > TIMEOUT_US) {
                char msg[128];
                snprintf(msg, sizeof(msg), "ERROR: bit %d low timeout", i);
                log_line(msg);
                return -1;
            }
        }
        /* Measure high-pulse duration */
        t0 = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - t0 > TIMEOUT_US) {
                char msg[128];
                snprintf(msg, sizeof(msg), "ERROR: bit %d high timeout", i);
                log_line(msg);
                return -1;
            }
        }
        uint32_t high_us = gpioTick() - t0;
        data[i / 8] <<= 1;
        if (high_us > BIT_THRESHOLD_US)
            data[i / 8] |= 1;
    }

    /* --- Checksum --- */
    uint8_t sum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (sum != data[4]) {
        log_line("ERROR: checksum mismatch");
        return -2;
    }

    /* --- Parse: humidity = data[0], temperature = data[2] --- */
    *humidity = (float)data[0];
    *temperature = (float)data[2];
    return 0;
}

int main(void)
{
    float humidity, temperature;
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 4 as input (external pull-up keeps line high) */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", DHT11_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("DHT11 bit-bang reader started on GPIO %d. Press Ctrl+C to exit.\n",
           DHT11_GPIO);

    while (g_running) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            rc = read_dht11(DHT11_GPIO, &humidity, &temperature);
            if (rc == 0) {
                success = 1;
                break;
            }
            gpioDelay(200000);  /* 200 ms between retries */
        }

        if (success) {
            char line[256];
            snprintf(line, sizeof(line),
                     "Temperature: %.1f C, Humidity: %.1f %%",
                     temperature, humidity);
            printf("%s\n", line);
            log_line(line);
        } else {
            log_line("ERROR: DHT11 read failed after retries");
        }

        /* Sleep in small increments so signals are caught promptly */
        uint32_t remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

