#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define MEASURE_DELAY_US 15000
#define LOG_FILE "sht31d_data.log"
#define SAMPLE_INTERVAL_S 5
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SHT31_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(sensor_data_t *data) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];
        data->temperature = -45.0f + (175.0f * temp_raw / 65535.0f);
        data->humidity = 100.0f * hum_raw / 65535.0f;
        return 0;
    }

    fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,ERROR,%s\n", timestamp, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            log_error("Sensor read failed");
        }
        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
    }

    cleanup();
    return EXIT_SUCCESS;
}

