#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_DEVID_REG 0x00
#define ADPD105_DEVID_VAL 0x2A
#define ADPD105_CH_RED_REG 0x64
#define ADPD105_CH_GREEN_REG 0x66
#define ADPD105_CH_BLUE_REG 0x68
#define CCT_LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adpd105_channel(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (reg 0x%02X): rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int verify_adpd105(int handle) {
    char devid;
    int rc = i2cReadI2CBlockData(handle, ADPD105_DEVID_REG, &devid, 1);
    if (rc != 1) {
        fprintf(stderr, "Failed to read device ID register\n");
        return -1;
    }
    if ((uint8_t)devid != ADPD105_DEVID_VAL) {
        fprintf(stderr, "Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                (uint8_t)devid, ADPD105_DEVID_VAL);
        return -1;
    }
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;
    float n = r + g + b;
    if (n == 0.0f) return 0.0f;
    float rp = r / n;
    float gp = g / n;
    float bp = b / n;
    float cct = 1000.0f * (1.0f - rp) / (rp * (1.0f - gp) + gp * (1.0f - bp) + bp);
    if (cct < 0.0f) cct = 0.0f;
    return cct;
}

static int log_cct(float cct) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", ts, cct) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (addr 0x%02X): %d\n",
                ADPD105_ADDR_1, i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2 (addr 0x%02X): %d\n",
                ADPD105_ADDR_2, i2c_handle_2);
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
        gpioTerminate();
        return 1;
    }

    if (verify_adpd105(i2c_handle_1) != 0 || verify_adpd105(i2c_handle_2) != 0) {
        fprintf(stderr, "ADPD105 verification failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(CCT_LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    while (running) {
        uint16_t red1 = 0, green1 = 0, blue1 = 0;
        uint16_t red2 = 0, green2 = 0, blue2 = 0;
        int err1 = 0, err2 = 0;

        if (read_adpd105_channel(i2c_handle_1, ADPD105_CH_RED_REG, &red1) != 0 ||
            read_adpd105_channel(i2c_handle_1, ADPD105_CH_GREEN_REG, &green1) != 0 ||
            read_adpd105_channel(i2c_handle_1, ADPD105_CH_BLUE_REG, &blue1) != 0) {
            fprintf(stderr, "Sensor 1 read error; skipping cycle\n");
            err1 = 1;
        }

        if (read_adpd105_channel(i2c_handle_2, ADPD105_CH_RED_REG, &red2) != 0 ||
            read_adpd105_channel(i2c_handle_2, ADPD105_CH_GREEN_REG, &green2) != 0 ||
            read_adpd105_channel(i2c_handle_2, ADPD105_CH_BLUE_REG, &blue2) != 0) {
            fprintf(stderr, "Sensor 2 read error; skipping cycle\n");
            err2 = 1;
        }

        if (!err1 && !err2) {
            float cct1 = calculate_cct(red1, green1, blue1);
            float cct2 = calculate_cct(red2, green2, blue2);
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_cct(avg_cct) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

