#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define LM75B_TEMP_REG 0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define POLL_INTERVAL_US   1000000  /* 1 second */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int init_circular_buffer(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++)
        cb->buffer[i] = 0.0f;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float calculate_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *temp_out)
{
    char reg = (char)LM75B_TEMP_REG;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature register address.\n");
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read 2 bytes from temperature register.\n");
        return -1;
    }

    /* LM75B: 9-bit signed, bits D9-D1, D0 always 0 */
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 1;  /* arithmetic shift keeps sign for negative temps */
    *temp_out = (float)raw * 0.5f;
    return 0;
}

static int control_fan(int gpio, int on)
{
    if (gpioWrite(gpio, on) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

int main(void)
{
    CircularBuffer temp_buffer;
    int fan_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, LM75B_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    if (init_circular_buffer(&temp_buffer) != 0) {
        fprintf(stderr, "Error: failed to initialize circular buffer.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed, retrying next cycle.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        add_to_buffer(&temp_buffer, temperature);
        float avg = calculate_average(&temp_buffer);

        printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);

        if (avg > TEMP_THRESHOLD_HIGH && fan_state == 0) {
            if (control_fan(FAN_GPIO, 1) == 0) {
                fan_state = 1;
                printf("Fan turned ON (average %.2f C > %.1f C)\n", avg, TEMP_THRESHOLD_HIGH);
            }
        } else if (avg < TEMP_THRESHOLD_LOW && fan_state == 1) {
            if (control_fan(FAN_GPIO, 0) == 0) {
                fan_state = 0;
                printf("Fan turned OFF (average %.2f C < %.1f C)\n", avg, TEMP_THRESHOLD_LOW);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

