    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;

    /* Send continuous measurement command */
    if (i2cWriteDevice(i2c_handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "Error writing continuous-measurement command\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, status(2)+crc */
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading sensor data (got %d bytes, expected 9)\n",
                bytes_read);
        return -1;
    }

    /* Validate CRC for each 2-byte word */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on status word\n");
        return -1;
    }

    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* SDP810 scale factors */
    data->pressure    = (float)raw_pressure    / 60.0f;
    data->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

