        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void check_pressure_threshold(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "WARNING: Pressure %.2f Pa exceeds threshold %.1f Pa\n",
                pressure, PRESSURE_THRESHOLD);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

