#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define MAX_RETRIES    3
#define MEASURE_DELAY  20000       /* microseconds (20 ms) */

/* Si7021 single-byte commands (no register addressing) */
#define CMD_MEASURE_RH_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_TEMP_PREV_RH   0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fclose(fp);
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(g_i2c_handle, buf, 1);
        if (rc == 0)
            return 0;
        gpioDelay(1000);  /* 1 ms backoff */
    }
    return -1;
}

static int i2c_read_bytes(uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(g_i2c_handle, (char *)buf, len);
        if (rc == len)
            return 0;
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Si7021 measurement                                                  */
/* ------------------------------------------------------------------ */
static int si7021_measure_rh(float *rh)
{
    if (i2c_write_cmd(CMD_MEASURE_RH_NO_HOLD) != 0) {
        log_error("Failed to send RH measurement command");
        return -1;
    }
    gpioDelay(MEASURE_DELAY);

    uint8_t buf[2];
    if (i2c_read_bytes(buf, 2) != 0) {
        log_error("Failed to read RH measurement result");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *rh = 125.0f * raw / 65536.0f - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static int si7021_measure_temp(float *temp)
{
    if (i2c_write_cmd(CMD_MEASURE_TEMP_NO_HOLD) != 0) {
        log_error("Failed to send temperature measurement command");
        return -1;
    }
    gpioDelay(MEASURE_DELAY);

    uint8_t buf[2];
    if (i2c_read_bytes(buf, 2) != 0) {
        log_error("Failed to read temperature measurement result");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = 175.72f * raw / 65536.0f - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                              */
/* ------------------------------------------------------------------ */
static int si7021_present(void)
{
    /* Issue a dummy read to confirm the device responds */
    uint8_t dummy[1];
    if (i2c_read_bytes(dummy, 1) != 0) {
        log_error("Si7021 not responding on I2C bus 1 at 0x40");
        return 0;
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file for appending");
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fflush(fp);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temp, rh);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus 1 at 0x40");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!si7021_present()) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 sensor initialized on I2C bus %d at 0x%02X.\n",
           I2C_BUS, SI7021_ADDR);
    printf("Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temp, rh;

        if (si7021_measure_temp(&temp) != 0) {
            log_error("Temperature measurement failed; skipping cycle");
        } else if (si7021_measure_rh(&rh) != 0) {
            log_error("Humidity measurement failed; skipping cycle");
        } else {
            log_data(temp, rh);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

