#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define I2C_BUS 1
#define CONFIG_REG 0x02
#define MEASURE_REG 0x00
#define CONFIG_14BIT 0x1000  /* Temp 14-bit, Hum 14-bit, Heater off */
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_S 5
#define CONVERSION_DELAY_US 20000  /* 20 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hdc1080(int handle) {
    /* Write 16-bit config: 14-bit temp, 14-bit humidity, heater off */
    char config[3] = { MEASURE_REG, (CONFIG_14BIT >> 8) & 0xFF, CONFIG_14BIT & 0xFF };
    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char reg = MEASURE_REG;
    char buf[4];

    /* Point to measurement register */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set measurement pointer\n");
        return -1;
    }

    /* Wait for conversion (14-bit temp + 14-bit humidity ~1.5 ms; 20 ms is safe) */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: temp_msb, temp_lsb, hum_msb, hum_lsb */
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read HDC1080 data\n");
        return -1;
    }

    unsigned int raw_temp = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    unsigned int raw_hum  = ((unsigned int)(unsigned char)buf[2] << 8) | (unsigned char)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, HDC1080_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hdc1080(i2c_handle) != 0) {
        fprintf(stderr, "Error: HDC1080 initialisation failed (sensor may be absent)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HDC1080 initialised on I2C bus %d at address 0x%02X. Logging every %d seconds.\n",
           I2C_BUS, HDC1080_ADDR, SAMPLE_INTERVAL_S);

    while (running) {
        float temperature, humidity;

        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

