#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADAPTER    "/dev/i2c-1"
#define STS40_ADDR     0x44
#define MEASURE_CMD    0x2C
#define MEASURE_CMD2   0xE0
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5
#define CONV_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = { msb, lsb };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD, MEASURE_CMD2) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint8_t data[3];
    if (i2c_read_bytes(fd, data, 3) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = (uint16_t)((data[0] << 8) | data[1]);
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_ADAPTER, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_ADAPTER, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temperature;
        if (read_temperature(fd, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            if (log_temperature(temperature) < 0)
                fprintf(stderr, "Logging failed for this sample.\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    if (close(fd) < 0)
        fprintf(stderr, "Warning: close(fd) failed: %s\n", strerror(errno));
    return 0;
}

