#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_INTERVAL_SEC 5
#define LOG_FILE_INTERVAL_SEC 60
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

#define CMD_START_PERIODIC 0x21B1
#define CMD_READ_MEASUREMENT 0xE000
#define CMD_STOP_PERIODIC 0x3F86

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static int logging_thread_created = 0;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error_log");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s: %s\n", ts, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *hum) {
    if (send_command(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    uint8_t data[9];
    if (i2cReadDevice(i2c_handle, (char *)data, 9) != 9) {
        log_error("I2C read measurement failed");
        return -1;
    }
    if (crc8(&data[0], 2) != data[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    *co2 = (data[0] << 8) | data[1];
    *temp = (data[3] << 8) | data[4];
    *hum = (data[6] << 8) | data[7];
    return 0;
}

static void init_circular_buffer(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void add_to_buffer(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void write_buffer_to_file(circular_buffer_t *buf, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        log_error("fopen write_buffer_to_file failed");
        return;
    }
    pthread_mutex_lock(&buf->mutex);
    int start = buf->tail;
    int end = buf->head;
    int count = buf->count;
    pthread_mutex_unlock(&buf->mutex);
    if (count == 0) {
        fclose(fp);
        return;
    }
    if (count == BUFFER_SIZE) {
        start = 0;
        end = BUFFER_SIZE;
    }
    for (int i = start; i != end; i = (i + 1) % BUFFER_SIZE) {
        char ts[64];
        struct tm *t = localtime(&buf->data[i].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, buf->data[i].co2, buf->data[i].temperature, buf->data[i].humidity);
    }
    fclose(fp);
}

static void *logging_thread_func(void *arg) {
    circular_buffer_t *buf = (circular_buffer_t *)arg;
    time_t last_write = 0;
    while (running) {
        time_t now = time(NULL);
        if (now - last_write >= LOG_FILE_INTERVAL_SEC) {
            char filename[256];
            struct tm *t = localtime(&now);
            strftime(filename, sizeof(filename), LOG_DIR "/scd40_data_%Y%m%d_%H%M%S.csv", t);
            write_buffer_to_file(buf, filename);
            last_write = now;
        }
        gpioDelay(100000);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("i2cOpen failed");
        gpioTerminate();
        return 1;
    }
    init_circular_buffer(&buffer);
    if (send_command(CMD_START_PERIODIC) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000000);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (pthread_create(&logging_thread, NULL, logging_thread_func, &buffer) != 0) {
        log_error("pthread_create failed");
        running = 0;
    } else {
        logging_thread_created = 1;
    }
    while (running) {
        uint16_t co2_raw, temp_raw, hum_raw;
        if (read_measurement(&co2_raw, &temp_raw, &hum_raw) == 0) {
            float co2 = 0, temp = 0, hum = 0;
            if (co2_raw != 0)
                co2 = (float)co2_raw;
            if (temp_raw != 0)
                temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
            if (hum_raw != 0)
                hum = 100.0f * (float)hum_raw / 65535.0f;
            sensor_data_t d = { .timestamp = time(NULL), .co2 = co2, .temperature = temp, .humidity = hum };
            add_to_buffer(&buffer, d);
        }
        gpioDelay(LOG_INTERVAL_SEC * 1000000);
    }
    if (logging_thread_created) {
        pthread_join(logging_thread, NULL);
    }
    if (send_command(CMD_STOP_PERIODIC) != 0) {
        log_error("Failed to stop periodic measurement");
    }
    write_buffer_to_file(&buffer, LOG_DIR "/scd40_data_final.csv");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

