#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "sdp810_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor\n");
        return -1;
    }

    data->pressure = (float)raw_pressure * (float)scale_factor / 1000.0f;
    data->temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
    return 0;
}

static void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fprintf(log_file, "timestamp,pressure_Pa,temperature_C\n");
    fflush(log_file);

    while (!terminate) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

