#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ICP10125_ADDR        0x63
#define ICP10125_REG_OTP     0x66
#define ICP10125_REG_CMD     0x4011
#define ICP10125_MEAS_DELAY_MS 20
#define ICP10125_POLL_DELAY_MS 1000
#define ICP10125_CRC_POLY    0x131
#define ICP10125_CRC_INIT    0xFFFF

#define GPIO_CHIP_NAME       "gpiochip4"
#define LED_BCM_PIN          17
#define PRESSURE_THRESHOLD   95000.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint16_t crc16(const uint8_t *data, size_t len) {
    uint16_t crc = ICP10125_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= (uint16_t)data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x0001)
                crc = (crc >> 1) ^ ICP10125_CRC_POLY;
            else
                crc >>= 1;
        }
    }
    return crc;
}

static int i2c_write_reg16(int fd, uint8_t reg_msb, uint8_t reg_lsb) {
    uint8_t buf[2] = { reg_msb, reg_lsb };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg_msb, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_otp(int fd, uint16_t otp[4]) {
    if (i2c_write_reg16(fd, ICP10125_REG_OTP, 0x00) < 0)
        return -1;
    usleep(10000);
    uint8_t buf[8];
    if (i2c_read_block(fd, buf, 8) < 0)
        return -1;
    for (int i = 0; i < 4; i++) {
        uint16_t raw = (uint16_t)buf[2 * i] | ((uint16_t)buf[2 * i + 1] << 8);
        if (crc16(&buf[2 * i], 2) != (raw & 0x03)) {
            fprintf(stderr, "CRC mismatch on OTP word %d\n", i);
            return -1;
        }
        otp[i] = raw & 0xFFF;
    }
    return 0;
}

static int trigger_measurement(int fd) {
    return i2c_write_reg16(fd, ICP10125_REG_CMD, 0x11);
}

static int read_measurement(int fd, uint8_t *buf) {
    if (i2c_write_reg16(fd, ICP10125_REG_CMD, 0x00) < 0)
        return -1;
    usleep(ICP10125_MEAS_DELAY_MS * 1000);
    return i2c_read_block(fd, buf, 6);
}

static int convert_data(const uint8_t *buf, uint32_t *raw_p, uint32_t *raw_t) {
    uint16_t crc = crc16(buf, 2);
    if (crc != (uint16_t)((buf[4] << 8) | buf[5])) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }
    *raw_p = ((uint32_t)buf[0] << 8) | buf[1];
    crc = crc16(buf + 2, 2);
    if (crc != (uint16_t)((buf[4] >> 2) | ((uint16_t)buf[5] << 6))) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    *raw_t = ((uint32_t)buf[2] << 8) | buf[3];
    return 0;
}

static float calculate_pressure(uint32_t raw_p, const uint16_t otp[4]) {
    float p = (float)raw_p;
    p = (p - (float)otp[0]) * (float)otp[1] / 65536.0f;
    p = p * (1.0f + (float)otp[2] / 65536.0f);
    p = p * (1.0f + (float)otp[3] / 65536.0f);
    return p;
}

static float calculate_temperature(uint32_t raw_t) {
    return (float)raw_t / 65536.0f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_BCM_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_BCM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_BCM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    uint16_t otp[4];
    if (read_otp(fd, otp) < 0) {
        fprintf(stderr, "Failed to read OTP coefficients. Sensor may be absent.\n");
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    printf("OTP coefficients: %u %u %u %u\n", otp[0], otp[1], otp[2], otp[3]);

    while (g_running) {
        if (trigger_measurement(fd) < 0) {
            fprintf(stderr, "Measurement trigger failed.\n");
            usleep(ICP10125_POLL_DELAY_MS * 1000);
            continue;
        }
        uint8_t buf[6];
        if (read_measurement(fd, buf) < 0) {
            fprintf(stderr, "Measurement read failed.\n");
            usleep(ICP10125_POLL_DELAY_MS * 1000);
            continue;
        }
        uint32_t raw_p, raw_t;
        if (convert_data(buf, &raw_p, &raw_t) < 0) {
            fprintf(stderr, "Data conversion failed.\n");
            usleep(ICP10125_POLL_DELAY_MS * 1000);
            continue;
        }
        float pressure = calculate_pressure(raw_p, otp);
        float temperature = calculate_temperature(raw_t);
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        int blink_freq = (pressure < PRESSURE_THRESHOLD) ? 5 : 1;
        for (int i = 0; i < 5 && g_running; i++) {
            gpiod_line_set_value(led, 1);
            usleep(500000 / blink_freq);
            gpiod_line_set_value(led, 0);
            usleep(500000 / blink_freq);
        }
        usleep(ICP10125_POLL_DELAY_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

