#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define FAN_GPIO 18
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define HIGH_TEMP 30.0
#define LOW_TEMP 28.0
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int raw = i2cReadWordData(handle, reg);
        if (raw >= 0) {
            *temp = (float)raw * 0.02 - 273.15;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X), retrying...\n", reg);
        gpioDelay(RETRY_DELAY_US);
        retries--;
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", RETRY_COUNT, reg);
    return -1;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    } else {
        fprintf(fp, "(timestamp error), Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }
    fclose(fp);
    return 0;
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > HIGH_TEMP && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (object %.2f C > %.1f C)\n", object_temp, HIGH_TEMP);
    } else if (object_temp < LOW_TEMP && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (object %.2f C < %.1f C)\n", object_temp, LOW_TEMP);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90614 temperature monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float ambient = 0.0f, object = 0.0f;
        int ok = 1;

        if (read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Ambient temperature read failed; skipping sample\n");
            ok = 0;
        }
        if (ok && read_temperature(i2c_handle, OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Object temperature read failed; skipping sample\n");
            ok = 0;
        }

        if (ok) {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            log_temperature(ambient, object);
            control_fan(object);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

