#define TMP102_ADDR 0x48
#define TMP102_TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temp_c) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, TMP102_TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading temperature: i2cReadI2CBlockData returned %d\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 4;
    *temp_c = (float)raw * 0.0625f;
    return 0;
}

static int log_temperature(float temp_c) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, temp_c) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TMP102_ADDR, handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp_c;
        if (read_temperature(handle, &temp_c) == 0) {
            if (log_temperature(temp_c) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        if (running) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
        }
    }

    if (i2cClose(handle) != 0) {
        fprintf(stderr, "Warning: i2cClose failed\n");
    }
    gpioTerminate();
    return 0;
}

