#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define REG_TEMP_LOW  0x00
#define REG_TEMP_HIGH 0x01
#define REG_HUM_LOW   0x02
#define REG_HUM_HIGH  0x03
#define REG_MEAS_CFG  0x0E
#define REG_CONFIG    0x0F
#define MEAS_TRIGGER  0x01
#define CONFIG_DEFAULT 0x00  /* heater off, 14-bit temp+humidity */
#define POLL_TIMEOUT_MS 500
#define POLL_DELAY_US 2000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *temp_raw, uint16_t *hum_raw) {
    uint8_t tl, th, hl, hh;
    if (read_register(REG_TEMP_LOW, &tl) < 0) return -1;
    if (read_register(REG_TEMP_HIGH, &th) < 0) return -1;
    if (read_register(REG_HUM_LOW, &hl) < 0) return -1;
    if (read_register(REG_HUM_HIGH, &hh) < 0) return -1;
    *temp_raw = ((uint16_t)th << 8) | tl;
    *hum_raw  = ((uint16_t)hh << 8) | hl;
    return 0;
}

static int trigger_and_wait(void) {
    if (write_register(REG_MEAS_CFG, MEAS_TRIGGER) < 0) return -1;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t cfg;
        if (read_register(REG_MEAS_CFG, &cfg) < 0) return -1;
        if ((cfg & MEAS_TRIGGER) == 0) return 0;
        gpioDelay(POLL_DELAY_US);
    }
    fprintf(stderr, "Measurement trigger timeout\n");
    return -1;
}

static int read_sensor(float *temp, float *hum) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (trigger_and_wait() < 0) {
            fprintf(stderr, "Trigger failed (attempt %d)\n", attempt + 1);
            continue;
        }
        uint16_t tr, hr;
        if (read_measurement(&tr, &hr) < 0) {
            fprintf(stderr, "Read failed (attempt %d)\n", attempt + 1);
            continue;
        }
        *temp = ((float)tr / 65536.0f) * 165.0f - 40.0f;
        *hum  = ((float)hr / 65536.0f) * 100.0f;
        return 0;
    }
    fprintf(stderr, "Sensor read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading CONFIG register */
    uint8_t cfg;
    if (read_register(REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "HDC2010 not responding at 0x%02X\n", HDC2010_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(REG_CONFIG, CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to set default config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC2010 logging started (addr 0x%02X). Press Ctrl+C to stop.\n", HDC2010_ADDR);

    while (!terminate) {
        float temp, hum;
        if (read_sensor(&temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        sleep(5);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

