#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x25
#define MEASURE_CMD    0x362F
#define READ_LEN       6
#define SAMPLE_US      500000  /* 500 ms */
#define MEAS_DELAY_US  45000   /* 45 ms for 500Pa range */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[READ_LEN];
    if (i2cReadDevice(handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: failed to read 6 bytes from SDP800\n");
        return -1;
    }

    /* Verify CRC for pressure word (bytes 0-1, CRC byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }

    /* Verify CRC for temperature word (bytes 3-4, CRC byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — sensor may be absent\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t pressure = 0, temperature = 0;

    while (g_running) {
        if (read_sdp800(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d C\n",
                   (int)pressure, (int)temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: read failed, will retry next cycle\n");
        }
        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

