#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define RELAY_GPIO_LINE 17
#define RELAY_CHIP_NAME "gpiochip0"

#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

#define MAX_PROFILE_SIZE 1024
#define MAX_LINE_LENGTH 256

#define KP 1.0
#define KI 0.01
#define KD 0.1

#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    float target_temp;
    int time_seconds;
} ProfilePoint;

static int read_profile(const char *filename, ProfilePoint *profile, int max_size) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    int count = 0;

    while (fgets(line, sizeof(line), fp) && count < max_size) {
        if (sscanf(line, "%d,%f", &profile[count].time_seconds, &profile[count].target_temp) == 2) {
            count++;
        } else {
            fprintf(stderr, "Warning: Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    return count;
}

static int spi_init(const char *device, uint32_t speed, uint8_t bits, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device '%s': %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int max6675_read_temp(int spi_fd, float *temp_celsius) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];

    if (raw & 0x04) {
        fprintf(stderr, "Error: MAX6675 open circuit or sensor absent\n");
        return -1;
    }

    *temp_celsius = (float)((raw >> 3) & 0x3FF) * 0.25f;
    return 0;
}

static float pid_calculate(float setpoint, float actual, float *integral, float *prev_error) {
    float error = setpoint - actual;
    *integral += error;
    float derivative = error - *prev_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;

    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

static void log_data(float temp, float duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    localtime_r(&t, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temp, duty_cycle);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_BITS, SPI_MODE);
    if (spi_fd < 0) return 1;

    struct gpiod_chip *chip = gpiod_chip_open_by_name(RELAY_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", RELAY_CHIP_NAME, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO_LINE);
    if (!relay_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    ProfilePoint profile[MAX_PROFILE_SIZE];
    int profile_size = read_profile(PROFILE_FILE, profile, MAX_PROFILE_SIZE);
    if (profile_size <= 0) {
        fprintf(stderr, "Error reading profile. Exiting.\n");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    int profile_index = 0;
    float integral = 0.0f, prev_error = 0.0f;
    float duty_cycle = 0.0f;

    while (program_running) {
        float temp_celsius;
        if (max6675_read_temp(spi_fd, &temp_celsius) < 0) {
            fprintf(stderr, "SPI read error. Skipping cycle.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (profile_index < profile_size && profile[profile_index].time_seconds <= time(NULL)) {
            duty_cycle = pid_calculate(profile[profile_index].target_temp, temp_celsius, &integral, &prev_error);
            profile_index++;
        } else {
            duty_cycle = pid_calculate(profile[profile_index].target_temp, temp_celsius, &integral, &prev_error);
        }

        if (gpiod_line_set_value(relay_line, (int)(duty_cycle > 0.5f)) < 0) {
            fprintf(stderr, "Error setting relay GPIO value: %s\n", strerror(errno));
        }

        log_data(temp_celsius, duty_cycle);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

