#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define HEATER_GPIO 17
#define PWM_GPIO 18
#define TEMP_SENSOR_GPIO 4
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_S 5
#define MAX_SENSOR_READINGS 5
#define MAX_SENSOR_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static struct gpiod_line *temp_line = NULL;

static double kp, ki, kd;
static double setpoint;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(double *temp) {
    FILE *fp;
    char path[256];
    char buffer[256];
    char *sensor_id = NULL;
    char *temp_str = NULL;
    int retries = 0;

    while (retries < MAX_SENSOR_RETRIES) {
        snprintf(path, sizeof(path), "/sys/bus/w1/devices/");
        fp = popen("ls /sys/bus/w1/devices/ | grep '28-'", "r");
        if (!fp) {
            fprintf(stderr, "Error: Failed to list w1 devices: %s\n", strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            pclose(fp);
            fprintf(stderr, "Error: Failed to read w1 device list: %s\n", strerror(errno));
            retries++;
            sleep(1);
            continue;
        }
        pclose(fp);

        sensor_id = strtok(buffer, "\n");
        if (sensor_id == NULL) {
            fprintf(stderr, "Error: No DS18B20 sensor found.\n");
            retries++;
            sleep(1);
            continue;
        }

        snprintf(path, sizeof(path), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);
        fp = fopen(path, "r");
        if (!fp) {
            fprintf(stderr, "Error: Failed to open %s: %s\n", path, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            fprintf(stderr, "Error: Failed to read from %s: %s\n", path, strerror(errno));
            fclose(fp);
            retries++;
            sleep(1);
            continue;
        }
        fclose(fp);

        if (strstr(buffer, "YES") == NULL) {
            fprintf(stderr, "Error: CRC check failed for sensor %s\n", sensor_id);
            retries++;
            sleep(1);
            continue;
        }

        temp_str = strstr(buffer, "t=");
        if (temp_str == NULL) {
            fprintf(stderr, "Error: Temperature data not found in %s\n", path);
            retries++;
            sleep(1);
            continue;
        }

        *temp = atof(temp_str + 2) / 1000.0;
        return 0;
    }

    fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_SENSOR_RETRIES);
    return -1;
}

static double calculate_pid(double current_temp) {
    double error = setpoint - current_temp;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    return output;
}

static int set_pwm_duty_cycle(double pid_output) {
    if (pid_output < 0) pid_output = 0;
    if (pid_output > 100) pid_output = 100;

    long duty_cycle_ns = (long)((pid_output / 100.0) * PWM_PERIOD_NS);
    if (duty_cycle_ns < 0) duty_cycle_ns = 0;
    if (duty_cycle_ns > PWM_PERIOD_NS) duty_cycle_ns = PWM_PERIOD_NS;

    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to set PWM high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duty_cycle_ns);

    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM low: %s\n", strerror(errno));
        return -1;
    }
    usleep(PWM_PERIOD_NS - duty_cycle_ns);
    return 0;
}

static int log_data(double temperature, double setpoint, double pid_output, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Temperature: %.2f, Setpoint: %.2f, PID Output: %.2f, Duty Cycle: %.2f\n",
                timestamp, temperature, setpoint, pid_output, duty_cycle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (heater_line) {
        gpiod_line_set_value(heater_line, 0);
        gpiod_line_release(heater_line);
        heater_line = NULL;
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (temp_line) {
        gpiod_line_release(temp_line);
        temp_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    kp = atof(argv[2]);
    ki = atof(argv[3]);
    kd = atof(argv[4]);

    if (kp <= 0 || ki < 0 || kd < 0) {
        fprintf(stderr, "Error: Invalid PID gains. Kp, Ki, and Kd must be positive.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_GPIO);
    if (!heater_line) {
        fprintf(stderr, "Error: Failed to get GPIO %d: %s\n", HEATER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        fprintf(stderr, "Error: Failed to get GPIO %d: %s\n", PWM_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    temp_line = gpiod_chip_get_line(chip, TEMP_SENSOR_GPIO);
    if (!temp_line) {
        fprintf(stderr, "Error: Failed to get GPIO %d: %s\n", TEMP_SENSOR_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(heater_line, "greenhouse-heater", 0) < 0) {
        fprintf(stderr, "Error: Failed to request heater GPIO as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse-pwm", 0) < 0) {
        fprintf(stderr, "Error: Failed to request PWM GPIO as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(temp_line, "greenhouse-temp") < 0) {
        fprintf(stderr, "Error: Failed to request temperature GPIO as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Greenhouse controller started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n",
           setpoint, kp, ki, kd);

    while (running) {
        double temperature = 0.0;
        double sum = 0.0;
        int valid_readings = 0;

        for (int i = 0; i < MAX_SENSOR_READINGS; i++) {
            if (read_temperature(&temperature) == 0) {
                sum += temperature;
                valid_readings++;
            } else {
                fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
            }
            sleep(1);
        }

        if (valid_readings == 0) {
            fprintf(stderr, "Error: No valid temperature readings. Skipping PID calculation.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        double avg_temp = sum / valid_readings;
        double pid_output = calculate_pid(avg_temp);

        if (set_pwm_duty_cycle(pid_output) < 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle.\n");
        }

        if (log_data(avg_temp, setpoint, pid_output, pid_output) < 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down greenhouse controller...\n");
    cleanup();
    return 0;
}

