#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define RELAY_GPIO     17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define RETRY_COUNT    3
#define RETRY_DELAY_MS 10
#define MEASURE_DELAY_MS 80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_bytes(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    if (i2c_write_bytes(fd, init_cmd, sizeof(init_cmd)) != 0)
        return -1;
    usleep(10000);
    return 0;
}

static int aht20_read(int fd, float *humidity) {
    uint8_t trigger[3] = {0xAC, 0x33, 0x00};
    uint8_t data[6];

    if (i2c_write_bytes(fd, trigger, sizeof(trigger)) != 0)
        return -1;

    usleep(MEASURE_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy or not calibrated\n");
        return -1;
    }

    uint32_t hum_raw = ((uint32_t)data[1] << 12) |
                       ((uint32_t)data[2] << 4)  |
                       ((uint32_t)data[3] >> 4);
    *humidity = ((float)hum_raw / 1048576.0f) * 100.0f;
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RELAY_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "aht20_relay", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                RELAY_GPIO, strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        goto cleanup;
    }

    printf("AHT20 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
            if (aht20_read(i2c_fd, &humidity) == 0) {
                success = 1;
                break;
            }
            if (attempt < RETRY_COUNT - 1)
                usleep(RETRY_DELAY_MS * 1000);
        }

        if (success) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(relay_line, 1) != 0)
                    fprintf(stderr, "Failed to turn relay ON: %s\n", strerror(errno));
                else
                    printf("Humidity above %.0f%%, turning dehumidifier ON\n", HUMIDITY_HIGH);
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(relay_line, 0) != 0)
                    fprintf(stderr, "Failed to turn relay OFF: %s\n", strerror(errno));
                else
                    printf("Humidity below %.0f%%, turning dehumidifier OFF\n", HUMIDITY_LOW);
            }
        } else {
            fprintf(stderr, "Failed to read humidity after %d attempts\n", RETRY_COUNT);
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    return ret;
}

