#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_CMD_TEMP 0xE3
#define HTU21D_CMD_HUMID 0xE5
#define API_URL "http://api.example.com/humidity"
#define API_PORT 80
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(float *humidity) {
    uint8_t cmd = HTU21D_CMD_HUMID;
    if (i2c_write_cmd(i2c_fd, cmd) < 0)
        return -1;

    usleep(50000);

    uint8_t data[3];
    if (i2c_read_bytes(i2c_fd, data, 3) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        syslog(LOG_ERR, "CRC mismatch on humidity data");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    raw &= 0xFFFC;
    *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int read_temperature(float *temperature) {
    uint8_t cmd = HTU21D_CMD_TEMP;
    if (i2c_write_cmd(i2c_fd, cmd) < 0)
        return -1;

    usleep(50000);

    uint8_t data[3];
    if (i2c_read_bytes(i2c_fd, data, 3) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        syslog(LOG_ERR, "CRC mismatch on temperature data");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    raw &= 0xFFFC;
    *temperature = -46.85f + 175.72f * (float)raw / 65536.0f;
    return 0;
}

static int post_data(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct hostent *server = gethostbyname(API_URL);
    if (!server) {
        syslog(LOG_ERR, "DNS lookup failed for %s", API_URL);
        close(sockfd);
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(API_PORT);
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connect failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);

    char request[256];
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: api.example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             strlen(json), json);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_logger", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D logger started");

    while (running) {
        float humidity;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_humidity(&humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                sleep(2);
        }

        if (success) {
            if (post_data(humidity) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            } else {
                syslog(LOG_ERR, "Failed to POST data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++)
            sleep(1);
    }

    syslog(LOG_INFO, "Shutting down");
    if (i2c_fd >= 0)
        close(i2c_fd);
    closelog();
    return 0;
}

