#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6
#define BMP280_OVERSAMPLING_1X 0x01
#define BMP280_MODE_FORCED 0x01
#define BMP280_CTRL_MEAS_FORCED (BMP280_OVERSAMPLING_1X << 5) | (BMP280_OVERSAMPLING_1X << 2) | BMP280_MODE_FORCED
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_calibration(int handle) {
    uint8_t buf[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, buf, sizeof(buf)) != 0)
        return -1;
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)calib.dig_P3) >> 8) + ((var1 * (int64_t)calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)calib.dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (uint32_t)((p >> 8) & 0xFFFFFFFF);
}

static int read_sensor(int handle, int32_t *adc_T, int32_t *adc_P) {
    uint8_t data[6];
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, BMP280_CTRL_MEAS_FORCED) != 0)
        return -1;
    gpioDelay(CONVERSION_DELAY_US);
    if (i2c_read_block(handle, BMP280_REG_DATA, data, 6) != 0)
        return -1;
    *adc_P = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *adc_T = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

static void log_breach(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Pressure breach: %.2f hPa\n", ts, pressure);
    fclose(fp);
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int verify_chip(void) {
    int id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    gpioDelay(2000);
    if (read_calibration(i2c_handle) != 0)
        return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES && running) {
        if (verify_chip() == 0) break;
        retries++;
        fprintf(stderr, "Verification failed (attempt %d/%d). Re-initializing I2C.\n", retries, MAX_RETRIES);
        if (init_i2c() != 0) {
            gpioDelay(1000000);
            continue;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Max retries reached. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP280 initialized. Monitoring pressure...\n");

    while (running) {
        int32_t adc_T, adc_P;
        if (read_sensor(i2c_handle, &adc_T, &adc_P) != 0) {
            fprintf(stderr, "Sensor read failed. Re-initializing I2C.\n");
            retries = 0;
            while (retries < MAX_RETRIES && running) {
                if (init_i2c() == 0 && verify_chip() == 0) break;
                retries++;
                gpioDelay(1000000);
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            continue;
        }
        compensate_temperature(adc_T);
        uint32_t p_pa = compensate_pressure(adc_P);
        double pressure = p_pa / 100.0;
        printf("Pressure: %.2f hPa\n", pressure);
        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            log_breach(pressure);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

