/*
 * Raspberry Pi 4B — TMP117 temperature + AHT20 humidity + PIR motion logger.
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define TMP117_ADDR      0x48
#define TMP117_TEMP_REG  0x00
#define TMP117_LSB       0.0078125f   /* °C per LSB (16-bit signed) */

#define AHT20_ADDR       0x38
#define AHT20_CMD_INIT    0xBE, 0x08, 0x00
#define AHT20_CMD_MEASURE 0xAC, 0x33, 0x00
#define AHT20_CMD_RESET   0xBA

#define PIR_GPIO_CHIP    "gpiochip4"
#define PIR_GPIO_LINE    17
#define SAMPLE_INTERVAL  1            /* seconds */
#define I2C_RETRIES      3
#define I2C_RETRY_DELAY  10000        /* microseconds */

#define LOG_DIR          "logs"
#define LOG_FILE_PREFIX  "sensor_data"
#define LOG_FILE_SUFFIX  ".csv"

/* ----------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_pir_line = NULL;

/* --------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_cmd(int fd, const uint8_t *cmd, size_t len);
static int  i2c_read_bytes(int fd, uint8_t *buf, size_t len);
static int  read_tmp117(int fd, float *temp);
static int  read_aht20(int fd, float *humidity, float *temperature);
static int  read_pir(struct gpiod_line *line);
static int  create_log_file(const char *path);
static int  log_data(const char *path, float temp, float hum, int motion);
static void cleanup(void);

/* --------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers ------------------------------- */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * TMP117: 16-bit signed big-endian, LSB = 0.0078125 °C.
 * Returns 0 on success, -1 on error.
 */
static int read_tmp117(int fd, float *temp)
{
    uint8_t reg = TMP117_TEMP_REG;
    uint8_t buf[2];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, &reg, 1) != 0) {
            usleep(I2C_RETRY_DELAY);
            continue;
        }
        if (i2c_read_bytes(fd, buf, 2) != 0) {
            usleep(I2C_RETRY_DELAY);
            continue;
        }
        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temp = (float)raw * TMP117_LSB;
        return 0;
    }
    return -1;
}

/*
 * AHT20: 7-byte response, bit 7 of data[0] = busy.
 * Returns 0 on success, -1 on error.
 */
static int read_aht20(int fd, float *humidity, float *temperature)
{
    uint8_t cmd[3] = AHT20_CMD_MEASURE;
    uint8_t buf[7];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, cmd, sizeof(cmd)) != 0) {
            usleep(I2C_RETRY_DELAY);
            continue;
        }
        usleep(20000); /* 20 ms measurement wait */

        if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0) {
            usleep(I2C_RETRY_DELAY);
            continue;
        }

        if (buf[0] & 0x80) {
            /* Busy — measurement not ready yet */
            usleep(5000);
            continue;
        }

        uint32_t hum_raw   = ((uint32_t)buf[1] << 12) |
                            ((uint32_t)buf[2] << 4)  |
                            ((uint32_t)buf[3] >> 4);
        uint32_t temp_raw  = (((uint32_t)buf[3] & 0x0F) << 16) |
                            ((uint32_t)buf[4] << 8)  |
                            (uint32_t)buf[5];

        *humidity     = (float)hum_raw   / 1048576.0f * 100.0f;
        *temperature = (float)temp_raw  / 1048576.0f * 100.0f;
        return 0;
    }
    return -1;
}

/* --------------------------- PIR sensor -------------------------------- */
static int read_pir(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

/* --------------------------- Logging ----------------------------------- */
static int create_log_file(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                path, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *path, float temp, float hum, int motion)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                path, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

/* --------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_pir_line) {
        gpiod_line_release(g_pir_line);
        g_pir_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request PIR line */
    g_chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", PIR_GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_pir_line = gpiod_chip_get_line(g_chip, PIR_GPIO_LINE);
    if (!g_pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(g_pir_line, "pir_sensor") != 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (ioctl(g_i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "TMP117 not detected at 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "AHT20 not detected at 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
    }

    /* Initialize AHT20 */
    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) == 0) {
        uint8_t init_cmd[3] = AHT20_CMD_INIT;
        if (i2c_write_cmd(g_i2c_fd, init_cmd, sizeof(init_cmd)) != 0) {
            fprintf(stderr, "AHT20 init failed\n");
        }
    }

    /* Create daily log file */
    time_t now = time(NULL);
    struct tm tm;
    if (localtime_r(&now, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    char filename[256];
    strftime(filename, sizeof(filename), LOG_DIR "/" LOG_FILE_PREFIX "_%Y%m%d" LOG_FILE_SUFFIX, &tm);
    if (create_log_file(filename) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", filename);

    /* Main loop */
    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;

        /* TMP117 */
        if (ioctl(g_i2c_fd, I2C_SLAVE, TMP117_ADDR) == 0) {
            if (read_tmp117(g_i2c_fd, &temp) != 0) {
                fprintf(stderr, "TMP117 read failed\n");
            }
        }

        /* AHT20 */
        if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) == 0) {
            if (read_aht20(g_i2c_fd, &hum, &temp) != 0) {
                fprintf(stderr, "AHT20 read failed\n");
            }
        }

        /* PIR */
        motion = read_pir(g_pir_line);
        if (motion < 0) {
            fprintf(stderr, "PIR read failed\n");
        }

        /* Log */
        if (log_data(filename, temp, hum, motion) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

