#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_DIRECTION_1_PIN 23
#define MOTOR_DIRECTION_2_PIN 24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_DURATION_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int motor_stop(struct gpiod_line *enable,
                      struct gpiod_line *dir1,
                      struct gpiod_line *dir2) {
    int ret = 0;
    if (enable) {
        ret = gpiod_line_set_value(enable, 0);
        if (ret < 0) {
            log_event("Error: Failed to disable motor enable line.");
        }
    }
    if (dir1) {
        ret = gpiod_line_set_value(dir1, 0);
        if (ret < 0) {
            log_event("Error: Failed to set motor direction line 1 to 0.");
        }
    }
    if (dir2) {
        ret = gpiod_line_set_value(dir2, 0);
        if (ret < 0) {
            log_event("Error: Failed to set motor direction line 2 to 0.");
        }
    }
    return ret;
}

static int motor_run(struct gpiod_line *enable,
                     struct gpiod_line *dir1,
                     struct gpiod_line *dir2) {
    int ret;
    ret = gpiod_line_set_value(enable, 1);
    if (ret < 0) {
        log_event("Error: Failed to enable motor.");
        return -1;
    }
    ret = gpiod_line_set_value(dir1, 1);
    if (ret < 0) {
        log_event("Error: Failed to set motor direction 1.");
        motor_stop(enable, dir1, dir2);
        return -1;
    }
    ret = gpiod_line_set_value(dir2, 0);
    if (ret < 0) {
        log_event("Error: Failed to set motor direction 2.");
        motor_stop(enable, dir1, dir2);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *dir1_line = NULL;
    struct gpiod_line *dir2_line = NULL;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event("Error: Failed to open gpiochip4. Exiting.");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    dir1_line = gpiod_chip_get_line(chip, MOTOR_DIRECTION_1_PIN);
    dir2_line = gpiod_chip_get_line(chip, MOTOR_DIRECTION_2_PIN);

    if (!rain_line || !enable_line || !dir1_line || !dir2_line) {
        log_event("Error: Failed to get GPIO lines. Exiting.");
        goto cleanup;
    }

    ret = gpiod_line_request_input(rain_line, "rain_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input(rain)");
        log_event("Error: Failed to request rain sensor line as input.");
        goto cleanup;
    }

    ret = gpiod_line_request_output(enable_line, "motor_enable", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(enable)");
        log_event("Error: Failed to request motor enable line as output.");
        goto cleanup;
    }

    ret = gpiod_line_request_output(dir1_line, "motor_dir1", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(dir1)");
        log_event("Error: Failed to request motor direction line 1 as output.");
        goto cleanup;
    }

    ret = gpiod_line_request_output(dir2_line, "motor_dir2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(dir2)");
        log_event("Error: Failed to request motor direction line 2 as output.");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started.");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            perror("gpiod_line_get_value(rain)");
            log_event("Error: Failed to read rain sensor. Retrying...");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain_value == 0) {
            log_event("Rain detected!");
            if (motor_run(enable_line, dir1_line, dir2_line) == 0) {
                log_event("Motor running forward for 5 seconds.");
                for (int i = 0; i < MOTOR_RUN_DURATION_SEC && program_running; i++) {
                    sleep(1);
                }
                motor_stop(enable_line, dir1_line, dir2_line);
                log_event("Motor stopped.");
            } else {
                log_event("Error: Motor control failed.");
            }
        }

        if (program_running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    log_event("Shutting down gracefully.");

cleanup:
    motor_stop(enable_line, dir1_line, dir2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (enable_line) gpiod_line_release(enable_line);
    if (dir1_line) gpiod_line_release(dir1_line);
    if (dir2_line) gpiod_line_release(dir2_line);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

