#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the aggregate CPU time (user + nice + system + idle) from /proc/stat.
 * Returns 0 on success, -1 on failure.
 */
static int read_cpu_stats(unsigned long long *user,
                          unsigned long long *nice,
                          unsigned long long *system,
                          unsigned long long *idle)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("fgets /proc/stat");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (sscanf(line, "cpu  %llu %llu %llu %llu",
               user, nice, system, idle) != 4) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        return -1;
    }
    return 0;
}

/*
 * Compute CPU usage as a percentage (0.0 to 100.0).
 * Returns 0 on success, -1 on failure.
 */
static int calculate_cpu_usage(double *usage)
{
    static unsigned long long prev_user = 0, prev_nice = 0,
                              prev_system = 0, prev_idle = 0;
    unsigned long long user, nice, system, idle;

    if (read_cpu_stats(&user, &nice, &system, &idle) != 0)
        return -1;

    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle;
    unsigned long long total = user + nice + system + idle;
    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle - prev_idle;

    if (delta_total == 0) {
        *usage = 0.0;
    } else {
        *usage = (double)(delta_total - delta_idle) / (double)delta_total * 100.0;
    }

    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;

    return 0;
}

/*
 * Map CPU usage (0.0 to 100.0) to a color gradient:
 *   0%  -> Green  (0,255,0)
 *   50% -> Yellow (255,255,0)
 *  100% -> Red    (255,0,0)
 */
static void map_cpu_to_color(double cpu_usage, int *r, int *g, int *b)
{
    if (cpu_usage < 0.0) cpu_usage = 0.0;
    if (cpu_usage > 100.0) cpu_usage = 100.0;

    if (cpu_usage < 50.0) {
        *r = (int)((cpu_usage / 50.0) * 255.0);
        *g = (int)(((50.0 - cpu_usage) / 50.0) * 255.0);
        *b = 0;
    } else {
        *r = (int)(((100.0 - cpu_usage) / 50.0) * 255.0);
        *g = 0;
        *b = (int)(((cpu_usage - 50.0) / 50.0) * 255.0);
    }
}

/*
 * Set the LED color using pigpio hardware PWM.
 * For a common-anode LED, the cathode is driven HIGH when the channel is off,
 * so we invert the values: 0 PWM = full off, 255 PWM = full on.
 */
static void set_led_color(int r, int g, int b)
{
    if (r < 0) r = 0;
    if (r > PWM_RANGE) r = PWM_RANGE;
    if (g < 0) g = 0;
    if (g > PWM_RANGE) g = PWM_RANGE;
