    uint8_t data[6];
    int32_t raw_pressure, raw_temperature;

    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading pressure/temperature data: %s\n", strerror(errno));
        return -1;
    }

