static int send_udp_data(const char *json_data) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", UDP_SERVER_IP);
        return -1;
    }

    if (sendto(udp_socket, json_data, strlen(json_data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (udp_socket >= 0) {
        close(udp_socket);
        udp_socket = -1;
    }
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(i2c_handle, BMP280_REG_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        cleanup();
        return 1;
    }

    if (i2c_write_reg(i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Error resetting BMP280: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    gpioDelay(2000);

    if (read_calibration_data(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    if (i2c_write_reg(i2c_handle, BMP280_REG_CONFIG, 0xA0) != 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_bmp280(i2c_handle, &temperature, &pressure) == 0) {
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
            if (send_udp_data(json_data) != 0) {
                fprintf(stderr, "UDP send failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "BMP280 read failed, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

