#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define BUFFER_SIZE 20
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 1000000

#define TEMP_MIN 25.0
#define TEMP_MID 40.0
#define TEMP_MAX 60.0

#define FAULT_NONE 0
#define FAULT_OPEN_COIL 1
#define FAULT_SHORT_GND 2
#define FAULT_SHORT_VCC 3

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "INVALID", sizeof(time_str));
        }
        printf("[%d] %s Temp: %.2f C, PWM: %d\n",
               idx, time_str, buffer[idx].temperature, buffer[idx].pwm_duty);
    }
    printf("--- End of Buffer ---\n\n");
}

static void add_to_buffer(float temperature, int pwm_duty) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        int fault = FAULT_NONE;
        if (raw & 0x00000001) fault = FAULT_OPEN_COIL;
        else if (raw & 0x00000002) fault = FAULT_SHORT_GND;
        else if (raw & 0x00000004) fault = FAULT_SHORT_VCC;
        fprintf(stderr, "MAX31855 fault detected: ");
        switch (fault) {
            case FAULT_OPEN_COIL:  fprintf(stderr, "Open coil\n"); break;
            case FAULT_SHORT_GND:  fprintf(stderr, "Short to GND\n"); break;
            case FAULT_SHORT_VCC:  fprintf(stderr, "Short to VCC\n"); break;
            default:               fprintf(stderr, "Unknown fault\n"); break;
        }
        return -2;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_MIN) return 0;
    if (temperature < TEMP_MID) return (int)((temperature - TEMP_MIN) / (TEMP_MID - TEMP_MIN) * 50.0f);
    if (temperature < TEMP_MAX) return (int)(50.0f + (temperature - TEMP_MID) / (TEMP_MAX - TEMP_MID) * 150.0f);
    return 255;
}

static void set_fan_speed(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO%d\n", FAN_GPIO);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        int ret = read_max31855(&temperature);

        if (ret == 0) {
            int duty = calculate_pwm_duty(temperature);
            set_fan_speed(duty);
            add_to_buffer(temperature, duty);
            printf("Temperature: %.2f C, PWM: %d\n", temperature, duty);
        } else if (ret == -2) {
            fprintf(stderr, "MAX31855 fault, skipping fan update.\n");
        } else {
            fprintf(stderr, "SPI read error, skipping fan update.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    print_buffer();

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

