#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int logging_enabled = 0;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    char buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    cal->ac1 = (buf[0] << 8) | buf[1];
    cal->ac2 = (buf[2] << 8) | buf[3];
    cal->ac3 = (buf[4] << 8) | buf[5];
    cal->ac4 = (buf[6] << 8) | buf[7];
    cal->ac5 = (buf[8] << 8) | buf[9];
    cal->ac6 = (buf[10] << 8) | buf[11];
    cal->b1 = (buf[12] << 8) | buf[13];
    cal->b2 = (buf[14] << 8) | buf[15];
    cal->mb = (buf[16] << 8) | buf[17];
    cal->mc = (buf[18] << 8) | buf[19];
    cal->md = (buf[20] << 8) | buf[21];
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    char buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return -1;
    }
    *ut = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)};
    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));
    char buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    *up = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static double calculate_temperature(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);
}

static void toggle_logging(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }
    bmp180_cal_t cal;
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(2, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO2 mode\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(2, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO2\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(2, FALLING_EDGE, 0, toggle_logging, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR on GPIO2\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("Press Ctrl+C to exit. Toggle logging with GPIO2.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                double temp = calculate_temperature(ut, &cal);
                double pres = calculate_pressure(up, ut, &cal);
                log_data(temp, pres);
            } else {
                fprintf(stderr, "Error: Sensor read failed, skipping log entry\n");
            }
        }
        gpioDelay(1000000);
    }
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

