#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_LINE 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

#define MAX31865_CONFIG_VBIAS 0x80
#define MAX31865_CONFIG_3WIRE 0x40
#define MAX31865_CONFIG_FAULT_AUTO 0x20
#define MAX31865_CONFIG_FAULT_OPEN 0x10
#define MAX31865_CONFIG_FAULT_SHORT_GND 0x08
#define MAX31865_CONFIG_FAULT_SHORT_VCC 0x04

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int max31865_init(void) {
    uint8_t config = MAX31865_CONFIG_VBIAS | MAX31865_CONFIG_3WIRE |
                     MAX31865_CONFIG_FAULT_AUTO;
    if (max31865_write_reg(MAX31865_CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

static int read_rtd_data(float *rtd_temp) {
    uint8_t rtd_msb = 0, rtd_lsb = 0, fault = 0;
    int16_t raw_rtd;
    float r_ref = 430.0, rtd_nom = 100.0, rtd_alpha = 0.00385;
    float rtd_resistance, rtd_temp_c;

    if (max31865_read_reg(MAX31865_RTD_MSB_REG, &rtd_msb) < 0) {
        return -1;
    }
    if (max31865_read_reg(MAX31865_RTD_LSB_REG, &rtd_lsb) < 0) {
        return -1;
    }
    if (max31865_read_reg(MAX31865_FAULT_REG, &fault) < 0) {
        return -1;
    }

    if (fault & 0x01) {
        if (fault & MAX31865_CONFIG_FAULT_OPEN) {
            fprintf(stderr, "MAX31865 fault: RTD open circuit\n");
        }
        if (fault & MAX31865_CONFIG_FAULT_SHORT_GND) {
            fprintf(stderr, "MAX31865 fault: RTD short to GND\n");
        }
        if (fault & MAX31865_CONFIG_FAULT_SHORT_VCC) {
            fprintf(stderr, "MAX31865 fault: RTD short to VCC\n");
        }
        return -2;
    }

    raw_rtd = (int16_t)(((uint16_t)rtd_msb << 8) | rtd_lsb);
    raw_rtd >>= 1;

    if (raw_rtd == 0) {
        fprintf(stderr, "MAX31865 fault: RTD reading is zero\n");
        return -2;
    }

    rtd_resistance = r_ref * (rtd_nom / (float)raw_rtd - 1.0);
    rtd_temp_c = (rtd_resistance / rtd_nom) * rtd_alpha;
    *rtd_temp = rtd_temp_c;

    return 0;
}

static void log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(cs_line, "max31865-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        fprintf(stderr, "Failed to initialize MAX31865\n");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float temperature = 0.0;
        int ret = read_rtd_data(&temperature);
        if (ret == 0) {
            log_data(temperature);
        } else if (ret == -2) {
            fprintf(stderr, "Sensor fault, skipping log entry\n");
        } else {
            fprintf(stderr, "SPI communication error\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

