#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define BME280_CHIP_ID_REG 0xD0
#define BME280_CHIP_ID 0x60
#define BME280_RESET_REG 0xE0
