#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_START 0xAA
#define BMP180_REG_CAL_LEN 22
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 50000
#define PRESSURE_THRESHOLD_HPA 5.0
#define OSS 0

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float pressure;
} pressure_data_t;

static pressure_data_t pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    uint8_t buf[BMP180_REG_CAL_LEN];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, (char *)buf, BMP180_REG_CAL_LEN) != BMP180_REG_CAL_LEN) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        return -1;
    }
    cal.ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal.ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal.ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal.ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal.ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal.ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal.b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal.b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal.mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal.mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal.md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
