    return (double)(p + ((x1 + x2 + 3791) >> 4));
}

static void log_data(double temp, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temp, pressure);
    fflush(log_file);
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temp(&ut) != 0) return;
    if (read_raw_pressure(&up) != 0) return;
