    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(BMP180_PRESSURE_CONV_US);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    return x1 + x2;
}

static double calculate_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (double)(p + ((x1 + x2 + 3791) >> 4));
}

static void log_data(double temp, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temp, pressure);
    fflush(log_file);
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temp(&ut) != 0) return;
    if (read_raw_pressure(&up) != 0) return;
    double temp = calculate_temperature(ut);
    double pressure = calculate_pressure(up, ut);
    log_data(temp, pressure);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_calibration() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(BMP180_TIMER_ID, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        cleanup();
        return 1;
    }

    printf("BMP180 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        gpioDelay(100000);
    }

    gpioSetTimerFuncEx(BMP180_TIMER_ID, 0, NULL, NULL);
    cleanup();
    printf("BMP180 logging stopped.\n");
    return 0;
}

