#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1.0f;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);
    return (float)raw / 1000.0f;
}

static int calculate_duty(float temp) {
    if (temp <= MIN_TEMP) return 0;
    if (temp >= MAX_TEMP) return PWM_RANGE;
    return (int)(((temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * PWM_RANGE);
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(log_fp, "%s, Temp: %.2f C, Duty: %d\n", ts, temp, duty) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp = read_cpu_temp();
        if (temp < 0.0f) {
            fprintf(stderr, "Temperature read error, skipping cycle\n");
        } else {
            int duty = calculate_duty(temp);
            if (gpioPWM(FAN_GPIO, duty) != 0) {
                fprintf(stderr, "gpioPWM failed\n");
            }
            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Log write failed\n");
            }
            printf("Temp: %.2f C, Duty: %d\n", temp, duty);
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

