    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    return (write(fd, buf, 2) == 2) ? 0 : -1;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_reg(fd, BMP280_CALIB_START, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t chip_id;
    if (i2c_read_reg(fd, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
        fprintf(stderr, "Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID_VAL) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                chip_id, BMP280_CHIP_ID_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_RESET_REG, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Failed to reset BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (bmp280_read_calibration(fd, cal) != 0) return -1;
    if (i2c_write_reg(fd, BMP280_CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, 0x27) != 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
        return -1;
    }
    uint8_t status;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i += 10) {
        if (i2c_read_reg(fd, BMP280_STATUS_REG, &status, 1) != 0) {
            fprintf(stderr, "Failed to read status: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x08) == 0) break;
        usleep(10000);
    }
    if (status & 0x08) {
        fprintf(stderr, "Measurement timeout.\n");
        return -1;
    }
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_PRESS_MSB_REG, data, 6) != 0) {
        fprintf(stderr, "Failed to read data registers: %s\n", strerror(errno));
        return -1;
    }
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    double v1 = ((double)raw_t / 16384.0 - (double)cal->dig_T1 / 1024.0) * (double)cal->dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0) *
                ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0) * (double)cal->dig_T3;
    *t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p, int32_t t_fine, const bmp280_calib_t *cal) {
    double v1 = (double)t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * (double)cal->dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)cal->dig_P5 * 2.0;
    v2 = v2 / 4.0 + (double)cal->dig_P4 * 65536.0;
    v1 = ((double)cal->dig_P3 * v1 * v1 / 524288.0 + (double)cal->dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)cal->dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - v2 / 4096.0) * 6250.0 / v1;
    v1 = (double)cal->dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)cal->dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)cal->dig_P7) / 16.0;
    return p / 100.0;
}

static void log_data(double temp, double press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
    } else {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }
    int fd = open(BMP280_I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", BMP280_I2C_BUS, strerror(errno));
        return 1;
    }
    int addr = BMP280_ADDR_DEFAULT;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return 1;
    }
    bmp280_calib_t cal;
    if (bmp280_init(fd, &cal) != 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X. Logging to %s every %d seconds.\n",
           addr, LOG_FILE, SAMPLE_INTERVAL_SEC);
    while (g_running) {
        int32_t raw_t, raw_p, t_fine;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) == 0) {
            double temp = bmp280_compensate_temp(raw_t, &cal, &t_fine);
            double press = bmp280_compensate_press(raw_p, t_fine, &cal);
            log_data(temp, press);
            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temp, press);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            usleep(100000);
        }
    }
    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

