#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define LM75_TEMP_REG 0x00
#define GPIO_CHIP "gpiochip4"
#define GPIO_LED 18
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE 60
#define POLL_INTERVAL_US 1000000

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static CircularBuffer temp_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    uint8_t reg = LM75_TEMP_REG;
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp = (float)raw / 256.0f;
    return 0;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(CircularBuffer *buf, float value) {
    pthread_mutex_lock(&buf->mutex);
    buf->buffer[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static float buffer_average(const CircularBuffer *buf) {
    pthread_mutex_lock(&buf->mutex);
    float sum = 0.0f;
    int count = buf->count;
    int start = (buf->count == BUFFER_SIZE) ? buf->head : 0;
    for (int i = 0; i < count; i++) {
        sum += buf->buffer[(start + i) % BUFFER_SIZE];
    }
    pthread_mutex_unlock(&buf->mutex);
    return (count > 0) ? (sum / count) : 0.0f;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_destroy(&temp_buffer.mutex);
}

static void *sensor_thread(void *arg) {
    (void)arg;
    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            if (temp > TEMP_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Sensor read failed, attempting re-initialization...\n");
            if (i2c_init() != 0) {
                fprintf(stderr, "I2C re-initialization failed, exiting.\n");
                running = 0;
            }
        }
        usleep(POLL_INTERVAL_US);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (i2c_init() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buffer_init(&temp_buffer);

    pthread_t tid;
    if (pthread_create(&tid, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pthread_join(tid, NULL);

    cleanup();
    return EXIT_SUCCESS;
}

