#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static double target_temperature = 25.0;
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;

static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: could not open config file '%s'. Using defaults.\n", filename);
        return 0;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    if (sz <= 0) {
        fclose(fp);
        return 0;
    }
    fseek(fp, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    if (!buf) {
        fclose(fp);
        return 0;
    }
    size_t rd = fread(buf, 1, (size_t)sz, fp);
    buf[rd] = '\0';
    fclose(fp);

    cJSON *root = cJSON_Parse(buf);
    free(buf);
    if (!root) {
        fprintf(stderr, "Error: JSON parse failed.\n");
        return -1;
    }

    cJSON *t = cJSON_GetObjectItemCaseSensitive(root, "target_temperature");
    if (t && t->type == cJSON_Number) target_temperature = t->valuedouble;

    cJSON *kp = cJSON_GetObjectItemCaseSensitive(root, "Kp");
    if (kp && kp->type == cJSON_Number) Kp = kp->valuedouble;

    cJSON *ki = cJSON_GetObjectItemCaseSensitive(root, "Ki");
    if (ki && ki->type == cJSON_Number) Ki = ki->valuedouble;

    cJSON *kd = cJSON_GetObjectItemCaseSensitive(root, "Kd");
    if (kd && kd->type == cJSON_Number) Kd = kd->valuedouble;

    cJSON_Delete(root);
    return 0;
}

static int max31865_init(void) {
    /* Config: VBIAS=1, auto-conversion, 15-bit RTD, faults cleared */
    char config[2] = {0x80, 0xC1};
    if (spiWrite(spi_handle, config, 2) != 2) {
        fprintf(stderr, "Error: failed to write MAX31865 config.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_rtd_code(int *code) {
    char tx[3] = {0x01, 0x00, 0x00};
    char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI read failed.\n");
        return -1;
    }
    if (rx[0] & 0x01) {
