#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg24(int fd, uint8_t reg, int32_t *val) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *val = (int32_t)((buf[0] << 16) | (buf[1] << 8) | buf[2]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3,
                                 uint16_t *ac4, uint16_t *ac5, uint16_t *ac6,
                                 int16_t *b1, int16_t *b2, int16_t *mb,
                                 int16_t *mc, int16_t *md) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, ac3) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC4, ac4) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC5, ac5) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC6, ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    if (i2c_read_reg16(fd, BMP180_REG_MSB, (int16_t *)ut) < 0) return -1;
    return 0;
}

static int read_raw_pressure(int fd, int oss, int32_t *up) {
    uint8_t cmd = BMP180_CMD_PRESSURE_OSS0 + (oss << 6);
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, cmd) < 0) return -1;
    usleep(2000 + (3000 << oss));
    if (i2c_read_reg24(fd, BMP180_REG_MSB, up) < 0) return -1;
    return 0;
}

static int compute_b5(int32_t ut, const int16_t *ac5, const uint16_t *ac6, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)*ac6) * (int32_t)*ac5) >> 15;
    int32_t x2 = ((int32_t)*ac2 * 2048) >> 11;
    int32_t x3 = (x1 * x1 * 2048) >> 14;
    int32_t x4 = (x2 * x1) >> 11;
    int32_t x5 = (x3 + x4 + 32768) >> 10;
    *b5_out = x5;
    return 0;
}

static int compute_temperature(int32_t ut, const int16_t *ac5, const uint16_t *ac6, double *temp_out) {
    int32_t b5;
    if (compute_b5(ut, ac5, ac6, &b5) < 0) return -1;
    int32_t b5_signed = b5;
    int32_t t = (b5_signed * 2 + 32768) >> 16;
    *temp_out = (double)t / 10.0;
    return 0;
}

static int compute_pressure(int32_t up, int oss, int32_t ut, const int16_t *ac5,
                            const uint16_t *ac6, const int16_t *b1, const int16_t *b2,
                            const int16_t *mb, const int16_t *mc, const int16_t *md,
                            double *pressure_out) {
    int32_t b5;
    if (compute_b5(ut, ac5, ac6, &b5) < 0) return -1;
    int32_t b6 = b5 - 4000;
    int32_t x1 = (b6 * b6 * (int32_t)b2) >> 12;
    int32_t x2 = (b6 * (int32_t)b1) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)ac4 * (x3 + 32768)) >> 15) + ((int32_t)b1 * 2048) >> 11;
    int32_t b4 = ((int32_t)ac3 * x3) >> 13;
    int32_t b7 = (up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    *pressure_out = (double)p;
    return 0;
}

static int log_breach(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;

    if (read_calibration_data(g_i2c_fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6,
                              &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read calibration data from BMP180: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("BMP180 initialized. Monitoring temperature and pressure...\n");

    while (g_running) {
        int32_t ut, up;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_raw_temperature(g_i2c_fd, &ut) == 0 &&
                read_raw_pressure(g_i2c_fd, 0, &up) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(100000);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d retries: %s\n",
                    MAX_RETRIES, strerror(errno));
            log_breach("Sensor read failure");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        double temperature, pressure;
        if (compute_temperature(ut, &ac5, &ac6, &temperature) < 0 ||
            compute_pressure(up, 0, ut, &ac5, &ac6, &b1, &b2, &mb, &mc, &md, &pressure) < 0) {
            fprintf(stderr, "Failed to compute temperature or pressure\n");
            log_breach("Calculation failure");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);

        if (temperature > 30.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature breach: %.2f C > 30.0 C", temperature);
            log_breach(msg);
        }
        if (pressure < 950.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Pressure breach: %.2f hPa < 950.0 hPa", pressure);
            log_breach(msg);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

