        if (temperature > 30.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature breach: %.2f C > 30.0 C", temperature);
            log_breach(msg);
        }
        if (pressure < 950.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Pressure breach: %.2f hPa < 950.0 hPa", pressure);
            log_breach(msg);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

