#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define FAN_GPIO 18
#define TEMP_THRESHOLD 30.0f
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 500000

typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t fan_on = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    uint8_t cmd = BMP180_CMD_TEMP;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return -1;
    }
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    uint8_t cmd = BMP180_CMD_PRESSURE_OSS0;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    *raw_pressure = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> 8;
    return 0;
}

static float calculate_temperature(int32_t raw_temp) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t raw_temp, raw_pressure;
    if (read_raw_temperature(&raw_temp) != 0) return;
    if (read_raw_pressure(&raw_pressure) != 0) return;
    float temperature = calculate_temperature(raw_temp);
    float pressure = calculate_pressure(raw_pressure, raw_temp);
    time_t now = time(NULL);
    buffer.data[buffer.head].timestamp = now;
    buffer.data[buffer.head].temperature = temperature;
    buffer.data[buffer.head].pressure = pressure;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
    if (temperature > TEMP_THRESHOLD && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
    } else if (temperature <= TEMP_THRESHOLD && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
    }
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n", (long)now, temperature, pressure);
}

static void cleanup(void) {
    if (fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        cleanup();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    memset(&buffer, 0, sizeof(buffer));
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        cleanup();
        return 1;
    }
    while (running) {
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

