#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define BMP180_CMD_PRESSURE_OSS1 0x74
#define BMP180_CMD_PRESSURE_OSS2 0xB4
#define BMP180_CMD_PRESSURE_OSS3 0xF4
#define GPIO_TOGGLE 27
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_MS 200
#define SAMPLE_INTERVAL_S 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_edge_tick = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    int16_t v;
    uint16_t uv;
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1) < 0) return -1;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac1 = v;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac2 = v;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac3 = v;
    uv = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac4 = uv;
    uv = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac5 = uv;
    uv = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    ac6 = uv;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b1 = v;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    b2 = v;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mb = v;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    mc = v;
    v = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);
    md = v;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int oss, int32_t *up) {
    int cmd;
    switch (oss) {
        case 0: cmd = BMP180_CMD_PRESSURE_OSS0; break;
        case 1: cmd = BMP180_CMD_PRESSURE_OSS1; break;
        case 2: cmd = BMP180_CMD_PRESSURE_OSS2; break;
        case 3: cmd = BMP180_CMD_PRESSURE_OSS3; break;
        default: return -1;
    }
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(2000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - oss);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int oss) {
    int32_t b5 = compute_b5(0);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << oss) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void log_pressure(int32_t pressure_pa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %ld\n", ts, (long)pressure_pa);
    fclose(fp);
}

static void toggle_logging(void) {
    uint32_t now = gpioTick();
    if (now - last_edge_tick > DEBOUNCE_MS * 1000) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_edge_tick = now;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() < 0) {
        fprintf(stderr, "BMP180 calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO_TOGGLE, PI_INPUT);
    gpioSetPullUpDown(GPIO_TOGGLE, PI_PUD_UP);
    if (gpioSetAlertFunc(GPIO_TOGGLE, toggle_logging) != 0) {
        fprintf(stderr, "GPIO alert setup failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Pressure logging started. Toggle GPIO27 to enable/disable.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(0, &up) == 0) {
                int32_t pressure = compute_pressure(up, 0);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Sensor read error\n");
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }
    gpioSetAlertFunc(GPIO_TOGGLE, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Clean exit.\n");
    return 0;
}

