#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define MAX31855_READ_INTERVAL_US 1000000
#define MAX31855_FAULT_BIT 0x0001
#define MAX31855_OPEN_FAULT_BIT 0x0002
#define MAX31855_GND_FAULT_BIT 0x0004
#define MAX31855_VCC_FAULT_BIT 0x0008
#define MAX31855_READ_ERROR_BIT 0x0010
#define MAX31855_RESET_BIT 0x0020
#define MAX31855_FAULT_MASK (MAX31855_OPEN_FAULT_BIT | MAX31855_GND_FAULT_BIT | MAX31855_VCC_FAULT_BIT)

#define KP 1.0
#define KI 0.1
#define MAX_DUTY_CYCLE 80.0
#define TARGET_TEMPERATURE 25.0
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static int read_max31855(double *temperature) {
    char buf[4];
    int bytes = spiRead(spi_handle, buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "SPI read failed: expected 4 bytes, got %d\n", bytes);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);
    if (raw & MAX31855_FAULT_MASK) {
        if (raw & MAX31855_OPEN_FAULT_BIT) fprintf(stderr, "MAX31855 open circuit fault\n");
        if (raw & MAX31855_GND_FAULT_BIT) fprintf(stderr, "MAX31855 short to GND fault\n");
        if (raw & MAX31855_VCC_FAULT_BIT) fprintf(stderr, "MAX31855 short to VCC fault\n");
        return -1;
    }
    if (raw & MAX31855_READ_ERROR_BIT) {
        fprintf(stderr, "MAX31855 read error bit set\n");
        return -1;
    }
    if (raw & MAX31855_RESET_BIT) {
        fprintf(stderr, "MAX31855 reset bit set\n");
        return -1;
    }
    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static double pid_control(double setpoint, double actual) {
    static double integral = 0.0;
    double error = setpoint - actual;
    integral += error;
    double output = KP * error + KI * integral;
    if (output < 0.0) { output = 0.0; integral = 0.0; }
    if (output > MAX_DUTY_CYCLE) { output = MAX_DUTY_CYCLE; integral = 0.0; }
    return output;
}

static void set_heater_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * 255.0 / 100.0));
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioWrite(HEATER_GPIO, 0);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Heater control started. Target: %.1fC, Heater GPIO: %d\n", TARGET_TEMPERATURE, HEATER_GPIO);
    while (running) {
        double temperature = 0.0;
        if (read_max31855(&temperature) == 0) {
            double duty_cycle = pid_control(TARGET_TEMPERATURE, temperature);
            set_heater_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("T: %.2fC  D: %.2f%%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Sensor read error — heater off\n");
            set_heater_duty_cycle(0.0);
            log_data(-999.0, 0.0);
        }
        gpioDelay(MAX31855_READ_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

