#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_OFF   PWM_RANGE
#define PWM_ON    0

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_US   500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "I/O error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s: %s\n",
                TEMP_FILE, strerror(errno));
    }

    return temp;
}

static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   PWM_OFF - r);
    gpioPWM(GREEN_PIN, PWM_OFF - g);
    gpioPWM(BLUE_PIN,  PWM_OFF - b);
}

static void apply_temperature(int temp_mdeg)
{
    if (temp_mdeg < 40000) {
        set_led_color(0, 0, 255);   /* Blue */
    } else if (temp_mdeg < 60000) {
        set_led_color(0, 255, 0);   /* Green */
    } else {
        set_led_color(255, 0, 0);   /* Red */
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Common-anode: full off = 255, full on = 0 */
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    /* Start with LED off */
    set_led_color(0, 0, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    while (g_running) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Skipping update due to temperature read error\n");
        } else {
            apply_temperature(temp);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
                   temp, 0, 0, 255);
        }
        gpioDelay(POLL_US);
    }

    /* Clean shutdown: turn off LED and release pigpio */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

