        uint32_t high_duration = gpioTick() - high_start;

        // Bit is 0 if high pulse is < 50us, otherwise 1
        bits[i] = (high_duration > 50) ? 1 : 0;
    }

    // Parse data from bits
    uint8_t humidity_int = (bits[16] << 8) | (bits[17] << 7) | (bits[18] << 6) | (bits[19] << 5) |
                           (bits[20] << 4) | (bits[21] << 3) | (bits[22] << 2) | (bits[23] << 1) | bits[24];
    uint8_t humidity_frac = (bits[25] << 8) | (bits[26] << 7) | (bits[27] << 6) | (bits[28] << 5) |
                            (bits[29] << 4) | (bits[30] << 3) | (bits[31] << 2) | (bits[32] << 1) | bits[33];
    uint8_t temp_int = (bits[34] << 8) | (bits[35] << 7) | (bits[36] << 6) | (bits[37] << 5) |
                       (bits[38] << 4) | (bits[39] << 3) | (bits[40] << 2) | (bits[41] << 1) | bits[42];
    uint8_t temp_frac = (bits[43] << 8) | (bits[44] << 7) | (bits[45] << 6) | (bits[46] << 5) |
                        (bits[47] << 4) | (bits[48] << 3) | (bits[49] << 2) | (bits[50] << 1) | bits[51];
    uint8_t checksum = (bits[52] << 8) | (bits[53] << 7) | (bits[54] << 6) | (bits[55] << 5) |
                       (bits[56] << 4) | (bits[57] << 3) | (bits[58] << 2) | (bits[59] << 1) | bits[60];

    // Validate checksum
    uint8_t calc_checksum = (uint8_t)(humidity_int + humidity_frac + temp_int + temp_frac);
    if (calc_checksum != checksum) {
        fprintf(stderr, "DHT22: Checksum error (calc=0x%02X, recv=0x%02X)\n", calc_checksum, checksum);
        return data;
    }

    // Convert data
    data.humidity = (float)humidity_int + (float)humidity_frac / 10.0f;
    data.temperature = (float)temp_int + (float)temp_frac / 10.0f;
    if (bits[32] == 1) {
        data.temperature = -data.temperature;
    }
    data.error = 0;
    return data;
}

int send_data(const char *url, const char *json_payload) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return 1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return 1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return 1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "HTTP request failed with code: %ld\n", http_code);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return 1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        DHT22Data dht22_data = read_dht22(DHT22_GPIO);

        if (dht22_data.error == 0) {
            char json_payload[128];
            snprintf(json_payload, sizeof(json_payload),
                     "{\"temperature\": %.1f, \"humidity\": %.1f}",
                     dht22_data.temperature, dht22_data.humidity);

            int retries = 0;
            int success = 0;
            while (retries < MAX_RETRIES && !success && program_running) {
                if (send_data(SERVER_URL, json_payload) == 0) {
                    success = 1;
                } else {
                    retries++;
                    if (retries < MAX_RETRIES) {
                        sleep(1);
                    }
                }
            }

            if (!success) {
                fprintf(stderr, "Failed to send data after %d retries\n", MAX_RETRIES);
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
        }

        // Sleep in 1-second increments to allow signal handling
        for (int i = 0; i < READ_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

