#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define LOG_FILE "pressure_log.txt"
#define GPIO_BUTTON 4
#define DEBOUNCE_US 200000

static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int read_calibration(void) {
    int16_t val;
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1) < 0) return -1;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac1 = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac2 = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac3 = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac4 = (uint16_t)val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac5 = (uint16_t)val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    ac6 = (uint16_t)val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b1 = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    b2 = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mb = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    mc = val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);
    md = val;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(26000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure_pa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %d hPa\n", s, pressure_pa / 100);
    fclose(fp);
}

static void button_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    if (tick - last_interrupt_tick < DEBOUNCE_US) return;
    last_interrupt_tick = tick;
    logging_enabled = !logging_enabled;
    if (logging_enabled) printf("Logging enabled.\n");
    else printf("Logging disabled.\n");
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        fprintf(stderr, "BMP180 calibration read failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO_BUTTON, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("Pressure logger started. Press button on GPIO4 to toggle logging.\n");
    while (program_running) {
        if (logging_enabled) {
            int32_t ut, up, b5, pressure_pa;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                b5 = compute_b5(ut);
                pressure_pa = compute_pressure(up, b5);
                log_pressure(pressure_pa);
            } else {
                fprintf(stderr, "Sensor read error\n");
            }
        }
        gpioDelay(2000000);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

