#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10
#define DHT_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read DHT22 via pigpio. Returns 0 on success, -1 on error.
 * humidity_out: 0.0 .. 100.0 %RH
 */
static int read_dht22(float *humidity_out) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = 1;
    int bit_idx = 0;
    uint32_t start_tick, elapsed;

    /* Start signal: pull low for >= 1 ms, then high for 20-40 us */
    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_GPIO, 0) < 0) return -1;
    gpioDelay(1000); /* 1 ms low */
    if (gpioWrite(DHT22_GPIO, 1) < 0) return -1;
    gpioDelay(30);  /* 30 us high */

    /* Switch to input; sensor pulls low */
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;

    /* Wait for sensor response: low then high */
    start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - start_tick > DHT_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 0) {
        if (gpioTick() - start_tick > DHT_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - start_tick > DHT_TIMEOUT_US) return -1;
    }

    /* Read 40 bits */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Low pulse (~50 us) */
        start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - start_tick > DHT_TIMEOUT_US) return -1;
        }
        /* High pulse: ~26-28 us = '0', ~70 us = '1' */
        start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
