#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_SPEED_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(int *temp_out) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", CPU_TEMP_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_out = temp;
    return 0;
}

static int get_max_fan_state(int *max_state_out) {
    FILE *fp = fopen(FAN_SPEED_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_SPEED_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *max_state_out = max_state;
    return 0;
}

static int set_fan_speed(int state) {
    int max_state;
    if (get_max_fan_state(&max_state) != 0) {
        return -1;
    }
    if (state < 0 || state > max_state) {
        fprintf(stderr, "Invalid fan state %d (max %d)\n", state, max_state);
        return -1;
    }
    FILE *fp = fopen(FAN_SPEED_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state %d: %s\n", state, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_SPEED_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_fan_speed(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - Fan speed set to state %d\n", timestamp, state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int determine_fan_state(int cpu_temp) {
    if (cpu_temp < 45000) {
        return 0;
    } else if (cpu_temp < 55000) {
        return 1;
    } else if (cpu_temp < 65000) {
        return 2;
    } else {
        return 3;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int current_state = -1;
    int last_logged_state = -1;

    while (g_running) {
        int cpu_temp;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_cpu_temp(&cpu_temp) == 0) {
                read_ok = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read CPU temperature after %d retries. Skipping cycle.\n", MAX_RETRIES);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int target_state = determine_fan_state(cpu_temp);

        if (target_state != current_state) {
            if (set_fan_speed(target_state) != 0) {
                fprintf(stderr, "Failed to set fan speed to state %d\n", target_state);
            } else {
                current_state = target_state;
                if (log_fan_speed(current_state) != 0) {
                    fprintf(stderr, "Failed to log fan speed change\n");
                } else {
                    last_logged_state = current_state;
                }
            }
        } else if (current_state != last_logged_state) {
            if (log_fan_speed(current_state) != 0) {
                fprintf(stderr, "Failed to log fan speed change\n");
            } else {
                last_logged_state = current_state;
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Failed to stop fan during shutdown\n");
    }
    if (log_fan_speed(0) != 0) {
        fprintf(stderr, "Failed to log shutdown\n");
    }

    return 0;
}

