#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define SAMPLE_INTERVAL_US 1000000

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define TARGET_TEMP 50.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static int read_max31855(float *temp) {
    char buf[4];
    int ret = spiRead(spi_handle, buf, 4);
    if (ret != 4) {
        log_message("SPI read error: incomplete transfer");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) log_message("MAX31855 fault: open circuit");
        else if (raw & 0x00000002) log_message("MAX31855 fault: short to GND");
        else if (raw & 0x00000001) log_message("MAX31855 fault: short to VCC");
        else log_message("MAX31855 fault: unknown");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temp = thermocouple_raw * 0.25;
    return 0;
}

static void set_heater_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty);
}

static void log_data(float temp, int duty, float pid_out) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Temp=%.2fC, PWM=%d, PID=%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, duty, pid_out);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0;
    float prev_error = 0.0;
    int heater_enabled = 0;

    while (running) {
        float temp;
        if (read_max31855(&temp) != 0) {
            set_heater_pwm(0);
            heater_enabled = 0;
            integral = 0.0;
            prev_error = 0.0;
            log_message("Sensor read failed, heater disabled");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            set_heater_pwm(0);
            heater_enabled = 0;
            integral = 0.0;
            prev_error = 0.0;
            char msg[128];
            snprintf(msg, sizeof(msg), "Failsafe: temp out of range (%.2fC)", temp);
            log_message(msg);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float error = TARGET_TEMP - temp;
        integral += error;
        float derivative = error - prev_error;
        float output = KP * error + KI * integral + KD * derivative;
        prev_error = error;

        int duty = (int)(output + 0.5);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        if (!heater_enabled || duty > 0) {
            set_heater_pwm(duty);
            heater_enabled = 1;
        }

        log_data(temp, duty, output);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_heater_pwm(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

