#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5
#define MIN_TEMP_C 40.0
#define MAX_TEMP_C 70.0
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp_milliC;
    if (fscanf(fp, "%d", &temp_milliC) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milliC;
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }
    int pwm_value = (duty_cycle * 255) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(float temp_c, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty_cycle) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 255) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("Error creating log file");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milliC = read_cpu_temp();
        if (temp_milliC < 0) {
            fprintf(stderr, "Error reading CPU temperature, skipping cycle\n");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        float temp_c = (float)temp_milliC / 1000.0f;
        int duty_cycle;

        if (temp_c <= MIN_TEMP_C) {
            duty_cycle = MIN_DUTY_CYCLE;
        } else if (temp_c >= MAX_TEMP_C) {
            duty_cycle = MAX_DUTY_CYCLE;
        } else {
            duty_cycle = (int)(((temp_c - MIN_TEMP_C) / (MAX_TEMP_C - MIN_TEMP_C)) * 100.0f);
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 100) duty_cycle = 100;
        }

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed\n");
        }

        if (log_data(temp_c, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d%%\n", temp_c, duty_cycle);
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

