#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define POLL_INTERVAL_US 1000000

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[3];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(10000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries\n", RETRY_COUNT);
    return -1;
}

static int log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
