#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_rotation(FILE *fp, int rotation_direction, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s - Rotation: %d, Angle: %.2f\n", timestamp, rotation_direction, angle) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *fp = NULL;
    int last_a = 0;
    int last_b = 0;
    int current_a = 0;
    int current_b = 0;
    int rotation_direction = 0;
    double angle = 0.0;
    int state = 0;
    int ret_code = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not register SIGINT handler: %s\n", strerror(errno));
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not register SIGTERM handler: %s\n", strerror(errno));
    }

    last_a = gpioRead(SENSOR_A_PIN);
    last_b = gpioRead(SENSOR_B_PIN);

    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Error reading initial sensor states\n");
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring rotary encoder. Press Ctrl+C to exit.\n");

    while (running) {
        current_a = gpioRead(SENSOR_A_PIN);
        current_b = gpioRead(SENSOR_B_PIN);

        if (current_a < 0 || current_b < 0) {
            fprintf(stderr, "Error reading sensor states\n");
            ret_code = EXIT_FAILURE;
            break;
        }

        if (current_a != last_a || current_b != last_b) {
            int a_changed = (current_a != last_a);
            int b_changed = (current_b != last_b);

            if (a_changed) {
                state = (state & 3) | (current_a << 1);
            }
            if (b_changed) {
                state = (state & 3) | (current_b << 0);
            }

            switch (state) {
                case 0: case 1: case 2: case 3:
                    break;
                case 4: case 5: case 6: case 7:
                    rotation_direction = 1;
                    angle += (360.0 / PULSES_PER_REVOLUTION);
                    if (angle >= 360.0) {
                        angle -= 360.0;
                    }
                    break;
                case 8: case 9: case 10: case 11:
                    rotation_direction = -1;
                    angle -= (360.0 / PULSES_PER_REVOLUTION);
                    if (angle < 0.0) {
                        angle += 360.0;
                    }
                    break;
                case 12: case 14:
                    rotation_direction = 1;
                    angle += (360.0 / PULSES_PER_REVOLUTION);
                    if (angle >= 360.0) {
                        angle -= 360.0;
                    }
                    break;
                case 13: case 15:
                    rotation_direction = -1;
                    angle -= (360.0 / PULSES_PER_REVOLUTION);
                    if (angle < 0.0) {
                        angle += 360.0;
                    }
                    break;
                default:
                    fprintf(stderr, "Invalid state: %d\n", state);
                    ret_code = EXIT_FAILURE;
                    goto cleanup;
            }

            if (log_rotation(fp, rotation_direction, angle) != 0) {
                ret_code = EXIT_FAILURE;
                goto cleanup;
            }

            last_a = current_a;
            last_b = current_b;
        }

        gpioDelay(1000);
    }

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return ret_code;
}

