#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG  0x60
#define LED_GPIO_LINE  17
#define IR_THRESHOLD   2000
#define SAMPLE_MS      100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(log_file, "timestamp,red,ir\n");
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (i2c_read_reg16(i2c_fd, FIFO_DATA_REG, &red) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }
        if (i2c_read_reg16(i2c_fd, FIFO_DATA_REG, &ir) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%u,%u\n", ts, red, ir);
        fflush(log_file);

        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

