#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static int log_rpm(float rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        float rpm = (float)pulses * 60.0f / (float)SAMPLE_INTERVAL_SEC;

        if (pulses == 0) {
            printf("No pulses detected this interval. Logging 0.00 RPM.\n");
        }

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    printf("Cleanup complete.\n");
    return 0;
}

