        return -1;
    }
    uint8_t data[4];
    if (i2c_read_block(i2c_fd, REG_FIFO_DATA, data, 4) != 0) {
        fprintf(stderr, "Error: Failed to read FIFO data.\n");
        return -1;
    }
    *red = (uint16_t)((data[0] << 8) | data[1]);
    *ir  = (uint16_t)((data[2] << 8) | data[3]);
    return 0;
}

static void log_data(uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Error: Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_adpd144ri() != 0) {
        fprintf(stderr, "Error: ADPD144RI initialization failed.\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error: Failed to open gpiochip0");
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("Error: Failed to get GPIO line 17");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        perror("Error: Failed to request GPIO line as output");
        cleanup();
        return 1;
    }

    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");
    while (running) {
        uint16_t red, ir;
        if (read_adpd144ri_data(&red, &ir) == 0) {
            log_data(red, ir);
            if (ir > IR_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Warning: Read failed, retrying...\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

