#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_CMD_MSB 0x36
#define FLOW_CMD_LSB 0x08
#define FLOW_SCALE 1000.0f
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "flow_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int initialize_sensor(void) {
    uint8_t cmd[2] = {FLOW_CMD_MSB, FLOW_CMD_LSB};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send flow start command to sensor.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed (expected 3 bytes, got %d).\n", bytes_read);
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC check failed for flow data.\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw_flow / FLOW_SCALE;
    return 0;
}

static void log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device on bus %d at address 0x%02X.\n", I2C_BUS, SLF3S_ADDR);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            log_flow_rate(flow_rate);
            printf("Flow Rate: %.2f uL/min\n", flow_rate);
        } else {
            fprintf(stderr, "Warning: Failed to read flow rate, retrying next cycle.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

