#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int iaq;
    int tvoc;
    int eco2;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, len);
        if (bytes_read == len) {
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): expected %d, got %d\n",
                retries + 1, MAX_RETRIES, len, bytes_read);
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t result = {0, 0, 0};
    result.tvoc = (data[1] << 8) | data[0];
    result.eco2 = (data[5] << 8) | data[4];
    result.iaq = 100 - (result.tvoc / 10) - ((result.eco2 - 400) / 50);
    if (result.iaq < 0) result.iaq = 0;
    if (result.iaq > 100) result.iaq = 100;
    return result;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->iaq, data->tvoc, data->eco2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
