#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 17
#define SAMPLE_RATE 16000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 2
#define FRAME_SIZE (NUM_CHANNELS * BITS_PER_SAMPLE / 8)
#define BUFFER_SIZE (SAMPLE_RATE * FRAME_SIZE)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(line, "inmp441-lr-select", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup_chip;
    }

    fd = open(I2S_DEVICE, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        goto cleanup_line;
    }

    if (ioctl(fd, SNDCTL_DSP_SETFMT, &(int){AFMT_S16_LE}) < 0) {
        fprintf(stderr, "Failed to set format: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &(int){NUM_CHANNELS}) < 0) {
        fprintf(stderr, "Failed to set channels: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    if (ioctl(fd, SNDCTL_DSP_SPEED, &(int){SAMPLE_RATE}) < 0) {
        fprintf(stderr, "Failed to set sample rate: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    fp = fopen("audio_capture.pcm", "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open audio_capture.pcm: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    printf("Capturing audio from INMP441 via ALSA I2S... Press Ctrl+C to stop.\n");

    while (running) {
        uint8_t buffer[BUFFER_SIZE];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));

        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            break;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "Unexpected EOF on I2S device.\n");
            break;
        }

        if (fwrite(buffer, 1, bytes_read, fp) != (size_t)bytes_read) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            break;
        }
    }

    ret = EXIT_SUCCESS;

    if (fp) fclose(fp);
cleanup_fd:
    if (fd >= 0) close(fd);
cleanup_line:
    if (line) gpiod_line_release(line);
cleanup_chip:
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("Audio capture complete. File saved as audio_capture.pcm\n");
    }
    return ret;
}

