#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define MAX_FLAME_DURATION_SEC 10
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    } else {
        fprintf(fp, "[timestamp error] %s\n", event);
    }
    fclose(fp);
}

static int set_fan_speed(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty = (duty_percent * 255) / 100;
    if (gpioPWM(FAN_PWM_PIN, duty) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return v;
}

static int calculate_duty_cycle(double flame_duration) {
    if (flame_duration < 0.0) flame_duration = 0.0;
    if (flame_duration > MAX_FLAME_DURATION_SEC) flame_duration = MAX_FLAME_DURATION_SEC;
    double scale = 0.8;
    double exponent = exp(-(flame_duration / 2.0));
    int duty = (int)(scale * exponent * 100.0);
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    return duty;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
