#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define HEATMAP_SIZE 32768
#define FRAME_NUMBER_OFFSET 0
#define FRAME_TIMESTAMP_OFFSET 4
#define FRAME_DATA_OFFSET 8
#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
    uint32_t reserved;
} __attribute__((packed)) config_header_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint64_t get_timestamp_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode.\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set data-ready pin mode.\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize trigger pin.\n");
        return -1;
    }
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d, mode %d).\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        return -1;
    }
    return 0;
}

static int write_config_header(FILE *fp) {
    config_header_t header;
    memset(&header, 0, sizeof(header));
    header.magic = MAGIC_NUMBER;
    header.timestamp = get_timestamp_us();
    header.start_frequency = 770000000;
    header.end_frequency = 790000000;
    header.num_chirps = 64;
    header.num_samples = 256;
    header.frame_period_ms = 100;

    if (fwrite(&header, sizeof(header), 1, fp) != 1) {
        fprintf(stderr, "Error: Failed to write config header.\n");
        return -1;
    }
    return 0;
}

static int read_heatmap_data(uint8_t *data, int len) {
    if (data == NULL || len <= 0) {
        fprintf(stderr, "Error: Invalid buffer for SPI read.\n");
        return -1;
    }
    int bytes_read = spiRead(spi_handle, (char *)data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: SPI read failed (expected %d, got %d).\n", len, bytes_read);
        return -1;
    }
    return 0;
}

static int log_frame(uint8_t *data, int len, uint32_t frame_number) {
    uint64_t timestamp = get_timestamp_us();
    if (fwrite(&frame_number, sizeof(frame_number), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame number.\n");
        return -1;
    }
    if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write timestamp.\n");
        return -1;
    }
    if (fwrite(data, len, 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame data.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("radar_data.log", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup();
        return 1;
    }

    if (write_config_header(log_file) != 0) {
        cleanup();
        return 1;
    }

    uint8_t *heatmap_data = malloc(HEATMAP_SIZE);
    if (heatmap_data == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        cleanup();
        return 1;
    }

    uint32_t frame_number = 0;
    while (running) {
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: Failed to assert trigger.\n");
            break;
        }
        gpioDelay(1000);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to deassert trigger.\n");
            break;
        }

        int ready = 0;
        for (int i = 0; i < 100 && running; i++) {
            if (gpioRead(DATA_READY_PIN) == 1) {
                ready = 1;
                break;
            }
            gpioDelay(1000);
        }
        if (!ready) {
            fprintf(stderr, "Warning: Data-ready timeout.\n");
            continue;
        }

        if (read_heatmap_data(heatmap_data, HEATMAP_SIZE) != 0) {
            break;
        }

        if (log_frame(heatmap_data, HEATMAP_SIZE, frame_number) != 0) {
            break;
        }

        frame_number++;
    }

    free(heatmap_data);
    cleanup();
    return 0;
}

