#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_RESULT 0x00
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_MANUFACTURER_ID 0x7E
#define OPT3001_REG_DEVICE_ID 0x7F

#define OPT3001_CONFIG_CONTINUOUS 0xC003
#define OPT3001_CONFIG_100MS 0x0000
#define OPT3001_CONFIG_AUTO_RANGE 0x0000

#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int opt3001_init(int handle) {
    int id;

    id = i2cReadByteData(handle, OPT3001_REG_MANUFACTURER_ID);
    if (id != 0x5449) {
        fprintf(stderr, "Error: Manufacturer ID mismatch (0x%04X, expected 0x5449)\n", id);
        return -1;
    }

    id = i2cReadByteData(handle, OPT3001_REG_DEVICE_ID);
    if (id != 0x3001) {
        fprintf(stderr, "Error: Device ID mismatch (0x%04X, expected 0x3001)\n", id);
        return -1;
    }

    if (i2cWriteWordData(handle, OPT3001_REG_CONFIG, OPT3001_CONFIG_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }

    return 0;
}

static int opt3001_read_lux(int handle, float *lux_out) {
    char buf[2];
    int raw;
    int exponent;
    int mantissa;

    if (i2cReadI2CBlockData(handle, OPT3001_REG_RESULT, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read result register\n");
        return -1;
    }

    raw = (buf[0] << 8) | buf[1];
    exponent = (raw >> 12) & 0x0F;
    mantissa = raw & 0x0FFF;

    *lux_out = 0.01f * (float)(1 << exponent) * (float)mantissa;
    return 0;
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    localtime_r(&t, &tm);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fflush(fp);
}

int main(void) {
    float lux;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, OPT3001_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: OPT3001 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (opt3001_read_lux(i2c_handle, &lux) == 0) {
            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down cleanly...\n");

    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

