/*
 * SainSmart IR Flame Detection Sensor Module reader using libgpiod v2.x API.
 *
 * Wiring:
 *   Sensor VCC -> 3.3V (Pin 1)
 *   Sensor GND -> GND  (Pin 9)
 *   Sensor DOUT -> GPIO17 (Pin 11)
 *
 * The sensor DO line is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buffer);
            return;
        }
    }
    printf("[unknown time] ");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    int ret;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure line settings: input with bias pull-up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error: cannot allocate line settings: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: cannot set line direction: %s\n", strerror(errno));
        goto cleanup_settings;
    }

    ret = gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: cannot set line bias: %s\n", strerror(errno));
        goto cleanup_settings;
    }

    /* Configure the line */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: cannot allocate line config: %s\n", strerror(errno));
        goto cleanup_settings;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, &(unsigned int){GPIO_LINE_OFFSET}, 1, settings);
    if (ret != 0) {
        fprintf(stderr, "Error: cannot add line settings: %s\n", strerror(errno));
        goto cleanup_line_cfg;
    }

    /* Request the line */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: cannot allocate request config: %s\n", strerror(errno));
        goto cleanup_line_cfg;
    }

    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Error: cannot request GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_req_cfg;
    }

    printf("Flame detection program started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: cannot read GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    /* Cleanup */
    gpiod_line_request_release(request);
    gpiod_request_config_free(req_cfg);
    gpiod_line_config_free(line_cfg);
    gpiod_line_settings_free(settings);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;

cleanup_req_cfg:
    gpiod_request_config_free(req_cfg);
cleanup_line_cfg:
    gpiod_line_config_free(line_cfg);
cleanup_settings:
    gpiod_line_settings_free(settings);
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

