#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define SI1145_REG_PARTID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX 0x2C
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_COMMAND 0x18

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_CMD_ALS_FORCE 0x06

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(i2c_handle, reg);
    if (r < 0) {
        fprintf(stderr, "Error reading reg 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (read_reg(SI1145_REG_PARTID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART ID: 0x%02X)\n", part_id);

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;

    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;

    if (write_reg(SI1145_REG_CHLIST, 0x03) < 0) return -1;

    return 0;
}

static int read_uv_index(uint8_t *uv_index) {
    return read_reg(SI1145_REG_UVINDEX, uv_index);
}

static int read_als_visible(uint16_t *als_visible) {
    uint8_t lo = 0, hi = 0;
    if (read_reg(SI1145_REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA1, &hi) < 0) return -1;
    *als_visible = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int trigger_als_force(void) {
    return write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE);
}

static void log_data(uint8_t uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        if (trigger_als_force() < 0) {
            fprintf(stderr, "Error triggering ALS force measurement\n");
            break;
        }

        gpioDelay(10000);

        uint8_t uv_index = 0;
        uint16_t als_visible = 0;

        if (read_uv_index(&uv_index) < 0) {
            fprintf(stderr, "Error reading UV index\n");
            break;
        }

        if (read_als_visible(&als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible\n");
            break;
        }

        printf("UV Index: %u, ALS Visible: %u\n", uv_index, als_visible);
        log_data(uv_index, als_visible);

        gpioDelay(1000000);
    }

    printf("\nCleaning up...\n");
    cleanup();
    return 0;
}

