#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define FLOW_REG       0x00
#define CMD_REG        0x08
#define CMD_START      0x3608
#define FLOW_SCALE     0.036f
#define ALARM_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t addr, uint16_t cmd) {
    uint8_t buf[3] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF), 0x00 };
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_sensor(int fd, uint8_t addr) {
    if (i2c_write_cmd(fd, addr, CMD_START) < 0) {
        fprintf(stderr, "Error: failed to start measurement on sensor 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_flow(int fd, uint8_t addr, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, addr, FLOW_REG, buf, sizeof(buf)) < 0) {
