#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_GPIO 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_US 50000

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

static SensorData buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_buffer(time_t timestamp, int reading) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        if (buffer[idx].timestamp != 0) {
            char time_str[32];
            struct tm *tm_info = localtime(&buffer[idx].timestamp);
            if (tm_info) {
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            } else {
                strncpy(time_str, "INVALID", sizeof(time_str));
            }
            printf("[%s] Reading: %d\n", time_str, buffer[idx].reading);
        }
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    printf("Obstacle detection system started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (program_running) {
        int reading = gpioRead(SENSOR_GPIO);
        if (reading < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", SENSOR_GPIO);
            break;
        }

        if (reading == 0) {
            time_t current_time = time(NULL);
            if (current_time == (time_t)-1) {
                fprintf(stderr, "Error: failed to get current time\n");
            } else {
                add_to_buffer(current_time, reading);
                printf("Obstacle detected! Timestamp: %ld\n", (long)current_time);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    print_buffer();
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

