#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR        0x55
#define REG_MODE_CTRL   0x1D
#define REG_OP_STATUS   0x1B
#define REG_X_LSB       0x2A
#define REG_X_MSB       0x2B
#define REG_Y_LSB       0x2C
#define REG_Y_MSB       0x2D
#define REG_Z_LSB       0x2E
#define REG_Z_MSB       0x2F
#define SCALE_FACTOR    0.0009765625f
#define SAMPLE_PERIOD_US 500000
#define ACTIVE_TIMEOUT_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lsb, int16_t *out) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int init_d7s(int fd) {
    if (i2c_write_reg8(fd, REG_MODE_CTRL, 0x10) < 0) {
        fprintf(stderr, "Failed to set D7S to active mode\n");
        return -1;
    }
    for (int i = 0; i < ACTIVE_TIMEOUT_S * 2; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_OP_STATUS, &status) < 0) {
            fprintf(stderr, "Failed to read D7S operating status\n");
            return -1;
        }
        if (status & 0x01) return 0;
        usleep(500000);
    }
    fprintf(stderr, "D7S did not become active within %d seconds\n", ACTIVE_TIMEOUT_S);
    return -1;
}

static void log_sample(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_d7s(g_i2c_fd) < 0) {
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen("fan_health.csv", "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }

    printf("D7S fan health monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x_raw, y_raw, z_raw;
        if (i2c_read_reg16_le(g_i2c_fd, REG_X_LSB, &x_raw) < 0 ||
            i2c_read_reg16_le(g_i2c_fd, REG_Y_LSB, &y_raw) < 0 ||
            i2c_read_reg16_le(g_i2c_fd, REG_Z_LSB, &z_raw) < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        float x = x_raw * SCALE_FACTOR;
        float y = y_raw * SCALE_FACTOR;
        float z = z_raw * SCALE_FACTOR;
        log_sample(g_csv, x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

