#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
    }
    return v;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output, ensure it starts OFF */
    if (safe_set_mode(LED_PIN, PI_OUTPUT) != 0 ||
        safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = safe_read(SENSOR_1_PIN);
        int s2 = safe_read(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 active-LOW: 0 = obstacle detected */
        if (s1 == 0 || s2 == 0) {
            if (safe_write(LED_PIN, 1) != 0) {
                break;
            }
        } else {
            if (safe_write(LED_PIN, 0) != 0) {
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure LED is OFF */
    (void)safe_write(LED_PIN, 0);
    gpioTerminate();
    printf("\nObstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

