#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x0E
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000
#define DEVID_REG      0x00
#define DEVID_VAL      0x8D
#define CTRL_REG       0x01
#define CTRL_VAL       0x00  /* continuous-conversion, all axes enabled, 50 mT range */
#define X_MSB_REG      0x02
#define Y_MSB_REG      0x04
#define Z_MSB_REG      0x06
#define SCALE_50MT     0.050f  /* mT per LSB for 50 mT range */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X)\n", reg, val);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed (reg=0x%02X)\n", reg);
        return -1;
    }
    char val_buf[1];
    if (i2cReadDevice(i2c_handle, val_buf, 1) != 1) {
        fprintf(stderr, "I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    *val = (uint8_t)val_buf[0];
    return 0;
}

static int read_magnetic_data(float *x, float *y, float *z) {
    uint8_t x_msb, y_msb, z_msb;
    if (i2c_read_reg(X_MSB_REG, &x_msb) != 0) return -1;
    if (i2c_read_reg(Y_MSB_REG, &y_msb) != 0) return -1;
