#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define WATER_SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "UNKNOWN TIMESTAMP: %s\n", message);
    }
    fclose(fp);
    return 0;
}

static int read_water_sensor(int gpio) {
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio, pigpio_error(level));
        return -1;
    }
    return level;
}

static void check_water_level(int gpio) {
    int level = read_water_sensor(gpio);
    if (level < 0) {
        log_event("ERROR: Failed to read water sensor");
        return;
    }
    if (level == 1) {
        printf("ALERT: Water detected!\n");
        fflush(stdout);
        log_event("ALERT: Water detected");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        log_event("ERROR: pigpio initialization failed");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(WATER_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", WATER_SENSOR_GPIO);
        log_event("ERROR: Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(WATER_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", WATER_SENSOR_GPIO);
        log_event("ERROR: Failed to set pull-down");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("INFO: Water monitoring daemon started");

    time_t last_reinit_attempt = time(NULL);

    while (running) {
        check_water_level(WATER_SENSOR_GPIO);

        time_t now = time(NULL);
        if (now - last_reinit_attempt >= REINIT_DELAY_SEC) {
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialization failed\n");
                log_event("ERROR: pigpio re-initialization failed");
            } else {
                log_event("INFO: pigpio re-initialized");
                last_reinit_attempt = now;
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("INFO: Water monitoring daemon stopped");
    gpioTerminate();
    return EXIT_SUCCESS;
}

