#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdatomic.h>

#define SENSOR_GPIO 4          /* BCM 4, physical pin 7 */
#define SAMPLE_PERIOD_US 1000000  /* 1 second in microseconds */
#define PULSES_PER_REV 1        /* one pulse per revolution */

static atomic_int g_pulse_count = 0;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in pigpio thread — keep it short       */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == PI_HIGH) {
        atomic_fetch_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Append one timestamped RPM line to the log file                    */
/* ------------------------------------------------------------------ */
static void log_rpm(int rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s %d\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor GPIO ---- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("rpm_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(\"rpm_log.txt\")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for rising-edge detection ---- */
    if (gpioSetAlertFunc(SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for GPIO %d\n", SENSOR_GPIO);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Start 1-second sampling timer ---- */
    if (gpioSetTimerFunc(0, SAMPLE_PERIOD_US, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFunc failed\n");
        gpioSetAlertFunc(SENSOR_GPIO, NULL);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        gpioDelay(SAMPLE_PERIOD_US);  /* pigpio busy-wait; ~1 s */

        int pulses = atomic_exchange(&g_pulse_count, 0);
        int rpm = (pulses * 60) / PULSES_PER_REV;

        log_rpm(rpm);
        printf("RPM: %d\n", rpm);
    }

    /* ---- Clean shutdown ---- */
    gpioSetAlertFunc(SENSOR_GPIO, NULL);
    gpioSetTimerFunc(0, 0, NULL);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    printf("\nRPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

