#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine states */
typedef enum {
    STATE_A_LOW = 0,
    STATE_A_HIGH = 1,
    STATE_B_LOW = 2,
    STATE_B_HIGH = 3
} QuadState;

/* Shared state between ISR and main loop */
typedef struct {
    QuadState state;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    volatile sig_atomic_t running;
} SharedData;

static SharedData shared;

/* ISR callback for sensor A */
static void sensorA_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&shared.mutex);
    switch (shared.state) {
        case STATE_A_LOW:
            if (level == 1) shared.state = STATE_A_HIGH;
            break;
        case STATE_A_HIGH:
            if (level == 0) shared.state = STATE_B_LOW;
            break;
        case STATE_B_LOW:
            if (level == 1) shared.state = STATE_B_HIGH;
            break;
        case STATE_B_HIGH:
            if (level == 0) shared.state = STATE_A_LOW;
            break;
    }
    pthread_cond_signal(&shared.cond);
    pthread_mutex_unlock(&shared.mutex);
}

/* ISR callback for sensor B */
static void sensorB_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&shared.mutex);
    switch (shared.state) {
        case STATE_A_LOW:
            if (level == 1) shared.state = STATE_B_HIGH;
            break;
        case STATE_A_HIGH:
            if (level == 0) shared.state = STATE_B_LOW;
            break;
        case STATE_B_LOW:
            if (level == 1) shared.state = STATE_A_HIGH;
            break;
        case STATE_B_HIGH:
            if (level == 0) shared.state = STATE_A_LOW;
            break;
    }
    pthread_cond_signal(&shared.cond);
    pthread_mutex_unlock(&shared.mutex);
}

/* Append a rotation event to the log file */
static void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s %s\n", timestamp, direction);
    fclose(fp);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    pthread_mutex_lock(&shared.mutex);
    shared.running = 0;
    pthread_cond_signal(&shared.cond);
    pthread_mutex_unlock(&shared.mutex);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with pull-up resistors */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize shared state */
    shared.state = STATE_A_LOW;
    pthread_mutex_init(&shared.mutex, NULL);
    pthread_cond_init(&shared.cond, NULL);
    shared.running = 1;

    /* Register ISR callbacks */
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensorA_isr) != 0) {
        fprintf(stderr, "Failed to set alert for GPIO %d\n", SENSOR_A_GPIO);
        pthread_mutex_destroy(&shared.mutex);
        pthread_cond_destroy(&shared.cond);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensorB_isr) != 0) {
        fprintf(stderr, "Failed to set alert for GPIO %d\n", SENSOR_B_GPIO);
        gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
        pthread_mutex_destroy(&shared.mutex);
        pthread_cond_destroy(&shared.cond);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (1) {
        pthread_mutex_lock(&shared.mutex);
        while (shared.running && shared.state == STATE_A_LOW) {
            pthread_cond_wait(&shared.cond, &shared.mutex);
        }
        if (!shared.running) {
            pthread_mutex_unlock(&shared.mutex);
            break;
        }

        QuadState current_state = shared.state;
        pthread_mutex_unlock(&shared.mutex);

        /* Determine direction from previous state */
        const char *direction = "UNKNOWN";
        switch (current_state) {
            case STATE_A_HIGH: direction = "CW"; break;
            case STATE_B_HIGH: direction = "CCW"; break;
            default: break;
        }

        log_rotation(direction);

        /* Wait for next state change */
        pthread_mutex_lock(&shared.mutex);
        while (shared.running && shared.state == current_state) {
            pthread_cond_wait(&shared.cond, &shared.mutex);
        }
        pthread_mutex_unlock(&shared.mutex);
    }

    /* Cleanup */
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);
    pthread_mutex_destroy(&shared.mutex);
    pthread_cond_destroy(&shared.cond);
    gpioTerminate();

    printf("Rotation detection stopped.\n");
    return EXIT_SUCCESS;
}

