#include <gpiod.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry on interrupt */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request touch line as input with rising-edge event detection */
    if (gpiod_line_request_rising_edge_events(touch_line, "touch-sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "led-toggle", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor on GPIO %d, LED on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_PIN, LED_PIN);

    int led_state = 0;
    struct timespec last_event = {0, 0};

    while (running) {
        /* Block up to POLL_TIMEOUT_MS waiting for a rising-edge event */
        int ev = gpiod_line_event_wait(touch_line, &(struct timespec){
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (long)(POLL_TIMEOUT_MS % 1000) * 1000000L
        });

        if (ev < 0) {
            if (errno == EINTR) {
                continue;  /* interrupted by signal */
            }
            fprintf(stderr, "gpiod_line_event_wait: %s\n", strerror(errno));
            goto cleanup;
        }

        if (ev == 0) {
            /* Timeout, no event — loop and check running flag */
            continue;
        }

        /* Event detected — read it to clear the event queue */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read: %s\n", strerror(errno));
            continue;
        }

        /* Debounce: ignore events within DEBOUNCE_MS of the last accepted one */
        struct timespec now = event.ts;
        long diff_ms = (now.tv_sec - last_event.tv_sec) * 1000L
                    + (now.tv_nsec - last_event.tv_nsec) / 1000000L;
        if (diff_ms < DEBOUNCE_MS) {
            continue;
        }
        last_event = now;

        /* Toggle LED */
        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("Touch detected! LED toggled to %s\n", led_state ? "ON" : "OFF");
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off on exit */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

