#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int overflow_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_2_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure LEDs start off */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_event(int sensor_pin, time_t timestamp, int state) {
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Index: %d, Sensor Pin: %d, Timestamp: %ld, State: %d\n",
               i, log_buffer[i].sensor_pin, (long)log_buffer[i].timestamp, log_buffer[i].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
    printf("--- End of Log Buffer ---\n\n");
}

static void cleanup(void) {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    int prev_state1 = -1;
    int prev_state2 = -1;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int state1 = gpioRead(SENSOR_1_PIN);
        int state2 = gpioRead(SENSOR_2_PIN);

        if (state1 < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", SENSOR_1_PIN);
            break;
        }
        if (state2 < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", SENSOR_2_PIN);
            break;
        }

        if (state1 != prev_state1) {
            if (gpioWrite(LED_1_PIN, state1) != 0) {
                fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_1_PIN);
                break;
            }
            log_event(SENSOR_1_PIN, time(NULL), state1);
            prev_state1 = state1;
        }

        if (state2 != prev_state2) {
            if (gpioWrite(LED_2_PIN, state2) != 0) {
                fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_2_PIN);
                break;
            }
            log_event(SENSOR_2_PIN, time(NULL), state2);
            prev_state2 = state2;
        }

        usleep(POLL_DELAY_US);
    }

    print_log_buffer();
    cleanup();
    return 0;
}

