#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define PULSES_PER_REVOLUTION 2
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int debounce_sensor(int gpio_pin) {
    int value1 = read_sensor(gpio_pin);
    if (value1 < 0) return -1;
    gpioDelay(DEBOUNCE_DELAY_US);
    int value2 = read_sensor(gpio_pin);
    if (value2 < 0) return -1;
    return (value1 == value2) ? value1 : -1;
}

double calculate_rpm(unsigned long long elapsed_microseconds) {
    if (elapsed_microseconds == 0) return 0.0;
    return (double)PULSES_PER_REVOLUTION * 60000000.0 / (double)elapsed_microseconds;
}

void log_data(FILE *log_file, int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int prev_sensor1_state = -1;
    int prev_sensor2_state = -1;
    unsigned long long last_pulse_time = 0;
    unsigned long long elapsed_microseconds = 0;

    printf("Monitoring rotating shaft... Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_state = debounce_sensor(SENSOR1_GPIO);
        int sensor2_state = debounce_sensor(SENSOR2_GPIO);

        if (sensor1_state < 0 || sensor2_state < 0) {
            gpioDelay(10000);
            continue;
        }

        if (sensor1_state != prev_sensor1_state || sensor2_state != prev_sensor2_state) {
            log_data(log_file, sensor1_state, sensor2_state);
            prev_sensor1_state = sensor1_state;
            prev_sensor2_state = sensor2_state;
        }

        if (sensor1_state == 1 && prev_sensor1_state == 0) {
            unsigned long long current_time = gpioTick();
            if (last_pulse_time != 0) {
                elapsed_microseconds = current_time - last_pulse_time;
            }
            last_pulse_time = current_time;
        }

        double rpm = calculate_rpm(elapsed_microseconds);
        printf("RPM: %.2f\n", rpm);

        gpioDelay(10000);
    }

    printf("\nExiting gracefully...\n");
    fclose(log_file);
    gpioTerminate();
    return 0;
}

