#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_DATA_REG 0x02
#define SPO2_DATA_REG 0x04
#define EXPECTED_PART_ID 0x82
#define LOG_FILE "biometric_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_heart_rate(int handle, uint8_t *hr) {
    return read_register(handle, HR_DATA_REG, hr);
}

static int read_spo2(int handle, uint8_t *spo2) {
    return read_register(handle, SPO2_DATA_REG, spo2);
}

static void log_data(FILE *fp, uint8_t hr, uint8_t spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, hr, spo2);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint8_t part_id = 0;
    uint8_t hr = 0, spo2 = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_register(i2c_handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Sensor not detected at address 0x%02X\n", SI1182_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Si1182 initialized. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        if (read_heart_rate(i2c_handle, &hr) == 0 && read_spo2(i2c_handle, &spo2) == 0) {
            log_data(log_file, hr, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

