#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27

#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US   100000  /* 100 ms */
#define LOG_FILE_NAME      "bridge_integrity.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped line to the log file                 */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tstruct = localtime_r(&now, &tm_buf);
    if (tstruct == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s: %s\n", ts, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error                  */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Activate / deactivate the alarm pin                                */
/* ------------------------------------------------------------------ */
static void set_alarm(int state)
{
    if (gpioWrite(ALARM_GPIO, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", ALARM_GPIO, state);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — deactivate alarm, close log, terminate pigpio            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    set_alarm(0);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
