/*
 * Raspberry Pi 3 Model B+ — Omron D7S-A0011 seismic sensor monitor
 *
 * Wiring:
 *   D7S-A0011 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   D7S-A0011 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   D7S-A0011 VDD  -> 3.3 V
 *   D7S-A0011 GND  -> GND
 *   LED anode      -> GPIO17 (via 330 Ω resistor) -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 *   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500           /* raw ADC count threshold */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register map (from datasheet) */
#define REG_CTRL1            0x1F
#define REG_X_AXIS_L         0x28
#define REG_X_AXIS_H         0x29
#define REG_Y_AXIS_L         0x2A
#define REG_Y_AXIS_H         0x2B
#define REG_Z_AXIS_L         0x2C
#define REG_Z_AXIS_H         0x2D

/* CTRL1 bit masks */
#define CTRL1_PD_BIT         0x01          /* power-down / standby */

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes -------------------------- */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(int16_t *x, int16_t *y, int16_t *z);
static int  calculate_magnitude(int16_t x, int16_t y, int16_t z);
static void log_event(int magnitude);
static void led_on(void);
static void led_off(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor init ------------------------------- */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(i2c_handle, REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "Error: cannot read CTRL1 (sensor absent or bus error)\n");
        return -1;
    }

    /* Clear power-down bit to wake the sensor */
    if (i2cWriteByteData(i2c_handle, REG_CTRL1, ctrl1 & ~CTRL1_PD_BIT) < 0) {
        fprintf(stderr, "Error: cannot write CTRL1 (power-up failed)\n");
        return -1;
    }

    /* Allow sensor to settle after wake-up */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* ------------------------- Read acceleration block ------------------------ */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        int n = i2cReadI2CBlockData(i2c_handle, REG_X_AXIS_L, buf, 6);
        if (n == 6) {
            *x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
            *y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
            *z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);
            return 0;
        }
        fprintf(stderr, "Warning: I2C block read returned %d (attempt %d/%d)\n",
                n, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(10000); /* 10 ms backoff */
    }

    fprintf(stderr, "Error: failed to read acceleration after %d retries\n",
            MAX_RETRIES);
    return -1;
}

/* ------------------------- Vibration magnitude ---------------------------- */
static int calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    double dx = (double)x;
    double dy = (double)y;
    double dz = (double)z;
    return (int)lround(sqrt(dx * dx + dy * dy + dz * dz));
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(int magnitude)
{
    time_t     now;
    struct tm  tm_info;
    char       ts[32];

    time(&now);
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(log_file, "%s  Vibration magnitude: %d\n", ts, magnitude);
    fflush(log_file);
}

/* ------------------------------- LED helpers ------------------------------ */
static void led_on(void)
{
    gpioWrite(LED_GPIO, 1);
}

static void led_off(void)
{
    gpioWrite(LED_GPIO, 0);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error: cannot open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    led_off();

    /* Initialize I2C and sensor */
    if (init_i2c() != 0 || init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started.  Threshold=%d  LED=GPIO%d  Log=%s\n",
           VIBRATION_THRESHOLD, LED_GPIO, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            int mag = calculate_magnitude(x, y, z);

            if (mag > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %d\n", mag);
                log_event(mag);
                led_on();
                gpioDelay(1000000); /* 1 s LED on */
                led_off();
            }
        } else {
            fprintf(stderr, "Warning: read failed, retrying next cycle\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

