static void led_off(void)
{
    gpioWrite(LED_GPIO, 0);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error: cannot open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    led_off();

    /* Initialize I2C and sensor */
    if (init_i2c() != 0 || init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started.  Threshold=%d  LED=GPIO%d  Log=%s\n",
           VIBRATION_THRESHOLD, LED_GPIO, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            int mag = calculate_magnitude(x, y, z);

            if (mag > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %d\n", mag);
                log_event(mag);
                led_on();
                gpioDelay(1000000); /* 1 s LED on */
                led_off();
            }
        } else {
            fprintf(stderr, "Warning: read failed, retrying next cycle\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

