/*
 * flame_monitor.c — Raspberry Pi 3 Model B+ flame sensor monitor
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27
 * (physical pins 3, 5, 7, 11, 13).  Each sensor's digital output is
 * wired to its GPIO and VCC/GND to 3.3 V and GND.  A flame is
 * represented by a LOW reading (0).
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_FILE         "/var/log/flame_events.log"
#define GPIO_CHIP_NAME   "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const int sensor_ids[NUM_SENSORS]            = {1, 2, 3, 4, 5};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, unsigned int pin, int flame)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose: %s", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame sensor monitoring started");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Monitoring %d sensors on GPIO %u, %u, %u, %u, %u",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "Initial read of GPIO %u: %s",
                   sensor_pins[i], strerror(errno));
            prev[i] = 1;   /* assume no flame until proven otherwise */
        } else {
            prev[i] = v;
        }
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                syslog(LOG_ERR, "Read error on GPIO %u: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: 0 -> 1 */
            if (prev[i] == 0 && v == 1) {
                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);
                int dv = gpiod_line_get_value(lines[i]);
                if (dv < 0) {
                    syslog(LOG_ERR, "Debounce read error on GPIO %u: %s",
                           sensor_pins[i], strerror(errno));
                    prev[i] = v;
                    continue;
                }
                if (dv == 1) {
                    log_event(sensor_ids[i], sensor_pins[i], 1);
                }
            }
            prev[i] = v;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down");

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

