#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS 0x04
#define VEML7700_CONFIG_VALUE 0x0000  /* gain=1/8, IT=100ms, no shutdown */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_write_config(int handle, uint16_t value) {
    char buf[3];
    buf[0] = VEML7700_REG_CONFIG;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 config register\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *raw) {
    char reg = VEML7700_REG_ALS;
    char data[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set ALS register pointer\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ALS data\n");
        return -1;
    }
    *raw = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static float calculate_lux(uint16_t raw) {
    return (float)raw * 0.0576f;
}

static int calculate_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
            timestamp, lux, brightness, error_code);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X\n",
                I2C_BUS, VEML7700_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (veml7700_write_config(i2c_handle, VEML7700_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Error: Failed to configure VEML7700 sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Adaptive Grow Light System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw;
        if (veml7700_read_als(i2c_handle, &raw) != 0) {
            fprintf(stderr, "Error: Failed to read ALS data\n");
            log_data(log_file, -1.0f, -1, -1);
            gpioDelay(1000000);
            continue;
        }

        float lux = calculate_lux(raw);
        int brightness = calculate_brightness(lux);

        if (gpioPWM(LED_GPIO, brightness) != 0) {
            fprintf(stderr, "Error: Failed to set LED PWM\n");
            log_data(log_file, lux, brightness, -1);
        } else {
            log_data(log_file, lux, brightness, 0);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

