#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR        0x44
#define OPT3001_REG_RESULT  0x00
#define OPT3001_REG_CONFIG  0x01
#define OPT3001_CONFIG_WORD 0xC810  /* RN=1100, CT=000, M=100, FC=00, L=0, OVF=0, CR=0, ME=0, FC=0, L=0, POL=0, M=100, CT=000, RN=1100 */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_DELAY_US       100000   /* 100 ms for first conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Swap bytes: pigpio i2cWordData returns/sends little-endian,         */
/* OPT3001 expects/reports big-endian (MSB first).                    */
/* ------------------------------------------------------------------ */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit big-endian value to an OPT3001 register.             */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    uint16_t swapped = swap16(value);
    int rc = i2cWriteWordData(handle, reg, swapped);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %d\n",
                reg, swapped, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from an OPT3001 register.            */
/* Returns 0 on success and stores value in *out; -1 on failure.       */
/* ------------------------------------------------------------------ */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = swap16((uint16_t)rc);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure OPT3001 for continuous conversion mode.                   */
/* ------------------------------------------------------------------ */
static int opt3001_configure(int handle)
{
    return opt3001_write_reg(handle, OPT3001_REG_CONFIG, OPT3001_CONFIG_WORD);
}

/* ------------------------------------------------------------------ */
/* Read lux from the OPT3001 result register.                          */
/* Returns 0 on success and stores lux in *lux_out; -1 on failure.     */
/* ------------------------------------------------------------------ */
static int opt3001_read_lux(int handle, float *lux_out)
{
    uint16_t raw;
    if (opt3001_read_reg(handle, OPT3001_REG_RESULT, &raw) != 0)
        return -1;

    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1 << exponent);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to the log file.                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_lux(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at OPT3001 address --- */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (opt3001_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Allow first conversion to complete --- */
    gpioDelay(CONV_DELAY_US);

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 greenhouse monitor started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float lux;
        if (opt3001_read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "Failed to read lux value; skipping sample\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (log_lux(lux) != 0)
                fprintf(stderr, "Warning: failed to log lux value\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(SAMPLE_INTERVAL_US / 10);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

