        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

