#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define FLOW_CMD_MSB 0x36
#define FLOW_CMD_LSB 0x08
#define FLOW_SCALE 90.0f
#define FLOW_MIN 0.0f
#define FLOW_MAX 100.0f
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEAS_DELAY_US 2000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int start_continuous_measurement(void) {
    char cmd[2] = {FLOW_CMD_MSB, FLOW_CMD_LSB};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error sending start-measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    char buf[3];
    int bytes = i2cReadDevice(i2c_handle, buf, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error reading flow data (got %d bytes): %s\n",
                bytes, bytes < 0 ? strerror(errno) : "short read");
        return -1;
    }
    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

static void log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_continuous_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            if (flow_rate >= FLOW_MIN && flow_rate <= FLOW_MAX) {
                log_data(flow_rate, "OK");
            } else {
                log_data(flow_rate, "INVALID");
            }
        } else {
            fprintf(stderr, "I2C read error, attempting recovery...\n");
            if (init_i2c() != 0 || start_continuous_measurement() != 0) {
                fprintf(stderr, "Recovery failed, terminating.\n");
                break;
            }
            log_data(0.0f, "ERROR");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

