            fprintf(stderr, "Error reading event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            time_t rawtime = time(NULL);
            if (rawtime == (time_t)-1) {
                fprintf(stderr, "Error getting time: %s\n", strerror(errno));
                continue;
            }
            struct tm *timeinfo = localtime(&rawtime);
            if (!timeinfo) {
                fprintf(stderr, "Error converting time: %s\n", strerror(errno));
                continue;
            }
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
                fprintf(stderr, "Error formatting timestamp\n");
                continue;
            }

            printf("[ALERT] Flame detected at: %s\n", timestamp);
            log_flame_event(timestamp);
        }
    }

    printf("\nExiting gracefully...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

