 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 digital-output flame sensor (active-low)
 *   -> GPIO17 (physical pin 11) : flame input
 *   -> GPIO18 (physical pin 12) : buzzer control (active-high)
 *
 * Build  : gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run    : ./flame_alert
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_PIN    17
