    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "<unknown-time>");
    }

    fprintf(g_log, "%s: %s\n", ts, msg);
    fflush(g_log);
}

