#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Touch detected\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int ret;
    int last_state = 0;
    int led_state = 0;
    uint32_t last_touch_tick = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n", TOUCH_SENSOR_PIN, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", LED_PIN, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise LED state: %s\n", pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Failed to read initial GPIO%d state: %s\n", TOUCH_SENSOR_PIN, pigpio_error(last_state));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO%d: %s\n", TOUCH_SENSOR_PIN, pigpio_error(current_state));
            break;
        }

        if (current_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_touch_tick > (uint32_t)(DEBOUNCE_MS * 1000)) {
                led_state = !led_state;
                ret = gpioWrite(LED_PIN, led_state);
                if (ret != 0) {
                    fprintf(stderr, "Failed to write GPIO%d: %s\n", LED_PIN, pigpio_error(ret));
                    break;
                }

                if (log_touch_event() != 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                }

                last_touch_tick = now;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

