#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define SI1182_PART_ID_REG 0x00
#define SI1182_HW_REV_REG 0x01
#define SI1182_LED_CURRENT_REG 0x0F
#define SI1182_AVG_REG 0x03
#define SI1182_ENABLE_REG 0x02
#define SI1182_HR_REG 0x2A
#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01
#define MIN_BPM 30
#define MAX_BPM 220
#define MOVING_AVG_SIZE 5
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int verify_sensor(void) {
    int part_id = i2cReadByteData(i2c_handle, SI1182_PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Sensor absent or wrong device.\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    int hw_rev = i2cReadByteData(i2c_handle, SI1182_HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X).\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, SI1182_LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing LED_CURRENT_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1182_AVG_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing AVG_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1182_ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing ENABLE_REG\n");
        return -1;
    }
    return 0;
}

static int read_heart_rate(int *raw_out) {
    int raw = i2cReadWordData(i2c_handle, SI1182_HR_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading HR_REG: %d\n", raw);
        return -1;
    }
    *raw_out = raw;
    return 0;
}

static int moving_average(int *buffer, int size, int new_value) {
    static int index = 0;
    static int sum = 0;
    sum -= buffer[index];
    sum += new_value;
    buffer[index] = new_value;
    index = (index + 1) % size;
    return sum / size;
}

static int validate_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

static int log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(log_file, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() != 0) {
        cleanup();
        return 1;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int raw_buffer[MOVING_AVG_SIZE] = {0};
    int valid_readings = 0;

    while (!terminate) {
        int raw = 0;
        if (read_heart_rate(&raw) == 0) {
            int bpm = (int)(raw * 0.5f);
            int filtered = moving_average(raw_buffer, MOVING_AVG_SIZE, bpm);
            if (validate_bpm(filtered)) {
                if (log_data(filtered) != 0) {
                    fprintf(stderr, "Logging failed, continuing...\n");
                }
                valid_readings++;
            } else {
                fprintf(stderr, "Invalid BPM: %d\n", filtered);
            }
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("Total valid readings: %d\n", valid_readings);
    cleanup();
    return 0;
}

