/*
 * TTP226 8-channel capacitive touch sensor counter on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT1 -> GPIO 5
 *   TTP226 OUT2 -> GPIO 6
 *   TTP226 OUT3 -> GPIO 7
 *   TTP226 OUT4 -> GPIO 8
 *   TTP226 OUT5 -> GPIO 9
 *   TTP226 OUT6 -> GPIO 10
 *   TTP226 OUT7 -> GPIO 11
 *   TTP226 OUT8 -> GPIO 12
 *   Counter bit 0 -> GPIO 17
 *   Counter bit 1 -> GPIO 18
 *   ...
 *   Counter bit 7 -> GPIO 24
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define STABILIZE_DELAY_US 200000 /* 200 ms */
#define LOG_FILE "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_touch_event(int channel, int counter)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
    }
}

static void display_counter(struct gpiod_line_request *out_req, int counter)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = (counter >> i) & 1;
        if (gpiod_line_request_set_value(out_req, output_pins[i], val) < 0) {
            fprintf(stderr, "Warning: set_value(GPIO %u, %d) failed: %s\n",
                    output_pins[i], val, strerror(errno));
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *out_req = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Pi Zero W). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Request sensor input lines --- */
    struct gpiod_line_config *sensor_cfg = gpiod_line_config_new();
    if (sensor_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct gpiod_line_settings *sensor_settings = gpiod_line_settings_new();
    if (sensor_settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(sensor_settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(sensor_settings, GPIOD_LINE_BIAS_PULL_UP);

    if (gpiod_line_config_add_line_settings(sensor_cfg, sensor_pins, NUM_CHANNELS, sensor_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n", strerror(errno));
        goto cleanup;
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, sensor_cfg);
    if (sensor_req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines(sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request output lines --- */
    struct gpiod_line_config *out_cfg = gpiod_line_config_new();
    if (out_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct gpiod_line_settings *out_settings = gpiod_line_settings_new();
    if (out_settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(out_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(out_settings, GPIOD_LINE_VALUE_INACTIVE);

    if (gpiod_line_config_add_line_settings(out_cfg, output_pins, NUM_CHANNELS, out_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings(output) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    out_req = gpiod_chip_request_lines(chip, NULL, out_cfg);
    if (out_req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines(output) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Stabilization delay so the pull-ups settle and the module is ready. */
    usleep(STABILIZE_DELAY_US);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor counter running. Press Ctrl+C to exit.\n");

    int counter = 0;
    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev_state[i] = 0;

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            enum gpiod_line_value val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val == GPIOD_LINE_VALUE_ERROR) {
                fprintf(stderr, "Error reading sensor GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising-edge detection: inactive-to-active (0 -> 1) without double-counting. */
            if (val == GPIOD_LINE_VALUE_ACTIVE && prev_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                display_counter(out_req, counter);
                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev_state[i] = (val == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;
        }
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all output pins to 0 before releasing. */
    if (out_req != NULL) {
        for (int i = 0; i < NUM_CHANNELS; i++)
            gpiod_line_request_set_value(out_req, output_pins[i], GPIOD_LINE_VALUE_INACTIVE);
        gpiod_line_request_release(out_req);
    }
    if (sensor_req != NULL)
        gpiod_line_request_release(sensor_req);
    if (out_cfg != NULL)
        gpiod_line_config_free(out_cfg);
    if (sensor_cfg != NULL)
        gpiod_line_config_free(sensor_cfg);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

