#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, int s1, int s2, int s3, int s4) {
    char ts[32];
    if (get_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d,%d\n", ts, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4];
    int pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    const char *consumer = "ky033-tracking";
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_input(lines[i], consumer) != 0) {
            fprintf(stderr, "Error: failed to request GPIO line %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error: failed to write header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Error: failed to flush header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    while (program_running) {
        int s1 = gpiod_line_get_value(lines[0]);
        int s2 = gpiod_line_get_value(lines[1]);
        int s3 = gpiod_line_get_value(lines[2]);
        int s4 = gpiod_line_get_value(lines[3]);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Warning: GPIO read error (s1=%d s2=%d s3=%d s4=%d): %s\n",
                    s1, s2, s3, s4, strerror(errno));
        }

        if (log_data(fp, s1, s2, s3, s4) != 0) {
            fprintf(stderr, "Error: logging failed, continuing...\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
