cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    for (int i = 0; i < 4; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
