#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_tilt_event(int sensor_number) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_17, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_18, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line17, "tilt-sensor-17",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with pull-up: %s\n",
                GPIO_PIN_17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line18, "tilt-sensor-18",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with pull-up: %s\n",
                GPIO_PIN_18, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring tilt sensors on GPIO17 and GPIO18. Press Ctrl+C to exit.\n");

    int prev17 = 1;
    int prev18 = 1;
    struct timespec last_event_time17 = {0, 0};
    struct timespec last_event_time18 = {0, 0};

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        if (val17 < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN_17, strerror(errno));
            break;
        }

        int val18 = gpiod_line_get_value(line18);
        if (val18 < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN_18, strerror(errno));
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (val17 == 0 && prev17 == 1) {
            long diff17 = (now.tv_sec - last_event_time17.tv_sec) * 1000L +
                          (now.tv_nsec - last_event_time17.tv_nsec) / 1000000L;
            if (diff17 >= DEBOUNCE_MS) {
                if (log_tilt_event(1) == 0) {
                    printf("Sensor 1 tilted\n");
                }
                last_event_time17 = now;
            }
        }

        if (val18 == 0 && prev18 == 1) {
            long diff18 = (now.tv_sec - last_event_time18.tv_sec) * 1000L +
                          (now.tv_nsec - last_event_time18.tv_nsec) / 1000000L;
            if (diff18 >= DEBOUNCE_MS) {
                if (log_tilt_event(2) == 0) {
                    printf("Sensor 2 tilted\n");
                }
                last_event_time18 = now;
            }
        }

        prev17 = val17;
        prev18 = val18;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

