#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_data(FILE *fp, int s1, int s2, int led) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor1 = NULL;
    struct gpiod_line *sensor2 = NULL;
    struct gpiod_line *led = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (sensor1 == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (sensor2 == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (led == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor1, "obstacle_sensor1") != 0) {
        fprintf(stderr, "Failed to request sensor1 as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(sensor2, "obstacle_sensor2") != 0) {
        fprintf(stderr, "Failed to request sensor2 as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "obstacle_led", 0) != 0) {
        fprintf(stderr, "Failed to request LED as output: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1_val = gpiod_line_get_value(sensor1);
        if (s1_val < 0) {
            fprintf(stderr, "Failed to read sensor1: %s\n", strerror(errno));
            break;
        }
        int s2_val = gpiod_line_get_value(sensor2);
        if (s2_val < 0) {
            fprintf(stderr, "Failed to read sensor2: %s\n", strerror(errno));
            break;
        }

        int led_state = (s1_val == 0 && s2_val == 0) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) != 0) {
            fprintf(stderr, "Failed to set LED: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, s1_val, s2_val, led_state) != 0) {
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led != NULL) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (sensor1 != NULL) {
        gpiod_line_release(sensor1);
    }
    if (sensor2 != NULL) {
        gpiod_line_release(sensor2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    printf("Program finished.\n");
    return ret;
}

