#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125  /* 8 kHz polling */
#define LED_ON_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

static void trigger_led(void)
{
    if (gpioWrite(LED_GPIO, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn LED on.\n");
        return;
    }
    gpioDelay(LED_ON_MS * 1000);
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn LED off.\n");
    }
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld\n", buf, ts.tv_nsec / 1000000L);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Microphone peak detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int mic_value = gpioRead(MIC_GPIO);
        if (mic_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", MIC_GPIO);
            break;
        }

        if (mic_value == 1) {
            print_timestamp();
            trigger_led();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup_gpio();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

