#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25
#define READ_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 sensor reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n", I2C_BUS, SI1175_ADDR);

    while (running) {
        uint8_t lsb = 0, msb = 0;

        if (i2c_read_reg8(fd, ALS_VIS_LSB_REG, &lsb) < 0) {
            fprintf(stderr, "Error reading ALS_VIS_LSB: %s\n", strerror(errno));
            goto cleanup;
        }

        if (i2c_read_reg8(fd, ALS_VIS_MSB_REG, &msb) < 0) {
            fprintf(stderr, "Error reading ALS_VIS_MSB: %s\n", strerror(errno));
            goto cleanup;
        }

        uint16_t als_value = ((uint16_t)msb << 8) | lsb;
        printf("ALS Visible: %u\n", als_value);

        usleep(READ_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting.\n");
    return ret;
}

