#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ_HZ  1000
#define PWM_RANGE    255
#define FADE_STEPS   50
#define FADE_DELAY_US 500000  /* 500 ms per step */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Common-anode: invert duty-cycle = 255 - value */
static int pwm_write(int pin, int value)
{
    if (value < 0) value = 0;
    if (value > PWM_RANGE) value = PWM_RANGE;
    int inverted = PWM_RANGE - value;
    if (gpioPWM(pin, inverted) < 0) {
        syslog(LOG_ERR, "gpioPWM(pin=%d, val=%d) failed", pin, inverted);
        return -1;
    }
    return 0;
}

static int set_all_off(void)
{
    if (pwm_write(RED_PIN, 0) < 0) return -1;
    if (pwm_write(GREEN_PIN, 0) < 0) return -1;
    if (pwm_write(BLUE_PIN, 0) < 0) return -1;
    return 0;
}

/* HSV -> RGB (0-255) */
static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    float c = v * s;
    float x = c * (1.0f - fabsf(fmodf(h / 60.0f, 2.0f) - 1.0f));
    float m = v - c;
    float rf, gf, bf;

    if (h < 60.0f) { rf = c; gf = x; bf = 0.0f; }
    else if (h < 120.0f) { rf = x; gf = c; bf = 0.0f; }
    else if (h < 180.0f) { rf = 0.0f; gf = c; bf = x; }
    else if (h < 240.0f) { rf = 0.0f; gf = x; bf = c; }
    else if (h < 300.0f) { rf = x; gf = 0.0f; bf = c; }
    else               { rf = c; gf = 0.0f; bf = x; }

    *r = (int)((rf + m) * 255.0f + 0.5f);
    *g = (int)((gf + m) * 255.0f + 0.5f);
    *b = (int)((bf + m) * 255.0f + 0.5f);
}

static int fade_to_hue(float target_hue)
{
    float current_hue;
    int r, g, b;

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        float t = (float)i / (float)(FADE_STEPS - 1);
        current_hue = target_hue + t * 360.0f;
        if (current_hue >= 360.0f) current_hue -= 360.0f;

        hsv_to_rgb(current_hue, 1.0f, 1.0f, &r, &g, &b);

        if (pwm_write(RED_PIN, r) < 0) return -1;
        if (pwm_write(GREEN_PIN, g) < 0) return -1;
        if (pwm_write(BLUE_PIN, b) < 0) return -1;

        usleep(FADE_DELAY_US);
    }
    return 0;
}

int main(void)
{
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RED_PIN=%d) failed", RED_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(GREEN_PIN=%d) failed", GREEN_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(BLUE_PIN=%d) failed", BLUE_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(RED_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(GREEN_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(BLUE_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(RED_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(GREEN_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(BLUE_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (set_all_off() < 0) {
        syslog(LOG_ERR, "Failed to set all pins off during init");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    FILE *urandom = fopen("/dev/urandom", "r");
    if (!urandom) {
        syslog(LOG_ERR, "Cannot open /dev/urandom");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read random seed from /dev/urandom");
        fclose(urandom);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    fclose(urandom);

    srand(seed);

    syslog(LOG_INFO, "Mood lamp started (seed=0x%08x)", seed);

    while (g_running) {
        float target_hue = (float)rand() / (float)RAND_MAX * 360.0f;
        syslog(LOG_INFO, "Fading to hue %.2f", target_hue);
        if (fade_to_hue(target_hue) < 0) {
            syslog(LOG_ERR, "Fade failed; aborting");
            break;
        }
        if (!g_running) break;
        sleep(5);
    }

    syslog(LOG_INFO, "Shutting down");
    set_all_off();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

