        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RED_PIN=%d) failed", RED_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(GREEN_PIN=%d) failed", GREEN_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(BLUE_PIN=%d) failed", BLUE_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(RED_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(GREEN_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(BLUE_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(RED_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(GREEN_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(BLUE_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (set_all_off() < 0) {
        syslog(LOG_ERR, "Failed to set all pins off during init");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    FILE *urandom = fopen("/dev/urandom", "r");
    if (!urandom) {
        syslog(LOG_ERR, "Cannot open /dev/urandom");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read random seed from /dev/urandom");
        fclose(urandom);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    fclose(urandom);

    srand(seed);

    syslog(LOG_INFO, "Mood lamp started (seed=0x%08x)", seed);

    while (g_running) {
        float target_hue = (float)rand() / (float)RAND_MAX * 360.0f;
        syslog(LOG_INFO, "Fading to hue %.2f", target_hue);
        if (fade_to_hue(target_hue) < 0) {
            syslog(LOG_ERR, "Fade failed; aborting");
            break;
        }
        if (!g_running) break;
        sleep(5);
    }

    syslog(LOG_INFO, "Shutting down");
    set_all_off();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

