#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A

#define LED_GPIO_LINE   17
#define RED_THRESHOLD   200
#define POLL_MS         200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%02X, expected 0x44\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

static void tcs34725_power_down(int fd) {
    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        tcs34725_power_down(i2c_fd);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        tcs34725_power_down(i2c_fd);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        tcs34725_power_down(i2c_fd);
        close(i2c_fd);
        return 1;
    }

    while (g_running) {
        uint16_t c, r, g, b;
        if (tcs34725_read(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read failed, re-initializing sensor...\n");
            tcs34725_power_down(i2c_fd);
            usleep(10000);
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
            continue;
        }

        int red_cal = (int)r - 20;
        if (red_cal < 0) red_cal = 0;

        if (gpiod_line_set_value(led, red_cal > RED_THRESHOLD ? 1 : 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        }

        printf("C: %5u  R: %5u  G: %5u  B: %5u  R_cal: %5d  LED: %s\n",
               c, r, g, b, red_cal, red_cal > RED_THRESHOLD ? "ON" : "OFF");

        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    tcs34725_power_down(i2c_fd);
    close(i2c_fd);
    return 0;
}

