#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define PWM_FREQ 800000
#define PWM_RANGE 255
#define I2C_BUS 1
#define SAMPLE_DELAY_US 100000
#define MAX_LUX 1000.0
#define MAX_BRIGHTNESS 255

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    gpioPWM(LED_PIN, brightness);
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CONT_HIGH_RES;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write BH1750 command.\n");
        return -1;
    }
    usleep(180000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data.\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static float map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    float norm = lux / MAX_LUX;
    if (norm > 1.0f) norm = 1.0f;
    float log_norm = log10f(1.0f + norm * 9.0f);
    float mapped = (log_norm / log10f(11.0f)) * MAX_BRIGHTNESS;
    if (mapped < 0.0f) mapped = 0.0f;
    if (mapped > MAX_BRIGHTNESS) mapped = MAX_BRIGHTNESS;
    return mapped;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, PWM_FREQ);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", BH1750_ADDR);
        gpioTerminate();
        return 1;
    }

    float lux = 0.0f;
    int consecutive_errors = 0;

    while (running) {
        if (read_bh1750(i2c_handle, &lux) != 0) {
            consecutive_errors++;
            if (consecutive_errors > 5) {
                fprintf(stderr, "Error: Too many consecutive I2C failures. Exiting.\n");
                break;
            }
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        consecutive_errors = 0;

        float brightness = map_lux_to_brightness(lux);
        set_led_brightness((int)brightness);

        usleep(SAMPLE_DELAY_US);
    }

    set_led_brightness(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

