#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_TIME_MS 120
#define NUM_LEDS 10
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_DELAY_US 0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CMD_OT_HRES) < 0) {
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void apa102_set_brightness(int spi_fd, uint8_t brightness) {
    uint8_t tx[4 + NUM_LEDS * 4 + 4];
    size_t idx = 0;

    memset(tx, 0x00, sizeof(tx));

    // Start frame: 0xE0 | brightness
    tx[idx++] = 0xE0 | (brightness & 0x1F);
    // Blue, Green, Red
    for (int i = 0; i < NUM_LEDS; i++) {
        tx[idx++] = 0xFF;
        tx[idx++] = 0xFF;
        tx[idx++] = 0xFF;
    }
    // End frame: 0xFF
    for (int i = 0; i < 4; i++) {
        tx[idx++] = 0xFF;
    }

    uint8_t rx[sizeof(tx)];
    if (spi_transfer(spi_fd, tx, rx, sizeof(tx)) < 0) {
        fprintf(stderr, "Failed to send APA102 frame\n");
    }
}

