    int i2c_fd = -1, spi_fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open /dev/spidev0.0: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting light-to-LED mapping. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(100000);
            continue;
        }

        if (lux < 10.0f) lux = 10.0f;
        if (lux > 300.0f) lux = 300.0f;

        float norm = (lux - 10.0f) / 290.0f;
        uint8_t brightness = (uint8_t)(norm * 31.0f);

        apa102_set_brightness(spi_fd, brightness);

        printf("Lux: %.2f, Brightness: %u\n", lux, brightness);
        usleep(100000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        apa102_set_brightness(spi_fd, 0);
        close(spi_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

