#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_TIME_US 180000
#define FADE_STEPS 50
#define FADE_DELAY_US 50000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HRES2) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command to BH1750 (handle %d)\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_US);
    return 0;
}

static int read_bh1750(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from BH1750 (handle %d)\n", handle);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void set_apa102_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led_data[4];
    for (int i = 0; i < 4; i++) {
        led_data[i] = (uint8_t)((brightness << 2) | (brightness >> 5));
    }
    uint8_t *frames[2] = {start_frame, led_data};
    for (int i = 0; i < 2; i++) {
        if (spiWrite(spi_handle, (char *)frames[i], 4) != 4) {
            fprintf(stderr, "Error: SPI write failed\n");
            return;
        }
    }
}

static void fade_to_brightness(int target) {
    int current = set_apa102_brightness(0);
    if (current < 0) return;
    if (target == current) return;
    int step = (target - current) / FADE_STEPS;
    if (step == 0) step = 1;
    for (int i = 0; i < FADE_STEPS; i++) {
        current += step;
        if (current < 0) current = 0;
        if (current > 31) current = 31;
        set_apa102_brightness(current);
        gpioDelay(FADE_DELAY_US / FADE_STEPS);
    }
    set_apa102_brightness(target);
}

static void cleanup(void) {
    set_apa102_brightness(0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }

    i2c_handles[0] = i2cOpen(1, BH1750_ADDR_LOW, 0);
    if (i2c_handles[0] >= 0) {
        if (init_bh1750(i2c_handles[0]) != 0) {
            fprintf(stderr, "Warning: Could not initialize BH1750 at 0x23\n");
            i2cClose(i2c_handles[0]);
            i2c_handles[0] = -1;
        }
    } else {
        fprintf(stderr, "Warning: Could not open I2C device at 0x23\n");
    }

    i2c_handles[1] = i2cOpen(1, BH1750_ADDR_HIGH, 0);
    if (i2c_handles[1] >= 0) {
        if (init_bh1750(i2c_handles[1]) != 0) {
            fprintf(stderr, "Warning: Could not initialize BH1750 at 0x5C\n");
            i2cClose(i2c_handles[1]);
            i2c_handles[1] = -1;
        }
    } else {
        fprintf(stderr, "Warning: Could not open I2C device at 0x5C\n");
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int valid_sensors = 0;
        int total_lux = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                int lux = read_bh1750(i2c_handles[i]);
                if (lux >= 0) {
                    total_lux += lux;
                    valid_sensors++;
                } else {
                    fprintf(stderr, "Warning: Sensor %d read error, skipping\n", i);
                }
            }
        }

        int target_brightness = 0;
        if (valid_sensors > 0) {
            int avg_lux = total_lux / valid_sensors;
            target_brightness = (int)((float)avg_lux / 1000.0 * 31.0);
            if (target_brightness > 31) target_brightness = 31;
        }

        fade_to_brightness(target_brightness);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

