#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_ALS_REG 0x04
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_CONFIG_VALUE 0x0000
#define NUM_LEDS 10
#define MAX_LUX 120000.0
#define MAX_BRIGHTNESS 255
#define GAMMA 2.2
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int init_i2c(void);
int init_veml7700(void);
int read_veml7700(uint16_t *als);
float calculate_lux(uint16_t raw_als);
int calculate_brightness(float lux);
int init_gpio(void);
void set_led_brightness(int brightness);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

// Initialize I2C bus
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Initialize VEML7700 sensor
int init_veml7700(void) {
    uint8_t config_buf[3];
    config_buf[0] = VEML7700_CONFIG_REG;
    config_buf[1] = (VEML7700_CONFIG_VALUE >> 8) & 0xFF;
    config_buf[2] = VEML7700_CONFIG_VALUE & 0xFF;

    if (write(i2c_fd, config_buf, 3) != 3) {
        fprintf(stderr, "Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait 10 ms for configuration to take effect
    return 0;
}

// Read ambient light sensor data with retries
int read_veml7700(uint16_t *als) {
    uint8_t reg = VEML7700_ALS_REG;
    uint8_t buf[2];
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write error (reg select): %s\n", strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        *als = (buf[0] << 8) | buf[1];
        return 0;
    }
    fprintf(stderr, "Failed to read VEML7700 after %d retries\n", I2C_RETRIES);
    return -1;
}

// Calculate lux from raw ALS value
float calculate_lux(uint16_t raw_als) {
    // VEML7700 default: integration time 100 ms, gain 1/8
    // lux = raw * 0.0288 (1/gain * 100ms/integration_time)
    return (float)raw_als * 0.0288f;
}

// Calculate brightness from lux using gamma correction
int calculate_brightness(float lux) {
    float normalized = lux / MAX_LUX;
    if (normalized > 1.0f) normalized = 1.0f;
    if (normalized < 0.0f) normalized = 0.0f;
    float brightness = powf(normalized, 1.0f / GAMMA) * MAX_BRIGHTNESS;
    return (int)brightness;
}

// Initialize GPIO using libgpiod
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, 18);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line 18: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "veml7700_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line 18 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

// Set LED brightness using bit-banging (800 kHz, 12-bit resolution)
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

    // Calculate number of high and low cycles for given brightness
    // For 800 kHz, 12-bit resolution: 1 cycle = 12.5 ns
    // We'll use a simple threshold-based approach: if brightness > 127, turn on, else off
    // For full resolution, use a lookup table or bit-banging
    // For simplicity, we'll use a simple threshold: brightness > 127 -> on
    int on_cycles = brightness > 127 ? brightness : 0;
    int off_cycles = brightness > 127 ? 0 : 255 - brightness;

    // Simple bit-banging: toggle pin high and low for given cycles
    // For simplicity, we'll use a simple loop with usleep
    // In production, use hardware PWM or precise bit-banging
    // For now, we'll use a simple threshold-based approach
    // For full resolution, use a lookup table or bit-banging
    // For simplicity, we'll use a simple threshold: brightness > 127 -> on
    int on_time_us = 125; // 12.5 ns per cycle
    int off_time_us = 125;

    // Turn off all LEDs initially (safe state)
    gpiod_line_set_value(led_line, 0);
    usleep(1000); // 1 ms settle

    // Turn on LEDs if brightness > 127
    if (brightness > 127) {
        for (int i = 0; i < on_cycles; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(on_time_us);
            gpiod_line_set_value(led_line, 0);
            usleep(off_time_us);
        }
    }
    // Turn off LEDs if brightness <= 127
    else {
        for (int i = 0; i < off_cycles; i++) {
            gpiod_line_set_value(led_line, 0);
            usleep(off_time_us);
            gpiod_line_set_value(led_line, 1);
            usleep(on_time_us);
        }
    }
}

// Cleanup resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    printf("VEML7700 LED Controller started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        uint16_t raw_als;
        if (read_veml7700(&raw_als) == 0) {
            float lux = calculate_lux(raw_als);
            int brightness = calculate_brightness(lux);
            set_led_brightness(brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read sensor data. Continuing...\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

