#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define POLL_INTERVAL_US 50000
#define SELF_TEST_READINGS 5
#define SELF_TEST_READ_DELAY_US 100000
#define SELF_TEST_RETRIES 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void self_test_failure(struct gpiod_line *buzzer, struct gpiod_line *led) {
    log_event("Self-test failed: sensor fault detected.");

    /* Blink LED rapidly: 100 ms on, 100 ms off, 5 cycles */
    for (int i = 0; i < 5 && program_running; i++) {
        if (gpiod_line_set_value(led, 1) < 0) {
            log_event("Error: failed to set LED on during self-test.");
            break;
        }
        usleep(100000);
        if (!program_running) break;
        if (gpiod_line_set_value(led, 0) < 0) {
            log_event("Error: failed to set LED off during self-test.");
            break;
        }
        usleep(100000);
    }

    /* Short-short-long-short buzzer pattern: 200 ms, 200 ms, 600 ms, 200 ms */
    for (int rep = 0; rep < SELF_TEST_RETRIES && program_running; rep++) {
        if (gpiod_line_set_value(buzzer, 1) < 0) {
            log_event("Error: failed to set buzzer on during self-test.");
            break;
        }
        usleep(200000);
        if (!program_running) break;
        if (gpiod_line_set_value(buzzer, 0) < 0) {
            log_event("Error: failed to set buzzer off during self-test.");
            break;
        }
        usleep(200000);
        if (!program_running) break;
        if (gpiod_line_set_value(buzzer, 1) < 0) {
            log_event("Error: failed to set buzzer on during self-test.");
            break;
        }
        usleep(600000);
        if (!program_running) break;
        if (gpiod_line_set_value(buzzer, 0) < 0) {
            log_event("Error: failed to set buzzer off during self-test.");
            break;
        }
        usleep(200000);
    }

    /* Ensure outputs are off on exit */
    gpiod_line_set_value(buzzer, 0);
    gpiod_line_set_value(led, 0);
}

static int run_self_test(struct gpiod_line *flame, struct gpiod_line *buzzer, struct gpiod_line *led) {
    log_event("Running self-test...");

    /* Blink LED twice: 500 ms on, 500 ms off */
    if (gpiod_line_set_value(led, 1) < 0) {
        log_event("Error: failed to set LED on during self-test.");
        return -1;
    }
    usleep(500000);
    if (!program_running) return -1;
    if (gpiod_line_set_value(led, 0) < 0) {
        log_event("Error: failed to set LED off during self-test.");
        return -1;
    }
    usleep(500000);
    if (!program_running) return -1;

    /* Read flame sensor 5 times at 100 ms intervals */
    int flame_detected = 1;
    for (int i = 0; i < SELF_TEST_READINGS; i++) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            log_event("Error: failed to read flame sensor during self-test.");
            return -1;
        }
        if (val != 0) { /* KY-026 is active-low: 0 = flame detected */
            flame_detected = 0;
            break;
        }
        usleep(SELF_TEST_READ_DELAY_US);
    }

    if (flame_detected) {
        log_event("Self-test passed: flame sensor working normally.");
        return 0;
    }

    log_event("Self-test failed: flame sensor fault detected.");
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL, *buzzer = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    /* Open GPIO chip 0 (Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error: failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines */
    flame = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame || !buzzer || !led) {
        fprintf(stderr, "Error: failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines with consumer label */
    if (gpiod_line_request_input(flame, "flame-sensor") < 0) {
        fprintf(stderr, "Error: failed to request flame sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        fprintf(stderr, "Error: failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "led", 0) < 0) {
        fprintf(stderr, "Error: failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Run self-test */
    if (run_self_test(flame, buzzer, led) < 0) {
        self_test_failure(buzzer, led);
        goto cleanup;
    }

    log_event("Flame sensor monitoring started.");

    /* Main polling loop */
    while (program_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            log_event("Error: failed to read flame sensor.");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val == 0) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                log_event("Error: failed to activate buzzer.");
            }
            if (gpiod_line_set_value(led, 1) < 0) {
                log_event("Error: failed to activate LED.");
            }

            /* Wait until flame is no longer detected (HIGH) */
            while (program_running) {
                int new_val = gpiod_line_get_value(flame);
                if (new_val < 0) {
                    log_event("Error: failed to read flame sensor during detection.");
                    break;
                }
                if (new_val == 1) {
                    log_event("Flame gone.");
                    break;
                }
                usleep(POLL_INTERVAL_US);
            }

            if (gpiod_line_set_value(buzzer, 0) < 0) {
