#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MAX_LUX 1000.0f
#define MIN_LUX 0.0f
#define MIN_RATE 0.5f
#define MAX_RATE 5.0f
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        perror("I2C read failed");
        return -1;
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int gpio_export(int pin) {
    char path[64];
    char buf[16];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        perror("Failed to export GPIO");
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to set GPIO direction");
        return -1;
    }
    if (write(fd, "out", 3) != 3) {
        perror("Failed to set GPIO direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        perror("Failed to unexport GPIO");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int pin, int value) {
    char path[64];
    char buf[2];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write GPIO value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_byte(i2c_fd, BH1750_CONT_HIGH_RES) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        uint16_t raw;
        if (i2c_read_word(i2c_fd, &raw) < 0) {
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float lux = (float)raw / 1.2f;

        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) buffer_count++;

        float sum = 0.0f;
        for (int i = 0; i < buffer_count; i++) sum += lux_buffer[i];
        float avg_lux = sum / (float)buffer_count;

        float rate = MIN_RATE + (avg_lux - MIN_LUX) * (MAX_RATE - MIN_RATE) / (MAX_LUX - MIN_LUX);
        if (rate < MIN_RATE) rate = MIN_RATE;
        if (rate > MAX_RATE) rate = MAX_RATE;

        static int led_state = 0;
        led_state = !led_state;
        gpio_write(GPIO_PIN, led_state);

        usleep((useconds_t)(1000000.0f / rate));
    }

    gpio_write(GPIO_PIN, 0);
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);
    return 0;
}

