#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define CHIP_NAME "gpiochip0"

/* Segment patterns for digit 5 (common cathode, active high)
 * Order: a,b,c,d,e,f,g,dp (dp unused)
 * 5: 1,1,1,0,1,1,0,0  -> 0b11101100
 */
static const unsigned char digit5[8] = {0x11, 0x11, 0x11, 0x00, 0x11, 0x11, 0x00, 0x00};

static void shift_out(struct gpiod_line *data, struct gpiod_line *clock,
                       struct gpiod_line *latch, const unsigned char *data_byte)
{
    for (int i = 7; i >= 0; i--) {
        int bit = (data_byte[i] & 0x80) ? 1 : 0;
        if (gpiod_line_set_value(data, bit) < 0) {
            perror("Failed to set data line value");
            return;
        }
        if (gpiod_line_set_value(clock, 1) < 0) {
            perror("Failed to set clock high");
            return;
        }
        if (gpiod_line_set_value(clock, 0) < 0) {
            perror("Failed to set clock low");
            return;
        }
        data_byte[i] = (unsigned char)(data_byte[i] << 1);
    }
    if (gpiod_line_set_value(latch, 1) < 0) {
        perror("Failed to set latch high");
        return;
    }
    if (gpiod_line_set_value(latch, 0) < 0) {
        perror("Failed to set latch low");
        return;
    }
}

int main(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    struct gpiod_line *data_line = gpiod_chip_get_line(chip, DATA_PIN);
    struct gpiod_line *clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    struct gpiod_line *latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0) {
        perror("Failed to request data line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(clock_line, "seven-seg", 0) < 0) {
        perror("Failed to request clock line as output");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        perror("Failed to request latch line as output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Seven-segment display showing digit 5 (blinking every 500 ms)\n");
    printf("Press Ctrl+C to exit.\n");

    while (1) {
        shift_out(data_line, clock_line, latch_line, digit5);
        usleep(500000);
        if (gpiod_line_set_value(latch_line, 1) < 0) {
            perror("Failed to set latch high (off)");
            break;
        }
        usleep(500000);
    }

    /* Cleanup: turn off display and release lines */
    gpiod_line_set_value(latch_line, 1);
    gpiod_line_set_value(data_line, 0);
    gpiod_line_set_value(clock_line, 0);
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

