#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define CONSUMER "blink_button"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Set up signal handler for graceful exit */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request button line as input with pull-up and falling-edge events */
    ret = gpiod_line_request_falling_edge_events_flags(button_line, CONSUMER,
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on BCM GPIO%d with button on BCM GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    /* Main loop: blink LED while waiting for button press */
    while (running) {
        /* Turn LED on */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (on)");
            break;
        }
        sleep(1);

        /* Turn LED off */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (off)");
            break;
        }
        sleep(1);

        /* Check for button press with 1-second timeout */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){1, 0});
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        } else if (ret > 0) {
            /* Read the event to clear it */
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("gpiod_line_event_read");
                break;
            }
            printf("Button pressed! Exiting.\n");
            break;
        }
        /* ret == 0 means timeout, loop again */
    }

    /* Cleanup: turn off LED and release lines */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

