#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 0.75

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install SIGINT handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure GPIO5 as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED starts in the OFF state */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main blink loop */
    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LED_PIN);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(DELAY_MS);

        if (!running) {
            break;
        }

        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LED_PIN);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(DELAY_MS);
    }

    /* Clean shutdown: turn off LED and release pigpio resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

