#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define LED_PIN    24
#define BUTTON_PIN 22
#define CHIP_NAME  "gpiochip0"
#define BLINK_MS   500

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line %d: %s\n", BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "led-blink", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(button_line, "button-read",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to request button line as input with pull-down: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("LED blink program running. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(button_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read button: %s\n", strerror(errno));
            break;
        }

        if (val == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to set LED on: %s\n", strerror(errno));
                break;
            }
            usleep(BLINK_MS * 1000);
            if (!running) break;
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
                break;
            }
            usleep(BLINK_MS * 1000);
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
                break;
            }
            while (running) {
                val = gpiod_line_get_value(button_line);
                if (val < 0) {
                    fprintf(stderr, "Failed to read button: %s\n", strerror(errno));
                    goto cleanup;
                }
                if (val == 1) break;
                usleep(10000);
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) gpiod_line_release(led_line);
    if (button_line) gpiod_line_release(button_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

