#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM303_ACCEL_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0f
#define IMPACT_PULSE_US 50000
#define POLL_DELAY_US 100000
#define ACCEL_SCALE 16384.0f

static int i2c_handle = -1;
static float impact_threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lsm303(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4_A\n");
        return -1;
    }
    return 0;
}

static int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

static float calculate_g(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / ACCEL_SCALE;
    float y_g = (float)y / ACCEL_SCALE;
    float z_g = (float)z / ACCEL_SCALE;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

static void log_impact(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", s, x, y, z);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G\n", impact_threshold);

    while (!terminate) {
        int16_t x, y, z;
        if (read_accel(&x, &y, &z) == 0) {
            float g = calculate_g(x, y, z);
            if (g > impact_threshold) {
                printf("Impact detected! G-force: %.2f\n", g);
                gpioWrite(GPIO_PIN, 1);
                gpioDelay(IMPACT_PULSE_US);
                gpioWrite(GPIO_PIN, 0);
                log_impact(x, y, z);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

