#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_RED_MSB 0x67
#define REG_GREEN_LSB 0x68
#define REG_GREEN_MSB 0x69
#define REG_BLUE_LSB 0x6A
#define REG_BLUE_MSB 0x6B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) for 0x%02X failed\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int read_als(uint16_t *als) {
    uint8_t lsb, msb;
    if (i2c_read_reg(REG_ALS_LSB, &lsb) != 0) return -1;
    if (i2c_read_reg(REG_ALS_MSB, &msb) != 0) return -1;
    *als = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_rgb(uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t lsb_r, msb_r, lsb_g, msb_g, lsb_b, msb_b;
    if (i2c_read_reg(REG_RED_LSB, &lsb_r) != 0) return -1;
    if (i2c_read_reg(REG_RED_MSB, &msb_r) != 0) return -1;
    if (i2c_read_reg(REG_GREEN_LSB, &lsb_g) != 0) return -1;
    if (i2c_read_reg(REG_GREEN_MSB, &msb_g) != 0) return -1;
    if (i2c_read_reg(REG_BLUE_LSB, &lsb_b) != 0) return -1;
    if (i2c_read_reg(REG_BLUE_MSB, &msb_b) != 0) return -1;
    *r = ((uint16_t)msb_r << 8) | lsb_r;
    *g = ((uint16_t)msb_g << 8) | lsb_g;
    *b = ((uint16_t)msb_b << 8) | lsb_b;
    return 0;
}

static int set_led_brightness(uint16_t als) {
    int duty = (int)(als * 255 / 65535);
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    if (gpioPWM(LED_GPIO, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int log_data(uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, r, g, b) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_reg(REG_MODE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to initialize ADPD188BI\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open color_log.csv\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,R,G,B\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        uint16_t als, r, g, b;
        if (read_als(&als) == 0 && read_rgb(&r, &g, &b) == 0) {
            if (set_led_brightness(als) == 0 && log_data(als, r, g, b) == 0) {
                printf("ALS: %u, R: %u, G: %u, B: %u\n", als, r, g, b);
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

