#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_REG_STATUS       0x00
#define FXOS8700_REG_OUT_X_MSB    0x01
#define FXOS8700_REG_WHO_AM_I     0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1    0x2A

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_VAL     0xC7

/* Impact threshold: 2g in m/s^2 (sensitivity 4096 counts/g, ±2g range) */
#define IMPACT_THRESHOLD_MPS2    19.62f

/* Sensitivity for ±2g range: 4096 counts/g */
#define SENSITIVITY_4096_PER_G   4096.0f

/* Acceleration full-scale range: ±2g */
#define ACCEL_RANGE_2G           2.0f

/* Acceleration conversion factor: g/count * 9.81 m/s^2/g */
#define ACCEL_CONV_G_TO_MPS2     (ACCEL_RANGE_2G * 9.81f / SENSITIVITY_4096_PER_G)

/* Sample period in microseconds (50 ms) */
#define SAMPLE_PERIOD_US        50000

/* Global I2C handle */
static int i2c_handle = -1;

/* Graceful shutdown flag */
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for SIGINT / SIGTERM                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an I2C register                             */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an I2C register                              */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z, X, Y, Z)                */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: expected 6 bytes, got %d\n", result);
        return -1;
    }

    /* Data is 14-bit left-justified in 16-bit words */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Convert to g and m/s^2 */
    *x = (float)raw_x * ACCEL_CONV_G_TO_MPS2;
    *y = (float)raw_y * ACCEL_CONV_G_TO_MPS2;
    *z = (float)raw_z * ACCEL_CONV_G_TO_MPS2;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log impact data to file                                            */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    } else {
        fprintf(fp, "UNKNOWN,%.3f,%.3f,%.3f,%.3f\n", x, y, z, magnitude);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Check if an impact has occurred                                     */
/* ------------------------------------------------------------------ */
static int check_impact(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    return (magnitude > IMPACT_THRESHOLD_MPS2) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                FXOS8700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint8_t who_am_i = 0;
    if (read_register(i2c_handle, FXOS8700_REG_WHO_AM_I, &who_am_i) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Put sensor in standby (clear CTRL_REG1 bit 0) */
    if (write_register(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure XYZ_DATA_CFG: ±2g range (0x00) */
    if (write_register(i2c_handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Activate sensor: set CTRL_REG1 bit 0 (active mode, 200 Hz ODR) */
    if (write_register(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after activation */
    gpioDelay(50000); /* 50 ms */

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700CQ impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (check_impact(x, y, z)) {
                log_impact(x, y, z, sqrtf(x * x + y * y + z * z));
                printf("Impact detected! x=%.3f y=%.3f z=%.3f m/s^2\n", x, y, z);
            }
        }
        /* On read error, just continue rather than crash */

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

