#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDR        0x53
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATAX0      0x32
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_BW_RATE     0x2C
#define ADXL345_DATARATE    0x2C
#define ADXL345_FULL_RES    0x08
#define ADXL345_RANGE_2G    0x00
#define ADXL345_ACTIVE      0x02
#define LED_GPIO            17
#define SAMPLE_PERIOD_US    100000  /* 100 ms */
#define THRESHOLD_G         2.0f
#define LOG_FILE            "accel_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int adxl345_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
    return rc;
}

static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_read_block(int handle, uint8_t reg, uint8_t *buf, int len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, got %d, want %d): %s\n",
                reg, rc, len, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }
    return 0;
}

static int adxl345_init(int handle)
{
    uint8_t devid = 0;
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 DEVID mismatch: got 0x%02X, expected 0xE5\n", devid);
        return -1;
    }

    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x00) < 0)   /* standby */
        return -1;
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT,
                          ADXL345_FULL_RES | ADXL345_RANGE_2G) < 0)
        return -1;
    if (adxl345_write_reg(handle, ADXL345_BW_RATE, 0x0A) < 0)      /* 100 Hz */
        return -1;
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, ADXL345_ACTIVE) < 0)
        return -1;

    return 0;
}

static int read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (adxl345_read_block(handle, ADXL345_DATAX0, raw, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* ±2g range: 3.9 mg/LSB -> divide by 1000 for g */
    *x = (float)rx / 1000.0f;
    *y = (float)ry / 1000.0f;
    *z = (float)rz / 1000.0f;
    return 0;
}

static void log_sample(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            log_sample(g_log_file, x, y, z);
            if (fabsf(x) > THRESHOLD_G || fabsf(y) > THRESHOLD_G || fabsf(z) > THRESHOLD_G)
                gpioWrite(LED_GPIO, 1);
            else
                gpioWrite(LED_GPIO, 0);
        } else {
            fprintf(stderr, "Read error — sample skipped\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

