#define REG_IDENTIFICATION_MODEL_ID 0x000
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSRANGE_START 0x018
#define REG_RESULT_RANGE_STATUS 0x04d
#define REG_RESULT_RANGE_VAL 0x062

#define EXPECTED_MODEL_ID 0xB4

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int vl6180x_write_reg(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl6180x_read_reg(uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write (addr) to reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl6180x_init(void) {
    uint8_t model_id = 0;
    if (vl6180x_read_reg(REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Cannot read model ID - sensor may be absent\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X)\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    uint8_t fresh_out = 0;
    if (vl6180x_read_reg(REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh_out) != 0) return -1;
