#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_ENABLE 0x80
#define SAMPLE_INTERVAL_US 10000
#define MAX_RETRIES 3

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_ENABLE) != 0) {
        fprintf(stderr, "Error: Failed to enable sensor on handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *data) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed on handle %d (result=%d)\n", handle, result);
        return -1;
    }
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static void log_data(FILE *fp, struct timespec ts, int16_t d1, int16_t d2, double tdoa) {
    fprintf(fp, "%ld,%ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, d1, d2, tdoa);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C for sensor 1 (addr 0x%02X)\n", SENSOR1_ADDR);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C for sensor 2 (addr 0x%02X)\n", SENSOR2_ADDR);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) != 0 || init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    struct timespec ts;
    int16_t d1, d2;
    int rc1, rc2;

    while (!terminate) {
        rc1 = read_sensor_data(i2c_handle1, &d1);
        rc2 = read_sensor_data(i2c_handle2, &d2);

        if (rc1 == 0 && rc2 == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            double tdoa = (double)(d1 - d2);
            log_data(log_file, ts, d1, d2, tdoa);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

