#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0b11000000000  /* mode 3, aux off, 16-bit words */

#define REG_X_GYRO  0x04
#define REG_Y_GYRO  0x06
#define REG_Z_GYRO  0x08
#define REG_X_ACCEL 0x0A
#define REG_Y_ACCEL 0x0C
#define REG_Z_ACCEL 0x0E

#define GYRO_SCALE  0.005f
#define ACCEL_SCALE 0.00025f

#define SAMPLE_PERIOD_US 100000
#define STALL_US         40

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ADIS16488A read protocol: send 16-bit word with MSB=0, then 7-bit reg addr.
 * Data is returned on the next transfer.
 */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    tx[0] = (reg << 1) & 0x7F;  /* MSB=0, 7-bit address */

    if (spiXfer(spi_handle, tx, rx, 4) < 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Stall between request and data-retrieval transfer */
    gpioDelay(STALL_US);

    /* Data is returned in rx[2..3] (little-endian) */
    *out = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[3]);
    return 0;
}

static int log_data(float gx, float gy, float gz,
                    float ax, float ay, float az) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, gx, gy, gz, ax, ay, az) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    atexit(cleanup);

    while (running) {
        int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;
        int err = 0;

        if (read_register(REG_X_GYRO, &raw_gx) != 0) err = 1;
        if (read_register(REG_Y_GYRO, &raw_gy) != 0) err = 1;
        if (read_register(REG_Z_GYRO, &raw_gz) != 0) err = 1;
        if (read_register(REG_X_ACCEL, &raw_ax) != 0) err = 1;
        if (read_register(REG_Y_ACCEL, &raw_ay) != 0) err = 1;
        if (read_register(REG_Z_ACCEL, &raw_az) != 0) err = 1;

        if (err) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gx = (float)raw_gx * GYRO_SCALE;
        float gy = (float)raw_gy * GYRO_SCALE;
        float gz = (float)raw_gz * GYRO_SCALE;
        float ax = (float)raw_ax * ACCEL_SCALE;
        float ay = (float)raw_ay * ACCEL_SCALE;
        float az = (float)raw_az * ACCEL_SCALE;

        if (log_data(gx, gy, gz, ax, ay, az) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    return EXIT_SUCCESS;
}

