#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Map */
#define ADIS16448_REG_X_GYRO_OUT  0x04
#define ADIS16448_REG_Y_GYRO_OUT  0x06
#define ADIS16448_REG_Z_GYRO_OUT  0x08
#define ADIS16448_REG_X_ACCL_OUT  0x0A
#define ADIS16448_REG_Y_ACCL_OUT  0x0C
#define ADIS16448_REG_Z_ACCL_OUT  0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Scaling factors */
#define GYRO_SCALE  0.05f    /* deg/sec per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

/* Global variables for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16448.
 * ADIS16448 SPI read requires a two-cycle transfer:
 *   1. Send 16-bit command (register address | 0x8000) in the first 16-bit transfer.
 *   2. Send 0x0000 in the second 16-bit transfer to clock out the data.
 * Returns the 16-bit register value, or -1 on error.
 */
static int16_t read_register(uint16_t reg) {
    char tx_buf[4];
    char rx_buf[4];
    int result;

    /* First transfer: send read command */
    tx_buf[0] = (reg >> 8) & 0xFF;
    tx_buf[1] = reg & 0xFF;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI write transfer failed for register 0x%04X (result=%d)\n", reg, result);
        return -1;
    }

    /* Stall time between transfers (datasheet: t_stall >= 40 us) */
    gpioDelay(40);

    /* Second transfer: dummy read to clock out data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read transfer failed for register 0x%04X (result=%d)\n", reg, result);
        return -1;
    }

    /* Data is returned in the second byte of the response */
    return (int16_t)(((uint16_t)(uint8_t)rx_buf[2] << 8) | (uint8_t)rx_buf[3]);
}

/* Read a signed 16-bit value from a register */
static int16_t read_signed_register(uint16_t reg) {
    int16_t raw = read_register(reg);
    if (raw < 0) {
        return -1;
    }
    return (int16_t)raw;
}

/* Read gyroscope data */
static int read_gyro(float *x, float *y, float *z) {
    int16_t raw_x = read_signed_register(ADIS16448_REG_X_GYRO_OUT);
    int16_t raw_y = read_signed_register(ADIS16448_REG_Y_GYRO_OUT);
    int16_t raw_z = read_signed_register(ADIS16448_REG_Z_GYRO_OUT);

    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (float)raw_x * GYRO_SCALE;
    *y = (float)raw_y * GYRO_SCALE;
    *z = (float)raw_z * GYRO_SCALE;
    return 0;
}

/* Read accelerometer data */
static int read_accel(float *x, float *y, float *z) {
    int16_t raw_x = read_signed_register(ADIS16448_REG_X_ACCL_OUT);
    int16_t raw_y = read_signed_register(ADIS16448_REG_Y_ACCL_OUT);
    int16_t raw_z = read_signed_register(ADIS16448_REG_Z_ACCL_OUT);

    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (float)raw_x * ACCL_SCALE;
    *y = (float)raw_y * ACCL_SCALE;
    *z = (float)raw_z * ACCL_SCALE;
    return 0;
}

int main(void) {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("ADIS16448 IMU Reader\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (!terminate) {
        if (read_gyro(&gyro_x, &gyro_y, &gyro_z) == 0 &&
            read_accel(&accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | "
                   "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

