    float accel_x, accel_y, accel_z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("ADIS16448 IMU Reader\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (!terminate) {
        if (read_gyro(&gyro_x, &gyro_y, &gyro_z) == 0 &&
            read_accel(&accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | "
                   "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

