#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_D345_ID 0xE5

#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define SCALE_FACTOR 256.0f
#define POLL_DELAY_US 10000
#define LED_ON_DELAY_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    int id = i2cReadByteData(handle, ADXL345_DEVID);
    if (id < 0) {
        fprintf(stderr, "Error reading DEVID: %d\n", id);
        return -1;
    }
    if (id != ADXL345_D345_ID) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n", id, ADXL345_D345_ID);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x00) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float magnitude, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Impact: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            timestamp, magnitude, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z, magnitude;
    while (!terminate) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
                log_impact(magnitude, x, y, z);
                gpioDelay(LED_ON_DELAY_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

