#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I       0x75
#define PWR_MGMT_1     0x6B
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43
#define ACCEL_CONFIG   0x1C
#define GYRO_CONFIG    0x1B

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to initialize the ICM-20602 */
static int init_imu(void) {
    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != ICM20602_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, ICM20602_WHO_AM_I);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */

    /* Set accelerometer range to +-2g (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG\n");
        return -1;
    }

    /* Set gyroscope range to +-250 dps (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
static int read_accelerometer(int16_t *ax, int16_t *ay, int16_t *az) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
