#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVICE "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define LOG_FILE "freefall_log.csv"

#define ADXL345_DEVID 0x00
#define ADXL345_BW_RATE 0x2C
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATAX0 0x32
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct gpiod_line_event event;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x04) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int adxl345_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);
    fprintf(log_fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(ADXL345_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", ADXL345_DEVICE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        i2c_write_reg8(i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    fprintf(log_fp, "timestamp,x,y,z\n");
    fflush(log_fp);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "GPIO event read error: %s\n", strerror(errno));
            continue;
        }
        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        uint8_t int_source;
        if (i2c_read_reg8(i2c_fd, ADXL345_INT_SOURCE, &int_source) < 0) continue;
        if (!(int_source & 0x04)) continue;

        int16_t x, y, z;
        if (adxl345_read_xyz(i2c_fd, &x, &y, &z) < 0) continue;
        log_data(x, y, z);
    }

    printf("\nShutting down...\n");
    i2c_write_reg8(i2c_fd, ADXL345_POWER_CTL, 0x00);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

