#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x69
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 4.375f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FREEFALL_WINDOW_SEC 1.0
#define IMPACT_WINDOW_SEC 1.0

#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, WHO_AM_I, &who_am_i, 1) != 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(handle, CTRL1_XL, 0x60) != 0) return -1;
    if (i2c_write_reg(handle, CTRL2_G, 0x60) != 0) return -1;
    return 0;
}

static int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_reg(handle, OUTX_L_G, buf, 6) != 0) return -1;
    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);
    if (i2c_read_reg(handle, OUTX_L_XL, buf, 6) != 0) return -1;
    int16_t ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t az = (int16_t)((buf[5] << 8) | buf[4]);
    data->gyro_x = gx * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_y = gy * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_z = gz * GYRO_SENSITIVITY / 1000.0f;
    data->accel_x = ax * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_y = ay * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_z = az * ACCEL_SENSITIVITY / 1000.0f;
    return 0;
}

static void log_data(FILE *fp, const sensor_data_t *data) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", ts,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(fp);
}

static void detect_fall(const sensor_data_t *data) {
    static enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    static time_t freefall_start = 0, impact_start = 0;
    float mag = sqrtf(data->accel_x * data->accel_x + data->accel_y * data->accel_y + data->accel_z * data->accel_z);
    time_t now = time(NULL);
    switch (state) {
        case IDLE:
            if (mag < FREEFALL_THRESHOLD) {
                freefall_start = now;
                state = FREEFALL;
            }
            break;
        case FREEFALL:
            if (mag > IMPACT_THRESHOLD) {
                impact_start = now;
                state = IMPACT;
            } else if (difftime(now, freefall_start) > FREEFALL_WINDOW_SEC) {
                state = IDLE;
            }
            break;
        case IMPACT:
            if (mag > FREEFALL_THRESHOLD) {
                freefall_start = now;
                state = FREEFALL;
            } else if (difftime(now, impact_start) > IMPACT_WINDOW_SEC) {
                state = IDLE;
            }
            break;
    }
    printf("State: %s\n", state == FREEFALL ? "FREEFALL" : state == IMPACT ? "IMPACT" : "IDLE");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_lsm6dsr(i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sensor_data_t data;
    while (running) {
        if (read_sensor_data(i2c_handle, &data) == 0) {
            log_data(log_file, &data);
            detect_fall(&data);
        } else {
            fprintf(stderr, "Read error, continuing\n");
        }
        gpioDelay(100000);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

