#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16266 register addresses */
#define ADIS16266_REG_WHO_AM_I   0x00
#define ADIS16266_REG_X_GYRO_OUT 0x14
#define ADIS16266_REG_Y_GYRO_OUT 0x16
#define ADIS16266_REG_Z_GYRO_OUT 0x18

#define ADIS16266_WHO_AM_I_VAL   0x3F5A

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* Gyroscope scale factor (degrees/sec per LSB) */
#define GYRO_SCALE 0.0305f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266                          */
/* ------------------------------------------------------------------ */
static int adis16266_read_register(int handle, uint8_t reg, int16_t *value)
{
    char tx[2];
    char rx[2];

    /* ADIS16266 register read: send address with bit 7 set */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* The response is returned in the next transaction */
    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X response\n", reg);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADIS16266                                          */
/* ------------------------------------------------------------------ */
static int adis16266_init(int handle)
{
    int16_t who_am_i = 0;

    if (adis16266_read_register(handle, ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if ((uint16_t)who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                (uint16_t)who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 initialized (WHO_AM_I = 0x%04X)\n", (uint16_t)who_am_i);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a gyroscope reading to CSV                                      */
/* ------------------------------------------------------------------ */
static int log_gyro_data(FILE *fp, float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x_raw, y_raw, z_raw;
    float x_rate, y_rate, z_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADIS16266 */
    if (adis16266_init(spi_handle) != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once with CSV header */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,x_rate_dps,y_rate_dps,z_rate_dps\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (!terminate) {
        if (adis16266_read_register(spi_handle, ADIS16266_REG_X_GYRO_OUT, &x_raw) != 0) {
            fprintf(stderr, "Error reading X_GYRO_OUT\n");
            break;
        }
        if (adis16266_read_register(spi_handle, ADIS16266_REG_Y_GYRO_OUT, &y_raw) != 0) {
            fprintf(stderr, "Error reading Y_GYRO_OUT\n");
            break;
        }
        if (adis16266_read_register(spi_handle, ADIS16266_REG_Z_GYRO_OUT, &z_raw) != 0) {
            fprintf(stderr, "Error reading Z_GYRO_OUT\n");
            break;
        }

        x_rate = (float)x_raw * GYRO_SCALE;
        y_rate = (float)y_raw * GYRO_SCALE;
        z_rate = (float)z_raw * GYRO_SCALE;

        if (log_gyro_data(log_file, x_rate, y_rate, z_rate) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

