#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected WHO_AM_I value for L3G4200D */
#define WHO_AM_I_EXPECTED 0xD3

/* Sensitivity: 8.75 mdps/LSB = 1/114.285 dps/LSB */
#define SENSITIVITY 114.285f

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Retry count for I2C writes */
#define I2C_WRITE_RETRIES 3

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to an I2C register with retries */
static int i2c_write_byte_retry(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_WRITE_RETRIES; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; /* Success */
        }
        fprintf(stderr, "I2C write attempt %d failed (reg 0x%02X, val 0x%02X): %d\n",
                attempt + 1, reg, value, result);
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1; /* All retries exhausted */
}

/* Read a byte from an I2C register */
static int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, result);
    }
    return result;
}

/* Read multiple bytes starting at a register */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (result != (int)len) {
        fprintf(stderr, "I2C block read error (reg 0x%02X, expected %u, got %d)\n",
                reg, len, result);
        return -1;
    }
    return 0;
}

/* Initialize the L3G4200D gyroscope */
static int gyro_init(int handle) {
    /* Verify device identity */
    int who_am_i = i2c_read_byte(handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* CTRL_REG1: Normal mode, all axes enabled, 100 Hz ODR (0x0F) */
    if (i2c_write_byte_retry(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: +-250 dps full-scale range, little-endian (0x00) */
    if (i2c_write_byte_retry(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read X, Y, Z angular velocities in degrees per second */
static int gyro_read(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L, buf, 6) != 0) {
        return -1;
    }

    /* Combine little-endian 16-bit two's complement values */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Log a sample with nanosecond precision timestamp */
static void log_sample(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, GYRO_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (gyro_init(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x, y, z;
        if (gyro_read(i2c_handle, &x, &y, &z) == 0) {
            log_sample(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US); /* 10 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

