#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define SAMPLE_MS      100
#define LOG_FILE       "vibration_log.csv"

/* D7S-0001 acceleration registers (LSB first, then MSB) */
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single register address, then read 2 bytes back. */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_X_LSB, x) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, y) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, z) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("Monitoring D7S-0001 at 0x%02X on %s. Press Ctrl+C to stop.\n",
           D7S_ADDR, I2C_BUS);

    while (g_running) {
        int16_t x, y, z;

        if (read_sensor(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

