#define SENSITIVITY_MGA_PER_LSB 0.146f
#define OFFSET_X_MGA 0.0f
#define OFFSET_Y_MGA 0.0f
#define OFFSET_Z_MGA 0.0f
#define SCALE_X_MGA 1.0f
#define SCALE_Y_MGA 1.0f
#define SCALE_Z_MGA 1.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int lis3mdl_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x70) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) < 0) return -1;
    return 0;
}

static int lis3mdl_read_xyz(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (raw_x - OFFSET_X_MGA) * SCALE_X_MGA;
    *y = (raw_y - OFFSET_Y_MGA) * SCALE_Y_MGA;
    *z = (raw_z - OFFSET_Z_MGA) * SCALE_Z_MGA;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > MAG_THRESHOLD_MGA) {
        fprintf(stderr, "ALERT: Magnetic field magnitude %.2f mG exceeds threshold %.2f mG\n", mag, MAG_THRESHOLD_MGA);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (lis3mdl_init(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "LIS3MDL init attempt %d/3 failed, retrying...\n", attempt + 1);
        usleep(100000);
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after 3 attempts.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen magnetic_log.txt");
        close(g_i2c_fd);
        return 1;
    }

    fprintf(g_log_fp, "# LIS3MDL log started: %s\n", ctime(&(time_t){time(NULL)}));
    fflush(g_log_fp);

    while (g_running) {
        float x, y, z;
        if (lis3mdl_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Read error, attempting re-init...\n");
            if (lis3mdl_init(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
        }
        usleep(SAMPLE_PERIOD_US);
    }

    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

