#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000

#define ADXL354_REG_DEVID 0x00
#define ADXL354_REG_PARTID 0x01
#define ADXL354_REG_REVID 0x02
#define ADXL354_REG_XDATA 0x08
#define ADXL354_REG_YDATA 0x0B
#define ADXL354_REG_ZDATA 0x0E
#define ADXL354_REG_STATUS 0x04
#define ADXL354_REG_POWER_CTL 0x2D
#define ADXL354_REG_RESET 0x1F

#define ADXL354_PARTID_EXPECTED 0x1D
#define ADXL354_SENSITIVITY 0.0000039f

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} AccelData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *data, int len) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (spiXfer(spi_handle, tx, rx, 2) == 2) {
            memcpy(data, rx + 1, len);
            return 0;
        }
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (spiXfer(spi_handle, tx, rx, 2) == 2) return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int initialize_adxl354(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354_REG_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Error: SPI read failed for PARTID\n");
        return -1;
    }
    if (partid != ADXL354_PARTID_EXPECTED) {
        fprintf(stderr, "Error: Incorrect PARTID 0x%02X (expected 0x%02X)\n", partid, ADXL354_PARTID_EXPECTED);
        return -1;
    }
    printf("ADXL354 detected, PARTID = 0x%02X\n", partid);

    if (spi_write_register(ADXL354_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Error: Failed to reset ADXL354\n");
        return -1;
    }
    gpioDelay(1000);

    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (spi_read_register(ADXL354_REG_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Error: SPI read failed for STATUS\n");
            return -1;
        }
        if ((status & 0x01) == 0) break;
        gpioDelay(1000);
    }
    if ((status & 0x01) != 0) {
        fprintf(stderr, "Error: ADXL354 not stable after reset\n");
        return -1;
    }

    uint8_t power_ctl = 0;
    if (spi_read_register(ADXL354_REG_POWER_CTL, &power_ctl, 1) != 0) {
        fprintf(stderr, "Error: SPI read failed for POWER_CTL\n");
        return -1;
    }
    power_ctl &= ~0x01;
    if (spi_write_register(ADXL354_REG_POWER_CTL, power_ctl) != 0) {
        fprintf(stderr, "Error: SPI write failed for POWER_CTL\n");
        return -1;
    }
    gpioDelay(1000);

    return 0;
}

static int read_acceleration(AccelData *data) {
    uint8_t x_raw[3], y_raw[3], z_raw[3];
    int16_t x_val, y_val, z_val;

    if (spi_read_register(ADXL354_REG_XDATA, x_raw, 3) != 0) return -1;
    if (spi_read_register(ADXL354_REG_YDATA, y_raw, 3) != 0) return -1;
    if (spi_read_register(ADXL354_REG_ZDATA, z_raw, 3) != 0) return -1;

    x_val = (int16_t)((x_raw[0] << 12) | (x_raw[1] << 4) | (x_raw[2] >> 4));
    y_val = (int16_t)((y_raw[0] << 12) | (y_raw[1] << 4) | (y_raw[2] >> 4));
    z_val = (int16_t)((z_raw[0] << 12) | (z_raw[1] << 4) | (z_raw[2] >> 4));

    data->x = (float)x_val * ADXL354_SENSITIVITY;
    data->y = (float)y_val * ADXL354_SENSITIVITY;
    data->z = (float)z_val * ADXL354_SENSITIVITY;
    return 0;
}

static void log_data(const AccelData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (initialize_adxl354() != 0) {
        fprintf(stderr, "Error: ADXL354 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging vibration data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        AccelData data;
        if (read_acceleration(&data) == 0) {
            log_data(&data);
        } else {
            fprintf(stderr, "Warning: SPI read error, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

