#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* ADIS16362 Scale Factors */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCL_SCALE  0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x00    /* Mode 3: CPOL=1, CPHA=1, active-high CE */

/* Sampling */
#define SAMPLE_DELAY_US 10000 /* 10 ms = 100 Hz */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16362.
 * Protocol: send address byte (MSB=1) + dummy byte, then read 2 bytes.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    tx[0] = (char)(reg | 0x80); /* MSB = 1 for read */
    tx[1] = 0x00;               /* dummy byte */

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/*
 * Log a single data row to the CSV file.
 * Timestamp is a high-precision UNIX epoch (seconds.nanoseconds).
 */
static void log_data(double timestamp, float gx, float gy, float gz,
                     float ax, float ay, float az) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    fprintf(log_file, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, gx, gy, gz, ax, ay, az);
    fflush(log_file);
}

int main(void) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accl_x, raw_accl_y, raw_accl_z;
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
    struct timespec ts;
    double timestamp;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d): %s\n",
                spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file for appending */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
