#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    ret = gpiod_line_request_input(line, "e18-d80nk-obstacle");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("Obstacle detection system started");

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        /* E18-D80NK outputs LOW (0) when obstacle detected */
        if (value == 0) {
            log_message("Obstacle detected!");
            log_message("Self-parking sequence started");
            /* Simulate self-parking sequence */
            log_message("Moving backward...");
            sleep(2);
            log_message("Turning left...");
            sleep(1);
            log_message("Turning right...");
            sleep(1);
            log_message("Self-parking sequence completed");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean shutdown */
    log_message("Shutting down...");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_message("Obstacle detection system stopped");

    return EXIT_SUCCESS;
}

