/*
 * KY-032 IR Obstacle Avoidance Sensor Reader (libgpiod v2)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Keyes KY-032 on GPIO17 (pin 11) and GPIO27 (pin 13)
 * Logic:   Active-low: 0 = obstacle detected, 1 = clear
 * Build:   gcc -O2 -Wall -Wextra -o ky032_avoid ky032_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN_17     17
#define GPIO_PIN_27     27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] ", ts);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_bulk bulk;
    int ret;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, &(const unsigned int){GPIO_PIN_17, GPIO_PIN_27}, 2, settings);
    if (ret != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request the lines together --- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoid");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                GPIO_PIN_17, GPIO_PIN_27, strerror(errno));
        goto cleanup;
    }

    /* --- Initialize bulk for single-call bulk read --- */
    gpiod_line_bulk_init(&bulk);
    ret = gpiod_line_request_get_lines(&bulk, req);
    if (ret != 0) {
        fprintf(stderr, "gpiod_line_request_get_lines failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance running. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int vals[2];

        ret = gpiod_line_request_get_values(req, &bulk, vals);
        if (ret != 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            break;
        }

        print_timestamp();
        printf("Sensor 17: %s  Sensor 27: %s\n",
               vals[0] == 0 ? "OBSTACLE" : "CLEAR",
               vals[1] == 0 ? "OBSTACLE" : "CLEAR");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

cleanup:
    if (req != NULL)
        gpiod_line_request_release(req);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return (ret == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

