#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22
#define OUTX_L_XL    0x28

/* Expected chip ID */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities for +-2g / +-250 dps */
#define GYRO_SENSITIVITY_MDPS_PER_LSB 0.00875f  /* mdps/LSB */
#define ACCEL_SENSITIVITY_MG_PER_LSB  0.000061f /* mg/LSB  */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error burst-reading %u bytes from 0x%02X (got %d)\n",
                len, reg, rc);
        return -1;
    }
    return 0;
}

static int initialize_lsm6dsr(void)
{
    uint8_t who_am_i = 0;

    if (i2c_read_reg(WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* CTRL1_XL: ODR=104 Hz (0x40), FS=+-2g (0x00) -> 0x40 */
    if (i2c_write_reg(CTRL1_XL, 0x40) != 0)
        return -1;

    /* CTRL2_G: ODR=104 Hz (0x40), FS=+-250 dps (0x00) -> 0x40 */
    if (i2c_write_reg(CTRL2_G, 0x40) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z)
{
    uint8_t buf[12];

    /* Burst-read 12 bytes starting at OUTX_L_G:
     *   gyro X/Y/Z (6 bytes) + accel X/Y/Z (6 bytes)
     */
    if (i2c_read_burst(OUTX_L_G, buf, sizeof(buf)) != 0)
        return -1;

    /* Gyroscope data: little-endian, 16-bit two's complement */
    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);

    /* Accelerometer data: little-endian, 16-bit two's complement */
    int16_t ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t az = (int16_t)((buf[11] << 8) | buf[10]);

    *gyro_x  = (float)gx * GYRO_SENSITIVITY_MDPS_PER_LSB;
    *gyro_y  = (float)gy * GYRO_SENSITIVITY_MDPS_PER_LSB;
    *gyro_z  = (float)gz * GYRO_SENSITIVITY_MDPS_PER_LSB;
    *accel_x = (float)ax * ACCEL_SENSITIVITY_MG_PER_LSB;
    *accel_y = (float)ay * ACCEL_SENSITIVITY_MG_PER_LSB;
    *accel_z = (float)az * ACCEL_SENSITIVITY_MG_PER_LSB;

    return 0;
}

int main(void)
{
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (pigpio rc=%d)\n",
                LSM6DSR_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Reading data every 100 ms (Ctrl+C to stop)...\n");

    while (!terminate) {
        if (read_sensor_data(&gyro_x, &gyro_y, &gyro_z,
                             &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f mdps, Y=%.2f mdps, Z=%.2f mdps | "
                   "Accel: X=%.2f mg, Y=%.2f mg, Z=%.2f mg\n",
                   gyro_x, gyro_y, gyro_z,
                   accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

