#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* Expected WHO_AM_I value for FXOS8700 */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single byte from an FXOS8700 register.
 * Returns 0 on success, -1 on error.
 */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/*
 * Write a single byte to an FXOS8700 register.
 * Returns 0 on success, -1 on error.
 */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/*
 * Initialize the FXOS8700 in hybrid mode.
 * Returns 0 on success, -1 on error.
 */
static int init_fxos8700(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (read_register(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /*
     * CTRL_REG1:
     *   DR=011 (800 Hz ODR), ACTIVE=1 (begin measurement)
     */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    /*
     * CTRL_REG2:
     *   F_READ=00 (400 Hz), M_MODE=00 (hybrid), Z_MODE=00 (high res),
     *   MODE=00 (accelerometer only)
     */
    if (write_register(handle, FXOS8700_CTRL_REG2, 0x00) != 0)
        return -1;

    /*
     * M_CTRL_REG1:
     *   M_DR=011 (800 Hz ODR), M_MODE=00 (hybrid)
     */
    if (write_register(handle, FXOS8700_M_CTRL_REG1, 0x20) != 0)
        return -1;

    /*
     * M_CTRL_REG2:
     *   M_HMS=0 (high performance), M_HMR=0 (high performance)
     */
    if (write_register(handle, FXOS8700_M_CTRL_REG2, 0x20) != 0)
        return -1;

    return 0;
}

/*
 * Read 12 bytes of combined accelerometer + magnetometer data.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz)
{
    char buffer[12];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (rc != 12) {
        fprintf(stderr, "Error reading sensor data block: %d\n", rc);
        return -1;
    }

    /*
     * Accelerometer data is 14-bit left-aligned, so the 16-bit value
     * is assembled from the two 8-bit words.
     */
    *ax = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]);
    *ay = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]);
    *az = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]);

    /* Magnetometer data is 16-bit, little-endian */
    *mx = (int16_t)(((uint16_t)buffer[6] << 8) | (uint8_t)buffer[7]);
    *my = (int16_t)(((uint16_t)buffer[8] << 8) | (uint8_t)buffer[9]);
    *mz = (int16_t)(((uint16_t)buffer[10] << 8) | (uint8_t)buffer[11]);

    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1D */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 initialized. Reading data every 100 ms. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            consecutive_errors = 0;
            printf("Accel: X=%6d  Y=%6d  Z=%6d  Mag: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting.\n");
                break;
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

