#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define WINDOW_DURATION_S  5
#define PAUSE_BETWEEN_WINDOWS_S 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d.\n",
                SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the pin reads LOW when no sound is present. */
    if (gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed for GPIO%d.\n",
                SOUND_SENSOR_GPIO);
        /* Non-fatal: continue anyway. */
    }

    return 0;
}

static int validate_threshold(const char *arg)
{
    char *endptr = NULL;
    errno = 0;
    long val = strtol(arg, &endptr, 10);

    if (errno != 0 || endptr == arg || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be a non-negative integer.\n");
        return -1;
    }
    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be positive.\n");
        return -1;
    }
    return (int)val;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        printf("[timestamp error]");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        printf("[timestamp error]");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        printf("[timestamp error]");
        return;
    }
    printf("[%s] ", buf);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum number of high readings in a 5-second window\n");
        return EXIT_FAILURE;
    }

    int threshold = validate_threshold(argv[1]);
    if (threshold < 0) {
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d for %d seconds.\n",
           SOUND_SENSOR_GPIO, WINDOW_DURATION_S);
    printf("Threshold: %d high-reading(s) per window.\n", threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int high_count = 0;
        uint32_t elapsed_us = 0;

        while (program_running && elapsed_us < (uint32_t)(WINDOW_DURATION_S * 1000000)) {
            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                        SOUND_SENSOR_GPIO, level);
                break;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            elapsed_us += SAMPLE_INTERVAL_US;
        }

        print_timestamp();
        printf("High readings: %d\n", high_count);
        fflush(stdout);

        if (high_count > threshold) {
            print_timestamp();
            printf("ALERT: High-reading count %d exceeds threshold %d.\n",
                   high_count, threshold);
            fflush(stdout);
        }

        if (program_running) {
            gpioDelay(PAUSE_BETWEEN_WINDOWS_S * 1000000);
        }
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

