/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12V electromagnetic door locks via libgpiod.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define LOG_FILE    "access_log.txt"
#define CODE_MIN    100000
#define CODE_MAX    999999
#define UNLOCK_SEC  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(void)
{
    return (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static int unlock_door(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(unlock)");
        return -1;
    }
    sleep(UNLOCK_SEC);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(lock)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_A_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_B_PIN)");
        goto cleanup;
    }

    int code = generate_code();
    printf("Security code: %06d\n", code);
    fflush(stdout);

    while (g_running) {
        printf("Enter security code: ");
        fflush(stdout);

        int entered;
        if (scanf("%d", &entered) != 1) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            int c;
            while ((c = getchar()) != '\n' && c != EOF)
                ;
            continue;
        }

        if (entered == code) {
            printf("Access granted!\n");
            fflush(stdout);

            if (unlock_door(line_a) != 0)
                fprintf(stderr, "Warning: unlock_door(DOOR_A) failed\n");

            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access\n");

            code = generate_code();
            printf("New security code: %06d\n", code);
            fflush(stdout);
        } else {
            printf("Access denied!\n");
            fflush(stdout);
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line_a)
        gpiod_line_set_value(line_a, 0);
    if (line_b)
        gpiod_line_set_value(line_b, 0);
    if (line_a)
        gpiod_line_release(line_a);
    if (line_b)
        gpiod_line_release(line_b);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

