#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_MAG_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_byte(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Error writing to magnetometer CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

