#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define CONFIG_A      0x00
#define CONFIG_B      0x01
#define MODE          0x02
#define DATA_X_MSB    0x03
#define DATA_X_LSB    0x04
#define DATA_Z_MSB    0x05
#define DATA_Z_LSB    0x06
#define DATA_Y_MSB    0x07
#define DATA_Y_LSB    0x08

#define SAMPLE_WINDOW 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "Error reading block from reg 0x%02X (got %d, expected %u)\n", reg, n, len);
        return -1;
    }
    return 0;
}

static int init_hmc5883l(int handle) {
    if (write_reg(handle, CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(handle, CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(handle, MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_raw(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(handle, DATA_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void apply_offsets(int16_t *x, int16_t *y, int16_t *z,
                          const int16_t *off_x, const int16_t *off_y, const int16_t *off_z) {
    *x -= *off_x;
    *y -= *off_y;
    *z -= *off_z;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t off_x = 0, off_y = 0, off_z = 0;
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    int samples = 0;

    while (running) {
        int16_t rx, ry, rz;
        if (read_raw(i2c_handle, &rx, &ry, &rz) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        x_sum += rx; y_sum += ry; z_sum += rz;
        samples++;

        if (samples >= SAMPLE_WINDOW) {
            off_x = x_sum / samples;
            off_y = y_sum / samples;
            off_z = z_sum / samples;
            x_sum = y_sum = z_sum = 0;
            samples = 0;
        }

        apply_offsets(&rx, &ry, &rz, &off_x, &off_y, &off_z);
        printf("X: %d, Y: %d, Z: %d\n", rx, ry, rz);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

