/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * I2C bus : /dev/i2c-1   (GPIO2=SDA, GPIO3=SCL)
 * I2C addr: 0x1D (SA0 tied high)
 * INT1    : GPIO23 (BCM 23, physical pin 16)
 *
 * Build  : gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D register definitions ---- */
#define LSM303D_ADDR        0x1D
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49
#define CTRL_REG1           0x20
#define CTRL_REG4           0x23
#define CTRL_REG5           0x24
#define CTRL_REG6           0x25
#define CTRL_REG7           0x26
#define INT1_CFG            0x30
#define INT1_SRC            0x31
#define OUT_X_L_A           0x28
#define OUT_X_H_A           0x29
#define OUT_Y_L_A           0x2A
#define OUT_Y_H_A           0x2B
#define OUT_Z_L_A           0x2C
#define OUT_Z_H_A           0x2D

/* ---- Configuration ---- */
#define I2C_BUS             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip4"   /* BCM GPIO controller on Pi Zero W */
#define INT1_PIN            23            /* BCM 23 */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000         /* 10 ms */
#define THRESHOLD_MG        2000          /* 2000 mg */
#define THRESHOLD_REG_VAL   (THRESHOLD_MG / 16)
#define SENSITIVITY_MG_LSB  0.061f        /* +/- 2 g */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_line  = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buf[BUFFER_SIZE];
static int            g_head = 0;   /* next write slot */
static int            g_count = 0;  /* valid samples */

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (ioctl(fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LSM303D_ADDR, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "i2c_smbus_write_byte_data(0x%02X, 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (ioctl(fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
