#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define SERIAL_PORT_1 "/dev/serial0"
#define SERIAL_PORT_2 "/dev/serial1"
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define CODE_BUFFER_SIZE 16
#define TIMEOUT_SEC 5
#define UNLOCK_DURATION_US 2000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_serial_code(int handle, char *code, int max_len) {
    char buf[CODE_BUFFER_SIZE];
    int n = serRead(handle, buf, sizeof(buf) - 1);
    if (n < 0) {
        fprintf(stderr, "serRead error on handle %d\n", handle);
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    buf[n] = '\0';
    for (int i = 0; i < n; i++) {
        if (buf[i] < '0' || buf[i] > '9') {
            return 0;
        }
    }
    if (n < CODE_LENGTH) {
        return 0;
    }
    strncpy(code, buf, CODE_LENGTH);
    code[CODE_LENGTH] = '\0';
    return 1;
}

static int authenticate(const char *code1, const char *code2) {
    return strncmp(code1, code2, CODE_LENGTH) == 0;
}

static int set_lock_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", gpio, state);
        return -1;
    }
    return 0;
}

static int unlock_doors(void) {
    if (set_lock_state(LOCK1_GPIO, 1) != 0) return -1;
    if (set_lock_state(LOCK2_GPIO, 1) != 0) return -1;
    gpioDelay(UNLOCK_DURATION_US);
    if (set_lock_state(LOCK1_GPIO, 0) != 0) return -1;
    if (set_lock_state(LOCK2_GPIO, 0) != 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_lock_state(LOCK1_GPIO, 0) != 0 || set_lock_state(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize locks to locked state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle1 = serOpen(SERIAL_PORT_1, BAUD_RATE, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open %s: %d\n", SERIAL_PORT_1, handle1);
        set_lock_state(LOCK1_GPIO, 0);
        set_lock_state(LOCK2_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = serOpen(SERIAL_PORT_2, BAUD_RATE, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open %s: %d\n", SERIAL_PORT_2, handle2);
        serClose(handle1);
        set_lock_state(LOCK1_GPIO, 0);
        set_lock_state(LOCK2_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char code1[CODE_LENGTH + 1] = {0};
    char code2[CODE_LENGTH + 1] = {0};
    int code1_ready = 0;
    int code2_ready = 0;
    uint32_t start_tick1 = 0;
    uint32_t start_tick2 = 0;

    while (running) {
        int r1 = read_serial_code(handle1, code1, sizeof(code1));
        if (r1 == 1) {
            code1_ready = 1;
            start_tick1 = gpioTick();
        } else if (r1 < 0) {
            code1_ready = 0;
        }

        int r2 = read_serial_code(handle2, code2, sizeof(code2));
        if (r2 == 1) {
            code2_ready = 1;
            start_tick2 = gpioTick();
        } else if (r2 < 0) {
            code2_ready = 0;
        }

        if (code1_ready && (gpioTick() - start_tick1) / 1000000 > TIMEOUT_SEC) {
            code1_ready = 0;
        }
        if (code2_ready && (gpioTick() - start_tick2) / 1000000 > TIMEOUT_SEC) {
            code2_ready = 0;
        }

        if (code1_ready && code2_ready && authenticate(code1, code2)) {
            if (unlock_doors() != 0) {
                fprintf(stderr, "Failed to unlock doors\n");
            }
            code1_ready = 0;
            code2_ready = 0;
        }

        gpioDelay(100000);
    }

    set_lock_state(LOCK1_GPIO, 0);
    set_lock_state(LOCK2_GPIO, 0);
    serClose(handle1);
    serClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

