#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define GPIO_CHIP_NAME "gpiochip0"
#define STROKE_DURATION_SEC 1
#define FAILSAFE_THRESHOLD_SEC 10
#define POLL_INTERVAL_US 50000
#define MOTION_HIGH_TIMEOUT_SEC 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

static void log_warning(const char *message) {
    syslog(LOG_WARNING, "%s", message);
}

static void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("motion_door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_error("Failed to register SIGINT handler");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to register SIGTERM handler");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_error("Failed to open gpiochip0");
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line (GPIO4)");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get relay line (GPIO17)");
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "motion_sensor") < 0) {
        log_error("Failed to request PIR line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "relay_strike", 0) < 0) {
        log_error("Failed to request relay line as output");
        goto cleanup;
    }

    log_event("Motion door strike system started");

    time_t motion_start_time = 0;
    int failsafe_active = 0;

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_error("Failed to read PIR sensor value");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                log_event("Motion detected");
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, motion_start_time) > MOTION_HIGH_TIMEOUT_SEC) {
                    if (!failsafe_active) {
                        failsafe_active = 1;
                        log_warning("Potential PIR malfunction: PIR pin HIGH for >10s");
                    }
                }
            }

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_error("Failed to energize relay");
            } else {
                log_event("Relay energized (door strike)");
            }

            sleep(STROKE_DURATION_SEC);

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_error("Failed to de-energize relay");
            } else {
                log_event("Relay de-energized");
            }

            motion_start_time = 0;
            failsafe_active = 0;
        } else {
            motion_start_time = 0;
            failsafe_active = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    log_event("Shutting down motion door strike system");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

