#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ACTIVE_LOW 0
#define RELAY_ACTIVE_HIGH 1

#define RELAY_ON  0
#define RELAY_OFF 1

#define RELAY_COUNT 4
#define SEQUENCE_LENGTH 4
#define SEQUENCE_DURATION_SEC 300
#define PAUSE_DURATION_SEC 60

#define TIMER_ID 0
#define TIMER_INTERVAL_SEC 60

static const int relay_pins[RELAY_COUNT] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static volatile sig_atomic_t running = 1;
static volatile int current_relay_index = 0;
static volatile int current_action = 0; /* 0=activate, 1=deactivate, 2=pause */
static volatile int timer_active = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int pin, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s - Relay on GPIO%d set to %s", timestamp, pin, state ? "OFF" : "ON");
}

static void set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO%d to %d", pin, state);
    } else {
        log_event(pin, state);
    }
}

static void activate_relay(int index) {
    if (index < 0 || index >= RELAY_COUNT) return;
    set_relay(relay_pins[index], RELAY_ON);
    current_action = 0;
}

