#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000ULL / SAMPLE_RATE_HZ)

#define SYSFS_PATH "/sys/kernel/mpu6050_accel"

typedef struct {
    float x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_fd = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static int timer_fd = -1;
static int sysfs_fd = -1;

static void cleanup(void) {
    if (timer_fd >= 0) {
        struct itimerspec ts = {0, 0};
        timerfd_settime(timer_fd, 0, &ts, NULL);
        close(timer_fd);
        timer_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (sysfs_fd >= 0) {
        close(sysfs_fd);
        sysfs_fd = -1;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(100000);
    if (i2c_write_byte(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_accel_data(accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(i2c_fd, ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / 16384.0f;
    data->y = (float)raw_y / 16384.0f;
    data->z = (float)raw_z / 16384.0f;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, accel_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)uc;
    if (!running) return;
    accel_data_t data;
    if (read_accel_data(&data) == 0) {
        add_to_buffer(&buffer, data);
    }
}

static int setup_sysfs(void) {
    if (mkdir(SYSFS_PATH, 0755) == -1 && errno != EEXIST) {
        fprintf(stderr, "Failed to create sysfs directory: %s\n", strerror(errno));
        return -1;
    }
    char path[256];
    snprintf(path, sizeof(path), "%s/latest", SYSFS_PATH);
    sysfs_fd = open(path, O_RDWR);
    if (sysfs_fd < 0) {
        fprintf(stderr, "Failed to open sysfs file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void write_sysfs(void) {
    char data[128];
    int idx = buffer.head - 1;
    if (idx < 0) idx = BUFFER_SIZE - 1;
    snprintf(data, sizeof(data), "X: %.4f, Y: %.4f, Z: %.4f",
             buffer.data[idx].x, buffer.data[idx].y, buffer.data[idx].z);
    if (write(sysfs_fd, data, strlen(data)) < 0) {
        fprintf(stderr, "Failed to write sysfs: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_SIGINFO;
    if (sigaction(SIGRTMIN, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register timer signal: %s\n", strerror(errno));
        return 1;
    }
    struct sigaction sa_term;
    memset(&sa_term, 0, sizeof(sa_term));
    sa_term.sa_handler = signal_handler;
    sigemptyset(&sa_term.sa_mask);
    sigaction(SIGINT, &sa_term, NULL);
    sigaction(SIGTERM, &sa_term, NULL);

    if (init_mpu6050() < 0) {
        return 1;
    }

    buffer.head = 0;
    buffer.count = 0;

    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timerfd_settime(timer_fd, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to start timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (setup_sysfs() < 0) {
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE_HZ);

    while (running) {
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(timer_fd, &rfds);
        int ret = pselect(timer_fd + 1, &rfds, NULL, NULL, &ts, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "pselect error: %s\n", strerror(errno));
            break;
        }
        if (ret > 0) {
            uint64_t expirations;
            ssize_t n = read(timer_fd, &expirations, sizeof(expirations));
            if (n < 0) {
                fprintf(stderr, "Timer read error: %s\n", strerror(errno));
                break;
            }
            write_sysfs();
        }
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

