static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **lines) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (*chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(*chip, relay_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line **lines) {
    if (chip != NULL) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (lines[i] != NULL) {
                gpiod_line_set_value(lines[i], 0);
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
}

static int toggle_relay(struct gpiod_line *line, int *state) {
    *state = !(*state);
    if (gpiod_line_set_value(line, *state) < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
        return -1;
    }
    printf("Relay on GPIO %u toggled to %s\n", gpiod_line_offset(line), *state ? "ON" : "OFF");
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int relay_states[NUM_RELAYS] = {0, 0, 0, 0};
    struct timespec last_toggle_time[NUM_RELAYS];
    struct timespec current_time;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        last_toggle_time[i].tv_sec = 0;
        last_toggle_time[i].tv_nsec = 0;
    }

    if (setup_signal_handlers() != 0) {
        goto cleanup;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    if (setup_gpio(&chip, lines) != 0) {
        goto cleanup;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        for (int i = 0; i < NUM_RELAYS; i++) {
            long elapsed_sec = current_time.tv_sec - last_toggle_time[i].tv_sec;
            long elapsed_nsec = current_time.tv_nsec - last_toggle_time[i].tv_nsec;
            if (elapsed_nsec < 0) {
                elapsed_sec--;
                elapsed_nsec += 1000000000L;
            }

            if (elapsed_sec >= prime_intervals[i]) {
                if (toggle_relay(lines[i], &relay_states[i]) != 0) {
                    goto cleanup;
                }
                last_toggle_time[i] = current_time;
            }
        }

        usleep(100000); // 100ms delay to prevent busy-waiting
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup_gpio(chip, lines);
    printf("Smart Lighting System stopped.\n");
    return ret;
}

