#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Gyroscope sensitivity for +-250 dps range
#define GYRO_SENSITIVITY 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Data structure for gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(const char *device, uint8_t addr);
int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
int i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len);
int gyro_init(int fd);
int gyro_read(int fd, gyro_data_t *data);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, gyro_data_t data);
void buffer_get_latest(circular_buffer_t *buffer, gyro_data_t *data);
void check_angular_velocity_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup(void);

// Initialize I2C device
int i2c_init(const char *device, uint8_t addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read an 8-bit register from I2C
int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Write an 8-bit value to an I2C register
int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read a burst of bytes from I2C starting from a register
int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Initialize the MPU-6050 gyroscope
int gyro_init(int fd) {
    // Verify sensor identity
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }

    // Allow time for the sensor to stabilize after waking up
    usleep(100000); // 100ms

    return 0;
}

