    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, MPU6050_ADDR);
    if (i2c_fd < 0) {
