#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_TIMEOUT_MS 1000
#define READ_RETRY_MS 10
#define READ_RETRY_COUNT (READ_TIMEOUT_MS / READ_RETRY_MS)

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

static void log_error(const char *message) {
    if (!error_log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        log_error("Failed to open UART");
        return -1;
    }
    return 0;
}

static int read_co2(int *co2_value) {
    unsigned char command[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[9];
    int bytes_read = 0;
    int retries = 0;

    if (serWrite(uart_handle, (char *)command, sizeof(command)) != (int)sizeof(command)) {
        log_error("Failed to write command to UART");
        return -1;
    }

    gpioDelay(100000); /* 100 ms */

    while (bytes_read < 9 && retries < READ_RETRY_COUNT) {
        int avail = serDataAvailable(uart_handle);
        if (avail > 0) {
            int to_read = (avail < 9 - bytes_read) ? avail : (9 - bytes_read);
            int r = serRead(uart_handle, (char *)(response + bytes_read), to_read);
            if (r > 0) {
                bytes_read += r;
            } else {
                log_error("serRead returned error");
                return -1;
            }
        } else {
            gpioDelay(READ_RETRY_MS * 1000);
            retries++;
        }
    }

    if (bytes_read < 9) {
        log_error("Timeout reading from UART");
        return -1;
    }

    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 255 - checksum + 1;
    if (checksum != response[8]) {
        fprintf(stderr, "Checksum mismatch: expected 0x%02X, got 0x%02X\n", checksum, response[8]);
        log_error("Checksum mismatch in response");
        return -1;
    }

    *co2_value = (response[2] << 8) | response[3];
    return 0;
}

static int log_data(int co2_value, int error_flag) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n",
                timestamp, co2_value, error_flag) < 0) {
        log_error("Failed to write to log file");
        return -1;
    }
    fflush(log_file);

    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n",
           timestamp, co2_value, error_flag);
    fflush(stdout);
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        fprintf(stderr, "Error opening error log file %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_uart() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int co2_value = 0;
        int error_flag = read_co2(&co2_value);

        if (error_flag == 0) {
            printf("CO2: %d ppm\n", co2_value);
        } else {
            co2_value = -1;
            printf("Error reading CO2\n");
        }

        if (log_data(co2_value, error_flag) != 0) {
            log_error("Failed to log data");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

