#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN    17
#define GREEN_RELAY_PIN  27
#define BLUE_RELAY_PIN   22

#define BH1750_ADDR      0x23
#define BH1750_CONT_HRES 0x10
#define BH1750_CONV_MS   120

#define LOG_FILE         "lighting_log.txt"
#define I2C_BUS          "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t val) {
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0)
        return -1;

    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux, int r, int g, int b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Relays: R=%d G=%d B=%d\n", ts, lux, r, g, b);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *lines[3];
    int pins[3] = {RED_RELAY_PIN, GREEN_RELAY_PIN, BLUE_RELAY_PIN};
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            for (int j = 0; j < i; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", pins[i], strerror(errno));
            for (int j = 0; j <= i; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        for (int i = 0; i < 3; i++)
            gpiod_line_release(lines[i]);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        for (int i = 0; i < 3; i++)
            gpiod_line_release(lines[i]);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        for (int i = 0; i < 3; i++)
            gpiod_line_release(lines[i]);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
            sleep(1);
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (lux < 50.0f) {
            r = 1;
        } else if (lux < 150.0f) {
            g = 1;
        } else if (lux < 300.0f) {
            b = 1;
        } else {
            r = 1; g = 1; b = 1;
        }

        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], r) < 0 ||
                gpiod_line_set_value(lines[i], g) < 0 ||
                gpiod_line_set_value(lines[i], b) < 0) {
                fprintf(stderr, "Failed to set relay GPIO %d: %s\n", pins[i], strerror(errno));
            }
        }

        log_data(log_fp, lux, r, g, b);
        sleep(1);
    }

    fprintf(stderr, "\nShutting down...\n");
    for (int i = 0; i < 3; i++)
        gpiod_line_set_value(lines[i], 0);
    fclose(log_fp);
    close(i2c_fd);
    for (int i = 0; i < 3; i++)
        gpiod_line_release(lines[i]);
    gpiod_chip_close(chip);
    return 0;
}

