#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000
#define MIN_DISTANCE 50
#define MAX_DISTANCE 100
#define MIN_DISTANCE_CM 10
#define MAX_DISTANCE_CM 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_distance_to_pwm(int distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;
    return (int)(((float)(distance_cm - MIN_DISTANCE_CM) /
                  (float)(MAX_DISTANCE_CM - MIN_DISTANCE_CM)) * (float)PWM_RANGE);
}

static void motor_a_forward(int pwm) {
    gpioWrite(MOTOR_A_IN1, 1);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN2, pwm);
}

static void motor_a_backward(int pwm) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 1);
    gpioPWM(MOTOR_A_IN2, pwm);
}

static void motor_a_stop(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN2, 0);
}

static void motor_b_forward(int pwm) {
    gpioWrite(MOTOR_B_IN3, 1);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN4, pwm);
}

static void motor_b_backward(int pwm) {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 1);
    gpioPWM(MOTOR_B_IN4, pwm);
}

static void motor_b_stop(void) {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN4, 0);
}

static void control_motors(int distance_a, int distance_b) {
    int pwm_a = map_distance_to_pwm(distance_a);
    int pwm_b = map_distance_to_pwm(distance_b);

