#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_RANGE 1000

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

int read_accel_gyro(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 14) < 0) {
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

void calculate_pitch_roll(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    float x = (float)ax;
    float y = (float)ay;
    float z = (float)az;
    *pitch = atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;
    *roll = atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
}

int set_pwm_duty_cycle(int fd, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int fd_duty = open(path, O_WRONLY);
    if (fd_duty < 0) {
        return -1;
    }
    char val[32];
    snprintf(val, sizeof(val), "%d", duty_cycle);
    if (write(fd_duty, val, strlen(val)) < 0) {
        close(fd_duty);
        return -1;
    }
    close(fd_duty);
    return 0;
}

int log_data(const char *filename, float pitch, float roll, int servo_pos) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", filename);
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", s, pitch, roll, servo_pos);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s\n", I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X\n", MPU6050_ADDR);
        close(i2c_fd);
        return 1;
    }

    int retries = 0;
    while (init_mpu6050(i2c_fd) != 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Retrying MPU6050 init (%d/%d)...\n", retries + 1, MAX_RETRIES);
        usleep(100000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Could not initialize MPU6050 after %d retries\n", MAX_RETRIES);
        close(i2c_fd);
        return 1;
    }

    char pwm_path[256];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error: Could not export PWM channel\n");
        close(i2c_fd);
        return 1;
    }
    if (write(pwm_fd, "0", 1) < 0) {
        fprintf(stderr, "Error: Could not write to PWM export\n");
        close(pwm_fd);
        close(i2c_fd);
        return 1;
    }
    close(pwm_fd);

    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error: Could not set PWM period\n");
        close(i2c_fd);
        return 1;
    }
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_NS);
    if (write(pwm_fd, period_str, strlen(period_str)) < 0) {
        fprintf(stderr, "Error: Could not write to PWM period\n");
        close(pwm_fd);
        close(i2c_fd);
        return 1;
    }
    close(pwm_fd);

    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error: Could not set PWM duty cycle\n");
        close(i2c_fd);
        return 1;
    }

    int servo_pos = 500;
    set_pwm_duty_cycle(pwm_fd, servo_pos);
    usleep(100000);

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_accel_gyro(i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Error: Could not read sensor data\n");
            usleep(100000);
            continue;
        }

        float pitch, roll;
        calculate_pitch_roll(ax, ay, az, &pitch, &roll);

        if (fabs(pitch) > 20.0) {
            servo_pos = (int)((pitch + 90.0) / 180.0 * 1000.0);
            if (servo_pos < 0) servo_pos = 0;
            if (servo_pos > 1000) servo_pos = 1000;
            set_pwm_duty_cycle(pwm_fd, servo_pos);
        }

        log_data(LOG_FILE, pitch, roll, servo_pos);
        usleep(100000);
    }

    set_pwm_duty_cycle(pwm_fd, 0);
    close(pwm_fd);
    close(i2c_fd);
    return 0;
}

