#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"
#define MAX_SCHEDULE_ENTRIES 100

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on;
} schedule_entry_t;

static volatile sig_atomic_t running = 1;
static int relay_gpios[4] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_gpios[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_gpios[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_gpios[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_schedule(const char *filename, schedule_entry_t *entries, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), fp) != NULL && count < max_entries) {
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &entries[count].hour,
                   &entries[count].minute,
                   &entries[count].second,
                   &entries[count].relay_number,
                   &entries[count].on) == 5) {
            if (entries[count].relay_number >= 1 && entries[count].relay_number <= 4) {
                count++;
            } else {
                fprintf(stderr, "Warning: invalid relay number in schedule: %d\n", entries[count].relay_number);
            }
        } else {
            fprintf(stderr, "Warning: invalid schedule entry format, skipping\n");
        }
    }

    fclose(fp);
    return count;
}

static int get_current_time(int *hour, int *minute, int *second) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Error getting local time");
        return -1;
    }

    *hour = timeinfo->tm_hour;
    *minute = timeinfo->tm_min;
    *second = timeinfo->tm_sec;
    return 0;
}

static int set_relay_state(int relay_number, int on) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Error: invalid relay number %d\n", relay_number);
        return -1;
    }
    int gpio_pin = relay_gpios[relay_number - 1];
    int duty = on ? PWM_RANGE : 0;
    if (gpioPWM(gpio_pin, duty) != 0) {
        fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

static int fade_relay(int relay_number, int on, int duration_seconds) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Error: invalid relay number %d\n", relay_number);
        return -1;
    }
    int gpio_pin = relay_gpios[relay_number - 1];
    int start_duty = on ? 0 : PWM_RANGE;
    int end_duty = on ? PWM_RANGE : 0;
    int step_size = (end_duty - start_duty) / (duration_seconds * PWM_FREQUENCY);
    if (step_size == 0) step_size = 1;

    for (int i = 0; i <= duration_seconds * PWM_FREQUENCY && running; i++) {
        int duty = start_duty + (i * step_size);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (gpioPWM(gpio_pin, duty) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", gpio_pin);
            return -1;
        }
        gpioDelay(1000000 / PWM_FREQUENCY);
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        gpioPWM(relay_gpios[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    schedule_entry_t schedule[MAX_SCHEDULE_ENTRIES];
    int num_entries = read_schedule(SCHEDULE_FILE, schedule, MAX_SCHEDULE_ENTRIES);
    if (num_entries < 0) {
        cleanup();
        return 1;
    }

    printf("Smart Home Lighting System started. %d schedule entries loaded.\n", num_entries);

    while (running) {
        int current_hour, current_minute, current_second;
        if (get_current_time(&current_hour, &current_minute, &current_second) != 0) {
            fprintf(stderr, "Error getting current time, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        for (int i = 0; i < num_entries && running; i++) {
            if (schedule[i].hour == current_hour &&
                schedule[i].minute == current_minute &&
                schedule[i].second == current_second) {
                printf("Executing schedule entry: relay %d, state %s\n",
                       schedule[i].relay_number,
                       schedule[i].on ? "ON" : "OFF");
                if (set_relay_state(schedule[i].relay_number, schedule[i].on) != 0) {
                    fprintf(stderr, "Error setting relay state, continuing...\n");
                }
                if (fade_relay(schedule[i].relay_number, !schedule[i].on, FADE_DURATION) != 0) {
                    fprintf(stderr, "Error fading relay, continuing...\n");
                }
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

