#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define SPEED_OF_SOUND_CM_PER_S 34300.0f
#define TRIGGER_PULSE_US       10
#define ECHO_TIMEOUT_US        30000  /* 30 ms max echo wait */
#define LOOP_DELAY_US          60000  /* 60 ms between measurements */
#define MAX_DISTANCE_US        (long)((MAX_DISTANCE_CM * SPEED_OF_SOUND_CM_PER_S) / 1000000.0f)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or read failure.
 * Uses pigpio's microsecond-precision timing.
 */
static float read_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    /* Ensure trigger is low before starting */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    /* Wait for echo rising edge (timeout if sensor absent or no object) */
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck low (sensor absent or wiring fault).\n");
            return -1.0f;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout).\n");
            return -1.0f;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        fprintf(stderr, "Error: Zero-length pulse (possible clock glitch).\n");
        return -1.0f;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0f;
    return distance;
}

static int map_frequency(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float fraction = (distance - MIN_DISTANCE_CM) /
                     (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(MIN_FREQUENCY_HZ +
                 fraction * (float)(MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));
}

