#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_PWM_frequency(unsigned pin, unsigned freq) {
    if (gpioSetPWMfrequency(pin, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int safe_set_PWM_range(unsigned pin, unsigned range) {
    if (gpioSetPWMrange(pin, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int safe_set_PWM_dutycycle(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int set_led_color(int red, int green, int blue) {
    if (safe_set_PWM_dutycycle(RED_PIN, red) != 0)   return -1;
    if (safe_set_PWM_dutycycle(GREEN_PIN, green) != 0) return -1;
    if (safe_set_PWM_dutycycle(BLUE_PIN, blue) != 0)  return -1;
    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RED_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(GREEN_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(BLUE_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_PWM_frequency(RED_PIN, PWM_FREQ) != 0 ||
        safe_set_PWM_frequency(GREEN_PIN, PWM_FREQ) != 0 ||
        safe_set_PWM_frequency(BLUE_PIN, PWM_FREQ) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_PWM_range(RED_PIN, PWM_RANGE) != 0 ||
        safe_set_PWM_range(GREEN_PIN, PWM_RANGE) != 0 ||
        safe_set_PWM_range(BLUE_PIN, PWM_RANGE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    double t = 0.0;
    while (running) {
        double proximity = (sin(t) + 1.0) / 2.0;
        int red   = (int)(proximity * PWM_RANGE);
        int green = (int)((1.0 - proximity) * PWM_RANGE);
        int blue  = 0;

        if (set_led_color(red, green, blue) != 0) {
            fprintf(stderr, "Error: failed to set LED color\n");
            break;
        }

        t += 0.01;
        if (t > 2.0 * M_PI) t -= 2.0 * M_PI;
        time_sleep(0.01);
    }

    cleanup();
    return EXIT_SUCCESS;
}

