#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define DEFAULT_POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
}

static int log_event(FILE *log_file, const char *timestamp, int value) {
    if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void check_earthquake_alert(int *window, int *count) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window[i] == 1) {
            (*count)++;
        }
    }
    if (*count >= 3) {
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));
        printf("EARTHQUAKE ALERT: %s\n", timestamp);
        fflush(stdout);
    }
    *count = 0;
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout, using default %d ms\n", DEFAULT_POLL_TIMEOUT_MS);
            poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
        }
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int event_count = 0;
    int high_count = 0;

    printf("Vibration sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = poll_timeout_ms / 1000;
        ts.tv_nsec = (poll_timeout_ms % 1000) * 1000000L;

        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        int value = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;

        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        if (log_event(log_file, timestamp, value) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        event_count++;

        if (value == 1) {
            high_count++;
        }

        if (event_count >= WINDOW_SIZE) {
            check_earthquake_alert(window, &high_count);
        }
    }

    printf("\nCleaning up...\n");
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

