#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* LSM303DLHC magnetometer I2C address (SA0 tied to GND) */
#define LSM303_MAG_ADDR 0x1E

/* LSM303DLHC magnetometer register addresses */
#define CRA_REG_M  0x00
#define MR_REG_M   0x02
#define OUT_X_H_M  0x03
#define OUT_X_L_M  0x04
#define OUT_Z_H_M  0x05
#define OUT_Z_L_M  0x06
#define OUT_Y_H_M  0x07
#define OUT_Y_L_M  0x08

/* Calibration offsets (replace with your measured values) */
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS "/dev/i2c-1"

/* Globals for cleanup in signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register via SMBus */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register via SMBus */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit big-endian axis from two consecutive registers */
static int i2c_read_axis16(int fd, uint8_t reg_h, int16_t *out)
{
    uint8_t hi, lo;
    if (i2c_read_reg8(fd, reg_h, &hi) < 0) return -1;
    if (i2c_read_reg8(fd, reg_h + 1, &lo) < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* Initialize the LSM303DLHC magnetometer */
static int init_magnetometer(int fd)
{
    /* CRA_REG_M: 0x14 -> ODR = 15 Hz, temp sensor off, ultra-high perf */
    if (i2c_write_reg8(fd, CRA_REG_M, 0x14) < 0) return -1;
    /* MR_REG_M: 0x00 -> continuous-conversion mode */
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) < 0) return -1;
    return 0;
}

/* Read calibrated magnetic-field data from the magnetometer */
static int read_magnetometer_data(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_axis16(fd, OUT_X_H_M, &raw_x) < 0) return -1;
    if (i2c_read_axis16(fd, OUT_Y_H_M, &raw_y) < 0) return -1;
    if (i2c_read_axis16(fd, OUT_Z_H_M, &raw_z) < 0) return -1;

