#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_US 200000  /* 200 ms in microseconds */
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t relay_state = 0;
static volatile uint32_t last_touch_tick = 0;
static volatile int running = 1;

/*
 * pigpio ISR callback for the touch sensor.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * We compute the elapsed time in microseconds with wrap-aware subtraction.
 */
static void touch_isr(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 1) {            /* Only act on rising edge (touch) */
        return;
    }

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_US) {
        return;                 /* Debounce: ignore touches within 200 ms */
    }
    last_touch_tick = tick;

    relay_state = !relay_state;

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: failed to write relay GPIO %d\n", RELAY_PIN);
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        return;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            timestamp, relay_state ? "ON" : "OFF");
    fclose(fp);
}

static void cleanup(void)
{
    /* Ensure relay is OFF before terminating pigpio */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during cleanup\n");
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with pull-down */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR for rising-edge touch events */
    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_isr) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);

    /* Main loop: sleep until signal received */
    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

