#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ACTIVATION_DURATION_SEC 5
#define RELAY_DEACTIVATION_GAP_SEC 1
#define SENSOR_READ_INTERVAL_SEC 10
#define LOG_FILE "irrigation_log.txt"

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Warning: failed to deactivate relay %d (GPIO%d): %s\n",
                        i + 1, relay_pins[i], strerror(errno));
            }
        }
    }
}

static void cleanup(void) {
    deactivate_all_relays();
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int activate_relay(int relay_number, int duration_seconds) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }
    int index = relay_number - 1;

    if (gpiod_line_set_value(lines[index], 0) < 0) {
        fprintf(stderr, "Failed to activate relay %d (GPIO%d): %s\n",
                relay_number, relay_pins[index], strerror(errno));
        return -1;
    }

    sleep(duration_seconds);

    if (gpiod_line_set_value(lines[index], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d (GPIO%d): %s\n",
                relay_number, relay_pins[index], strerror(errno));
        return -1;
    }
    return 0;
}

static int log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d activated - Moisture level: %d\n",
                timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) == EOF) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture_level = rand() % 101;
        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS && program_running; i++) {
                if (activate_relay(i + 1, RELAY_ACTIVATION_DURATION_SEC) < 0) {
                    fprintf(stderr, "Error activating relay %d\n", i + 1);
                    break;
                }
                if (i < NUM_RELAYS - 1 && program_running) {
                    sleep(RELAY_DEACTIVATION_GAP_SEC);
                }
            }
            if (program_running) {
                for (int i = 0; i < NUM_RELAYS; i++) {
                    if (log_irrigation_event(i + 1, moisture_level) < 0) {
                        fprintf(stderr, "Error logging irrigation event for relay %d\n", i + 1);
                    }
                }
            }
        }

        if (program_running) {
            sleep(SENSOR_READ_INTERVAL_SEC);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

