/*
 * Miniature automated plant watering system for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - SG90 valve servo on GPIO17 (physical pin 11)
 *   - SG90 nozzle servo on GPIO18 (physical pin 12)
 *   - SG90 signal wire: 5 V (external supply recommended)
 *
 * Behavior:
 *   - Simulated soil-moisture readings cycle every second: 20, 40, 60, 80, 100.
 *   - If moisture < 50, open valve (90 degrees) and sweep nozzle through
 *     0, 45, 90, 135, 180 degrees at 2 s/step, hold for 5 s, then close
 *     valve (0 degrees).  If moisture >= 50, skip watering.
 *   - After each cycle, wait 5 s before the next moisture reading.
 *   - On SIGINT/SIGTERM, stop both servos, release pigpio, and exit.
 *
 * Build:  gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO      17
#define NOZZLE_GPIO     18

#define VALVE_OPEN_US   1500   /* 90 degrees  */
#define VALVE_CLOSE_US  500    /* 0 degrees   */
#define NOZZLE_MIN_US   500    /* 0 degrees   */
#define NOZZLE_MAX_US   2500   /* 180 degrees */
#define NOZZLE_STEP_US  1000   /* 45 degrees  */

#define MOISTURE_MIN    20
#define MOISTURE_MAX    100
#define MOISTURE_THRESHOLD 50

#define SERVO_RETRIES   3
#define SERVO_BACKOFF_US 100000  /* 100 ms */
#define LOOP_DELAY_US   5000000  /* 5 s   */
#define NOZZLE_HOLD_US  5000000  /* 5 s   */
#define NOZZLE_STEP_US  2000000  /* 2 s   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Set servo position with retries                                     */
/* ------------------------------------------------------------------ */
static int set_servo(int gpio, int pulse_us)
{
    for (int attempt = 0; attempt < SERVO_RETRIES; ++attempt) {
        int rc = gpioServo(gpio, pulse_us);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "gpioServo(gpio=%d, pulse=%d us) failed (rc=%d), "
                "attempt %d/%d\n",
                gpio, pulse_us, rc, attempt + 1, SERVO_RETRIES);
        usleep(SERVO_BACKOFF_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Stop a servo (0 pulse = coast)                                      */
/* ------------------------------------------------------------------ */
static void stop_servo(int gpio)
{
    (void)gpioServo(gpio, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call even if pigpio is uninitialised             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_servo(VALVE_GPIO);
    stop_servo(NOZZLE_GPIO);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers early ----------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        /* Read simulated moisture */
        int moisture = (rand() % (MOISTURE_MAX - MOISTURE_MIN + 1)) + MOISTURE_MIN;
        printf("Moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold — watering...\n");

            /* Open valve (90 degrees) */
            if (set_servo(VALVE_GPIO, VALVE_OPEN_US) != 0) {
                fprintf(stderr,
                        "ERROR: valve servo failed to open after %d retries\n",
                        SERVO_RETRIES);
                break;
            }

            /* Sweep nozzle through 0, 45, 90, 135, 180 degrees */
            for (int angle = 0; angle <= 180 && g_running; angle += 45) {
                int pulse = NOZZLE_MIN_US +
                            (int)((float)angle / 180.0f *
                                  (float)(NOZZLE_MAX_US - NOZZLE_MIN_US));
                if (set_servo(NOZZLE_GPIO, pulse) != 0) {
                    fprintf(stderr,
                            "ERROR: nozzle servo failed at angle %d\n",
                            angle);
                    break;
                }
                usleep(NOZZLE_STEP_US);
            }

            /* Hold at 90 degrees for 5 s */
            if (g_running) {
                set_servo(NOZZLE_GPIO, VALVE_OPEN_US);
                usleep(NOZZLE_HOLD_US);
            }

            /* Close valve (0 degrees) */
            if (set_servo(VALVE_GPIO, VALVE_CLOSE_US) != 0) {
                fprintf(stderr,
                        "WARNING: valve servo failed to close after %d retries\n",
                        SERVO_RETRIES);
            }
        } else {
            printf("Moisture above threshold — skipping watering.\n");
        }

        /* Wait 5 s before next cycle (interruptible) */
        for (int i = 0; i < 50 && g_running; ++i)
            usleep(100000);  /* 100 ms */
    }

    /* ---- Cleanup --------------------------------------------------- */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

