#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define SPEED_OF_SOUND_CM_PER_US 0.01715
#define TIMEOUT_US               50000
#define MIN_GUARD_MS             60
#define LOOP_DELAY_MS            1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long monotonic_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int trigger_sensor(struct gpiod_line *trigger)
{
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static long long measure_pulse_width(struct gpiod_line *echo)
{
    long long start_time, end_time;
    int val;

    start_time = monotonic_us();
    while (1) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error reading echo: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1)
            break;
        if (monotonic_us() - start_time > TIMEOUT_US)
            return -1;
    }

    end_time = monotonic_us();
    while (1) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error reading echo: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0)
            break;
        if (monotonic_us() - end_time > TIMEOUT_US)
            return -1;
    }

    return end_time - start_time;
}

static float calculate_distance(long long pulse_width)
{
    return (float)pulse_width * SPEED_OF_SOUND_CM_PER_US;
}

static void log_distance(FILE *fp, float distance)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error getting trigger line (BCM %d): %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error getting echo line (BCM %d): %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
