        fprintf(stderr, "Error requesting trigger as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error requesting echo as input: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Error triggering sensor\n");
            fprintf(fp, "%ld, -1\n", (long)time(NULL));
            fflush(fp);
        } else {
            long long pulse_width = measure_pulse_width(echo);
            if (pulse_width < 0) {
                fprintf(stderr, "Error measuring pulse width\n");
                fprintf(fp, "%ld, -1\n", (long)time(NULL));
                fflush(fp);
            } else {
