#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_SYSTEM_MODE      0x0080
#define VL53L1X_REG_SYSTEM_INTERRUPT 0x0044
#define VL53L1X_REG_RESULT_DISTANCE  0x0096  /* MSB */
#define VL53L1X_REG_RESULT_DISTANCE_LSB 0x0097  /* LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a 16-bit big-endian value */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address, then a 16-bit big-endian value */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "VL53L1X: failed to write soft reset\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle */

    /* Set ranging mode (register 0x0080 = 0x01) */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x0001) < 0) {
        fprintf(stderr, "VL53L1X: failed to set ranging mode\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status;
    uint16_t dist_msb, dist_lsb;

    /* Check data-ready interrupt */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT, &status) < 0) {
        fprintf(stderr, "VL53L1X: failed to read interrupt status\n");
        return -1;
    }
    if (!(status & 0x0001)) {
        /* Data not ready yet */
        return 1;
    }

    /* Read 16-bit distance (MSB at 0x0096, LSB at 0x0097) */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_msb) < 0) {
        fprintf(stderr, "VL53L1X: failed to read distance MSB\n");
        return -1;
    }
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE_LSB, &dist_lsb) < 0) {
        fprintf(stderr, "VL53L1X: failed to read distance LSB\n");
        return -1;
    }

    *distance_mm = ((uint16_t)dist_msb << 8) | dist_lsb;
    return 0;
}

static void control_relay(int gpio, int state)
{
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", gpio);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(RELAY_GPIO, 0);  /* Ensure relay starts LOW */

    /* Open I2C bus to VL53L1X */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (err=%d)\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X door sensor ready. Polling every %d ms. Ctrl+C to exit.\n",
           POLL_DELAY_US / 1000);

    while (g_running) {
        uint16_t distance_mm;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            printf("Distance: %u mm\n", distance_mm);
            if (distance_mm <= (DISTANCE_THRESHOLD_CM * 10)) {
                printf("Object within %d cm! Opening door...\n", DISTANCE_THRESHOLD_CM);
                control_relay(RELAY_GPIO, 1);
            } else {
                control_relay(RELAY_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
        }
        /* rc == 1: data not ready, no error */

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

