/*
 * Automated plant watering system using four 5V relay modules on a
 * Raspberry Pi 4 Model B using libgpiod v1 API.
 *
 * Relays (active-low, HIGH = inactive):
 *   BCM GPIO17 -> physical pin 11
 *   BCM GPIO18 -> physical pin 12
 *   BCM GPIO27 -> physical pin 13
 *   BCM GPIO22 -> physical pin 15
 *
 * Build: gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_DURATION  5          /* seconds each relay is energized */
#define POLL_INTERVAL   60         /* seconds between watering cycles */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_watering_cycle(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: Watering cycle started\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open gpiochip0 ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- Request lines as outputs, initial value HIGH (inactive) ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "watering-relay", 1) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_RELAYS && program_running; i++) {
            if (log_watering_cycle() != 0) {
                fprintf(stderr, "Warning: failed to log watering cycle\n");
            }

            /* Activate relay (active-low: set line LOW) */
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set line %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }

            printf("Relay %d (BCM %u) energized for %d seconds\n",
                   i + 1, relay_pins[i], RELAY_DURATION);

            /* Sleep in 1-second increments so signals are caught promptly */
            for (int s = 0; s < RELAY_DURATION && program_running; s++) {
                sleep(1);
            }

            /* Deactivate relay (set line HIGH) */
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set line %u HIGH: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }

            printf("Relay %d (BCM %u) deactivated\n", i + 1, relay_pins[i]);
        }

        /* Wait until next watering cycle (interruptible by signals) */
        for (int s = 0; s < POLL_INTERVAL && program_running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    /* ---- Close chip ---- */
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Watering system stopped.\n");
    return ret;
}

