#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define LOG_FILE "smart_lighting.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

void set_relay_state(int pin, int state) {
    gpioWrite(pin, state);
}

void set_all_relays(int state) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        gpioWrite(pins[i], state);
    }
}

void set_relay_pwm(int pin, int duty_cycle) {
    gpioPWM(pin, duty_cycle);
}

void simulate_sunrise() {
    log_event("Sunrise simulation started");
    for (int i = 0; i <= SUNRISE_DURATION && program_running; i++) {
        int duty_cycle = (int)(((float)i / SUNRISE_DURATION) * PWM_RANGE);
        set_all_relays(1);
        set_relay_pwm(RELAY1_PIN, duty_cycle);
        set_relay_pwm(RELAY2_PIN, duty_cycle);
        set_relay_pwm(RELAY3_PIN, duty_cycle);
        set_relay_pwm(RELAY4_PIN, duty_cycle);
        gpioDelay(1000000);
    }
    set_all_relays(0);
    log_event("Sunrise simulation complete");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        return 1;
    }

    log_event("Program started");
    simulate_sunrise();

    set_all_relays(0);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

