#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75
#define MPU6050_GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Angular velocity threshold (degrees/second) */
#define THRESHOLD 250.0

/* Sample period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Maximum re-initialisation attempts */
#define MAX_REINIT_ATTEMPTS 3

/* Structure to hold gyroscope data with timestamp */
typedef struct {
    struct timespec timestamp;
    double x;
    double y;
    double z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* I2C handle */
static int i2c_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize MPU-6050 sensor */
static int init_mpu6050(void) {
    int status;

    /* Wake up the MPU-6050 (clear sleep bit) */
    status = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        return -1;
    }

    /* Set sample rate divider to 0 (1 kHz / (1 + 0) = 1 kHz) */
    status = i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07);
    if (status < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
        return -1;
    }

    /* Set gyroscope full-scale range to +/- 250 deg/s (FS_SEL = 0) */
    status = i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
        return -1;
    }

    return 0;
}

/* Read gyroscope data from MPU-6050 */
static int read_gyro_data(double *x, double *y, double *z) {
    char buf[6];
    int status;

    /* Read 6 bytes of gyroscope data starting at GYRO_XOUT_H */
    status = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    /* Convert raw data to degrees/second (+/- 250 deg/s range, 131 LSB/deg/s) */
    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (double)raw_x / 131.0;
    *y = (double)raw_y / 131.0;
    *z = (double)raw_z / 131.0;

    return 0;
}

/* Add data to circular buffer */
static void add_to_buffer(double x, double y, double z) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static bool check_threshold(double x, double y, double z) {
    return (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int reinit_attempts = 0;
    double x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output and ensure it's off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                MPU6050_WHO_AM_I_VAL, who_am_i);
        cleanup();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            if (check_threshold(x, y, z)) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }

            printf("X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data. Attempting re-initialisation...\n");
            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialisation attempts reached. Exiting.\n");
                break;
            }
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Re-initialisation failed. Retrying...\n");
                gpioDelay(1000000); /* 1 second delay before retry */
                continue;
            }
            reinit_attempts = 0;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

