#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_NS 10000000L  /* 10 ms */
#define MAX_RETRIES     3
#define GYRO_XOUT_H     0x43
#define GYRO_YOUT_H     0x45
#define GYRO_ZOUT_H     0x47
#define GYRO_SCALE      131.0f      /* ±250 dps range */

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "CS low failed: %s\n", strerror(errno));
            usleep(1000);
            continue;
        }
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "CS high failed: %s\n", strerror(errno));
            usleep(1000);
            continue;
        }
        if (ret < 1) {
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            usleep(1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t tx[7] = { GYRO_XOUT_H, 0, 0, 0, 0, 0, 0 };
    uint8_t rx[7] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *x = (int16_t)((rx[2] << 8) | rx[1]);
    *y = (int16_t)((rx[4] << 8) | rx[3]);
    *z = (int16_t)((rx[6] << 8) | rx[5]);
    return 0;
}

static void log_data(float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    if (fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    if (fflush(log_fp) == EOF)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

static void cleanup(void)
{
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI config failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Cannot request CS line as output: %s\n",
                strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-9250 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Gyro read failed after %d retries; continuing.\n",
                    MAX_RETRIES);
            usleep(SAMPLE_PERIOD_NS);
            continue;
        }

        float x_rate = (float)raw_x / GYRO_SCALE;
        float y_rate = (float)raw_y / GYRO_SCALE;
        float z_rate = (float)raw_z / GYRO_SCALE;

        log_data(x_rate, y_rate, z_rate);
        usleep(SAMPLE_PERIOD_NS);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

