#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_BITS 8

#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8
#define LED_GPIO_LINE 17

#define BUFFER_SIZE 64
#define THRESHOLD 200.0f
#define SENSITIVITY 131.0f

#define REG_SMPLRT_DIV 0x19
#define REG_CONFIG 0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_GYRO_XOUT_H 0x43
#define REG_GYRO_YOUT_H 0x45
#define REG_GYRO_ZOUT_H 0x47
#define REG_PWR_MGMT_1 0x6B

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    time_t timestamp;
    float x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static int spi_fd = -1;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spidev");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }

    cs_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!cs_chip) {
        perror("gpiod_chip_open_by_name");
        close(spi_fd); spi_fd = -1; return -1;
    }

    cs_line = gpiod_chip_get_line(cs_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("gpiod_chip_get_line (CS)");
        gpiod_chip_close(cs_chip); cs_chip = NULL;
        close(spi_fd); spi_fd = -1; return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050-cs", 1) < 0) {
        perror("gpiod_line_request_output (CS)");
        gpiod_chip_close(cs_chip); cs_chip = NULL;
        close(spi_fd); spi_fd = -1; return -1;
    }

    led_line = gpiod_chip_get_line(cs_chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_line_release(cs_line); cs_line = NULL;
        gpiod_chip_close(cs_chip); cs_chip = NULL;
        close(spi_fd); spi_fd = -1; return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050-led", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_line_release(cs_line); cs_line = NULL;
        gpiod_chip_close(cs_chip); cs_chip = NULL;
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static void spi_deinit(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (cs_chip) {
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

static int mpu6050_write(uint8_t reg, uint8_t val) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), val };
    uint8_t rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) return -1;
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (gpiod_line_set_value(cs_line, 1) < 0) ret = -1;
    return (ret < 0) ? -1 : 0;
}

static int mpu6050_read(uint8_t reg, uint8_t *val) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) return -1;
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (gpiod_line_set_value(cs_line, 1) < 0) ret = -1;
    if (ret < 0) return -1;
    *val = rx[1];
    return 0;
}

static int mpu6050_init(void) {
    if (mpu6050_write(REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (mpu6050_write(REG_SMPLRT_DIV, 0x07) < 0) return -1;
    if (mpu6050_write(REG_CONFIG, 0x00) < 0) return -1;
    if (mpu6050_write(REG_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t xh, xl, yh, yl, zh, zl;

    if (mpu6050_read(REG_GYRO_XOUT_H, &xh) < 0) return -1;
    if (mpu6050_read(REG_GYRO_YOUT_H, &yh) < 0) return -1;
    if (mpu6050_read(REG_GYRO_ZOUT_H, &zh) < 0) return -1;

    if (mpu6050_read(REG_GYRO_XOUT_H + 1, &xl) < 0) return -1;
    if (mpu6050_read(REG_GYRO_YOUT_H + 1, &yl) < 0) return -1;
    if (mpu6050_read(REG_GYRO_ZOUT_H + 1, &zl) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld,%.2f,%.2f,%.2f\n",
               (long)gyro_buffer[idx].timestamp,
               gyro_buffer[idx].x,
               gyro_buffer[idx].y,
               gyro_buffer[idx].z);
    }
    fflush(stdout);
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (mpu6050_init() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        spi_deinit();
        return 1;
    }

    printf("MPU-6050 stability monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "SPI read error: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }

        add_to_buffer(x, y, z);
        check_threshold(x, y, z);
        usleep(10000);
    }

    print_buffer();
    spi_deinit();
    printf("Exiting.\n");
    return 0;
}

