#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define LED_GPIO 21
#define TILT_THRESHOLD 45.0
#define LOG_FILE "tilt_log.txt"
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    float roll;
    float pitch;
} tilt_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpu6050(int handle) {
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU-6050 (PWR_MGMT_1 write failed)\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range (ACCEL_CONFIG write failed)\n");
        return -1;
    }
    return 0;
}

static tilt_data_t read_tilt_data(int handle) {
    char buf[6];
    tilt_data_t tilt = {0.0f, 0.0f};

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return tilt;
    }

    int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    tilt.roll = atan2f((float)accel_y, (float)accel_z) * 180.0f / (float)M_PI;
    tilt.pitch = atan2f((float)-accel_x, sqrtf((float)accel_y * (float)accel_y + (float)accel_z * (float)accel_z)) * 180.0f / (float)M_PI;

    return tilt;
}

static void log_data(const tilt_data_t *tilt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            tilt->roll, tilt->pitch);
    fclose(fp);
}

static void control_led(float roll, float pitch) {
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d\n", MPU6050_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    while (running) {
        tilt_data_t tilt = read_tilt_data(i2c_handle);
        log_data(&tilt);
        control_led(tilt.roll, tilt.pitch);
        printf("Roll: %.2f, Pitch: %.2f\n", tilt.roll, tilt.pitch);
        gpioDelay(100000);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

