#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */
#define SPI_BITS    8

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Sampling: 100 Hz -> 10 ms delay */
#define SAMPLE_DELAY_US 10000

/* Max retries for SPI re-initialisation */
#define MAX_RETRIES 3

/* Global state for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADXRS290                            */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    /* ADXRS290: read command is OR'd with 0x80 */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Response is the second byte of the transfer */
    *out = (int16_t)((uint8_t)rx[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read both axes                                                       */
/* ------------------------------------------------------------------ */
static int read_gyro_data(gyro_data_t *data)
{
    if (read_register(ADXRS290_REG_X_RATE, &data->x_rate) != 0)
        return -1;
    if (read_register(ADXRS290_REG_Y_RATE, &data->y_rate) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample                                                       */
/* ------------------------------------------------------------------ */
static void log_data(const gyro_data_t *data)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    if (fprintf(log_file, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                data->x_rate, data->y_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialise SPI                                                       */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int retry_count = 0;

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "timestamp,x_rate,y_rate\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Signal handling */
    struct sigaction sa;
