{
    int retry_count = 0;

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    if (init_spi() != 0) {
        gpioTerminate();
