    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "timestamp,x_rate,y_rate\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main sampling loop */
    while (!terminate) {
        gyro_data_t data;

        if (read_gyro_data(&data) != 0) {
            fprintf(stderr, "Gyro read failed (attempt %d/%d)\n",
                    retry_count + 1, MAX_RETRIES);
            retry_count++;

            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }

            /* Close and re-open SPI */
            spiClose(spi_handle);
            spi_handle = -1;
            if (init_spi() != 0) {
                fprintf(stderr, "SPI re-initialisation failed. Exiting.\n");
                break;
            }
            retry_count++;
            continue;
        }

        retry_count = 0;
        log_data(&data);
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    cleanup();
    return EXIT_SUCCESS;
}

