#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define SEISMIC_DURATION_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file);
    }
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;
    static uint32_t start_tick = 0;
    static int both_high = 0;

    if (level == 1) {
        if (gpio == SENSOR_1_PIN) {
            if (!both_high) {
                start_tick = gpioTick();
                both_high = 1;
            }
        } else if (gpio == SENSOR_2_PIN) {
            if (!both_high) {
                start_tick = gpioTick();
                both_high = 1;
            }
        }
    } else if (level == 0) {
        if (gpio == SENSOR_1_PIN) {
            both_high = 0;
        } else if (gpio == SENSOR_2_PIN) {
            both_high = 0;
        }
    }

    if (both_high) {
        uint32_t elapsed = gpioTick() - start_tick;
        if (elapsed >= (uint32_t)(SEISMIC_DURATION_MS * 1000)) {
            trigger_alert();
            log_event("Seismic event detected!");
            both_high = 0;
        }
    }
}

