#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <stdatomic.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0: CPOL=0, CPHA=0 */

/* GPIO pins */
#define LED_PIN 17

/* Circular buffer */
#define BUFFER_SIZE 100

/* Angular velocity threshold (degrees per second) */
#define ANGULAR_VELOCITY_THRESHOLD 20.0

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0

/* Data structure for gyro data */
typedef struct {
    struct timespec timestamp;
    double angular_velocity;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static atomic_int buffer_head = 0;
static atomic_int buffer_tail = 0;

/* SPI handle */
static int spi_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Function to read a single register from the ADXRS290 */
static int read_register(uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADXRS290: set MSB of register address to 1 for read */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (returned %d)\n", reg_addr, result);
        return -1;
    }

    *data = (uint8_t)rx_buf[1];
    return 0;
}

/* Function to read angular velocity from the ADXRS290 */
static int read_angular_velocity(double *angular_velocity) {
    uint8_t xl_data, xh_data;

    if (read_register(ADXRS290_REG_RATE_XL, &xl_data) != 0) {
        return -1;
    }
    if (read_register(ADXRS290_REG_RATE_XH, &xh_data) != 0) {
        return -1;
    }

    int16_t raw_data = (int16_t)((xh_data << 8) | xl_data);
    *angular_velocity = (double)raw_data / SENSITIVITY;
    return 0;
}

/* Function to add data to the circular buffer */
static void add_to_buffer(struct timespec timestamp, double angular_velocity) {
    int head = atomic_load(&buffer_head);
    gyro_buffer[head].timestamp = timestamp;
    gyro_buffer[head].angular_velocity = angular_velocity;
    atomic_store(&buffer_head, (head + 1) % BUFFER_SIZE);
}

/* Function to check if the angular velocity exceeds the threshold */
static int check_threshold(double angular_velocity) {
    return (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD);
}

/* Function to control the LED */
static void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        double angular_velocity;

        if (read_angular_velocity(&angular_velocity) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(ts, angular_velocity);

            if (check_threshold(angular_velocity)) {
                control_led(1);
            } else {
                control_led(0);
            }
        } else {
            fprintf(stderr, "Failed to read angular velocity\n");
        }

        gpioDelay(10000); /* 10 ms delay (10,000 microseconds) */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

