/* Function to control the LED */
static void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        double angular_velocity;

        if (read_angular_velocity(&angular_velocity) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(ts, angular_velocity);

            if (check_threshold(angular_velocity)) {
                control_led(1);
            } else {
                control_led(0);
            }
        } else {
            fprintf(stderr, "Failed to read angular velocity\n");
        }

        gpioDelay(10000); /* 10 ms delay (10,000 microseconds) */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

