#define PWM_FREQ 100
#define MAX_DURATION 3600

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void turn_off_all_lamps(void) {
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);
}

static void cleanup(void) {
    turn_off_all_lamps();
    gpioTerminate();
}

static int validate_duration(int duration) {
    if (duration <= 0 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be between 1 and %d seconds.\n", MAX_DURATION);
        return -1;
    }
    return 0;
}

static int fade_lamp(int gpio, int duration_seconds) {
    if (gpioSetPWMrange(gpio, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", gpio);
        return -1;
    }
    if (gpioSetPWMfrequency(gpio, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", gpio);
        return -1;
    }

    int step_delay_us = (duration_seconds * 1000000) / PWM_RANGE;
    if (step_delay_us < 1000) step_delay_us = 1000;

    for (int i = 0; i <= PWM_RANGE && running; i++) {
        if (gpioPWM(gpio, i) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", gpio);
            return -1;
        }
        gpioDelay(step_delay_us);
    }

    if (!running) return -1;

    for (int i = PWM_RANGE; i >= 0 && running; i--) {
        if (gpioPWM(gpio, i) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", gpio);
            return -1;
        }
        gpioDelay(step_delay_us);
    }

    return 0;
}

