        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fade duration: %d seconds.\n", duration);
    printf("Lamp 1 (GPIO%d), Lamp 2 (GPIO%d), Lamp 3 (GPIO%d)\n", LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO);
    printf("Press Ctrl+C to stop early.\n");

    int ret = EXIT_SUCCESS;

    if (fade_lamp(LAMP1_GPIO, duration) != 0) {
        fprintf(stderr, "Error: failed to fade lamp 1 (GPIO%d).\n", LAMP1_GPIO);
        ret = EXIT_FAILURE;
    } else {
        printf("Lamp 1 (GPIO%d) faded successfully.\n", LAMP1_GPIO);
    }

    if (ret == EXIT_SUCCESS && fade_lamp(LAMP2_GPIO, duration) != 0) {
        fprintf(stderr, "Error: failed to fade lamp 2 (GPIO%d).\n", LAMP2_GPIO);
        ret = EXIT_FAILURE;
    } else {
        printf("Lamp 2 (GPIO%d) faded successfully.\n", LAMP2_GPIO);
    }

    if (ret == EXIT_SUCCESS && fade_lamp(LAMP3_GPIO, duration) != 0) {
        fprintf(stderr, "Error: failed to fade lamp 3 (GPIO%d).\n", LAMP3_GPIO);
        ret = EXIT_FAILURE;
    } else {
        printf("Lamp 3 (GPIO%d) faded successfully.\n", LAMP3_GPIO);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Smart Sunset Simulator complete.\n");
    } else {
        fprintf(stderr, "Smart Sunset Simulator failed.\n");
    }

    cleanup();
    return ret;
}

