#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_RELAY    17
#define YELLOW_RELAY 22
#define GREEN_RELAY  23
#define BLUE_RELAY   24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void all_off(struct gpiod_line *red, struct gpiod_line *yellow,
                    struct gpiod_line *green, struct gpiod_line *blue) {
    set_relay(red, 1);
    set_relay(yellow, 1);
    set_relay(green, 1);
    set_relay(blue, 1);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *yellow = NULL, *green = NULL, *blue = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red    = gpiod_chip_get_line(chip, RED_RELAY);
    yellow = gpiod_chip_get_line(chip, YELLOW_RELAY);
    green  = gpiod_chip_get_line(chip, GREEN_RELAY);
    blue   = gpiod_chip_get_line(chip, BLUE_RELAY);

    if (!red || !yellow || !green || !blue) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(yellow, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(green, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(blue, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");

    while (running) {
        printf("RED ON\n");
        set_relay(red, 0);
        set_relay(yellow, 1);
        set_relay(green, 1);
        set_relay(blue, 1);
        sleep(10);

        if (!running) break;

        printf("RED + YELLOW ON\n");
        set_relay(red, 0);
        set_relay(yellow, 0);
        set_relay(green, 1);
        set_relay(blue, 1);
        sleep(2);

        if (!running) break;

        printf("GREEN ON\n");
        set_relay(red, 1);
        set_relay(yellow, 1);
        set_relay(green, 0);
        set_relay(blue, 1);
        sleep(10);

        if (!running) break;

        printf("YELLOW ON\n");
        set_relay(red, 1);
        set_relay(yellow, 0);
        set_relay(green, 1);
        set_relay(blue, 1);
        sleep(3);
    }

    all_off(red, yellow, green, blue);
    ret = EXIT_SUCCESS;

cleanup:
    if (red)    gpiod_line_release(red);
    if (yellow) gpiod_line_release(yellow);
    if (green)  gpiod_line_release(green);
    if (blue)   gpiod_line_release(blue);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

