#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LOG_FILE "touch_relay.log"

static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_init(int handle) {
    if (i2cWriteByteData(handle, 0x80, 0x63) < 0) {
        log_message("Error: MPR121 reset failed");
        return -1;
    }
    gpioDelay(1000);
    if (i2cWriteByteData(handle, 0x5E, 0x00) < 0) {
        log_message("Error: MPR121 stop mode failed");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x5D, 0x01) < 0) {
        log_message("Error: MPR121 enable electrode 0 failed");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x41, 0x0A) < 0) {
        log_message("Error: MPR121 touch threshold failed");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x42, 0x08) < 0) {
        log_message("Error: MPR121 release threshold failed");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x5B, 0x21) < 0) {
        log_message("Error: MPR121 debounce failed");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x5C, 0x0D) < 0) {
