#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int set_output_line(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int count = 0;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (count == DEBOUNCE_READS) ? 1 : 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        if (flame_detected) {
            if (set_output_line(buzzer_line, 1) < 0 || set_output_line(led_line, 1) < 0) {
                fprintf(stderr, "Failed to activate outputs, exiting.\n");
                break;
            }
            if (log_event("Flame Detected") < 0) {
                fprintf(stderr, "Failed to log event, exiting.\n");
                break;
            }
            printf("Flame Detected!\n");

            while (program_running) {
                int val = gpiod_line_get_value(flame_line);
                if (val < 0) {
                    fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
                    break;
                }
                if (val == 1) break;
                usleep(POLL_INTERVAL_MS * 1000);
            }

            if (set_output_line(buzzer_line, 0) < 0 || set_output_line(led_line, 0) < 0) {
                fprintf(stderr, "Failed to deactivate outputs, exiting.\n");
                break;
            }
        }

        if (program_running) usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

