    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }
    return 0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to activate solenoid on GPIO%d\n", pin);
        return 1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

static int log_dispense(int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return 1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return 1;
    }
    fprintf(fp, "%s, Solenoid 1 (GPIO%d), Solenoid 2 (GPIO%d), %d ms\n",
            timestamp, SOLENOID_1_PIN, SOLENOID_2_PIN, duration_ms);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        int half_duration = DISPENSE_DURATION_MS / 2;

        if (activate_solenoid(SOLENOID_1_PIN, half_duration) != 0) {
            cleanup();
            return 1;
        }
        if (activate_solenoid(SOLENOID_2_PIN, half_duration) != 0) {
            cleanup();
            return 1;
        }

        if (log_dispense(DISPENSE_DURATION_MS) != 0) {
            cleanup();
            return 1;
        }

        if (running) {
            gpioDelay(DISPENSE_INTERVAL_S * 1000000);
        }
    }

    cleanup();
    printf("Pneumatic dispensing system stopped.\n");
    return 0;
}

