#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* Motor A connections */
#define MOTOR_A_FORWARD  17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE   24

/* Motor B connections */
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE   25

/* PID constants */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle avoidance parameters */
#define OBSTACLE_THRESHOLD 20.0
#define OBSTACLE_SPEED 127

/* PWM range (0-255) */
#define PWM_RANGE 255

/* Control loop period in microseconds (50 ms) */
#define LOOP_DELAY_US 50000

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* PID state */
static double integral = 0.0;
static double previous_error = 0.0;

/* Function prototypes */
static void signal_handler(int sig);
static void set_motor_speed(int motor, int speed);
static void stop_motors(void);
static double simulate_tilt_sensor(void);
static double simulate_distance_sensor(void);
static int calculate_motor_speeds(double tilt_error, double distance,
                                  int *motor_a_speed, int *motor_b_speed);
static void log_data(double tilt_error, double distance,
                     int motor_a_speed, int motor_b_speed);

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Set motor speed.
 * speed: -255..255 (negative = reverse)
 */
static void set_motor_speed(int motor, int speed)
{
    int forward_pin, backward_pin, enable_pin;

    switch (motor) {
    case 'A':
        forward_pin  = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin   = MOTOR_A_ENABLE;
        break;
    case 'B':
        forward_pin  = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin   = MOTOR_B_ENABLE;
        break;
    default:
        fprintf(stderr, "Invalid motor character: '%c'\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        speed = -speed;
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }

    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;

    gpioPWM(enable_pin, speed);
}

static void stop_motors(void)
{
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(MOTOR_A_ENABLE, 0);
    gpioPWM(MOTOR_B_ENABLE, 0);
}

/*
 * Simulate tilt sensor.
 * Returns a random float between -10.0 and 10.0 degrees.
 */
static double simulate_tilt_sensor(void)
{
    return ((double)rand() / (double)RAND_MAX) * 20.0 - 10.0;
}

/*
 * Simulate distance sensor.
 * Returns a random float between 2.0 and 400.0 cm.
 */
static double simulate_distance_sensor(void)
{
    return ((double)rand() / (double)RAND_MAX) * 400.0 + 2.0;
}

/*
 * Calculate motor speeds for PID control.
 * Returns 0 on success, -1 on invalid input.
 */
static int calculate_motor_speeds(double tilt_error, double distance,
                                  int *motor_a_speed, int *motor_b_speed)
{
    if (motor_a_speed == NULL || motor_b_speed == NULL)
        return -1;

    /* PID calculation */
    double proportional = KP * tilt_error;
    integral += KI * tilt_error;
    double derivative = KD * (tilt_error - previous_error);
    double output = proportional + integral + derivative;

    /* Clamp output to [-255, 255] */
    if (output > 255.0) output = 255.0;
    if (output < -255.0) output = -255.0;

    *motor_a_speed = (int)output;
    *motor_b_speed = (int)output;

    previous_error = tilt_error;

    return 0;
}

static void log_data(double tilt_error, double distance,
                     int motor_a_speed, int motor_b_speed)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void)
{
    int motor_a_speed = 0;
    int motor_b_speed = 0;
    double tilt_error, distance;

    /* Seed random number generator */
    srand((unsigned int)time(NULL));

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes */
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    /* Set PWM range */
    gpioSetPWMrange(MOTOR_A_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE);

    /* Open log file */
    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    /* Write CSV header */
    fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Main control loop */
    while (running) {
        tilt_error = simulate_tilt_sensor();
        distance = simulate_distance_sensor();

        /* Obstacle avoidance */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -OBSTACLE_SPEED;
            motor_b_speed = -OBSTACLE_SPEED;
        } else {
            if (calculate_motor_speeds(tilt_error, distance,
                                       &motor_a_speed, &motor_b_speed) != 0) {
                fprintf(stderr, "PID calculation failed\n");
                motor_a_speed = 0;
                motor_b_speed = 0;
            }
        }

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

