#include <pigpio.h>
#include <alsa/asoundlib.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_CHANNELS    1
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0

#define PWM_RANGE 1000
#define PWM_FREQ  1000

#define SINE_AMPLITUDE 500
#define SINE_FREQUENCY 100

#ifdef __linux__
#define ALSA_AVAILABLE 1
#else
#define ALSA_AVAILABLE 0
#endif

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_pwm(int pin, int value) {
    if (value < 0) value = 0;
    if (value > PWM_RANGE) value = PWM_RANGE;
    if (gpioPWM(pin, value) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d: %s\n", pin, pigpio_error(0));
        return -1;
    }
    return 0;
}

static void set_color(int r, int g, int b) {
    set_pwm(RED_PIN, r);
    set_pwm(GREEN_PIN, g);
    set_pwm(BLUE_PIN, b);
}

static void map_to_color(double rms, int *r, int *g, int *b) {
    double norm = rms / 255.0;
    if (norm > 1.0) norm = 1.0;

    double hue = 0.66 - 0.33 * norm;
    if (hue < 0.0) hue = 0.0;
    if (hue > 1.0) hue = 1.0;

    double s = 0.5 + 0.5 * norm;
    if (s < 0.0) s = 0.0;
    if (s > 1.0) s = 1.0;

    double v = 0.5 + 0.5 * norm;
    if (v < 0.0) v = 0.0;
    if (v > 1.0) v = 1.0;

    double h = hue * 6.0;
    int hi = (int)(h) % 6;
    double f = h - (double)hi;
    double p = v * (1.0 - s);
    double q = v * (1.0 - s * f);
    double t = v * (1.0 - s * (1.0 - f));

    double rf, gf, bf;
    switch (hi) {
        case 0: rf = v; gf = t; bf = p; break;
        case 1: rf = q; gf = v; bf = p; break;
        case 2: rf = p; gf = v; bf = t; break;
        case 3: rf = p; gf = q; bf = v; break;
        case 4: rf = t; gf = p; bf = v; break;
        default: rf = v; gf = p; bf = q; break;
    }

    *r = (int)(rf * PWM_RANGE);
    *g = (int)(gf * PWM_RANGE);
    *b = (int)(bf * PWM_RANGE);
}

