        goto fail;
    }

    unsigned int r = DEFAULT_SAMPLE_RATE;
    if (snd_pcm_hw_params_set_rate_near(*handle, params, &r, NULL) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(errno));
        goto fail;
    }
    *rate = (int)r;

    unsigned int frames = DEFAULT_PERIOD_SIZE;
    if (snd_pcm_hw_params_set_period_size_near(*handle, params, &frames, NULL) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n", snd_strerror(errno));
        goto fail;
    }

    if (snd_pcm_hw_params_set_periods(*handle, params, 2, 0) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_periods failed: %s\n", snd_strerror(errno));
