        fprintf(stderr, "ALSA initialization failed. Simulating sine wave.\n");
    } else {
        printf("ALSA initialized: device=default, rate=%d Hz, channels=%d\n", sample_rate, channels);
    }

    int period_size = DEFAULT_PERIOD_SIZE;
    short *audio_buffer = (short *)malloc((size_t)period_size * channels * sizeof(short));
    if (!audio_buffer) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        if (alsa_handle) snd_pcm_close(alsa_handle);
        gpioTerminate();
        return 1;
    }

    int sine_phase = 0;
    int sine_step = (SINE_FREQUENCY * 256) / sample_rate;
    if (sine_step == 0) sine_step = 1;

    while (g_running) {
