                fprintf(stderr, "Audio read error, continuing...\n");
                usleep(10000);
                continue;
            }

            double sum_sq = 0.0;
            for (int i = 0; i < period_size * channels; i++) {
                double s = (double)audio_buffer[i];
                sum_sq += s * s;
            }
            double rms = sqrt(sum_sq / (double)(period_size * channels));
            double scaled = rms * sensitivity;
            map_to_color(scaled, &r, &g, &b);
        } else {
            sine_phase = (sine_phase + sine_step) % 256;
            double sine_val = (double)sine_phase / 255.0 * 2.0 * M_PI;
            double amp = SINE_AMPLITUDE * (1.0 + sin(sine_val));
            map_to_color(amp, &r, &g, &b);
        }

        set_color(r, g, b);
        usleep(10000);
    }

    printf("\nShutting down...\n");
    set_color(0, 0, 0);
    free(audio_buffer);
    if (alsa_handle) snd_pcm_close(alsa_handle);
    gpioTerminate();
    return 0;
