#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 50400
#define STEP_DELAY_US 100000

static const int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LAMPS];
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %d\n", lamp_pins[i]);
            cleanup();
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "sunrise_sim", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %d\n", lamp_pins[i]);
            cleanup();
            return -1;
        }
    }
    return 0;
}

static void set_all_lamps(int value) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpiod_line_set_value(lines[i], value);
    }
}

static void sleep_until(time_t target) {
    while (time(NULL) < target && running) {
        usleep(100000);
    }
}

static void sunrise(void) {
    printf("Sunrise phase started\n");
    time_t start = time(NULL);
    int duty = 0;
    while (time(NULL) - start < SUNRISE_DURATION && running) {
        for (int i = 0; i < NUM_LAMPS; i++) {
            gpiod_line_set_value(lines[i], (duty % 2 == 0) ? 0 : 1);
        }
        duty++;
        usleep(STEP_DELAY_US);
    }
    set_all_lamps(1);
    printf("Sunrise phase complete\n");
}

static void daytime(void) {
    printf("Daytime phase started\n");
    time_t start = time(NULL);
    while (time(NULL) - start < DAYTIME_DURATION && running) {
        for (int i = 0; i < NUM_LAMPS; i++) {
            gpiod_line_set_value(lines[i], 0);
        }
        usleep(STEP_DELAY_US);
    }
    set_all_lamps(1);
    printf("Daytime phase complete\n");
}

static void sunset(void) {
    printf("Sunset phase started\n");
    time_t start = time(NULL);
    int duty = 0;
    while (time(NULL) - start < SUNSET_DURATION && running) {
        for (int i = 0; i < NUM_LAMPS; i++) {
            gpiod_line_set_value(lines[i], (duty % 2 == 0) ? 0 : 1);
        }
        duty++;
        usleep(STEP_DELAY_US);
    }
    set_all_lamps(1);
    printf("Sunset phase complete\n");
}

static void nighttime(void) {
    printf("Nighttime phase started\n");
    time_t start = time(NULL);
    while (time(NULL) - start < NIGHTTIME_DURATION && running) {
        for (int i = 0; i < NUM_LAMPS; i++) {
            gpiod_line_set_value(lines[i], 1);
        }
        usleep(STEP_DELAY_US);
    }
    set_all_lamps(1);
    printf("Nighttime phase complete\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    set_all_lamps(1);

    while (running) {
        time_t sunrise_start = time(NULL);
        sunrise();
        sleep_until(sunrise_start + SUNRISE_DURATION);

        time_t daytime_start = time(NULL);
        daytime();
        sleep_until(daytime_start + DAYTIME_DURATION);

        time_t sunset_start = time(NULL);
        sunset();
        sleep_until(sunset_start + SUNSET_DURATION);

        time_t nighttime_start = time(NULL);
        nighttime();
        sleep_until(nighttime_start + NIGHTTIME_DURATION);
    }

    cleanup();
    printf("Program terminated gracefully\n");
    return 0;
}

