#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define TIMESTAMP_FORMAT "%Y%m%d_%H%M%S"
#define TIMESTAMP_LEN 20

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, TIMESTAMP_FORMAT, timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE_PATH, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }
    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

static int record_video(const char *filename) {
    char command[512];
    int ret;

    ret = snprintf(command, sizeof(command),
                   "raspivid -o %s%s -t %d000", VIDEO_DIR, filename, VIDEO_DURATION);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: filename too long\n");
        return -1;
    }

    ret = system(command);
    if (ret == -1) {
        perror("Error executing raspivid");
        return -1;
    } else if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    } else if (!WIFEXITED(ret)) {
        fprintf(stderr, "raspivid terminated abnormally\n");
        return -1;
    }
    return 0;
}

int main(void) {
    char timestamp[TIMESTAMP_LEN];
    int last_state = 1;
    uint32_t last_trigger_tick = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d\n", MOTION_SENSOR_GPIO);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to install SIGINT handler");
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    while (program_running) {
        int current_state = gpioRead(MOTION_SENSOR_GPIO);
        uint32_t now_tick = gpioTick();

        if (current_state == 0 && last_state == 1) {
            if (now_tick - last_trigger_tick >= (uint32_t)(DEBOUNCE_DELAY_MS * 1000)) {
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    if (record_video(timestamp) == 0) {
                        if (log_motion_event(timestamp) == 0) {
                            printf("Motion detected at %s. Video recorded.\n", timestamp);
                        } else {
                            fprintf(stderr, "Failed to log motion event.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to record video.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to generate timestamp.\n");
                }
                last_trigger_tick = now_tick;
            }
        }
        last_state = current_state;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

