#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low -> 0x68) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_GYRO_XOUT_L  0x44
#define MPU6050_REG_GYRO_YOUT_H  0x45
#define MPU6050_REG_GYRO_YOUT_L  0x46
#define MPU6050_REG_GYRO_ZOUT_H  0x47
#define MPU6050_REG_GYRO_ZOUT_L  0x48

/* Sensitivity for ±250°/s range: 131 LSB per °/s */
#define GYRO_SENSITIVITY 131.0f

/* Sampling interval in microseconds (10 ms -> 100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum consecutive I2C errors before re-initialization */
#define MAX_I2C_ERRORS 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize MPU-6050: wake, set sample rate, set gyro range          */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    /* Wake up: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (wake): %s\n",
                strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake */

    /* Sample rate divider: 125 Hz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV: %s\n",
                strerror(errno));
        return -1;
    }

    /* Gyro full-scale range: ±250 °/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyroscope data (X_H, X_L, Y_H, Y_L, Z_H, Z_L)        */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    /*
     * i2cReadI2CBlockData performs a combined read: the register address
     * is sent first, then the data bytes are read back.
     */
    int bytes_read = i2cReadI2CBlockData(handle,
                                         MPU6050_REG_GYRO_XOUT_H,
                                         buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read returned %d bytes (expected 6): %s\n",
                bytes_read, strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw gyro data to degrees per second                         */
/* ------------------------------------------------------------------ */
static void convert_to_degps(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                             float *x_degps, float *y_degps, float *z_degps)
{
    *x_degps = (float)raw_x / GYRO_SENSITIVITY;
    *y_degps = (float)raw_y / GYRO_SENSITIVITY;
    *z_degps = (float)raw_z / GYRO_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Log one data row to CSV                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x_degps, float y_degps, float z_degps)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Warning: clock_gettime failed: %s\n",
                strerror(errno));
        return;
    }

    long millis = ts.tv_nsec / 1000000L;
    time_t now = ts.tv_sec;

    fprintf(fp, "%ld.%03ld,%.2f,%.2f,%.2f\n",
            (long)now, millis, x_degps, y_degps, z_degps);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mpu6050(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open gyro_log.csv: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("Vibration monitoring started. Press Ctrl+C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_gyro_data(g_i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            consecutive_errors = 0;

            float x_degps, y_degps, z_degps;
            convert_to_degps(raw_x, raw_y, raw_z,
                             &x_degps, &y_degps, &z_degps);

            log_data(g_log_file, x_degps, y_degps, z_degps);
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C error #%d\n", consecutive_errors);

            if (consecutive_errors >= MAX_I2C_ERRORS) {
                fprintf(stderr, "Too many I2C errors. Re-initializing...\n");
                i2cClose(g_i2c_handle);
                g_i2c_handle = -1;
                gpioDelay(100000); /* 100 ms settle */

                g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
                if (g_i2c_handle < 0) {
                    fprintf(stderr, "Re-open failed: %s\n",
                            strerror(errno));
                    break;
                }

                if (init_mpu6050(g_i2c_handle) < 0) {
                    fprintf(stderr, "Re-init failed.\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

