#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ADXL345_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_SEC 0.5f
#define ALARM_HOLD_SEC 5.0f
#define SAMPLE_INTERVAL_US 100000
#define SCALE_FACTOR 256.0f

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adxl345(int handle) {
    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL register\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening freefall.log\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

static void trigger_alarm(void) {
    gpioWrite(ALARM_GPIO, 1);
    time_sleep(ALARM_HOLD_SEC);
    gpioWrite(ALARM_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_adxl345(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("Freefall detection started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        float x, y, z;
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                printf("Freefall detected!\n");
                log_freefall(x, y, z);
                time_sleep(FREEFALL_DURATION_SEC);
                if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
                    if (detect_freefall(x, y, z)) {
                        printf("Freefall confirmed!\n");
                        trigger_alarm();
                    }
                }
            }
        }
        time_sleep(SAMPLE_INTERVAL_US / 1000000.0);
    }
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

