#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_MS 200
#define ECHO_TIMEOUT_US 100000
#define MAX_PULSE_US 23200
#define LOG_FILE "distance_log.txt"

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_state = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;
static FILE *log_file = NULL;

static void trigger_pulse(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        start_tick = tick;
        echo_state = 1;
        pthread_mutex_unlock(&pulse_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&pulse_mutex);
        end_tick = tick;
        echo_state = 2;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static int calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us > MAX_PULSE_US) return -1;
    return (int)((pulse_width_us / 2.0) / 29.1);
}

static void log_distance(int distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    if (log_file != NULL) {
        fprintf(log_file, "%ld,%d\n", (long)ts.tv_nsec, distance);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();

        uint32_t start_wait = 0;
        uint32_t end_wait = 0;
        int got_start = 0;
        int got_end = 0;

        for (int i = 0; i < 1000 && running; i++) {
            pthread_mutex_lock(&pulse_mutex);
            if (echo_state == 1) {
                start_wait = start_tick;
                got_start = 1;
            }
            if (echo_state == 2) {
                end_wait = end_tick;
                got_end = 1;
            }
            pthread_mutex_unlock(&pulse_mutex);
            gpioDelay(1000);
        }

        if (!running) break;

        if (!got_start || !got_end) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue;
        }

        uint32_t pulse_width_us;
        if (end_wait >= start_wait) {
            pulse_width_us = end_wait - start_wait;
        } else {
            pulse_width_us = (0xFFFFFFFF - start_wait) + end_wait + 1;
        }

        if (pulse_width_us > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Echo pulse too long (%u us)\n", pulse_width_us);
            continue;
        }

        int distance = calculate_distance(pulse_width_us);
        if (distance < 0) {
            fprintf(stderr, "Distance out of range (%u us)\n", pulse_width_us);
            continue;
        }

        log_distance(distance);
        printf("Distance: %d cm\n", distance);

        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000);
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    printf("Program terminated.\n");
    return 0;
}

