#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define SENSITIVITY 16384.0f
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    float freefall_threshold;
    float impact_threshold;
} config_t;

static config_t config = {
    .freefall_threshold = DEFAULT_FREEFALL_THRESHOLD,
    .impact_threshold = DEFAULT_IMPACT_THRESHOLD
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %d\n", value, reg, result);
    }
    return result;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from reg 0x%02X: %d\n", reg, result);
    }
    return result;
}

static int init_lis3dh(int handle) {
    if (i2c_write_byte(handle, CTRL_REG1, 0x77) < 0) return -1;
    if (i2c_write_byte(handle, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (i2c_read_block(handle, OUT_X_L, buf, 6) == 6) {
            int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
            int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
            int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
            *x = (float)raw_x / SENSITIVITY;
            *y = (float)raw_y / SENSITIVITY;
            *z = (float)raw_z / SENSITIVITY;
            return 0;
        }
        retries--;
        if (retries > 0) gpioDelay(1000);
    }
    return -1;
}

static int detect_freefall(float x, float y, float z, float threshold) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    return (magnitude < threshold) ? 1 : 0;
}

static int detect_impact(float x, float y, float z, float threshold) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    return (magnitude > threshold) ? 1 : 0;
}

static void activate_buzzer(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(1000000);
    gpioWrite(gpio, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc > 1) config.freefall_threshold = atof(argv[1]);
    if (argc > 2) config.impact_threshold = atof(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize LIS3DH\n");
        cleanup();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    int freefall_active = 0;

    while (running) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z, config.freefall_threshold)) {
                if (!freefall_active) {
                    printf("Freefall detected!\n");
                    freefall_active = 1;
                }
            } else if (detect_impact(x, y, z, config.impact_threshold)) {
                printf("Impact detected!\n");
                activate_buzzer(BUZZER_GPIO);
            } else {
                freefall_active = 0;
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

