#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

/* Motor 1 (X-axis) pins */
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

/* Motor 2 (Y-axis) pins */
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEPS_PER_REV 2048
#define STEP_DELAY_US 1000
#define STEPS_PER_MM 10
#define SQUARE_SIDE_MM 50

static volatile sig_atomic_t running = 1;

static const int motor1_pins[4] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4};
static const int motor2_pins[4] = {MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};

/* Single-coil wave drive sequence for 28BYJ-48 */
static const int wave_seq[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_pins(const int pins[4], int step) {
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(pins[i], wave_seq[step][i]) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static int move_motor(const int pins[4], int steps, int direction) {
    int step_count = 0;
    int current_step = 0;

    while (step_count < steps && running) {
        if (set_motor_pins(pins, current_step) < 0) {
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
        current_step = (current_step + direction + 4) % 4;
        step_count++;
    }
    return 0;
}

static int move_x(int steps) {
    return move_motor(motor1_pins, steps, 1);
}

static int move_y(int steps) {
    return move_motor(motor2_pins, steps, 1);
}

static int draw_square(void) {
    int steps = SQUARE_SIDE_MM * STEPS_PER_MM;

    if (move_x(steps) < 0) return -1;
    if (move_y(steps) < 0) return -1;
    if (move_x(-steps) < 0) return -1;
    if (move_y(-steps) < 0) return -1;
    return 0;
}

static void stop_motors(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(motor1_pins[i], 0);
        gpioWrite(motor2_pins[i], 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(motor1_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", motor1_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetMode(motor2_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", motor2_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Drawing a square. Press Ctrl+C to stop early.\n");

    if (draw_square() < 0) {
        fprintf(stderr, "Error: Motor movement failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    stop_motors();
    gpioTerminate();
    printf("Square drawn successfully.\n");
    return EXIT_SUCCESS;
}

