#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000
#define SHUTDOWN_COMMAND "sudo shutdown -h now"

#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_lis3dh(void) {
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = *y = *z = 0;
        return -1;
    }
    *x = (int16_t)((buffer[1] << 8) | buffer[0]) >> 4;
    *y = (int16_t)((buffer[3] << 8) | buffer[2]) >> 4;
    *z = (int16_t)((buffer[5] << 8) | buffer[4]) >> 4;
    return 0;
}

static float convert_to_g(int16_t raw_value) {
    return (float)raw_value * 0.0009765625f;
}

static int log_event(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fclose(fp);
    return 0;
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    int ret = system(SHUTDOWN_COMMAND);
    if (ret == -1) {
        fprintf(stderr, "Error executing shutdown command\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

