#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define POLL_INTERVAL_US   10000
#define ALERT_DURATION_S   2
#define NO_LINE_THRESHOLD  5

#define CONSUMER_NAME      "line_follower"

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t program_running = 1;
static CircularBuffer sensor_buffer;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void init_circular_buffer(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void add_to_buffer(CircularBuffer *buf, SensorData data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void print_buffer(const CircularBuffer *buf) {
    printf("--- Sensor Buffer (%d entries) ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("[%d] L:%d C:%d R:%d\n", i,
               buf->data[idx].left, buf->data[idx].center, buf->data[idx].right);
    }
    printf("-------------------------------\n");
}

static void move_forward(void) {
    printf("Moving forward\n");
}

static void turn_left(void) {
    printf("Turning left\n");
}

static void turn_right(void) {
    printf("Turning right\n");
}

static void stop_motion(void) {
    printf("Stopping\n");
}

static void trigger_alert(void) {
    printf("ALERT: No line detected for %d consecutive readings\n", NO_LINE_THRESHOLD);
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
        return;
    }
    sleep(ALERT_DURATION_S);
    if (gpiod_line_set_value(alert_line, 0) < 0) {
        fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    struct gpiod_line *alert_line = NULL;
    int ret = EXIT_FAILURE;

    init_circular_buffer(&sensor_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, CONSUMER_NAME) < 0 ||
        gpiod_line_request_input(center_line, CONSUMER_NAME) < 0 ||
        gpiod_line_request_input(right_line, CONSUMER_NAME) < 0) {
        fprintf(stderr, "Failed to request sensor lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(alert_line, CONSUMER_NAME, 0) < 0) {
        fprintf(stderr, "Failed to request alert line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    int no_line_count = 0;

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        SensorData data = {left_val, center_val, right_val};
        add_to_buffer(&sensor_buffer, data);

        if (center_val == 0) {
            no_line_count++;
        } else {
            no_line_count = 0;
        }

        if (no_line_count >= NO_LINE_THRESHOLD) {
            trigger_alert();
            no_line_count = 0;
        }

        if (center_val == 0) {
            move_forward();
        } else if (left_val == 0) {
            turn_left();
        } else if (right_val == 0) {
            turn_right();
        } else {
            stop_motion();
        }

        print_buffer(&sensor_buffer);
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alert_line) gpiod_line_set_value(alert_line, 0);
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (alert_line) gpiod_line_release(alert_line);
    if (chip) gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return ret;
}

