#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD_MT 5.0f
#define SAMPLE_INTERVAL_US 100000
#define POLL_TIMEOUT_MS 50
#define POLL_DELAY_US 1000
#define LOG_FILE "magnetic_events.txt"

#define SI7210_REG_MEAS_STATUS 0xC1
#define SI7210_REG_FIELD_DATA 0xC0
#define SI7210_CMD_START_MEAS 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    }
    fclose(fp);
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        log_event("I2C open failed");
        return -1;
    }
    return 0;
}

static int read_field_raw(int16_t *raw) {
    int status = i2cReadByteData(i2c_handle, SI7210_REG_MEAS_STATUS);
    if (status < 0) {
        fprintf(stderr, "i2cReadByteData status failed: %d\n", status);
        return -1;
    }
    if (status != 0x00) {
        fprintf(stderr, "Measurement not ready (status=0x%02X)\n", status);
        return -1;
    }
    int lsb = i2cReadByteData(i2c_handle, SI7210_REG_FIELD_DATA);
    if (lsb < 0) {
        fprintf(stderr, "i2cReadByteData field LSB failed: %d\n", lsb);
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, SI7210_REG_FIELD_DATA + 1);
    if (msb < 0) {
        fprintf(stderr, "i2cReadByteData field MSB failed: %d\n", msb);
        return -1;
    }
    *raw = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int start_measurement(void) {
    int rc = i2cWriteByteData(i2c_handle, SI7210_REG_MEAS_STATUS, SI7210_CMD_START_MEAS);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData start failed: %d\n", rc);
        return -1;
    }
    return 0;
}

static int wait_for_measurement(void) {
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        int status = i2cReadByteData(i2c_handle, SI7210_REG_MEAS_STATUS);
        if (status < 0) {
            fprintf(stderr, "i2cReadByteData poll failed: %d\n", status);
            return -1;
        }
        if (status == 0x00) return 0;
        gpioDelay(POLL_DELAY_US);
    }
    fprintf(stderr, "Measurement timeout\n");
    return -1;
}

static int read_field_mt_x100(int16_t *raw_out) {
    if (start_measurement() < 0) return -1;
    if (wait_for_measurement() < 0) return -1;
