#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int new_socket = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (new_socket >= 0) {
        close(new_socket);
        new_socket = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d to LOW\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int setup_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    printf("Listening on port %d...\n", PORT);
    return 0;
}

static void handle_client(int socket_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t valread;

    while (running) {
        memset(buffer, 0, BUFFER_SIZE);
        valread = read(socket_fd, buffer, BUFFER_SIZE - 1);
        if (valread > 0) {
            buffer[valread] = '\0';
            char *command = strtok(buffer, "\r\n");
            while (command != NULL) {
                char *endptr;
                long val = strtol(command, &endptr, 10);
                if (*endptr == '\0') {
                    if (val == 1) {
                        if (gpioWrite(GPIO_PIN, 1) == 0) {
                            log_event("Relay turned ON");
                            printf("Relay turned ON\n");
                        } else {
                            log_event("Error: Failed to turn ON relay");
                            fprintf(stderr, "Error: Failed to turn ON relay\n");
                        }
                    } else if (val == 0) {
                        if (gpioWrite(GPIO_PIN, 0) == 0) {
                            log_event("Relay turned OFF");
                            printf("Relay turned OFF\n");
                        } else {
                            log_event("Error: Failed to turn OFF relay");
                            fprintf(stderr, "Error: Failed to turn OFF relay\n");
                        }
                    } else {
                        log_event("Invalid command received");
                        fprintf(stderr, "Invalid command received: %s\n", command);
                    }
                } else {
                    if (strcasecmp(command, "ON") == 0) {
                        if (gpioWrite(GPIO_PIN, 1) == 0) {
                            log_event("Relay turned ON");
                            printf("Relay turned ON\n");
                        } else {
                            log_event("Error: Failed to turn ON relay");
                            fprintf(stderr, "Error: Failed to turn ON relay\n");
                        }
                    } else if (strcasecmp(command, "OFF") == 0) {
                        if (gpioWrite(GPIO_PIN, 0) == 0) {
                            log_event("Relay turned OFF");
                            printf("Relay turned OFF\n");
                        } else {
                            log_event("Error: Failed to turn OFF relay");
                            fprintf(stderr, "Error: Failed to turn OFF relay\n");
                        }
                    } else {
                        log_event("Invalid command received");
                        fprintf(stderr, "Invalid command received: %s\n", command);
                    }
                }
                command = strtok(NULL, "\r\n");
            }
        } else if (valread == 0) {
            printf("Client disconnected\n");
            log_event("Client disconnected");
            break;
        } else {
            perror("read failed");
            log_event("Error: read failed");
            break;
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (setup_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    if (setup_socket() != 0) {
        cleanup();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_address;
        socklen_t addrlen = sizeof(client_address);

        new_socket = accept(server_fd, (struct sockaddr *)&client_address, &addrlen);
        if (new_socket < 0) {
            if (running) {
                perror("accept failed");
                log_event("Error: accept failed");
            }
            continue;
        }

        printf("Connection accepted from %s:%d\n",
               inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        log_event("Connection accepted");

        handle_client(new_socket);

        close(new_socket);
        new_socket = -1;
    }

    cleanup();
    return 0;
}

