/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F liquid flow monitor
 * Library : pigpio (I2C + GPIO)
 * Sensors : 2x Sensirion SLF3S-1300F on I2C bus 1 (0x08, 0x09)
 * Relay   : GPIO 18 (BCM), active-high
 * Flow    : below 5.0 ml/min → relay ON
 *           above/equal 5.0 ml/min → relay OFF
 * Log     : flow_log.txt (append)
 *
 * Build   : gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run     : sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define RELAY_GPIO           18
#define FLOW_THRESHOLD_ML_MIN 5.0f
#define POLL_DELAY_US        100000          /* 100 ms */
#define LOG_FILE             "flow_log.txt"
#define SCALE_FACTOR_ML_MIN   (1.0f / 1500.0f)

/* SLF3S-1300F: start continuous measurement, no averaging */
static const uint8_t SLF3S_START_CMD[2] = { 0x36, 0x08 };

/* ----------------------------- Globals ----------------------------------- */
static int  i2c_h1 = -1;
static int  i2c_h2 = -1;
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static void  cleanup(void);
static int   init_i2c(void);
static int   init_relay(void);
static int   send_start_cmd(int handle);
static int   read_flow(int handle, float *flow_out);
static void  control_relay(float f1, float f2);
static void  log_flow(float f1, float f2);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (i2c_h1 >= 0) {
        i2cClose(i2c_h1);
        i2c_h1 = -1;
    }
    if (i2c_h2 >= 0) {
        i2cClose(i2c_h2);
        i2c_h2 = -1;
    }
    /* Ensure relay is off before terminating pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
    }
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_h1 < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(0x%02X) failed: %d\n", SENSOR1_ADDR, i2c_h1);
        return -1;
    }

    i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_h2 < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(0x%02X) failed: %d\n", SENSOR2_ADDR, i2c_h2);
        i2cClose(i2c_h1);
        i2c_h1 = -1;
        return -1;
    }
    return 0;
}

/* ----------------------------- Relay init --------------------------------- */
static int init_relay(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, OUTPUT) failed\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

/* ----------------------------- Send start command -------------------------- */
static int send_start_cmd(int handle)
{
    int rc = i2cWriteDevice(handle, (char *)SLF3S_START_CMD, 2);
    if (rc != 0) {
        fprintf(stderr, "[WARN] i2cWriteDevice(handle=%d) returned %d\n", handle, rc);
        return -1;
    }
    return 0;
}

/* ----------------------------- CRC-8 (Sensirion spec) ---------------------- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- Read flow rate ------------------------------ */
static int read_flow(int handle, float *flow_out)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "[WARN] i2cReadDevice(handle=%d) returned %d\n", handle, rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d (calc=0x%02X, got=0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR_ML_MIN;
    return 0;
}

/* ----------------------------- Relay control ------------------------------- */
static void control_relay(float f1, float f2)
{
    int below = (f1 < FLOW_THRESHOLD_ML_MIN) || (f2 < FLOW_THRESHOLD_ML_MIN);
    if (gpioWrite(RELAY_GPIO, below ? 1 : 0) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", RELAY_GPIO, below ? 1 : 0);
    }
}

/* ----------------------------- Logging ------------------------------------- */
static void log_flow(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[WARN] Cannot open %s: ", LOG_FILE);
        perror("");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[WARN] clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Main ---------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
