        int ok1 = read_flow(i2c_h1, &f1);
        int ok2 = read_flow(i2c_h2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            control_relay(f1, f2);
            log_flow(f1, f2);
            printf("S1: %.2f ml/min | S2: %.2f ml/min | Relay: %s\n",
                   f1, f2,
                   (f1 < FLOW_THRESHOLD_ML_MIN || f2 < FLOW_THRESHOLD_ML_MIN)
                   ? "ON" : "OFF");
        } else {
