#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT1_PIN 23
#define MOTOR_INPUT2_PIN 24

#define POLL_INTERVAL_US 200000   /* 200 ms */
#define MOTOR_RUN_US 5000000      /* 5 s   */
#define RAIN_THRESHOLD 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        syslog(LOG_WARNING, "gpioWrite(%u, %u) failed", gpio, level);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    if (safe_write(MOTOR_ENABLE_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT1_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT2_PIN, 0) != 0) return -1;
    return 0;
}

static int motor_close(void)
{
    if (safe_write(MOTOR_INPUT1_PIN, 1) != 0) return -1;
    if (safe_write(MOTOR_INPUT2_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_ENABLE_PIN, 1) != 0) return -1;
    return 0;
}

static int motor_open(void)
{
    if (safe_write(MOTOR_INPUT1_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT2_PIN, 1) != 0) return -1;
    if (safe_write(MOTOR_ENABLE_PIN, 1) != 0) return -1;
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Rain-actuated window controller starting");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        goto fail_gpio;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        goto fail_gpio;
    }
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_INPUT1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_INPUT2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_PINS) failed");
        goto fail_gpio;
    }

    if (motor_stop() != 0) {
        syslog(LOG_ERR, "Initial motor_stop failed");
        goto fail_gpio;
    }

    int rain_count = 0;
    int last_rain = gpioRead(RAIN_SENSOR_PIN);
    if (last_rain < 0) {
        syslog(LOG_ERR, "Initial gpioRead(RAIN_SENSOR_PIN) failed");
        goto fail_gpio;
    }

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN_SENSOR_PIN) failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain == 0) {
            rain_count++;
            if (rain_count >= RAIN_THRESHOLD) {
                syslog(LOG_INFO, "Rain detected (%d consecutive polls)", rain_count);
                if (motor_close() != 0) {
                    syslog(LOG_ERR, "Failed to start motor close sequence");
                } else {
                    syslog(LOG_INFO, "Motor close sequence started");
                    gpioDelay(MOTOR_RUN_US);
                    if (motor_stop() != 0) {
                        syslog(LOG_ERR, "Failed to stop motor after run");
                    } else {
                        syslog(LOG_INFO, "Motor stopped");
                    }
                }
                rain_count = 0;
            }
        } else {
            rain_count = 0;
        }

        last_rain = rain;
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;

fail_gpio:
    gpioTerminate();
    closelog();
    return EXIT_FAILURE;
}

