                    } else {
                        syslog(LOG_INFO, "Motor stopped");
                    }
                }
                rain_count = 0;
            }
        } else {
            rain_count = 0;
        }

        last_rain = rain;
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;

fail_gpio:
    gpioTerminate();
    closelog();
    return EXIT_FAILURE;
}

