#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    200000   /* 200 ms */
#define POLL_US        10000    /* 10 ms  */
#define STOP_PULSE_US  0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) != 0) {
        fprintf(stderr, "gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static int lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, LOCK_PULSE_US) != 0)
        return -1;
    return 0;
}

static int unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, UNLOCK_PULSE_US) != 0)
        return -1;
    return 0;
}

static int stop_servo(void)
{
    printf("Stopping servo...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, STOP_PULSE_US) != 0)
        return -1;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO 21 and 22 as inputs with internal pull-ups. */
    if (gpioSetMode(21, PI_INPUT) != 0 ||
        gpioSetMode(22, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button GPIO modes\n");
        stop_servo();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(21, PI_PUD_UP);
    gpioSetPullUpDown(22, PI_PUD_UP);

    /* Ensure servo is stopped at startup. */
    if (stop_servo() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready.\n");
    printf("  GPIO 21 -> Lock   (pulse %d us)\n", LOCK_PULSE_US);
    printf("  GPIO 22 -> Unlock (pulse %d us)\n", UNLOCK_PULSE_US);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_lock_state   = 0;
    int last_unlock_state = 0;

    while (g_running) {
        int lock_pressed   = gpioRead(21) == 0;   /* pulled to ground */
        int unlock_pressed = gpioRead(22) == 0;   /* pulled to ground */

        if (lock_pressed && !last_lock_state) {
            if (lock_door() != 0)
                fprintf(stderr, "Failed to lock door\n");
            gpioDelay(DEBOUNCE_US);
        }
        last_lock_state = lock_pressed;

        if (unlock_pressed && !last_unlock_state) {
            if (unlock_door() != 0)
                fprintf(stderr, "Failed to unlock door\n");
            gpioDelay(DEBOUNCE_US);
        }
        last_unlock_state = unlock_pressed;

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: stop servo, release pigpio resources. */
    stop_servo();
    gpioTerminate();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

