#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN      4
#define FLOODLIGHT_PIN 17
#define LOG_FILE     "security_log.txt"
#define FLOODLIGHT_DURATION_SEC 60
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s: %s\n", ts, event_type, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_floodlight(void)
{
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", FLOODLIGHT_PIN);
        return -1;
    }
    return 0;
}

static int deactivate_floodlight(void)
{
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", FLOODLIGHT_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    deactivate_floodlight();
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (deactivate_floodlight() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Smart Security Light running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", PIR_PIN);
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected! Activating floodlight for %d seconds.\n",
                   FLOODLIGHT_DURATION_SEC);

            if (activate_floodlight() != 0) {
                break;
            }

            if (log_event("Motion Detected", "Floodlight activated") != 0) {
                fprintf(stderr, "Warning: failed to log motion event\n");
            }

            /*
             * Sleep in 100 ms increments so SIGINT/SIGTERM is caught
             * promptly and cleanly turned off.
             */
            for (int i = 0; i < FLOODLIGHT_DURATION_SEC * 10 && g_running; i++) {
                gpioDelay(POLL_DELAY_US);
            }

            if (deactivate_floodlight() != 0) {
                break;
            }

            if (log_event("Floodlight Deactivated",
                          "Floodlight deactivated after 60 seconds") != 0) {
                fprintf(stderr, "Warning: failed to log deactivation event\n");
            }

            /*
             * Ensure the PIR is cleared before the next activation window.
             * PIRs typically have a settle/debounce delay after a trigger.
             */
            gpioDelay(500000);  /* 500 ms */
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

