#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS 0x00
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_E0TTH 0x41
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Baseline filtering: MHD/NHD/NCL/FDL */
    if (mpr121_write_reg(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_R, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=00 (6 samples), SFI=10 (4 samples), CDT=00 (1us) */
    if (mpr121_write_reg(handle, 0x2C, 0x24) < 0) return -1;

    /* Auto-config: enable 3.3V, 0.5C, 16uA, 0.5us */
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG1, 0x00) < 0) return -1;

    /* Upper/lower/target limits for electrode 0 */
    if (mpr121_write_reg(handle, MPR121_USL, 0xC0) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_LSL, 0x80) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_TL, 0xB0) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(int handle) {
    int rc = i2cReadWordData(handle, MPR121_TOUCHSTATUS);
    if (rc < 0) {
        fprintf(stderr, "Failed to read touch status: %s\n", pigpio_error(rc));
        return -1;
    }
    /* pigpio returns low byte first; MPR121 touch status is 12 bits */
    return (rc & 0x0FFF);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    bool relay_state = false;
    bool last_touch = false;

    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Sensor read error; retrying in 100 ms\n");
            gpioDelay(100000);
            continue;
        }

        bool touch_0 = (touch_status & 0x0001) != 0;

        if (touch_0 && !last_touch) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state ? 1 : 0) < 0) {
                fprintf(stderr, "Failed to write relay GPIO\n");
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            fflush(stdout);
            gpioDelay(200000); /* 200 ms debounce */
        }

        last_touch = touch_0;
        gpioDelay(50000); /* 50 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

