#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <stdarg.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_PWM_FREQ_HZ 50
#define SERVO_PWM_PERIOD_US (1000000 / SERVO_PWM_FREQ_HZ)
#define SERVO_PWM_STEP_US (SERVO_PWM_PERIOD_US / 100)
#define SERVO_PWM_STEPS 100
#define SERVO_PWM_STEP_DELAY_US 1000
#define SERVO_PWM_STOP_US 1500
#define SERVO_PWM_STOP_STEPS 75
#define SERVO_PWM_STOP_DELAY_US 1000
#define BUFFER_SIZE 1024
#define PORT 5000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t servo_pwm_thread;
static int servo_pwm_thread_created = 0;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);

    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (servo_pwm_thread_created) {
        pthread_cancel(servo_pwm_thread);
        pthread_join(servo_pwm_thread, NULL);
        servo_pwm_thread_created = 0;
    }
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void *servo_pwm_thread_func(void *arg) {
    (void)arg;
    int current_step = 0;
    int direction = 1;

    while (running) {
        int pulse_width = SERVO_PWM_STOP_US;
        if (current_step > 0 && current_step < SERVO_PWM_STEPS) {
            int angle = (current_step * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) / SERVO_PWM_STEPS) + SERVO_MIN_ANGLE;
            pulse_width = SERVO_MIN_PULSE_US + (angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / SERVO_MAX_ANGLE);
        }

        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_message(LOG_ERR, "Failed to set servo line high: %s", strerror(errno));
            break;
        }
        usleep(pulse_width);

        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_message(LOG_ERR, "Failed to set servo line low: %s", strerror(errno));
            break;
        }
        usleep(SERVO_PWM_PERIOD_US - pulse_width);

        current_step += direction;
        if (current_step >= SERVO_PWM_STEPS) {
            current_step = SERVO_PWM_STEPS - 1;
            direction = -1;
        } else if (current_step <= 0) {
            current_step = 0;
            direction = 1;
        }
    }

    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
    }
    return NULL;
}

static void set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    if (!servo_pwm_thread_created) {
        if (pthread_create(&servo_pwm_thread, NULL, servo_pwm_thread_func, NULL) != 0) {
            log_message(LOG_ERR, "Failed to create servo PWM thread: %s", strerror(errno));
            return;
        }
        servo_pwm_thread_created = 1;
    }

    int current_step = (angle - SERVO_MIN_ANGLE) * SERVO_PWM_STEPS / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE);
    if (current_step < 0) current_step = 0;
    if (current_step > SERVO_PWM_STEPS) current_step = SERVO_PWM_STEPS;

    log_message(LOG_INFO, "Setting servo to angle %d (step %d)", angle, current_step);
}

static int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
        return -1;
    }
    return value;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t valread;

    while ((valread = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[valread] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';

        char *command = strtok(buffer, " ");
        if (command == NULL) {
            log_message(LOG_WARNING, "Invalid command received: %s", buffer);
            continue;
        }

        if (strcmp(command, "SERVO") == 0) {
            char *angle_str = strtok(NULL, " ");
            if (angle_str == NULL) {
                log_message(LOG_WARNING, "SERVO command requires an angle");
                continue;
            }
            int angle = atoi(angle_str);
            if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
                log_message(LOG_WARNING, "Invalid angle %d for SERVO command", angle);
                continue;
            }
            set_servo_angle(angle);
            log_message(LOG_INFO, "Received SERVO command: %d", angle);
        } else if (strcmp(command, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value >= 0) {
                char response[64];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                if (send(client_socket, response, strlen(response), 0) < 0) {
                    log_message(LOG_ERR, "Failed to send PIR response: %s", strerror(errno));
                }
            } else {
                log_message(LOG_ERR, "Failed to read PIR sensor");
            }
            log_message(LOG_INFO, "Received PIR command");
        } else {
            log_message(LOG_WARNING, "Unknown command: %s", command);
        }
    }

    if (valread == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (valread < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
    }

    close(client_socket);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen("security.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (new_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_message(LOG_INFO, "New connection from %s", client_ip);

        handle_client(new_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

