    int current_step = (angle - SERVO_MIN_ANGLE) * SERVO_PWM_STEPS / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE);
    if (current_step < 0) current_step = 0;
    if (current_step > SERVO_PWM_STEPS) current_step = SERVO_PWM_STEPS;

    log_message(LOG_INFO, "Setting servo to angle %d (step %d)", angle, current_step);
}

static int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
        return -1;
    }
    return value;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t valread;

    while ((valread = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[valread] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';

        char *command = strtok(buffer, " ");
        if (command == NULL) {
            log_message(LOG_WARNING, "Invalid command received: %s", buffer);
            continue;
        }

        if (strcmp(command, "SERVO") == 0) {
            char *angle_str = strtok(NULL, " ");
            if (angle_str == NULL) {
                log_message(LOG_WARNING, "SERVO command requires an angle");
                continue;
            }
            int angle = atoi(angle_str);
            if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
                log_message(LOG_WARNING, "Invalid angle %d for SERVO command", angle);
                continue;
            }
            set_servo_angle(angle);
            log_message(LOG_INFO, "Received SERVO command: %d", angle);
        } else if (strcmp(command, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value >= 0) {
                char response[64];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                if (send(client_socket, response, strlen(response), 0) < 0) {
                    log_message(LOG_ERR, "Failed to send PIR response: %s", strerror(errno));
                }
            } else {
                log_message(LOG_ERR, "Failed to read PIR sensor");
            }
            log_message(LOG_INFO, "Received PIR command");
        } else {
            log_message(LOG_WARNING, "Unknown command: %s", command);
        }
    }

    if (valread == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (valread < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
    }

    close(client_socket);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen("security.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (new_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_message(LOG_INFO, "New connection from %s", client_ip);

        handle_client(new_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

