    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK HIGH: %s", strerror(errno));
            return -1;
        }
        usleep(1);
        value <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) {
            syslog(LOG_ERR, "Failed to read DOUT: %s", strerror(errno));
            return -1;
        }
        if (bit) value |= 1;
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK LOW: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    /* 25th pulse: select Channel A, Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) return -1;
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) return -1;
    usleep(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (value & 0x800000) value |= 0xFF000000;
    *out_value = (int32_t)value;
    return 0;
}

static float calculate_weight(int32_t raw, float scale, int32_t tare_offset) {
    return (float)(raw - tare_offset) / scale;
}

static int32_t average_readings(struct gpiod_line *dout, struct gpiod_line *sck, int num_readings) {
    int32_t sum = 0;
    for (int i = 0; i < num_readings; i++) {
        int32_t val;
        if (read_hx711(dout, sck, &val) != 0) {
            syslog(LOG_ERR, "Failed to read HX711 on iteration %d", i + 1);
            return 0;
        }
        sum += val;
        usleep(10000);
    }
    return sum / num_readings;
}

static int tare_sensor(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *tare_offset) {
    syslog(LOG_INFO, "Starting tare (averaging %d readings)...", TARE_READINGS);
    int32_t offset = average_readings(dout, sck, TARE_READINGS);
    syslog(LOG_INFO, "Tare complete. Offset: %d", offset);
    *tare_offset = offset;
    return 0;
}

static int control_solenoid(struct gpiod_line *solenoid, int duration_ms) {
    if (gpiod_line_set_value(solenoid, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(solenoid, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD_GRAMS;
    float scale = DEFAULT_SCALE_FACTOR;
    int solenoid_duration = DEFAULT_SOLENOID_DURATION_MS;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atof(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            solenoid_duration = atoi(argv[++i]);
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor (threshold=%.2f, scale=%.2f)", threshold, scale);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_LINE);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_LINE);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_LINE);

    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int32_t tare_offset = 0;
    if (tare_sensor(dout, sck, &tare_offset) != 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        goto cleanup;
    }

    syslog(LOG_INFO, "Weight monitoring started. Threshold: %.2f grams, Scale: %.2f", threshold, scale);

    while (program_running) {
        int32_t raw_weight = 0;
        int retries = 0;
        bool read_ok = false;

        while (retries < MAX_RETRIES && program_running) {
            if (read_hx711(dout, sck, &raw_weight) == 0) {
                read_ok = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) usleep(100000);
        }

        if (!read_ok) {
            syslog(LOG_ERR, "Failed to read HX711 after %d retries, exiting", MAX_RETRIES);
            break;
        }

        float weight = calculate_weight(raw_weight, scale, tare_offset);
        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold (%.2f > %.2f), activating solenoid", weight, threshold);
            if (control_solenoid(solenoid, solenoid_duration) != 0) {
                syslog(LOG_ERR, "Solenoid control failed");
            }
        }

        usleep(500000);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down...");
    gpiod_line_set_value(solenoid, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return 0;
}

