/*
 * relay_controller.c — MQTT-controlled relay on Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control on localhost:1883 and drives GPIO17
 * (BCM 17, physical pin 11) HIGH for "ON" and LOW for "OFF".
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *               -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define MQTT_QOS       0
#define MQTT_KEEPALIVE 60
#define GPIO_PIN       17          /* BCM 17, physical pin 11 */
#define RECONNECT_DELAY 5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                        int result, int rc, const char *msg)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d (rc=%d)",
               MQTT_HOST, MQTT_PORT, rc);

        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Subscribe failed: %s", mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s (rc=%d)",
               msg ? msg : "unknown", rc);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata,
                           int rc)
{
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d)", rc);
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message on %s", message->topic);
        return;
    }

    /* NUL-terminate payload for safe string handling */
    char payload[256];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) != 0)
            syslog(LOG_ERR, "Failed to set GPIO%d HIGH", GPIO_PIN);
        else
            syslog(LOG_INFO, "Relay ON (GPIO%d HIGH)", GPIO_PIN);
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) != 0)
            syslog(LOG_ERR, "Failed to set GPIO%d LOW", GPIO_PIN);
        else
            syslog(LOG_INFO, "Relay OFF (GPIO%d LOW)", GPIO_PIN);
    } else {
        syslog(LOG_ERR, "Invalid MQTT payload '%s' on %s",
               payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GPIO_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Relay OFF at startup */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO%d LOW", GPIO_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- mosquitto init --- */
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    /* --- connect & retry loop --- */
    while (g_running) {
        int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT,
                                   MQTT_KEEPALIVE);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_connect failed: %s",
                   mosquitto_strerror(rc));
            sleep(RECONNECT_DELAY);
            continue;
        }

        rc = mosquitto_loop_start(g_mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop_start failed: %s",
                   mosquitto_strerror(rc));
            mosquitto_disconnect(g_mosq);
            sleep(RECONNECT_DELAY);
            continue;
        }

        /* Wait for signal or loop error */
        while (g_running)
            sleep(1);

        mosquitto_loop_stop(g_mosq, false);
        mosquitto_disconnect(g_mosq);
        sleep(RECONNECT_DELAY);
    }

    /* --- graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

