#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define SERVO1 7
#define SERVO2 8
#define SERVO3 9
#define SERVO4 10
#define SERVO5 11

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_RANGE (SERVO_MAX_PULSE - SERVO_MIN_PULSE)

#define PWM_FREQ 50
#define PWM_RANGE 1000

static const int servo_pins[] = {SERVO1, SERVO2, SERVO3, SERVO4, SERVO5};
static const int positions[] = {1000, 1500, 2000, 500, 2500};
static const int num_servos = sizeof(servo_pins) / sizeof(servo_pins[0]);

static int pwm_initialized = 0;

static void cleanup(void) {
    if (pwm_initialized) {
        for (int i = 0; i < num_servos; i++) {
            gpioPWM(servo_pins[i], 0);
        }
        gpioTerminate();
        pwm_initialized = 0;
    }
}

static int initialize_pwm(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    pwm_initialized = 1;

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(servo_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", servo_pins[i]);
            cleanup();
            return -1;
        }
        if (gpioSetPWMfrequency(servo_pins[i], PWM_FREQ) != PWM_FREQ) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", servo_pins[i]);
            cleanup();
            return -1;
        }
        if (gpioSetPWMrange(servo_pins[i], PWM_RANGE) != PWM_RANGE) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", servo_pins[i]);
            cleanup();
            return -1;
        }
    }
    return 0;
}

static int set_servo_position(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE || pulse_width > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse width %d out of range for GPIO %d.\n", pulse_width, gpio);
        return -1;
    }
    int duty_cycle = (int)(((long)pulse_width - SERVO_MIN_PULSE) * PWM_RANGE / SERVO_RANGE);
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

int main(void) {
    if (initialize_pwm() != 0) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_servos; i++) {
        if (set_servo_position(servo_pins[i], positions[i]) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moved to positions: %d, %d, %d, %d, %d\n",
           positions[0], positions[1], positions[2], positions[3], positions[4]);

    sleep(3);

    cleanup();
    return EXIT_SUCCESS;
}

