#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <time.h>

/* Motor A */
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

/* Motor B */
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

/* Encoders */
#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

/* Quadrature encoder: one count per rising edge */
#define TICKS_PER_REV 64
#define PWM_FREQ 10000
#define PWM_RANGE 255
#define CONTROL_PERIOD_US 100000
#define STALL_TIMEOUT_S 2

/* PI controller parameters */
#define KP 0.5
#define KI 0.05

static volatile sig_atomic_t running = 1;

/* Shared encoder counters (atomic) */
static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;

/* Last edge timestamps for stall detection */
static struct timespec last_a_rise = {0, 0};
static struct timespec last_a_fall = {0, 0};
static struct timespec last_b_rise = {0, 0};
static struct timespec last_b_fall = {0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        atomic_fetch_add(&encoder_a_count, 1);
        clock_gettime(CLOCK_MONOTONIC, &last_a_rise);
    } else if (level == 0) {
        clock_gettime(CLOCK_MONOTONIC, &last_a_fall);
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        atomic_fetch_add(&encoder_b_count, 1);
        clock_gettime(CLOCK_MONOTONIC, &last_b_rise);
    } else if (level == 0) {
        clock_gettime(CLOCK_MONOTONIC, &last_b_fall);
    }
}

static void check_stall(void) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    double a_rise_diff = (now.tv_sec - last_a_rise.tv_sec) +
                         (now.tv_nsec - last_a_rise.tv_nsec) / 1e9;
    double a_fall_diff = (now.tv_sec - last_a_fall.tv_sec) +
                         (now.tv_nsec - last_a_fall.tv_nsec) / 1e9;
    double b_rise_diff = (now.tv_sec - last_b_rise.tv_sec) +
                         (now.tv_nsec - last_b_rise.tv_nsec) / 1e9;
    double b_fall_diff = (now.tv_sec - last_b_fall.tv_sec) +
                         (now.tv_nsec - last_b_fall.tv_nsec) / 1e9;

    if (a_rise_diff > STALL_TIMEOUT_S) {
        fprintf(stderr, "Warning: Encoder A stalled (no rising edge for %.1f s)\n",
                a_rise_diff);
    }
    if (a_fall_diff > STALL_TIMEOUT_S) {
        fprintf(stderr, "Warning: Encoder A stalled (no falling edge for %.1f s)\n",
                a_fall_diff);
    }
    if (b_rise_diff > STALL_TIMEOUT_S) {
        fprintf(stderr, "Warning: Encoder B stalled (no rising edge for %.1f s)\n",
                b_rise_diff);
    }
    if (b_fall_diff > STALL_TIMEOUT_S) {
        fprintf(stderr, "Warning: Encoder B stalled (no falling edge for %.1f s)\n",
                b_fall_diff);
    }
}

static void set_motor_a(int pwm_value) {
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

    /* Drive IN1 high, IN2 low for forward motion */
    gpioWrite(MOTOR_A_IN1, 1);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN1, pwm_value);
}

static void set_motor_b(int pwm_value) {
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

    /* Drive IN3 high, IN4 low for forward motion */
    gpioWrite(MOTOR_B_IN3, 1);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN3, pwm_value);
}

static void stop_motors(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_B_IN3, 0);
}

static int calculate_pwm(double error, double integral, double *integral_accum) {
    double output = KP * error + KI * integral;

    if (output < 0.0) {
        output = 0.0;
        *integral_accum = 0.0;
    } else if (output > (double)PWM_RANGE) {
        output = (double)PWM_RANGE;
        *integral_accum = (double)PWM_RANGE / KI;
    }

    return (int)(output + 0.5);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs as outputs */
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder GPIOs as inputs with pull-downs */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set encoder GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_DOWN);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_DOWN);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_DOWN);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_DOWN);

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_IN3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register encoder ISRs */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, FALLING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, FALLING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register encoder ISRs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize encoder timestamps */
    clock_gettime(CLOCK_MONOTONIC, &last_a_rise);
    clock_gettime(CLOCK_MONOTONIC, &last_a_fall);
    clock_gettime(CLOCK_MONOTONIC, &last_b_rise);
    clock_gettime(CLOCK_MONOTONIC, &last_b_fall);

    /* Initialize PI controller state */
    double integral_a = 0.0;
    double integral_b = 0.0;

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Closed-loop speed control started. Target RPM: 50.0\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        /* Read and reset encoder counts atomically */
        int a_count = atomic_exchange(&encoder_a_count, 0);
        int b_count = atomic_exchange(&encoder_b_count, 0);

        /* Calculate shaft RPM from ticks (one tick = 1/64 rev) */
        double rpm_a = (double)a_count * 60.0 / (double)TICKS_PER_REV;
        double rpm_b = (double)b_count * 60.0 / (double)TICKS_PER_REV;

        /* Calculate errors and update integrals */
        double error_a = (double)TICKS_PER_REV * 50.0 / 60.0 - rpm_a;
        double error_b = (double)TICKS_PER_REV * 50.0 / 60.0 - rpm_b;

        integral_a += error_a;
        integral_b += error_b;

        /* Clamp integrals to prevent windup */
        if (integral_a < 0.0) integral_a = 0.0;
        if (integral_a > (double)PWM_RANGE / KI) integral_a = (double)PWM_RANGE / KI;
        if (integral_b < 0.0) integral_b = 0.0;
        if (integral_b > (double)PWM_RANGE / KI) integral_b = (double)PWM_RANGE / KI;

        /* Calculate PWM outputs */
        int pwm_a = calculate_pwm(error_a, integral_a, &integral_a);
        int pwm_b = calculate_pwm(error_b, integral_b, &integral_b);

        /* Set motor PWMs */
        set_motor_a(pwm_a);
        set_motor_b(pwm_b);

        /* Print status */
        printf("A: RPM=%.2f PWM=%d  B: RPM=%.2f PWM=%d\n",
               rpm_a, pwm_a, rpm_b, pwm_b);

        /* Check for encoder stall */
        check_stall();

        /* Sleep for control period */
        gpioDelay(CONTROL_PERIOD_US);
    }

    /* Cleanup */
    stop_motors();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

