#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define MAIN_LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
        printf("[%s] Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    } else {
        printf("[unknown] Relay state: %s\n", state ? "ON" : "OFF");
    }
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    printf("Relay control started. Touch sensor on GPIO %d, relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            int debounced_state = gpioRead(TOUCH_SENSOR_PIN);

            if (debounced_state < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d during debounce\n", TOUCH_SENSOR_PIN);
                break;
            }

            if (debounced_state == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        last_touch_state = touch_state;
        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nRelay control stopped. Relay turned OFF.\n");
    return EXIT_SUCCESS;
}

