#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_SEC 1
#define DEBOUNCE_TIMEOUT_SEC 1

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid to open state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIMEOUT_SEC * 1000, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started. Solenoid valve opened.");

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_mutex);
        int current_pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = ((double)current_pulses / PULSES_PER_LITER) * 60.0;

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Flow rate: %.2f L/min", lpm);
        log_event(log_message);

        static int valve_open = 1;
        if (lpm > LPM_THRESHOLD && !valve_open) {
            if (gpioWrite(SOLENOID_PIN, 0) == 0) {
                log_event("Solenoid valve closed.");
                valve_open = 0;
            } else {
                log_event("Error closing solenoid valve.");
            }
        } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS) && valve_open) {
            if (gpioWrite(SOLENOID_PIN, 1) == 0) {
                log_event("Solenoid valve opened.");
                valve_open = 1;
            } else {
                log_event("Error opening solenoid valve.");
            }
        }
    }

    log_event("Shutting down. Reopening solenoid valve.");
    gpioWrite(SOLENOID_PIN, 1);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

