#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define MAX_BUFFER 1024
#define HX711_TIMEOUT_US 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_RANGE 1000
#define SERVO_CENTER 1500
#define SERVO_OPEN_US 1500
#define SERVO_CLOSED_US 500
#define SERVO_SETTLE_US 500000
#define SERVO_CLOSE_US 1000
#define SERVO_CLOSE_DELAY_US 1000000
