#define SERVO_CLOSE_RETRIES 3
#define SERVO_OPEN_RETRIES 3
#define SERVO_CLOSE_RETRY_DELAY_US 100000
#define SERVO_OPEN_RETRY_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int server_socket = -1;
static int client_socket = -1;
static int hx711_data_pin = 23;
static int hx711_sck_pin = 24;
static int servo_pin = 18;
