static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(hx711_data_pin, PI_INPUT);
    gpioSetMode(hx711_sck_pin, PI_OUTPUT);
    gpioSetMode(servo_pin, PI_OUTPUT);
    gpioWrite(hx711_sck_pin, 0);
    gpioServo(servo_pin, SERVO_CLOSED_US);
    return 0;
}

static int read_hx711(double *weight) {
    int32_t value = 0;
    int timeout = 0;
    gpioWrite(hx711_sck_pin, 0);
    gpioDelay(1);
    while (gpioRead(hx711_data_pin) == 1) {
        gpioDelay(1);
