            timestamp, target_weight, actual_weight, error_message ? error_message : "");
    fclose(fp);
    return 0;
}

static int send_data(int sock, const char *data) {
    size_t total = strlen(data);
    size_t sent = 0;
    while (sent < total) {
        ssize_t n = send(sock, data + sent, total - sent, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "send failed: %s\n", strerror(errno));
            return -1;
        }
        sent += n;
    }
    return 0;
}

static int receive_data(int sock, char *buffer, size_t buffer_size) {
    ssize_t n = recv(sock, buffer, buffer_size - 1, 0);
    if (n < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "recv failed: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) return 0;
    buffer[n] = '\0';
    return (int)n;
}

static int handle_client(int client_sock) {
    char buffer[MAX_BUFFER];
    int n = receive_data(client_sock, buffer, sizeof(buffer));
    if (n <= 0) {
        fprintf(stderr, "Client disconnected\n");
        return -1;
    }
    buffer[strcspn(buffer, "\r\n")] = '\0';
    double target_weight = atof(buffer);
