#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_DELAY_MS;

    if (argc > 1 && strcmp(argv[1], "-d") == 0 && argc > 2) {
        debounce_ms = atoi(argv[2]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Invalid debounce delay. Using default %d ms.\n", DEBOUNCE_DELAY_MS);
            debounce_ms = DEBOUNCE_DELAY_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay started. Touch GPIO %d to toggle relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Debounce delay: %d ms. Press Ctrl+C to exit.\n", debounce_ms);

    int relay_state = 0;
    int last_touch_state = 0;
    uint32_t last_debounce_tick = 0;

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor on GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        uint32_t now = gpioTick();

        if (touch_state == 1 && last_touch_state == 0) {
            if (now - last_debounce_tick >= (uint32_t)(debounce_ms * 1000)) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error writing to relay on GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
                last_debounce_tick = now;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nRelay turned OFF and pigpio terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

