#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INCREMENT 10
#define INITIAL_ANGLE 90

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_terminal_raw(void) {
    struct termios raw;
    if (tcgetattr(STDIN_FILENO, &raw) != 0) {
        perror("tcgetattr");
        return -1;
    }
    raw.c_lflag &= ~(ECHO | ICANON | IEXTEN | ISIG);
    raw.c_iflag &= ~(IXON | IXOFF | IXANY);
    raw.c_cflag |= (CLOCAL | CREAD);
    raw.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    raw.c_cflag |= CS8;
    raw.c_oflag &= ~(OPOST | ONLCR);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 1;
    if (tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void) {
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &g_orig_termios);
}

static int angle_to_pulse_us(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (int)((long)(angle - MIN_ANGLE) *
        (MAX_PULSE_US - MIN_PULSE_US) / (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int angle) {
    int pulse = angle_to_pulse_us(angle);
    if (pulse < MIN_PULSE_US || pulse > MAX_PULSE_US) {
        fprintf(stderr, "Pulse %d out of range [%d, %d]\n", pulse, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "gpioServo failed on pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (tcgetattr(STDIN_FILENO, &g_orig_termios) != 0) {
        perror("tcgetattr");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int angle = INITIAL_ANGLE;
    if (set_servo_angle(angle) != 0) {
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo angle: %d degrees\n", angle);

    while (g_running) {
        int c = getchar();
        if (c == '+') {
            angle += INCREMENT;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
        } else if (c == '-') {
            angle -= INCREMENT;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
        } else if (c == 'q') {
            break;
        } else {
            continue;
        }
        if (set_servo_angle(angle) != 0) {
            break;
        }
        printf("Servo angle: %d degrees\n", angle);
    }

    gpioServo(SERVO_PIN, 0);
    restore_terminal();
    gpioTerminate();
    return EXIT_SUCCESS;
}

