#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17
#define DEBOUNCE_MS         2
#define SAMPLE_INTERVAL_S   5
#define LOG_FILE_NAME       "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry if interrupted by signal */
    }
}

static void sleep_until_next_second(void)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    unsigned int remaining_ms = (unsigned int)(999 - (now.tv_nsec / 1000000));
    if (remaining_ms > 0) {
        sleep_ms(remaining_ms);
    }
}

static void log_rpm(FILE *log_file, double rpm)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* Request the line as input with pull-up bias (A3144 open-collector output) */
    if (gpiod_line_request_input_flags(line, "motor-rpm-monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup_line;
    }

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    struct timespec last_event_ts = {0, 0};
    int pulse_count = 0;

    while (g_running) {
        /*
         * Edge-triggered event wait with a 1-second timeout so we can
         * exit the loop when g_running is cleared by a signal.
         */
        struct timespec ts_timeout = {1, 0};
        int ev = gpiod_line_event_wait(line, &ts_timeout);

        if (ev < 0) {
            if (errno == EINTR) {
                continue; /* Signal interrupted the wait; re-check g_running */
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n",
                    strerror(errno));
            goto cleanup_all;
        }

        if (ev == 0) {
            /* Timeout — no event within 1 second — loop back to check g_running */
            continue;
        }

        /* Event detected — read it to clear the event queue */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n",
                    strerror(errno));
            continue;
        }

        /* Debounce: ignore events within DEBOUNCE_MS of the last accepted one */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - last_event_ts.tv_sec) * 1000L +
                          (now.tv_nsec - last_event_ts.tv_nsec) / 1000000L;

        if (elapsed_ms < DEBOUNCE_MS) {
            continue;
        }
        last_event_ts = now;

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pulse_count++;
        }

        sleep_until_next_second();
    }

    /* Calculate and log the final RPM */
    double rpm = ((double)pulse_count / (double)SAMPLE_INTERVAL_S) * 60.0;
    log_rpm(log_file, rpm);
    printf("Final RPM: %.2f\n", rpm);
    ret = EXIT_SUCCESS;

cleanup_all:
    if (log_file != NULL) {
        fclose(log_file);
    }
cleanup_line:
    if (line != NULL) {
        gpiod_line_release(line);
    }
cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Program finished.\n");
    }
    return ret;
}

