#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24

#define PULSES_PER_LITER 450.0
#define KP 1.0
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.csv"

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user);
static double calculate_flow_rate(int pulses, double interval_s);
static int control_valve(double current_flow_rate, double target_flow_rate);
static void log_data(double current_flow_rate, int valve_position);
static void signal_handler(int signal);
static int initialize_gpio(void);
static void cleanup_gpio(void);

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: Target flow rate must be positive.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return 1;
        }
    }

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: Target flow rate not specified.\n");
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
        return 1;
    }

    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    fprintf(log_file, "timestamp_ms,flow_rate_L_min,valve_position\n");
    fflush(log_file);

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses = pulse_count;
        pulse_count = 0;

        double interval_s = (double)SAMPLE_INTERVAL_US / 1000000.0;
        double current_flow_rate = calculate_flow_rate(pulses, interval_s);

        int valve_position = control_valve(current_flow_rate, target_flow_rate);

        log_data(current_flow_rate, valve_position);
    }

    cleanup_gpio();
    printf("Flow control stopped.\n");
    return 0;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        pulse_count++;
    }
}

static double calculate_flow_rate(int pulses, double interval_s) {
    if (interval_s <= 0.0) return 0.0;
    return (double)pulses / PULSES_PER_LITER / interval_s;
}

static int control_valve(double current_flow_rate, double target_flow_rate) {
    double error = target_flow_rate - current_flow_rate;
    double output = KP * error;

    int duty_cycle = (int)output;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(VALVE_GPIO, duty_cycle);
    return duty_cycle;
}

static void log_data(double current_flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, current_flow_rate, valve_position);
    fflush(log_file);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(ENABLE_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(ENABLE_GPIO, 1);
    gpioPWM(VALVE_GPIO, 0);

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(VALVE_GPIO, 0);
    gpioWrite(ENABLE_GPIO, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

