#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define TAG_LENGTH 10
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_US 50000
#define LOCK_DURATION_US 5000000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static const unsigned char VALID_TAG[TAG_LENGTH] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rfid_tag(unsigned char *tag) {
    unsigned char tx[TAG_LENGTH];
    unsigned char rx[TAG_LENGTH];
    memset(tx, 0x00, TAG_LENGTH);
    memset(rx, 0x00, TAG_LENGTH);

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, TAG_LENGTH) != TAG_LENGTH) {
        log_event("RFID read failed");
        return -1;
    }

    for (int i = 0; i < TAG_LENGTH; i++) {
        if (rx[i] != VALID_TAG[i]) {
            log_event("Invalid RFID tag");
            return -1;
        }
    }

    memcpy(tag, rx, TAG_LENGTH);
    return 0;
}

static int authenticate(void) {
    unsigned char tag[TAG_LENGTH];
    int rc;

    rc = read_rfid_tag(tag);
    if (rc != 0) return rc;

    if (gpioRead(BUTTON_PIN) == 0) {
        log_event("Button pressed");
        gpioDelay(DEBOUNCE_US);
        if (gpioRead(BUTTON_PIN) == 0) {
            return 0;
        }
    }
    log_event("Button press failed");
    return -1;
}

static void lock_engage(void) {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    log_event("Locks engaged");
}

static void lock_disengage(void) {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    log_event("Locks disengaged");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    lock_disengage();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        if (gpioRead(BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(BUTTON_PIN) == 0) {
                int auth = authenticate();
                if (auth == 0) {
                    lock_engage();
                    gpioDelay(LOCK_DURATION_US);
                    lock_disengage();
                    log_event("Access granted");
                } else {
                    log_event("Access denied");
                }
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

