#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

#define MOTOR_1_ENA 23
#define MOTOR_1_IN1 24
#define MOTOR_1_IN2 25
#define MOTOR_2_ENB 12
#define MOTOR_2_IN3 16
#define MOTOR_2_IN4 20
#define ENCODER_1_A 5
#define ENCODER_1_B 6
#define ENCODER_2_A 26
#define ENCODER_2_B 19

#define PULSES_PER_REV 600.0
#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define PWM_DUTY_MAX (PWM_PERIOD_US / 2)

#define TARGET_RPM 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6];
static struct gpiod_line *encoder_lines[4];
static pthread_t encoder_threads[2];
static volatile int32_t encoder_counts[2] = {0, 0};
static pthread_mutex_t encoder_mutex[2];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double speed1, double speed2, double p, double i, double d, double out) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", ts, speed1, speed2, p, i, d, out);
    fflush(log_file);
}

static void *encoder_thread(void *arg) {
    int idx = *(int *)arg;
    int a_pin = (idx == 0) ? ENCODER_1_A : ENCODER_2_A;
    int b_pin = (idx == 0) ? ENCODER_1_B : ENCODER_2_B;
    int a_line_idx = (idx == 0) ? 0 : 2;
    int b_line_idx = (idx == 0) ? 1 : 3;

    struct gpiod_line *line_a = encoder_lines[a_line_idx];
    struct gpiod_line *line_b = encoder_lines[b_line_idx];

    int last_a = gpiod_line_get_value(line_a);
    if (last_a < 0) {
        fprintf(stderr, "Failed to read encoder A pin %d\n", a_pin);
        return NULL;
    }

    while (running) {
        int cur_a = gpiod_line_get_value(line_a);
        if (cur_a < 0) {
            fprintf(stderr, "Encoder A read error\n");
            break;
        }

        int cur_b = gpiod_line_get_value(line_b);
        if (cur_b < 0) {
            fprintf(stderr, "Encoder B read error\n");
            break;
        }

        if (cur_a != last_a) {
            int32_t *count = &encoder_counts[idx];
            pthread_mutex_lock(&encoder_mutex[idx]);
            if (cur_a != last_a) {
                if (cur_b != last_a) {
                    *count += 1;
                } else {
                    *count -= 1;
                }
            }
            pthread_mutex_unlock(&encoder_mutex[idx]);
            last_a = cur_a;
        }
        usleep(10);
    }
    return NULL;
}

static void motor_forward(int idx) {
    if (idx == 0) {
        gpiod_line_set_value(motor_lines[0], 1);
        gpiod_line_set_value(motor_lines[1], 0);
        gpiod_line_set_value(motor_lines[2], 1);
        gpiod_line_set_value(motor_lines[3], 0);
    } else {
        gpiod_line_set_value(motor_lines[4], 1);
        gpiod_line_set_value(motor_lines[5], 0);
        gpiod_line_set_value(motor_lines[6], 1);
        gpiod_line_set_value(motor_lines[7], 0);
    }
}

static void motor_backward(int idx) {
    if (idx == 0) {
        gpiod_line_set_value(motor_lines[0], 1);
        gpiod_line_set_value(motor_lines[1], 1);
        gpiod_line_set_value(motor_lines[2], 0);
        gpiod_line_set_value(motor_lines[3], 0);
    } else {
        gpiod_line_set_value(motor_lines[4], 1);
        gpiod_line_set_value(motor_lines[5], 1);
        gpiod_line_set_value(motor_lines[6], 0);
        gpiod_line_set_value(motor_lines[7], 0);
    }
}

static void motor_stop(int idx) {
    if (idx == 0) {
        gpiod_line_set_value(motor_lines[0], 0);
        gpiod_line_set_value(motor_lines[1], 0);
        gpiod_line_set_value(motor_lines[2], 0);
        gpiod_line_set_value(motor_lines[3], 0);
    } else {
        gpiod_line_set_value(motor_lines[4], 0);
        gpiod_line_set_value(motor_lines[5], 0);
        gpiod_line_set_value(motor_lines[6], 0);
        gpiod_line_set_value(motor_lines[7], 0);
    }
}

static void pwm_set_duty(int idx, int duty_us) {
    if (duty_us < 0) duty_us = 0;
    if (duty_us > PWM_DUTY_MAX) duty_us = PWM_DUTY_MAX;

    if (idx == 0) {
        gpiod_line_set_value(motor_lines[0], duty_us > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[1], duty_us > 0 ? 0 : 0);
        gpiod_line_set_value(motor_lines[2], duty_us > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[3], duty_us > 0 ? 0 : 0);
    } else {
        gpiod_line_set_value(motor_lines[4], duty_us > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[5], duty_us > 0 ? 0 : 0);
        gpiod_line_set_value(motor_lines[6], duty_us > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[7], duty_us > 0 ? 0 : 0);
    }
}

static double calculate_pid(double setpoint, double actual, double *prev_e, double *prev_i, double dt) {
    double e = setpoint - actual;
    *prev_i += e * dt;
    if (*prev_i > 1000.0) *prev_i = 1000.0;
    if (*prev_i < -1000.0) *prev_i = -1000.0;
    double de = e - *prev_e;
    double out = KP * e + KI * (*prev_i) + KD * de / dt;
    *prev_e = e;
    return out;
}

static void cleanup(void) {
    if (chip) {
        motor_stop(0);
        motor_stop(1);
        for (int i = 0; i < 6; i++) {
            if (motor_lines[i]) gpiod_line_release(motor_lines[i]);
        }
        for (int i = 0; i < 4; i++) {
            if (encoder_lines[i]) gpiod_line_release(encoder_lines[i]);
        }
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    int motor_pins[] = {MOTOR_1_ENA, MOTOR_1_IN1, MOTOR_1_IN2, MOTOR_2_ENB, MOTOR_2_IN3, MOTOR_2_IN4};
    int encoder_pins[] = {ENCODER_1_A, ENCODER_1_B, ENCODER_2_A, ENCODER_2_B};

    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d\n", motor_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_pwm", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output\n", motor_pins[i]);
            cleanup();
            return 1;
        }
    }

    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d\n", encoder_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder") < 0) {
            fprintf(stderr, "Failed to request encoder line %d events\n", encoder_pins[i]);
            cleanup();
            return 1;
        }
    }

    for (int i = 0; i < 2; i++) {
        pthread_mutex_init(&encoder_mutex[i], NULL);
        int *tid = malloc(sizeof(int));
        if (!tid) {
            fprintf(stderr, "Memory allocation failed\n");
            cleanup();
            return 1;
        }
        *tid = i;
        if (pthread_create(&encoder_threads[i], NULL, encoder_thread, tid) != 0) {
            fprintf(stderr, "Failed to create encoder thread %d\n", i);
            free(tid);
            cleanup();
            return 1;
        }
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "timestamp,speed1_rpm,speed2_rpm,pid_p,pid_i,pid_d,pid_out\n");
    fflush(log_file);

    double prev_e[2] = {0, 0};
    double prev_i[2] = {0, 0};
    struct timespec last_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        struct timespec cur_time;
        clock_gettime(CLOCK_MONOTONIC, &cur_time);
        double dt = (cur_time.tv_sec - last_time.tv_sec) + (cur_time.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = cur_time;

        if (dt < (SAMPLE_TIME_MS / 1000.0)) {
            usleep((SAMPLE_TIME_MS / 1000.0 - dt) * 1000000);
            continue;
        }

        int32_t counts[2];
        for (int i = 0; i < 2; i++) {
            pthread_mutex_lock(&encoder_mutex[i]);
            counts[i] = encoder_counts[i];
            encoder_counts[i] = 0;
            pthread_mutex_unlock(&encoder_mutex[i]);
        }

        double speed1 = (counts[0] / PULSES_PER_REV) * (60.0 / dt);
        double speed2 = (counts[1] / PULSES_PER_REV) * (60.0 / dt);

        double out1 = calculate_pid(TARGET_RPM, speed1, &prev_e[0], &prev_i[0], dt);
        double out2 = calculate_pid(TARGET_RPM, speed2, &prev_e[1], &prev_i[1], dt);

        int duty1 = (int)(out1 * PWM_DUTY_MAX);
        int duty2 = (int)(out2 * PWM_DUTY_MAX);

        if (duty1 > 0) {
            motor_forward(0);
            pwm_set_duty(0, duty1);
        } else if (duty1 < 0) {
            motor_backward(0);
            pwm_set_duty(0, -duty1);
        } else {
            motor_stop(0);
        }

        if (duty2 > 0) {
            motor_forward(1);
            pwm_set_duty(1, duty2);
        } else if (duty2 < 0) {
            motor_backward(1);
            pwm_set_duty(1, -duty2);
        } else {
            motor_stop(1);
        }

        log_data(speed1, speed2, KP, KI, KD, (duty1 + duty2) / 2.0);
    }

    for (int i = 0; i < 2; i++) {
        pthread_join(encoder_threads[i], NULL);
        pthread_mutex_destroy(&encoder_mutex[i]);
        free(encoder_threads[i]);
    }

    cleanup();
    return 0;
}

