    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "timestamp,speed1_rpm,speed2_rpm,pid_p,pid_i,pid_d,pid_out\n");
    fflush(log_file);

    double prev_e[2] = {0, 0};
    double prev_i[2] = {0, 0};
    struct timespec last_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        struct timespec cur_time;
        clock_gettime(CLOCK_MONOTONIC, &cur_time);
        double dt = (cur_time.tv_sec - last_time.tv_sec) + (cur_time.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = cur_time;

        if (dt < (SAMPLE_TIME_MS / 1000.0)) {
            usleep((SAMPLE_TIME_MS / 1000.0 - dt) * 1000000);
            continue;
        }

        int32_t counts[2];
        for (int i = 0; i < 2; i++) {
            pthread_mutex_lock(&encoder_mutex[i]);
            counts[i] = encoder_counts[i];
            encoder_counts[i] = 0;
            pthread_mutex_unlock(&encoder_mutex[i]);
        }

        double speed1 = (counts[0] / PULSES_PER_REV) * (60.0 / dt);
        double speed2 = (counts[1] / PULSES_PER_REV) * (60.0 / dt);

        double out1 = calculate_pid(TARGET_RPM, speed1, &prev_e[0], &prev_i[0], dt);
        double out2 = calculate_pid(TARGET_RPM, speed2, &prev_e[1], &prev_i[1], dt);

        int duty1 = (int)(out1 * PWM_DUTY_MAX);
        int duty2 = (int)(out2 * PWM_DUTY_MAX);

        if (duty1 > 0) {
            motor_forward(0);
            pwm_set_duty(0, duty1);
        } else if (duty1 < 0) {
            motor_backward(0);
            pwm_set_duty(0, -duty1);
        } else {
            motor_stop(0);
        }

        if (duty2 > 0) {
            motor_forward(1);
            pwm_set_duty(1, duty2);
        } else if (duty2 < 0) {
            motor_backward(1);
            pwm_set_duty(1, -duty2);
        } else {
            motor_stop(1);
        }

        log_data(speed1, speed2, KP, KI, KD, (duty1 + duty2) / 2.0);
    }

    for (int i = 0; i < 2; i++) {
        pthread_join(encoder_threads[i], NULL);
        pthread_mutex_destroy(&encoder_mutex[i]);
        free(encoder_threads[i]);
    }

    cleanup();
    return 0;
}

