#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_F 0x2B
#define MPR121_NHD_F 0x2C
#define MPR121_NCL_F 0x2D
#define MPR121_FDL_F 0x2E
#define MPR121_MHD_R 0x2F
#define MPR121_NHD_R 0x30
#define MPR121_NCL_R 0x31
#define MPR121_FDL_R 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

int mpr121_read(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(handle, MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_F, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_R, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(handle, MPR121_ECR, 0x00) < 0) return -1;

    return 0;
}

int mpr121_read_touch_status(int handle, uint16_t *touch_status) {
    uint8_t low, high;
    if (mpr121_read(handle, MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (mpr121_read(handle, MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

void log_relay_state(int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        perror("Error opening relay_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s Relay: %s\n", s, state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d: %d\n", MPR121_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("MPR121 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(50000);
            continue;
        }

        int relay_state = (touch_status > 0) ? 1 : 0;
        gpioWrite(RELAY_GPIO, relay_state);
        log_relay_state(relay_state);

        gpioDelay(50000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

