#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP "/dev/gpiochip0"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int activate_valve(struct gpiod_line *line, int gpio_pin, const char *valve_name, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH for %s.\n", gpio_pin, valve_name);
        return -1;
    }

    char log_message[128];
    snprintf(log_message, sizeof(log_message), "Valve %s activated for %d ms", valve_name, duration_ms);
    if (log_event(log_message) != 0) {
        fprintf(stderr, "Warning: Failed to log valve activation for %s.\n", valve_name);
    }

    usleep(duration_ms * 1000);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW for %s.\n", gpio_pin, valve_name);
        return -1;
    }

    snprintf(log_message, sizeof(log_message), "Valve %s deactivated", valve_name);
    if (log_event(log_message) != 0) {
        fprintf(stderr, "Warning: Failed to log valve deactivation for %s.\n", valve_name);
    }

    return 0;
}

void cleanup() {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Failed to get GPIO 17 line");
        cleanup();
        return 1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Failed to get GPIO 18 line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(valve1_line, "valve_control", 0) < 0) {
        perror("Failed to request GPIO 17 as output");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(valve2_line, "valve_control", 0) < 0) {
        perror("Failed to request GPIO 18 as output");
        cleanup();
        return 1;
    }

    printf("Greenhouse water distribution system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        printf("Activating Valve 1 for 500ms...\n");
        if (activate_valve(valve1_line, VALVE1_GPIO, "Valve 1", 500) != 0) {
            fprintf(stderr, "Error activating Valve 1.\n");
            break;
        }
        sleep(5);

        if (!program_running) break;

        printf("Activating Valve 2 for 1000ms...\n");
        if (activate_valve(valve2_line, VALVE2_GPIO, "Valve 2", 1000) != 0) {
            fprintf(stderr, "Error activating Valve 2.\n");
            break;
        }
        sleep(10);
    }

    cleanup();
    printf("Greenhouse water distribution system stopped.\n");
    return 0;
}

