#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

// MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_ELECONFIG1 0x5F
#define MPR121_MHD_F 0x2B
#define MPR121_NHD_F 0x2C
#define MPR121_NCL_F 0x2D
#define MPR121_FDL_F 0x2E
#define MPR121_MHD_R 0x2F
#define MPR121_NHD_R 0x30
#define MPR121_NCL_R 0x31
#define MPR121_FDL_R 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

int mpr121_init(int handle) {
    // Soft reset
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); // 10 ms

    // Stop mode
    if (mpr121_write(handle, MPR121_ECR, 0x00) < 0) return -1;

    // Filter configuration (baseline tracking)
    if (mpr121_write(handle, MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_F, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_R, 0x00) < 0) return -1;

    // Touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + i * 2, 0x10) < 0) return -1; // Touch threshold
        if (mpr121_write(handle, MPR121_E0RTH + i * 2, 0x0A) < 0) return -1; // Release threshold
    }

    // Debounce: 3 samples for touch, 3 for release
    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    // Configuration registers
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1; // 16 uA charge current
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1; // 0.5 us charge time

    // Enable 12 electrodes, enter run mode
    if (mpr121_write(handle, MPR121_ECR, 0x8C) < 0) return -1;

    gpioDelay(100000); // 100 ms for stabilization
    return 0;
}

int mpr121_read_touch_status(int handle) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Touch detected! Relay toggled. Status: 0x%04X\n", touch_status);
        }

        gpioDelay(100000); // 100 ms
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

