        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);
    return 0;
}

void stop_motors(const MotorPins *pins) {
    gpioPWM(pins->motor1_pin, 0);
    gpioPWM(pins->motor2_pin, 0);
}

void cleanup_gpio(void) {
    stop_motors((MotorPins *)&(MotorPins){MOTOR1_PIN, MOTOR2_PIN});
    gpioTerminate();
}

HapticPattern generate_haptic_pattern(void) {
    HapticPattern pattern;
    pattern.length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
    pattern.steps = (HapticStep *)malloc(pattern.length * sizeof(HapticStep));
    if (pattern.steps == NULL) {
        fprintf(stderr, "Memory allocation failed for haptic pattern\n");
        pattern.length = 0;
        return pattern;
    }
    for (int i = 0; i < pattern.length; i++) {
        pattern.steps[i].duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        pattern.steps[i].duration_ms = (rand() % (MAX_STEP_DELAY_MS - MIN_STEP_DELAY_MS + 1)) + MIN_STEP_DELAY_MS;
    }
    return pattern;
}

void play_haptic_pattern(const HapticPattern *pattern, const MotorPins *pins) {
    for (int i = 0; i < pattern->length; i++) {
        if (shutdown_flag) break;
        gpioPWM(pins->motor1_pin, pattern->steps[i].duty_cycle);
        gpioPWM(pins->motor2_pin, pattern->steps[i].duty_cycle);
        gpioDelay(pattern->steps[i].duration_ms * 1000);
    }
    stop_motors(pins);
}

int main(void) {
    MotorPins motor_pins = {MOTOR1_PIN, MOTOR2_PIN};
    srand(time(NULL));
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }
    signal(SIGINT, signal_handler);
    printf("Haptic feedback started. Press Ctrl+C to exit.\n");
    while (!shutdown_flag) {
        HapticPattern pattern = generate_haptic_pattern();
        if (pattern.steps != NULL) {
            play_haptic_pattern(&pattern, &motor_pins);
            free(pattern.steps);
        }
    }
    cleanup_gpio();
    printf("Haptic feedback stopped.\n");
    return EXIT_SUCCESS;
}

