#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_LOCK_PIN 27
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int count = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) && timeout < HX711_TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= HX711_TIMEOUT_US) {
        fprintf(stderr, "HX711 timeout waiting for data ready\n");
        return -1;
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(data_pin)) {
            count++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (count & 0x800000) {
        count |= 0xFF000000;
    }
    return count;
}

static double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

static int load_calibration(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: calibration file not found, using defaults\n");
        return -1;
    }
    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fprintf(stderr, "Warning: calibration file invalid, using defaults\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_calibration(const char *filename, double scale, double offset) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.6lf %.6lf\n", scale, offset);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, const char *filename) {
    double sum = 0.0;
    int valid = 0;

    printf("Starting one-time calibration. Remove all weight from the load cell.\n");
    gpioDelay(5000000);

    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw < 0) {
            fprintf(stderr, "Calibration read %d failed, skipping\n", i);
            continue;
        }
        sum += (double)raw;
        valid++;
        gpioDelay(100000);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid calibration readings, aborting\n");
        return -1;
    }

    offset = sum / valid;
    printf("Calibration offset: %.2f\n", offset);

    printf("Place a known weight on the load cell.\n");
    gpioDelay(5000000);

    sum = 0.0;
    valid = 0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw < 0) {
            fprintf(stderr, "Calibration read %d failed, skipping\n", i);
            continue;
        }
        sum += (double)raw;
        valid++;
        gpioDelay(100000);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid calibration readings, aborting\n");
        return -1;
    }

    double avg_raw = sum / valid;
    scale_factor = avg_raw / 10.0;
    printf("Calibration scale factor: %.6f\n", scale_factor);

    if (save_calibration(filename, scale_factor, offset) != 0) {
        fprintf(stderr, "Warning: could not save calibration data\n");
    }
    return 0;
}

static void log_weight(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f kg\n", timestamp, weight);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, CALIBRATION_FILE) != 0) {
            fprintf(stderr, "HX711 calibration failed, exiting\n");
            gpioTerminate();
            return 1;
        }
    }

    gpioSetMode(SOLENOID_LOCK_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_LOCK_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = convert_to_weight(raw);
        log_weight(weight);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_LOCK_PIN, 1);
            printf("Weight %.2f kg exceeds threshold, lock engaged\n", weight);
        } else {
            gpioWrite(SOLENOID_LOCK_PIN, 0);
            printf("Weight %.2f kg below threshold, lock released\n", weight);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_LOCK_PIN, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

