#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_US 5000000
#define CHECK_INTERVAL_US 60000000
#define POST_CLOSE_DELAY_US 60000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin mode");
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialize PWM to 0");
        return -1;
    }
    return 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= 3) ? 1 : 0;
}

static void close_window(void) {
    log_event("Closing window");
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 150) != 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        return;
    }
    gpioDelay(MOTOR_RUN_TIME_US);
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 low");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set PWM to 0");
        return;
    }
    log_event("Window closed");
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected");
            close_window();
            gpioDelay(POST_CLOSE_DELAY_US);
        } else {
            log_event("No rain detected");
            gpioDelay(CHECK_INTERVAL_US);
        }
    }

    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    log_event("Program terminated");
    closelog();
    return EXIT_SUCCESS;
}

