#include <errno.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define SCALE_FACTOR 100.0
#define LOG_FILE "stock_events.txt"
#define SAMPLE_INTERVAL_US 1000000
#define HX711_TIMEOUT_US 100000
#define HX711_READY_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out_value) {
    if (out_value == NULL) return -1;

    uint32_t start_tick = gpioTick();
    int data = 0;

    while (gpioRead(HX711_DT_PIN) == 1) {
        if ((gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: DT stuck high\n");
            return -1;
        }
        gpioDelay(10);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DT_PIN)) data |= 1;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    *out_value = data;
    return 0;
}

static float convert_to_grams(int raw_value) {
    return (float)raw_value / SCALE_FACTOR;
}

static int log_event(float weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Weight: %.2f g\n", timestamp, weight) < 0) {
