    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid\n");
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
