        fprintf(stderr, "Failed to initialize solenoid to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Kitchen stock monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = 0;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float weight = convert_to_grams(raw_value);
        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Stock level low! Activating solenoid lock.\n");
            if (activate_solenoid(5000) != 0) {
                fprintf(stderr, "Solenoid activation failed\n");
            }
            if (log_event(weight) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

