#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define SOLENOID_HOLD_US 5000000
#define CLOCK_HALF_US 1
#define READ_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;
static FILE *security_log_file = NULL;
static FILE *calibration_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(clock_pin, 0) < 0) return -1;

    uint32_t start_tick = gpioTick();
    int timeout = 0;

    while (gpioRead(data_pin) == 1) {
        if (gpioTick() - start_tick > HX711_TIMEOUT_US) {
            timeout = 1;
            break;
        }
        gpioDelay(100);
    }

    if (timeout) return -2;

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) < 0) return -1;
        gpioDelay(CLOCK_HALF_US);
        value = (value << 1) | (gpioRead(data_pin) & 1);
        if (gpioWrite(clock_pin, 0) < 0) return -1;
        gpioDelay(CLOCK_HALF_US);
    }

    if (gpioWrite(clock_pin, 1) < 0) return -1;
    gpioDelay(CLOCK_HALF_US);
    if (gpioWrite(clock_pin, 0) < 0) return -1;
    gpioDelay(CLOCK_HALF_US);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0;
}

static double convert_to_kg(long raw_value) {
    return (double)raw_value / calibration_factor;
}

static int calibrate_hx711(int data_pin, int clock_pin, double known_weight) {
    printf("Calibrating HX711...\n");
    printf("Place a known weight (%.2f kg) on the load cell.\n", known_weight);
    printf("Press Enter to continue...\n");
    getchar();

    long raw_value;
    int ret = read_hx711(data_pin, clock_pin, &raw_value);
    if (ret != 0) {
        fprintf(stderr, "Error reading HX711 during calibration: %d\n", ret);
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(calibration_file, "%.6f\n", calibration_factor) < 0) {
        fprintf(stderr, "Error writing calibration factor to file: %s\n", strerror(errno));
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    if (fclose(calibration_file) != 0) {
        fprintf(stderr, "Error closing calibration file: %s\n", strerror(errno));
        calibration_file = NULL;
        return -1;
    }
    calibration_file = NULL;

    printf("Calibration complete. Saved to %s.\n", CALIBRATION_FILE);
    return 0;
}

static int load_calibration_factor(void) {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file %s: %s. Using default calibration factor.\n", CALIBRATION_FILE, strerror(errno));
        return -1;
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Warning: Could not read calibration factor from %s. Using default calibration factor.\n", CALIBRATION_FILE);
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    if (fclose(calibration_file) != 0) {
        fprintf(stderr, "Warning: Error closing calibration file: %s\n", strerror(errno));
    }
    calibration_file = NULL;

    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0;
}

static int log_security_event(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    security_log_file = fopen(SECURITY_LOG_FILE, "a");
    if (security_log_file == NULL) {
        fprintf(stderr, "Error opening security log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(security_log_file, "%s - Weight: %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error writing to security log file: %s\n", strerror(errno));
        fclose(security_log_file);
        security_log_file = NULL;
        return -1;
    }

    if (fclose(security_log_file) != 0) {
        fprintf(stderr, "Error closing security log file: %s\n", strerror(errno));
        security_log_file = NULL;
        return -1;
    }
    security_log_file = NULL;

    printf("Security event logged: %s - Weight: %.2f kg\n", timestamp, weight);
    return 0;
}

static int control_solenoid(int solenoid_pin, int state) {
    if (gpioSetMode(solenoid_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(solenoid_pin, state) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (security_log_file != NULL) {
        fclose(security_log_file);
        security_log_file = NULL;
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
        calibration_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (load_calibration_factor() != 0) {
        fprintf(stderr, "Using default calibration factor.\n");
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, 10.0) != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    if (control_solenoid(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize solenoid pin.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value;
        int ret = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value);

        if (ret == 0) {
            double weight = convert_to_kg(raw_value);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                if (log_security_event(weight) == 0) {
                    if (control_solenoid(SOLENOID_PIN, 1) == 0) {
                        printf("Solenoid locked.\n");
                    } else {
                        fprintf(stderr, "Failed to lock solenoid.\n");
                    }
                    gpioDelay(SOLENOID_HOLD_US);
                    if (control_solenoid(SOLENOID_PIN, 0) == 0) {
                        printf("Solenoid unlocked.\n");
                    } else {
                        fprintf(stderr, "Failed to unlock solenoid.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to log security event.\n");
                }
            }
        } else if (ret == -2) {
            fprintf(stderr, "HX711 communication timeout. Check wiring.\n");
        } else {
            fprintf(stderr, "HX711 read error: %d\n", ret);
        }

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

