#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define VALVE_GPIO 18
#define CHIP_NAME "gpiochip0"
#define DURATION_MIN 1
#define DURATION_MAX 3600

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading config file: file is empty or unreadable\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Error parsing config file: expected '=' in 'duration=<seconds>'\n");
        return -1;
    }

    *eq = '\0';
    char *key = line;
    char *value_str = eq + 1;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error parsing config file: expected key 'duration', got '%s'\n", key);
        return -1;
    }

    char *endptr;
    long val = strtol(value_str, &endptr, 10);
    if (*endptr != '\0' || val <= 0 || val > DURATION_MAX) {
        fprintf(stderr, "Error parsing config file: duration must be a positive integer between 1 and %d\n", DURATION_MAX);
