#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin assignments */
#define SENSOR_LEFT    4
#define SENSOR_MIDDLE  17
#define SENSOR_RIGHT   27
#define MOTOR_LEFT_PWM 22
#define MOTOR_LEFT_DIR 23
#define MOTOR_RIGHT_PWM 24
#define MOTOR_RIGHT_DIR 25

/* Motor speeds (0-255) */
#define BASE_SPEED 150
#define TURN_FACTOR 127  /* half speed */

/* PWM frequency (Hz) */
#define PWM_FREQ 1000

/* Log file path */
#define LOG_FILE "trace_log.txt"

/* Sampling interval (microseconds) */
#define SAMPLE_US 10000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read three IR sensors; returns 0 or 1 for each sensor               */
/* ------------------------------------------------------------------ */
static int read_sensors(void)
{
    int left  = gpioRead(SENSOR_LEFT);
    int mid   = gpioRead(SENSOR_MIDDLE);
    int right = gpioRead(SENSOR_RIGHT);

    if (left < 0 || mid < 0 || right < 0) {
        fprintf(stderr, "Error: gpioRead failed (left=%d mid=%d right=%d)\n",
                left, mid, right);
        return -1;
    }
    return (left << 0) | (mid << 1) | (right << 2);
}

/* ------------------------------------------------------------------ */
/* Drive motors: speed range 0-255, direction 0=forward, 1=backward   */
/* ------------------------------------------------------------------ */
static void set_motor(int left_speed, int left_dir,
                      int right_speed, int right_dir)
{
    if (gpioPWM(MOTOR_LEFT_PWM, left_speed) < 0)
        fprintf(stderr, "Warning: gpioPWM left PWM failed\n");
    if (gpioWrite(MOTOR_LEFT_DIR, left_dir) < 0)
        fprintf(stderr, "Warning: gpioWrite left DIR failed\n");

    if (gpioPWM(MOTOR_RIGHT_PWM, right_speed) < 0)
        fprintf(stderr, "Warning: gpioPWM right PWM failed\n");
    if (gpioWrite(MOTOR_RIGHT_DIR, right_dir) < 0)
        fprintf(stderr, "Warning: gpioWrite right DIR failed\n");
}

/* ------------------------------------------------------------------ */
/* Stop both motors                                                    */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    gpioPWM(MOTOR_LEFT_PWM, 0);
    gpioPWM(MOTOR_RIGHT_PWM, 0);
}

/* ------------------------------------------------------------------ */
/* Log one cycle: timestamp + sensor states + motor speeds             */
/* ------------------------------------------------------------------ */
static void log_data(int sensors, int left_speed, int right_speed)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(g_log, "%s,%d,%d,%d,%d,%d\n",
            ts,
            (sensors >> SENSOR_LEFT)   & 1,
            (sensors >> SENSOR_MIDDLE) & 1,
            (sensors >> SENSOR_RIGHT)  & 1,
            left_speed,
            right_speed);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Fatal: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_MIDDLE, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Fatal: failed to set sensor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor control pins ---- */
    if (gpioSetMode(MOTOR_LEFT_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Fatal: failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency ---- */
    if (gpioSetPWMfrequency(MOTOR_LEFT_PWM, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_PWM, PWM_FREQ) < 0) {
        fprintf(stderr, "Fatal: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Fatal: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,left,middle,right,left_speed,right_speed\n");
        fflush(g_log);
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        int sensors = read_sensors();
        if (sensors < 0) {
            /* Sensor read error — stop motors and continue */
            stop_motors();
            gpioDelay(SAMPLE_US);
            continue;
        }

        int left_speed  = BASE_SPEED;
        int right_speed = BASE_SPEED;
        int left_dir   = 0;
        int right_dir  = 0;

        if (sensors & (1 << SENSOR_MIDDLE)) {
            /* Middle sensor is black — drive straight */
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED;
            left_dir  = 0;
            right_dir = 0;
        } else if (sensors & (1 << SENSOR_LEFT)) {
            /* Left sensor is black — turn right */
            left_speed  = TURN_FACTOR;
            right_speed = BASE_SPEED;
            left_dir  = 0;
            right_dir = 0;
        } else if (sensors & (1 << SENSOR_RIGHT)) {
            /* Right sensor is black — turn left */
            left_speed  = BASE_SPEED;
            right_speed = TURN_FACTOR;
            left_dir  = 0;
            right_dir = 0;
        } else {
            /* No black line — stop */
            left_speed  = 0;
            right_speed = 0;
            left_dir  = 0;
            right_dir = 0;
        }

        set_motor(left_speed, left_dir, right_speed, right_dir);
        log_data(sensors, left_speed, right_speed);

        gpioDelay(SAMPLE_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

