#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **sensor_line,
                     struct gpiod_line **led_line) {
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    *sensor_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_PIN);
    if (!*sensor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*sensor_line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        *sensor_line = NULL;
        return -1;
    }

    *led_line = gpiod_chip_get_line(*chip, ALARM_LED_PIN);
    if (!*led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(*sensor_line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        *sensor_line = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*led_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_line_release(*sensor_line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        *sensor_line = NULL;
        *led_line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *sensor_line,
                         struct gpiod_line *led_line) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int sound_sensor_mode(struct gpiod_line *sensor_line, struct gpiod_line *led_line) {
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context: %s\n", strerror(errno));
        return -1;
    }

    void *publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket: %s\n", strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    int linger = 1000;
    if (zmq_setsockopt(publisher, ZMQ_LINGER, &linger, sizeof(linger)) < 0) {
        fprintf(stderr, "Failed to set ZMQ_LINGER: %s\n", strerror(errno));
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return -1;
    }

    if (zmq_bind(publisher, ZMQ_ADDRESS) < 0) {
        fprintf(stderr, "Failed to bind ZeroMQ publisher: %s\n", strerror(errno));
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Sound sensor mode running. Publishing SOUND_ALERTS on %s\n", ZMQ_ADDRESS);

    while (running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read sound sensor: %s\n", strerror(errno));
            break;
        }

        if (val == 0) {
            char message[64];
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            strftime(message, sizeof(message), "%Y-%m-%d %H:%M:%S", t);

            if (zmq_send(publisher, message, strlen(message), 0) < 0) {
                fprintf(stderr, "Failed to send ZeroMQ message: %s\n", strerror(errno));
            } else {
                printf("Sound detected at %s\n", message);
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    zmq_close(publisher);
    zmq_ctx_destroy(context);
    return 0;
}

static int alarm_node_mode(struct gpiod_line *led_line) {
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context: %s\n", strerror(errno));
        return -1;
    }

    void *subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket: %s\n", strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    if (zmq_connect(subscriber, ZMQ_ADDRESS) < 0) {
        fprintf(stderr, "Failed to connect to ZeroMQ publisher: %s\n", strerror(errno));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    if (zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        fprintf(stderr, "Failed to set ZMQ_SUBSCRIBE: %s\n", strerror(errno));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Alarm node mode running. Subscribing to %s/%s\n", ZMQ_ADDRESS, ZMQ_TOPIC);

    while (running) {
        zmq_msg_t message;
        int rc = zmq_recvmsg(subscriber, &message, 0);
        if (rc < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Failed to receive ZeroMQ message: %s\n", strerror(errno));
            break;
        }

        if (rc > 0) {
            char *msg_data = (char *)zmq_msg_data(&message);
            printf("Alarm triggered: %s\n", msg_data);
            gpiod_line_set_value(led_line, 1);
            sleep(ALARM_DURATION_S);
            gpiod_line_set_value(led_line, 0);
        }

        zmq_msg_close(&message);
    }

    zmq_close(subscriber);
    zmq_ctx_destroy(context);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;

    if (init_gpio(&chip, &sensor_line, &led_line) < 0) {
        return EXIT_FAILURE;
    }

    int ret = EXIT_FAILURE;
    if (strcmp(argv[1], "sound_sensor") == 0) {
        ret = sound_sensor_mode(sensor_line, led_line);
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        ret = alarm_node_mode(led_line);
    } else {
        fprintf(stderr, "Invalid mode. Use sound_sensor or alarm_node.\n");
    }

    cleanup_gpio(chip, sensor_line, led_line);
    return (ret == EXIT_SUCCESS) ? EXIT_SUCCESS : EXIT_FAILURE;
}

