#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 1000
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 200

static volatile uint32_t pulses[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static volatile int decoding = 0;
static volatile uint32_t last_edge_tick = 0;

static MQTTClient mqtt_client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
static MQTTClient_message pubmsg = MQTTClient_message_initializer;
static MQTTClient_deliveryToken token;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != PI_OFF && level != PI_ON) return;

    uint32_t duration = tick - last_edge_tick;
    last_edge_tick = tick;

    if (duration > NEC_HDR_MARK - NEC_TOLERANCE &&
        duration < NEC_HDR_MARK + NEC_TOLERANCE) {
        if (decoding == 0) {
            decoding = 1;
            pulse_count = 0;
            last_tick = tick;
        }
        return;
    }

    if (decoding == 0) return;

    if (pulse_count < MAX_PULSES) {
        pulses[pulse_count++] = duration;
    } else {
        decoding = 0;
        pulse_count = 0;
        syslog(LOG_ERR, "Pulse buffer overflow, resetting decoder");
    }
}

static int decode_nec(uint32_t *p, int n, uint32_t *addr, uint32_t *cmd) {
    if (n < 34) return -1;
    if (p[0] < NEC_HDR_MARK - NEC_TOLERANCE || p[0] > NEC_HDR_MARK + NEC_TOLERANCE) return -1;
    if (p[1] < NEC_HDR_SPACE - NEC_TOLERANCE || p[1] > NEC_HDR_SPACE + NEC_TOLERANCE) return -1;

    uint32_t raw = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= n) return -1;
        if (p[idx] < NEC_BIT_MARK - NEC_TOLERANCE || p[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return -1;
        if (p[idx + 1] < NEC_ONE_SPACE - NEC_TOLERANCE || p[idx + 1] > NEC_ONE_SPACE + NEC_TOLERANCE) {
            if (p[idx + 1] < NEC_ZERO_SPACE - NEC_TOLERANCE || p[idx + 1] > NEC_ZERO_SPACE + NEC_TOLERANCE) return -1;
            raw <<= 1;
        } else {
            raw = (raw << 1) | 1;
        }
    }

    uint8_t addr_byte = (raw >> 24) & 0xFF;
    uint8_t addr_inv = (raw >> 16) & 0xFF;
    uint8_t cmd_byte = (raw >> 8) & 0xFF;
    uint8_t cmd_inv = raw & 0xFF;

    if ((uint8_t)(~addr_byte) != addr_inv) return -1;
    if ((uint8_t)(~cmd_byte) != cmd_inv) return -1;

    *addr = addr_byte;
    *cmd = cmd_byte;
    return 0;
}

static void publish_json(uint32_t addr, uint32_t cmd) {
    char json[128];
    snprintf(json, sizeof(json), "{\"address\": %u, \"command\": %u}", addr, cmd);
    pubmsg.payload = json;
    pubmsg.payloadlen = (int)strlen(json);
    pubmsg.qos = 1;
    pubmsg.retained = 0;
    MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function");
        gpioTerminate();
        closelog();
        return 1;
    }

    MQTTClient_create(&mqtt_client, MQTT_BROKER, "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(mqtt_client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "IR decoder started on GPIO%d", IR_GPIO);

    while (running) {
        if (decoding && pulse_count >= 34) {
            uint32_t addr, cmd;
            if (decode_nec(pulses, pulse_count, &addr, &cmd) == 0) {
                syslog(LOG_INFO, "Decoded NEC: addr=0x%02X cmd=0x%02X", addr, cmd);
                publish_json(addr, cmd);
            } else {
                syslog(LOG_ERR, "Invalid NEC frame");
            }
            decoding = 0;
            pulse_count = 0;
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return 0;
}

