#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define CONVERSION_DELAY_MS 180
#define SAMPLE_INTERVAL_S 1

static const uint8_t sensor_addrs[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};
static int i2c_fds[NUM_SENSORS];
static int i2c_fd = -1;
static int udp_sock = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_open(uint8_t addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t cmd = 0x20; /* One-Time High-Resolution mode */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x20) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "read() failed: %s (got %zd bytes)\n", strerror(errno), r);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int udp_open(void) {
    int s = socket(AF_INET, SOCK_DGRAM, 0);
    if (s < 0) {
        fprintf(stderr, "socket() failed: %s\n", strerror(errno));
        return -1;
    }
    return s;
}

static int udp_send(int s, const char *msg) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(s, msg, strlen(msg), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(sensor_addrs[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Sensor %d (0x%02X) init failed\n", i + 1, sensor_addrs[i]);
        }
    }

    udp_sock = udp_open();
    if (udp_sock < 0) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) close(i2c_fds[i]);
        }
        return 1;
    }

    while (!terminate) {
        char data[256];
        size_t pos = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] < 0) continue;
            float lux;
            if (bh1750_read_lux(i2c_fds[i], &lux) == 0) {
                pos += snprintf(data + pos, sizeof(data) - pos, "%d,%.1f;", i + 1, lux);
            } else {
                pos += snprintf(data + pos, sizeof(data) - pos, "%d,NaN;", i + 1);
            }
        }

        if (pos > 0) {
            data[pos - 1] = '\0';
            if (udp_send(udp_sock, data) < 0) {
                fprintf(stderr, "UDP send failed; continuing\n");
            }
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    if (udp_sock >= 0) close(udp_sock);
    return 0;
