#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_start(int fd)
{
    uint8_t buf[1] = {0x00};
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write start failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_airflow(int fd, float *flow_out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_start(fd) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint8_t data[2];
        if (i2c_read_data(fd, data, sizeof(data)) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        raw &= 0x3FFF;

        *flow_out = ((float)raw - 3277.0f) * 0.1f;
        return 0;
    }

    fprintf(stderr, "Failed to read airflow after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AWM7300V_ADDR, strerror(errno));
        close(g_i2c_fd);
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started on %s at addr 0x%02X. Press Ctrl+C to exit.\n",
           I2C_BUS, AWM7300V_ADDR);

    while (g_running) {
        float flow_rate;
        if (read_airflow(g_i2c_fd, &flow_rate) == 0) {
            log_flow_rate(g_log_fp, flow_rate);
            printf("Flow rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    return EXIT_SUCCESS;
}

