        return -1;
    }
    *bytes_read = bytes;
    return 0;
}

static int find_magic_word(const uint8_t *buffer, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        int match = 1;
        for (int j = 0; j < MAGIC_WORD_SIZE; j++) {
            if (buffer[i + j] != magic_word[j]) {
                match = 0;
                break;
            }
        }
        if (match) return i;
    }
    return -1;
}

static int parse_tlv_header(const uint8_t *buffer, int *type, int *length) {
    if (buffer[0] != 0x02 || buffer[1] != 0x04) {
        fprintf(stderr, "Invalid TLV magic word\n");
        return -1;
    }
    *type = buffer[2] | (buffer[3] << 8);
    *length = buffer[4] | (buffer[5] << 8) | (buffer[6] << 16) | (buffer[7] << 24);
    return 0;
}

static int parse_detected_points(const uint8_t *buffer, int length, RadarData *data, int max_objects) {
    int offset = 0;
