#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void parse_radar_data(const char *line, time_t *timestamp, float *range) {
    char *endptr;
    long val = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != ',') {
        *timestamp = 0;
        *range = 0.0f;
        return;
    }
    *timestamp = (time_t)val;
    *range = strtof(endptr + 1, &endptr);
    if (endptr == endptr + 1) {
        *range = 0.0f;
    }
}

static void log_detection(time_t timestamp, float range) {
    struct tm tm_info;
    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char time_str[32];
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    time_t last_data_time = 0;

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int ret = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            /* Timeout — no data within READ_TIMEOUT_SEC seconds */
            if (last_data_time != 0) {
                fprintf(stderr, "Warning: no data for %d seconds\n", READ_TIMEOUT_SEC);
                last_data_time = 0;
            }
            continue;
        }

        char read_buf[256];
        ssize_t bytes_read = read(uart_fd, read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "read error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            continue;
        }

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    time_t ts;
                    float range;
                    parse_radar_data(line_buf, &ts, &range);
                    if (ts != 0 && range > 0.0f) {
                        log_detection(ts, range);
                        last_data_time = ts;
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    /* Line too long — discard */
                    line_len = 0;
                }
            }
        }

        sleep((int)POLL_INTERVAL_SEC);
    }

    if (uart_fd >= 0) {
        tcflush(uart_fd, TCIOFLUSH);
        close(uart_fd);
    }
    return EXIT_SUCCESS;
}

