#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27

#define SERIAL_PORT        "/dev/ttyAMA0"
#define BAUD_RATE          115200
#define LOOP_DELAY_US      100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only set flag                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure sensor pins as inputs with pull-up  */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = { LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1 on success, -1 on error           */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Warning: gpioRead failed on pin %d (rc=%d).\n", pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Log a sensor reading with timestamp                                 */
/* ------------------------------------------------------------------ */
static void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n",
           timestamp, left, middle, right);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Send emergency stop message over serial                             */
/* ------------------------------------------------------------------ */
static void send_emergency_stop(void)
{
    const char *msg = "EMERGENCY STOP!\n";
    ssize_t n = write(g_serial_fd, msg, strlen(msg));
    if (n < 0) {
        fprintf(stderr, "Error: serial write failed: %s\n", strerror(errno));
    } else if (n != (ssize_t)strlen(msg)) {
        fprintf(stderr, "Warning: partial serial write (%zd of %zu bytes).\n",
                n, strlen(msg));
    }
}

/* ------------------------------------------------------------------ */
/* Open serial port at 115200 8N1, no flow control                     */
/* ------------------------------------------------------------------ */
static int open_serial(void)
{
    int fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SERIAL_PORT, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);

    tty.c_cflag &= ~PARENB;   /* no parity */
    tty.c_cflag &= ~CSTOPB;   /* 1 stop bit */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;       /* 8 data bits */
    tty.c_cflag &= ~CRTSCTS;  /* no hardware flow control */
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); /* no software flow control */
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG); /* raw mode */

    tty.c_oflag &= ~OPOST;   /* raw output */
    tty.c_oflag &= ~ONLCR;   /* no NL->CR translation */

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;     /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_serial_fd >= 0) {
        close(g_serial_fd);
        g_serial_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    g_serial_fd = open_serial();
    if (g_serial_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("KY-033 obstacle detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int left   = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            /* Error already reported; continue running */
        } else {
            log_sensor_data(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                send_emergency_stop();
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}
